# Module level on purpose: handle_message imports `re` locally further down, which
# would make a bare `re` inside it an unbound local.
_BARE_NUMBER = re.compile(r'[\s₪$€+\-]*\d[\d,]*(?:\.\d+)?[\s₪$€]*')

# Store monitor process
monitor_process = None

# Allowed user IDs for sensitive commands (add more IDs separated by commas)
# Only the owner (TELEGRAM_CHAT_ID in .env) may use the bot; empty means nobody is authorised.
ALLOWED_USER_IDS = [int(x) for x in str(TELEGRAM_CHAT_ID).split(",") if x.strip().isdigit()]

def is_authorized(user_id: int) -> bool:
    """Check if user is authorized for sensitive commands"""
    return user_id in ALLOWED_USER_IDS

async def unauthorized_message(update: Update):
    """Send unauthorized message"""
    await update.message.reply_text(
        "🔒 *Access Denied*\n\n"
        "This command is restricted to authorized users only.",
        parse_mode='Markdown'
    )


