async def price(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Get current price and key stats for a stock"""
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'price'
        await update.message.reply_text("📊 Which stock? Send the symbol (e.g. AAPL, NVDA):")
        return
    
    symbol = context.args[0].upper()
    await _do_price(update, symbol)


async def _do_price(update: Update, symbol: str):
    """Execute price lookup"""
    await update.message.reply_text(f"⏳ Fetching price data for {symbol}...")
    
    try:
        stock = yf.Ticker(symbol)
        info = stock.info
        
        # Get real-time price data from info
        current_price = info.get('regularMarketPrice') or info.get('currentPrice')
        prev_close = info.get('previousClose') or info.get('regularMarketPreviousClose')
        
        if not current_price:
            # Fallback to history if info doesn't have real-time data
            hist = stock.history(period='5d')
            if hist.empty:
                await update.message.reply_text(f"❌ Could not find data for {symbol}")
                return
            current_price = hist['Close'].iloc[-1]
            prev_close = hist['Close'].iloc[-2] if len(hist) > 1 else current_price
        
        change = current_price - prev_close
        change_pct = (change / prev_close) * 100 if prev_close else 0
        
        # Get additional info
        high_52w = info.get('fiftyTwoWeekHigh')
        low_52w = info.get('fiftyTwoWeekLow')
        market_cap = info.get('marketCap', 0) or 0
        pe_ratio = info.get('trailingPE')
        volume = info.get('volume', 0) or 0
        beta = info.get('beta')
        dividend_yield = info.get('dividendYield')
        dividend_rate = info.get('dividendRate')
        
        # Format values
        high_52w_str = f"${high_52w:.2f}" if high_52w else "N/A"
        low_52w_str = f"${low_52w:.2f}" if low_52w else "N/A"
        pe_str = f"{pe_ratio:.2f}" if pe_ratio else "N/A"
        beta_str = f"{beta:.2f}" if beta else "N/A"
        
        # Format dividend
        if dividend_yield and dividend_rate:
            div_str = f"${dividend_rate:.2f} ({dividend_yield*100:.2f}%)"
        elif dividend_yield:
            div_str = f"{dividend_yield*100:.2f}%"
        elif dividend_rate:
            div_str = f"${dividend_rate:.2f}"
        else:
            div_str = "None"
        
        # Format market cap
        if market_cap >= 1e12:
            mc_str = f"${market_cap/1e12:.2f}T"
        elif market_cap >= 1e9:
            mc_str = f"${market_cap/1e9:.2f}B"
        elif market_cap >= 1e6:
            mc_str = f"${market_cap/1e6:.2f}M"
        else:
            mc_str = f"${market_cap:,.0f}"
        
        emoji = "📈" if change >= 0 else "📉"
        sign = "+" if change >= 0 else ""
        
        message = f"""
{emoji} *{symbol}* - {info.get('shortName', symbol)}

💵 *Price:* ${current_price:.2f}
📊 *Change:* {sign}{change:.2f} ({sign}{change_pct:.2f}%)

📈 *52W High:* {high_52w_str}
📉 *52W Low:* {low_52w_str}
🏢 *Market Cap:* {mc_str}
📊 *P/E Ratio:* {pe_str}
⚡ *Beta:* {beta_str}
💰 *Dividend:* {div_str}
📦 *Volume:* {volume:,}
"""
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error fetching {symbol}: {str(e)}")


