async def _do_news(update: Update, symbol: str):
    """Execute news lookup - prioritizes material news (deals, company changes, contracts)"""
    await update.message.reply_text(f"⏳ Fetching news for {symbol}...")
    
    try:
        news_data = news_collector.get_stock_news(symbol)
        all_articles = news_data.get('articles', [])
        
        # Filter out clickbait sources and prioritize material news
        clickbait_sources = ['seeking alpha', 'seekingalpha', 'motley fool', 'benzinga', 'investorplace']
        material_categories = ['deals_agreements', 'company_changes', 'regulatory_legal', 'product_feature']
        material_keywords = [
            'deal', 'agreement', 'partnership', 'partner', 'contract', 'acquisition', 'acquire',
            'merger', 'merge', 'appoint', 'hire', 'ceo', 'cfo', 'executive', 'resign', 'retire',
            'launch', 'unveil', 'announce', 'fda', 'approval', 'sec', 'government', 'award',
            'license', 'collaboration', 'joint venture', 'investment', 'stake', 'buyout',
            'restructur', 'layoff', 'expand', 'open', 'close', 'facility', 'plant', 'factory',
            'billion', 'million', 'revenue', 'earnings', 'guidance', 'forecast', 'upgrade',
            'downgrade', 'lawsuit', 'settlement', 'fine', 'investigation', 'patent', 'regulatory'
        ]
        
        # Score and filter articles
        scored_articles = []
        for article in all_articles:
            source = article.get('source', '').lower()
            title = article.get('title', '').lower()
            categories = article.get('categories', [])
            
            # Skip clickbait sources
            if any(cb in source for cb in clickbait_sources):
                continue
            
            # Calculate material score
            score = 0
            
            # Boost for material categories
            for cat in categories:
                if cat in material_categories:
                    score += 3
            
            # Boost for material keywords in title
            for keyword in material_keywords:
                if keyword in title:
                    score += 2
                    break
            
            # Boost for credible sources
            credible_sources = ['reuters', 'bloomberg', 'wsj', 'wall street', 'cnbc', 'sec.gov', 
                               'pr newswire', 'business wire', 'globe newswire', 'yahoo finance',
                               'associated press', 'ap news', 'financial times', 'barron']
            for cs in credible_sources:
                if cs in source:
                    score += 2
                    break
            
            if score > 0:
                article['material_score'] = score
                scored_articles.append(article)
        
        # Sort by material score and take top 7
        scored_articles.sort(key=lambda x: x.get('material_score', 0), reverse=True)
        articles = scored_articles[:7]
        
        # If not enough material news, fall back to any non-clickbait news
        if len(articles) < 3:
            for article in all_articles:
                source = article.get('source', '').lower()
                if not any(cb in source for cb in clickbait_sources):
                    if article not in articles:
                        articles.append(article)
                        if len(articles) >= 7:
                            break
        
        if not articles:
            await update.message.reply_text(f"📭 No material news found for {symbol}")
            return
        
        message = f"📰 *Material News for {symbol}*\n\n"
        
        for i, article in enumerate(articles, 1):
            title = article.get('title', 'No title')[:70]
            source = article.get('source', 'Unknown')
            url = article.get('url', '')
            impact = article.get('impact', 'Neutral')
            categories = article.get('categories', [])
            
            impact_emoji = "🟢" if impact == "Positive" else "🔴" if impact == "Negative" else "⚪"
            
            # Category emoji
            cat_emoji = ""
            if 'deals_agreements' in categories:
                cat_emoji = "🤝"
            elif 'company_changes' in categories:
                cat_emoji = "👔"
            elif 'product_feature' in categories:
                cat_emoji = "🚀"
            elif 'regulatory_legal' in categories:
                cat_emoji = "⚖️"
            elif 'earnings_financial' in categories:
                cat_emoji = "📊"
            
            # Make title a clickable link if URL exists
            if url:
                message += f"{i}. {impact_emoji}{cat_emoji} [{title}]({url})\n"
            else:
                message += f"{i}. {impact_emoji}{cat_emoji} *{title}*\n"
            message += f"   📤 {source}\n\n"
        
        await update.message.reply_text(message, parse_mode='Markdown', disable_web_page_preview=True)
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error fetching news: {str(e)}")


