async def _do_analyze(update: Update, symbol: str):
    """Execute full analysis"""
    await update.message.reply_text(f"⏳ Running full analysis for {symbol}... This may take a moment.")
    
    try:
        stock = yf.Ticker(symbol)
        info = stock.info
        hist = stock.history(period='3mo')
        
        if hist.empty:
            await update.message.reply_text(f"❌ Could not find data for {symbol}")
            return
        
        # Price data
        current_price = hist['Close'].iloc[-1]
        
        # Technical indicators
        ma_20 = hist['Close'].tail(20).mean()
        ma_50 = hist['Close'].tail(50).mean()
        
        # RSI calculation
        delta = hist['Close'].diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        rs = gain / loss
        rsi = 100 - (100 / (1 + rs)).iloc[-1]
        
        # Analyst data
        target_mean = info.get('targetMeanPrice', 0)
        target_low = info.get('targetLowPrice', 0)
        target_high = info.get('targetHighPrice', 0)
        rec = info.get('recommendationKey', 'N/A')
        num_analysts = info.get('numberOfAnalystOpinions', 0)
        
        # Calculate upside
        upside = ((target_mean - current_price) / current_price * 100) if target_mean else 0
        
        # Trend assessment
        if current_price > ma_20 > ma_50:
            trend = "🟢 BULLISH"
        elif current_price < ma_20 < ma_50:
            trend = "🔴 BEARISH"
        else:
            trend = "🟡 NEUTRAL"
        
        # RSI assessment
        if rsi > 70:
            rsi_signal = "⚠️ Overbought"
        elif rsi < 30:
            rsi_signal = "💡 Oversold"
        else:
            rsi_signal = "✅ Normal"
        
        message = f"""
🔍 *Full Analysis: {symbol}*
{info.get('shortName', symbol)}

💵 *Current Price:* ${current_price:.2f}

📊 *Technical Analysis:*
• Trend: {trend}
• 20-Day MA: ${ma_20:.2f}
• 50-Day MA: ${ma_50:.2f}
• RSI(14): {rsi:.1f} {rsi_signal}
• Price vs 20MA: {((current_price/ma_20)-1)*100:+.1f}%
• Price vs 50MA: {((current_price/ma_50)-1)*100:+.1f}%

🎯 *Analyst Targets:*
• Low: ${target_low:.2f}
• Mean: ${target_mean:.2f}
• High: ${target_high:.2f}
• Upside: {upside:+.1f}%
• Rating: {rec.upper()} ({num_analysts} analysts)

📈 *Recommendation:*
"""
        # Add recommendation
        if upside > 20 and trend == "🟢 BULLISH":
            message += "✅ Strong Buy Signal - Bullish trend with >20% upside"
        elif upside > 10 and rsi < 70:
            message += "🟢 Buy - Good upside potential"
        elif upside < -10:
            message += "🔴 Caution - Trading above analyst targets"
        elif rsi > 70:
            message += "⚠️ Wait - Overbought, wait for pullback"
        else:
            message += "🟡 Hold - Monitor for better entry"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error analyzing {symbol}: {str(e)}")


