async def _do_technical(update: Update, symbol: str):
    """Execute technical analysis"""
    await update.message.reply_text(f"⏳ Calculating technical indicators for {symbol}...")
    
    try:
        stock = yf.Ticker(symbol)
        hist = stock.history(period='3mo')
        
        if hist.empty or len(hist) < 50:
            await update.message.reply_text(f"❌ Not enough data for {symbol}")
            return
        
        close = hist['Close']
        current = close.iloc[-1]
        
        # Moving averages
        ma_10 = close.tail(10).mean()
        ma_20 = close.tail(20).mean()
        ma_50 = close.tail(50).mean()
        
        # RSI
        delta = close.diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        rs = gain / loss
        rsi = 100 - (100 / (1 + rs)).iloc[-1]
        
        # MACD
        exp1 = close.ewm(span=12, adjust=False).mean()
        exp2 = close.ewm(span=26, adjust=False).mean()
        macd = exp1 - exp2
        signal = macd.ewm(span=9, adjust=False).mean()
        macd_val = macd.iloc[-1]
        signal_val = signal.iloc[-1]
        
        # Bollinger Bands
        sma_20 = close.rolling(window=20).mean()
        std_20 = close.rolling(window=20).std()
        upper_band = (sma_20 + (std_20 * 2)).iloc[-1]
        lower_band = (sma_20 - (std_20 * 2)).iloc[-1]
        
        # Volume analysis
        avg_volume = hist['Volume'].tail(20).mean()
        current_volume = hist['Volume'].iloc[-1]
        vol_ratio = current_volume / avg_volume
        
        message = f"""
📊 *Technical Indicators: {symbol}*

💵 *Price:* ${current:.2f}

📈 *Moving Averages:*
• 10-Day: ${ma_10:.2f} ({((current/ma_10)-1)*100:+.1f}%)
• 20-Day: ${ma_20:.2f} ({((current/ma_20)-1)*100:+.1f}%)
• 50-Day: ${ma_50:.2f} ({((current/ma_50)-1)*100:+.1f}%)

📉 *RSI (14):* {rsi:.1f}
{"⚠️ Overbought" if rsi > 70 else "💡 Oversold" if rsi < 30 else "✅ Normal"}

📊 *MACD:*
• MACD: {macd_val:.3f}
• Signal: {signal_val:.3f}
• {"🟢 Bullish" if macd_val > signal_val else "🔴 Bearish"}

📏 *Bollinger Bands:*
• Upper: ${upper_band:.2f}
• Lower: ${lower_band:.2f}
• Width: {((upper_band-lower_band)/current)*100:.1f}%

📦 *Volume:*
• Today: {current_volume:,.0f}
• Avg (20d): {avg_volume:,.0f}
• Ratio: {vol_ratio:.1f}x {"📈" if vol_ratio > 1.5 else ""}
"""
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


