            # If multiple watchlists exist, ask which one
            if len(watchlists) > 1:
                pending_commands[user_id] = 'select_watchperf'
                
                msg = "📈 *Watchlist Performance*\n\n"
                msg += "Select a watchlist:\n"
                for i, (name, wl_data) in enumerate(watchlists.items(), 1):
                    stocks_count = len(wl_data.get("stocks", {}))
                    is_active = "✅" if name == active else ""
                    msg += f"{i}. *{name}* ({stocks_count} stocks) {is_active}\n"
                
