async def _show_watchperf(update: Update, watchlist_name: str):
    """Show performance for a specific watchlist"""
    try:
        # Load watchlist
        if os.path.exists("watchlists.json"):
            with open("watchlists.json", "r") as f:
                data = json.load(f)
                
                watchlists = data.get("watchlists", {})
                watchlist_names = list(watchlists.keys())
                
                # First try to parse as number
                actual_name = None
                try:
                    idx = int(watchlist_name) - 1
                    if 0 <= idx < len(watchlist_names):
                        actual_name = watchlist_names[idx]
                except ValueError:
                    pass
                
                # If not a valid number, check by name (case-insensitive)
                if not actual_name:
                    for name in watchlists.keys():
                        if name.lower() == watchlist_name.lower():
                            actual_name = name
                            break
                
                if not actual_name:
                    await update.message.reply_text(f"❌ Watchlist '{watchlist_name}' not found.")
                    return
                
                stocks_data = watchlists.get(actual_name, {}).get("stocks", {})
                if isinstance(stocks_data, list):
                    stocks = {s: {} for s in stocks_data}
                else:
                    stocks = stocks_data
        else:
            stocks = {}
            actual_name = "default"
        
        if not stocks:
            await update.message.reply_text(f"📋 Watchlist *{actual_name}* is empty.\nUse /add SYMBOL to add stocks.", parse_mode='Markdown')
            return
        
        await update.message.reply_text(f"⏳ Calculating performance for {len(stocks)} stocks in *{actual_name}*...", parse_mode='Markdown')
        
        performance_data = []
        errors = []
        today = datetime.now()
        
        for symbol, saved_data in stocks.items():
            try:
                stock = yf.Ticker(symbol)
                info = stock.info
                current_price = info.get('regularMarketPrice') or info.get('currentPrice', 0)
                
                if not current_price:
                    errors.append(f"⚪ *{symbol}*: No price data")
                    continue
                
                # Get added date and price
                added_at_str = saved_data.get('added_at', '')
                added_price = saved_data.get('added_price', 0)
                
                if added_at_str:
                    try:
                        added_date = datetime.fromisoformat(added_at_str)
                        days_watching = (today - added_date).days
                    except:
                        days_watching = 0
                        added_date = None
                else:
                    days_watching = 0
                    added_date = None
                
                # If we don't have the added price, try to fetch historical
                if not added_price and added_date:
                    try:
                        hist = stock.history(start=added_date.strftime('%Y-%m-%d'), end=(added_date + timedelta(days=5)).strftime('%Y-%m-%d'))
                        if not hist.empty:
                            added_price = hist['Close'].iloc[0]
                    except:
                        pass
                
                # Calculate performance
                if added_price and added_price > 0:
                    change = current_price - added_price
                    change_pct = ((current_price - added_price) / added_price) * 100
                else:
                    change = 0
                    change_pct = 0
                    added_price = current_price  # Fallback
                
                # Format days watching
                if days_watching >= 365:
                    years = days_watching // 365
                    months = (days_watching % 365) // 30
                    time_str = f"{years}y {months}m" if months > 0 else f"{years}y"
                elif days_watching >= 30:
                    months = days_watching // 30
                    time_str = f"{months}m {days_watching % 30}d"
                else:
                    time_str = f"{days_watching}d"
                
                performance_data.append({
                    'symbol': symbol,
                    'name': saved_data.get('name', symbol),
                    'added_price': added_price,
                    'current_price': current_price,
                    'change': change,
                    'change_pct': change_pct,
                    'days_watching': days_watching,
                    'time_str': time_str,
                    'added_date_display': saved_data.get('added_date_display', 'Unknown'),
                    'note': saved_data.get('notes', '')
                })
                
            except Exception as e:
                errors.append(f"⚪ *{symbol}*: Error - {str(e)[:30]}")
        
        if not performance_data:
            await update.message.reply_text("❌ Could not fetch performance data.")
            return
        
        # Sort by change % (best performers first)
        performance_data.sort(key=lambda x: x['change_pct'], reverse=True)
        
        # Build message
        message = f"📈 *WATCHLIST PERFORMANCE - {actual_name}*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += "_Since you added each stock_\n\n"
        
        # Calculate totals
        total_gain = sum(p['change_pct'] for p in performance_data)
        avg_gain = total_gain / len(performance_data) if performance_data else 0
        winners = sum(1 for p in performance_data if p['change_pct'] > 0)
        losers = sum(1 for p in performance_data if p['change_pct'] < 0)
        
        message += f"🏆 *Winners:* {winners} | 📉 *Losers:* {losers}\n"
        message += f"📊 *Avg Performance:* {avg_gain:+.1f}%\n\n"
        
        for item in performance_data:
            emoji = "🟩" if item['change_pct'] >= 0 else "🔴"
            sign = "+" if item['change_pct'] >= 0 else ""
            
            message += f"{emoji} *{item['symbol']}*: {sign}{item['change_pct']:.1f}%\n"
            message += f"   📅 Watching: {item['time_str']} (since {item['added_date_display']})\n"
            message += f"   💵 ${item['added_price']:.2f} → ${item['current_price']:.2f} ({sign}${item['change']:.2f})\n"
            if item['note']:
                message += f"   📝 _{item['note'][:50]}{'...' if len(item['note']) > 50 else ''}_\n"
            message += "\n"
        
        # Add errors
        if errors:
            message += "\n*Issues:*\n"
            for err in errors:
                message += f"{err}\n"
        
        # Split if too long
        if len(message) <= 4096:
            await update.message.reply_text(message, parse_mode='Markdown')
        else:
            # Split into parts
            parts = []
            current = f"📈 *WATCHLIST PERFORMANCE - {actual_name}*\n━━━━━━━━━━━━━━━━━━━━\n\n"
            
            for item in performance_data:
                emoji = "🟩" if item['change_pct'] >= 0 else "🔴"
                sign = "+" if item['change_pct'] >= 0 else ""
                
                block = f"{emoji} *{item['symbol']}*: {sign}{item['change_pct']:.1f}%\n"
                block += f"   📅 Watching: {item['time_str']} (since {item['added_date_display']})\n"
                block += f"   💵 ${item['added_price']:.2f} → ${item['current_price']:.2f}\n\n"
                
                if len(current) + len(block) > 4000:
                    parts.append(current)
                    current = f"📈 *{actual_name} (cont.)*\n\n"
                
                current += block
            
            if current:
                parts.append(current)
            
            for part in parts:
                await update.message.reply_text(part, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def remove_stock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove stock from watchlist"""
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'remove'
        await update.message.reply_text("➖ Which stock to remove? Send the symbol:")
        return
    
    symbol = context.args[0].upper()
    await _do_remove(update, symbol)


async def _do_remove(update: Update, symbol: str):
    """Execute remove from watchlist"""
    from datetime import datetime
    
    try:
        if os.path.exists("watchlists.json"):
            with open("watchlists.json", "r") as f:
                data = json.load(f)
            active = data.get("active_watchlist", "default")
            stocks = data.get("watchlists", {}).get(active, {}).get("stocks", {})
        else:
            await update.message.reply_text("📋 Watchlist is empty")
            return
        
        if symbol not in stocks:
            await update.message.reply_text(f"ℹ️ {symbol} is not in your watchlist")
            return
        
        del stocks[symbol]
        data["updated_at"] = datetime.now().isoformat()
        
        with open("watchlists.json", "w") as f:
            json.dump(data, f, indent=2)
        
        await update.message.reply_text(f"✅ Removed *{symbol}* from watchlist!", parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def week_summary(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Weekly news summary for a stock"""
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'week'
        await update.message.reply_text("📅 Which stock? Send the symbol:")
        return
    
    symbol = context.args[0].upper()
    await _do_week(update, symbol)


async def _do_week(update: Update, symbol: str):
    """Execute weekly summary"""
    await update.message.reply_text(f"⏳ Generating weekly summary for {symbol}... This may take a moment.")
    
    try:
        # Get news
        news_data = news_collector.get_stock_news(symbol)
        articles = news_data.get('articles', [])[:10]
        
        # Get price data
        stock = yf.Ticker(symbol)
        hist = stock.history(period='7d')
        
        if hist.empty:
            await update.message.reply_text(f"❌ Could not find data for {symbol}")
            return
        
        start_price = hist['Close'].iloc[0]
        end_price = hist['Close'].iloc[-1]
        week_change = ((end_price - start_price) / start_price) * 100
        
        message = f"""
📅 *Weekly Summary: {symbol}*

💵 *Price Performance:*
• Start: ${start_price:.2f}
• End: ${end_price:.2f}
• Change: {week_change:+.2f}% {"📈" if week_change > 0 else "📉"}

📰 *Key News ({len(articles)} articles):*
"""
        for i, article in enumerate(articles[:5], 1):
            title = article.get('title', 'No title')[:60]
            url = article.get('url', '')
            impact = article.get('impact', 'Neutral')
            emoji = "🟢" if impact == "Positive" else "🔴" if impact == "Negative" else "⚪"
            
            if url:
                message += f"{i}. {emoji} [{title}]({url})\n"
            else:
                message += f"{i}. {emoji} {title}\n"
        
        # AI Summary if available
        if HAS_OPENAI and articles:
            try:
                prompt = f"Summarize these news headlines for {symbol} in 2-3 sentences: " + \
                         " | ".join([a.get('title', '')[:50] for a in articles[:5]])
                
                response = client.chat.completions.create(
                    model="gpt-4o",
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=150
                )
                ai_summary = response.choices[0].message.content.strip()
                message += f"\n🤖 *AI Summary:*\n{ai_summary}"
            except:
                pass
        
        await update.message.reply_text(message, parse_mode='Markdown', disable_web_page_preview=True)
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


def _fetch_portfolio_data_sync(holdings):
    """Fetch all portfolio stock data synchronously (runs in thread to avoid blocking event loop)"""
    total_cost = 0
    total_value = 0
    total_day_change = 0
    total_premarket_change = 0
    total_afterhours_change = 0
    holding_results = []

    _today_str = _us_market_date().strftime('%Y-%m-%d')

    for holding in holdings:
        symbol = holding['symbol']
        shares = holding['shares']
        avg_price = holding['purchase_price']
        cost = holding['total_cost']
        # A lot bought TODAY must measure its day/pre-market P/L from the price YOU
        # paid, not yesterday's close — otherwise it credits you a move you bought into.
        bought_today = str(holding.get('purchase_date', '')).startswith(_today_str)

        try:
            stock = yf.Ticker(symbol)
            info = stock.info

            # Before the open Yahoo's regularMarketPrice/previousClose still describe
            # yesterday, so "today" has to be measured against the session that is
            # actually running right now.
            session = resolve_session_prices(symbol, info)
            current_price = session['live_price']
            prev_close = session['day_baseline']

            if current_price and prev_close:
                if bought_today:
                    live_price = current_price

                    # Everything measured from YOUR buy price; no separate PM/AH double-count.
                    current_value = live_price * shares
                    profit_loss = current_value - cost
                    profit_pct = (profit_loss / cost) * 100 if cost else 0

                    day_change_per_share = live_price - avg_price
                    day_change_total = day_change_per_share * shares
                    day_change_pct = (day_change_per_share / avg_price) * 100 if avg_price else 0

                    pre_pct = 0
                    post_pct = 0
                    pre_change_total = 0
                    post_change_total = 0

                    holding_results.append({
                        'symbol': symbol, 'shares': shares, 'avg_price': avg_price,
                        'current_price': live_price, 'current_value': current_value,
                        'profit_loss': profit_loss, 'profit_pct': profit_pct,
                        'day_change_total': day_change_total, 'day_change_pct': day_change_pct,
                        'cost': cost, 'has_data': True, 'pre_pct': pre_pct, 'post_pct': post_pct,
                        'bought_today': True
                    })
                    total_cost += cost
                    total_value += current_value
                    total_day_change += day_change_total
                    continue

                current_value = current_price * shares
                profit_loss = current_value - cost
                profit_pct = (profit_loss / cost) * 100

                day_change_per_share = current_price - prev_close
                day_change_total = day_change_per_share * shares
                day_change_pct = (day_change_per_share / prev_close) * 100

                pre_pct = session['pre_pct']
                post_pct = session['post_pct']
                pre_change_total = session['pre_change'] * shares
                post_change_total = session['post_change'] * shares

                total_cost += cost
                total_value += current_value
                total_day_change += day_change_total
                total_premarket_change += pre_change_total
                total_afterhours_change += post_change_total

                holding_results.append({
                    'symbol': symbol, 'shares': shares, 'avg_price': avg_price,
                    'current_price': current_price, 'current_value': current_value,
                    'profit_loss': profit_loss, 'profit_pct': profit_pct,
                    'day_change_total': day_change_total, 'day_change_pct': day_change_pct,
                    'cost': cost, 'has_data': True, 'pre_pct': pre_pct, 'post_pct': post_pct
                })
            else:
                holding_results.append({
                    'symbol': symbol, 'shares': shares, 'cost': cost,
                    'has_data': False, 'profit_pct': 0, 'day_change_total': 0, 'profit_loss': 0
                })
                total_cost += cost
        except Exception as e:
            holding_results.append({
                'symbol': symbol, 'shares': shares, 'cost': cost,
                'has_data': False, 'error': True, 'profit_pct': 0, 'day_change_total': 0, 'profit_loss': 0
            })
            total_cost += cost
    
    return holding_results, total_cost, total_value, total_day_change, total_premarket_change, total_afterhours_change


async def portfolio(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show portfolio with live prices and P/L"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("⏳ Loading portfolio with live prices...")
    
    try:
        # Load portfolio
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        
        if not os.path.exists(portfolio_file):
            await update.message.reply_text("❌ Portfolio file not found!")
            return
        
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        
        holdings = portfolio_data.get('holdings', [])
        free_cash = _usd_cash_total(portfolio_data)
        
        if not holdings and free_cash == 0:
            await update.message.reply_text("📋 Portfolio is empty!")
            return
        
        # Run blocking yfinance calls in a thread to avoid freezing the bot
        holding_results, total_cost, total_value, total_day_change, total_premarket_change, total_afterhours_change = await asyncio.to_thread(_fetch_portfolio_data_sync, holdings)
        
        # Sort by overall $ P/L (most loss to most gain)
        holding_results.sort(key=lambda x: x.get('profit_loss', 0))
        
        message = "💼 *MY PORTFOLIO*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        for h in holding_results:
            if not h.get('has_data'):
                if h.get('error'):
                    message += f"*{h['symbol']}* - Error\n\n"
                else:
                    message += f"*{h['symbol']}* - No data\n\n"
                continue
            
            # Emoji based on profit/loss
            pl_emoji = "🟢" if h['profit_loss'] >= 0 else "🔴"
            day_emoji = "📈" if h['day_change_total'] >= 0 else "📉"
            
            new_tag = " 🆕" if h.get('bought_today') else ""
            message += f"*{h['symbol']}* ({h['shares']:.0f} shares){new_tag}\n"
            message += f"   💵 ${h['current_price']:.2f} {day_emoji} {h['day_change_pct']:+.2f}%"
            if h.get('bought_today'):
                message += " _(vs your buy)_"

            # Add pre-market/after-hours if available
            ext_info = []
            if h.get('pre_pct', 0) != 0:
                ext_info.append(f"🌅PM:{h['pre_pct']:+.1f}%")
            if h.get('post_pct', 0) != 0:
                ext_info.append(f"🌙AH:{h['post_pct']:+.1f}%")
            if ext_info:
                message += f" | {' '.join(ext_info)}"
            message += "\n"
            
            message += f"   📊 Avg: ${h['avg_price']:.2f} → {pl_emoji} {h['profit_pct']:+.1f}%\n"
            message += f"   💰 Value: ${h['current_value']:,.0f} (P/L: ${h['profit_loss']:+,.0f})\n\n"
        
        # Portfolio totals
        unrealized_pl = total_value - total_cost
        unrealized_pct = (unrealized_pl / total_cost) * 100 if total_cost > 0 else 0
        total_day_pct = (total_day_change / (total_value - total_day_change)) * 100 if total_value > total_day_change else 0
        
        # Calculate realized P/L from sold_history
        realized_pl = 0
        sold_history = portfolio_data.get('sold_history', [])
        for s in sold_history:
            realized_pl += s.get('profit_loss', 0)
        
        total_pl = unrealized_pl + realized_pl
        total_invested = total_cost + sum(s.get('cost_basis', 0) for s in sold_history)
        total_pl_pct = (total_pl / total_invested * 100) if total_invested > 0 else 0
        
        total_emoji = "🟢" if total_pl >= 0 else "🔴"
        unreal_emoji = "🟢" if unrealized_pl >= 0 else "🔴"
        real_emoji = "🟢" if realized_pl >= 0 else "🔴"
        day_total_emoji = "📈" if total_day_change >= 0 else "📉"
        
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += f"*TOTAL PORTFOLIO*\n"
        message += f"💰 Stocks: *${total_value:,.2f}*\n"
        if free_cash > 0:
            message += f"💵 Cash: *${free_cash:,.2f}*\n"
            total_with_cash = total_value + free_cash
            message += f"🏦 Total Value: *${total_with_cash:,.2f}*\n"
        message += f"📊 Cost: ${total_cost:,.2f}\n"
        message += f"{unreal_emoji} Unrealized P/L: *${unrealized_pl:+,.2f}* ({unrealized_pct:+.1f}%)\n"
        message += f"{real_emoji} Realized P/L: *${realized_pl:+,.2f}* ({len(sold_history)} trades)\n"
        message += f"{total_emoji} Total P/L: *${total_pl:+,.2f}* ({total_pl_pct:+.1f}%)\n"
        message += f"{day_total_emoji} Today: *${total_day_change:+,.2f}* ({total_day_pct:+.2f}%)\n"
        
        # Pre-market and After-hours P/L (separate from main totals)
        if total_premarket_change != 0 or total_afterhours_change != 0:
            message += "\n*Extended Hours:*\n"
            if total_premarket_change != 0:
                pm_emoji = "🌅" 
                pm_pct = (total_premarket_change / total_value) * 100 if total_value > 0 else 0
                pm_sign = "📈" if total_premarket_change >= 0 else "📉"
                message += f"{pm_emoji} Pre-Market: {pm_sign} *${total_premarket_change:+,.2f}* ({pm_pct:+.2f}%)\n"
            if total_afterhours_change != 0:
                ah_emoji = "🌙"
                ah_pct = (total_afterhours_change / total_value) * 100 if total_value > 0 else 0
                ah_sign = "📈" if total_afterhours_change >= 0 else "📉"
                message += f"{ah_emoji} After-Hours: {ah_sign} *${total_afterhours_change:+,.2f}* ({ah_pct:+.2f}%)\n"
                
                # Combined: Today + After-Hours (total from yesterday close to AH price)
                combined_change = total_day_change + total_afterhours_change
                combined_pct = (combined_change / (total_value - total_day_change)) * 100 if (total_value - total_day_change) > 0 else 0
                combined_sign = "📈" if combined_change >= 0 else "📉"
                message += f"🌃 Today + AH: {combined_sign} *${combined_change:+,.2f}* ({combined_pct:+.2f}%)\n"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def today(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show today's portfolio performance with daily P/L - FAST batch version"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("📊 Loading today's performance...")
    
    try:
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        
        if not os.path.exists(portfolio_file):
            await update.message.reply_text("❌ Portfolio file not found!")
            return
        
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        
        holdings = portfolio_data.get('holdings', [])
        
        if not holdings:
            await update.message.reply_text("📋 Portfolio is empty!")
            return
        
        # Group holdings by symbol (combine duplicate entries). Also track the
        # portion BOUGHT TODAY (shares + cost) so its day P/L can be measured from
        # the actual purchase price instead of yesterday's close, which is
        # misleading for a position opened during the current session.
        _today_str = _us_market_date().strftime('%Y-%m-%d')
        symbol_data = {}
        for holding in holdings:
            symbol = holding['symbol']
            if symbol not in symbol_data:
                symbol_data[symbol] = {'shares': 0, 'cost': 0, 'today_shares': 0, 'today_cost': 0}
            symbol_data[symbol]['shares'] += holding['shares']
            symbol_data[symbol]['cost'] += holding['total_cost']
            # A lot counts as "bought today" if its purchase_date is the US date.
            if str(holding.get('purchase_date', '')).startswith(_today_str):
                shares_h = holding['shares']
                cost_h = holding.get('total_cost')
                if cost_h is None and holding.get('purchase_price') is not None:
                    cost_h = holding['purchase_price'] * shares_h
                symbol_data[symbol]['today_shares'] += shares_h
                symbol_data[symbol]['today_cost'] += (cost_h or 0)
        
        import yfinance as yf
        from datetime import datetime
        import math
        
        symbols_list = list(symbol_data.keys())
        
        # Primary source: Yahoo's official quote fields via .info — regularMarketPrice
        # (live) and regularMarketPreviousClose (the prior session's close). These match
        # the day-change % brokers/Yahoo show. fast_info.previous_close is NOT reliable
        # (it can return a close from the wrong session), so it is only a fallback.
        def _fetch_quote(sym):
            try:
                info = yf.Ticker(sym).info
                last = info.get('regularMarketPrice') or info.get('currentPrice')
                prev = info.get('regularMarketPreviousClose') or info.get('previousClose')
                if last and prev:
                    last = float(last); prev = float(prev)
                    if not math.isnan(last) and not math.isnan(prev):
                        return sym, last, prev
            except Exception:
                pass
            # Fallback: fast_info (less accurate previous_close, but better than nothing)
            try:
                fi = yf.Ticker(sym).fast_info
                last = float(fi.last_price)
                prev = float(fi.previous_close)
                if last and prev and not math.isnan(last) and not math.isnan(prev):
                    return sym, last, prev
            except Exception:
                pass
            return sym, None, None

        try:
            quote_rows = await asyncio.gather(
                *[asyncio.to_thread(_fetch_quote, s) for s in symbols_list]
            )
        except Exception:
            quote_rows = []
        quotes = {sym: (last, prev) for sym, last, prev in quote_rows}

        # Fallback source: batch daily download, used only for symbols whose live quote
        # failed. Run in a thread to avoid blocking the event loop.
        try:
            batch_data = await asyncio.to_thread(
                yf.download,
                symbols_list,
                period='5d',
                group_by='ticker',
                progress=False,
                threads=True
            )
        except Exception:
            batch_data = None

        if not quotes and batch_data is None:
            await update.message.reply_text("❌ Error fetching data. Please try again.")
            return

        us_today = _us_market_date().date()

        # Simple market status (avoid extra API call) — use US Eastern time so the
        # status matches the US session regardless of the bot's local timezone.
        now = _us_market_date()
        hour = now.hour
        minute = now.minute
        weekday = now.weekday()

        if weekday >= 5:  # Weekend
            market_status = "🔴 Market Closed (Weekend)"
        elif hour < 9 or (hour == 9 and minute < 30):
            market_status = "🟡 Pre-Market"
        elif hour >= 16:
            market_status = "🟠 After Hours"
        else:
            market_status = "🟢 Market Open"
        
        total_day_change = 0
        total_value = 0
        results = []
        
        for symbol in symbols_list:
            shares = symbol_data[symbol]['shares']

            try:
                current_price, prev_close = quotes.get(symbol, (None, None))

                # Fallback to the daily download when the live quote is unavailable.
                if current_price is None or prev_close is None:
                    hist = None
                    if batch_data is not None and not batch_data.empty:
                        if len(symbols_list) == 1:
                            hist = batch_data
                        elif symbol in batch_data.columns.get_level_values(0):
                            hist = batch_data[symbol]

                    if hist is None or hist.empty:
                        results.append({'symbol': symbol, 'shares': shares, 'error': 'No data'})
                        continue

                    close_col = hist['Close'].dropna()
                    if len(close_col) < 1:
                        results.append({'symbol': symbol, 'shares': shares, 'error': 'No price data'})
                        continue

                    # Use today's bar as current if present, and the session right before
                    # it as previous; otherwise the latest close is the current reference.
                    bar_dates = [idx.date() for idx in close_col.index]
                    current_price = float(close_col.iloc[-1])
                    if bar_dates[-1] == us_today and len(close_col) > 1:
                        prev_close = float(close_col.iloc[-2])
                    else:
                        prev_close = current_price

                # Check for NaN
                if math.isnan(current_price) or math.isnan(prev_close):
                    results.append({'symbol': symbol, 'shares': shares, 'error': 'Invalid data'})
                    continue

                # Calculate daily change.
                # Shares held from before today move from yesterday's close; shares
                # bought TODAY move from their actual purchase price (not the open),
                # since you only owned them from your entry.
                today_shares = symbol_data[symbol].get('today_shares', 0)
                today_cost = symbol_data[symbol].get('today_cost', 0)
                prior_shares = shares - today_shares

                day_change_value = (current_price - prev_close) * prior_shares
                if today_shares:
                    # (current * today_shares) - what you paid for them today
                    day_change_value += (current_price * today_shares) - today_cost

                current_value = current_price * shares

                # Effective reference price so the displayed % reflects the blended
                # basis (yesterday's close for old shares, buy price for today's).
                if shares and (current_value - day_change_value) != 0:
                    effective_ref = (current_value - day_change_value) / shares
                    day_change_pct = ((current_price - effective_ref) / effective_ref) * 100 if effective_ref else 0
                else:
                    day_change_pct = ((current_price - prev_close) / prev_close) * 100 if prev_close != 0 else 0

                total_day_change += day_change_value
                total_value += current_value

                results.append({
                    'symbol': symbol,
                    'shares': shares,
                    'price': current_price,
                    'prev_close': prev_close,
                    'change_pct': day_change_pct,
                    'change_value': day_change_value,
                    'value': current_value,
                    'today_shares': today_shares
                })
            except Exception as e:
                results.append({'symbol': symbol, 'shares': shares, 'error': str(e)})
        
        # Sort by change % (most down to most up)
        results.sort(key=lambda x: x.get('change_pct', 0))
        
        # Get stocks sold today and calculate their intraday P/L (open → sell price)
        sold_today = []
        sold_pl_total = 0
        try:
            sold_history = portfolio_data.get('sold_history', [])
            today_str = _us_market_date().strftime('%Y-%m-%d')
            sold_symbols = []
            sold_entries = []
            for s in sold_history:
                if s.get('sell_date', '').startswith(today_str):
                    sold_symbols.append(s['symbol'])
                    sold_entries.append(s)
            
            if sold_symbols:
                # Fetch open prices for sold stocks
                unique_sold = list(set(sold_symbols))
                try:
                    sold_batch = await asyncio.to_thread(
                        yf.download, unique_sold, period='1d', group_by='ticker', progress=False, threads=True
                    )
                except:
                    sold_batch = None
                
                for s in sold_entries:
                    sym = s['symbol']
                    sell_price = s['sell_price']
                    shares = s['shares']
                    open_price = sell_price  # fallback
                    
                    try:
                        if sold_batch is not None and not sold_batch.empty:
                            if len(unique_sold) == 1:
                                try:
                                    sh = sold_batch[sym]
                                except (KeyError, TypeError):
                                    sh = sold_batch
                            else:
                                sh = sold_batch[sym]
                            if sh is not None and not sh.empty and 'Open' in sh.columns:
                                op = sh['Open'].dropna()
                                if len(op) > 0:
                                    open_price = float(op.iloc[-1])
                    except:
                        pass
                    
                    # Per user's chosen convention: (today's open - sell price) * shares
                    pl = (open_price - sell_price) * shares
                    pl_pct = ((open_price - sell_price) / open_price * 100) if open_price else 0
                    sold_pl_total += pl
                    sold_today.append({
                        'symbol': sym,
                        'shares': shares,
                        'sell_price': sell_price,
                        'open_price': open_price,
                        'pl': pl,
                        'pl_pct': pl_pct
                    })
        except:
            pass
        
        # Build message
        message = f"📊 *TODAY'S PERFORMANCE*\n"
        message += f"📅 {_us_market_date().strftime('%b %d, %Y')}\n"
        message += f"{market_status}\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        for r in results:
            if 'error' in r:
                message += f"*{r['symbol']}* ❌ Error\n\n"
                continue
            
            emoji = "🟢" if r['change_pct'] >= 0 else "🔴"
            arrow = "▲" if r['change_pct'] >= 0 else "▼"
            bought_today_tag = " 🆕" if r.get('today_shares') else ""

            message += f"{emoji} *{r['symbol']}* {arrow} *{r['change_pct']:+.2f}%*{bought_today_tag}\n"
            message += f"   ${r['price']:.2f} | {r['shares']:.0f} shares\n"
            if r.get('today_shares'):
                message += f"   Day P/L: ${r['change_value']:+,.2f} _(from your buy price)_\n\n"
            else:
                message += f"   Day P/L: ${r['change_value']:+,.2f}\n\n"
        
        # Show sold stocks and their intraday P/L
        if sold_today:
            message += "📤 *SOLD TODAY:*\n"
            for st in sold_today:
                s_emoji = "🟢" if st['pl'] >= 0 else "🔴"
                message += f"{s_emoji} *{st['symbol']}* — {st['shares']:.0f} shares @ ${st['sell_price']:.2f}\n"
                message += f"   Open: ${st['open_price']:.2f} → Sold: ${st['sell_price']:.2f}\n"
                message += f"   Day P/L: ${st['pl']:+,.2f} ({st['pl_pct']:+.2f}%)\n\n"
        
        # Calculate rising/falling
        rising_pl = sum(r['change_value'] for r in results if 'error' not in r and r['change_value'] >= 0)
        falling_pl = sum(r['change_value'] for r in results if 'error' not in r and r['change_value'] < 0)
        rising_count = sum(1 for r in results if 'error' not in r and r['change_value'] >= 0)
        falling_count = sum(1 for r in results if 'error' not in r and r['change_value'] < 0)
        
        # Include sold stocks P/L in totals
        total_day_change += sold_pl_total
        
        # Daily totals
        base_value = total_value - total_day_change  # approximate open value
        total_day_pct = (total_day_change / base_value * 100) if base_value > 0 else 0
        day_emoji = "🟢" if total_day_change >= 0 else "🔴"
        
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += f"*DAILY P/L*\n"
        message += f"{day_emoji} *${total_day_change:+,.2f}* ({total_day_pct:+.2f}%)\n"
        message += f"\n🟢 Rising ({rising_count}): *${rising_pl:+,.2f}*\n"
        message += f"🔴 Falling ({falling_count}): *${falling_pl:+,.2f}*\n"
        if sold_today:
            sold_emoji = "🟢" if sold_pl_total >= 0 else "🔴"
            message += f"{sold_emoji} Sold ({len(sold_today)}): *${sold_pl_total:+,.2f}*\n"
            for st in sold_today:
                st_emoji = "🟢" if st['pl'] >= 0 else "🔴"
                message += f"    {st_emoji} {st['symbol']} ({st['shares']:.0f}) ${st['pl']:+,.2f}\n"
        message += f"\n💰 Portfolio: ${total_value:,.2f}"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        return {
            'date': _us_market_date().strftime('%Y-%m-%d'),
            'change_usd': round(total_day_change, 6),
            'change_pct': round(total_day_pct, 6),
            'stocks_value_usd': round(total_value, 6),
            'market_status': market_status,
        }
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _capture_today_performance_for_totallog():
    """Run the exact /today calculation silently and return its final totals."""
    class _SilentMessage:
        async def reply_text(self, *args, **kwargs):
            return None

    class _InternalUser:
        id = ALLOWED_USER_IDS[0]

    class _InternalUpdate:
        effective_user = _InternalUser()
        message = _SilentMessage()

    result = await today(_InternalUpdate(), None)
    if result and str(result.get('market_status', '')).startswith('🔴 Market Closed (Weekend)'):
        # Yahoo quote fields retain Friday's move on weekends. There is no new
        # session, so the real Saturday/Sunday stock move is zero.
        result['change_usd'] = 0.0
        result['change_pct'] = 0.0
    return result


async def today_watchlist(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show today's watchlist performance with daily P/L"""
    await update.message.reply_text("👀 Loading watchlist performance...")
    
    try:
        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        
        if not os.path.exists(watchlist_file):
            await update.message.reply_text("❌ Watchlist file not found!")
            return
        
        with open(watchlist_file, 'r', encoding='utf-8') as f:
            watchlist_data = json.load(f)
        
        # Get active watchlist
        active_name = watchlist_data.get('active_watchlist', 'default')
        watchlists = watchlist_data.get('watchlists', {})
        active_watchlist = watchlists.get(active_name, {})
        stocks = active_watchlist.get('stocks', {})
        watchlist_display_name = active_watchlist.get('name', active_name)
        
        if not stocks:
            await update.message.reply_text("📋 Watchlist is empty!")
            return
        
        # Check market status
        import yfinance as yf
        spy = yf.Ticker("SPY")
        spy_info = spy.info
        market_state = spy_info.get('marketState', 'CLOSED')
        
        if market_state == 'REGULAR':
            market_status = "🟢 Market Open"
        elif market_state in ['PRE', 'PREPRE']:
            market_status = "🟡 Pre-Market"
        elif market_state in ['POST', 'POSTPOST']:
            market_status = "🟠 After Hours"
        else:
            market_status = "🔴 Market Closed"
        
        total_extended_change = 0
        results = []
        
        for symbol in stocks.keys():
            try:
                stock = yf.Ticker(symbol)
                info = stock.info
                hist = stock.history(period='2d')
                
                if not hist.empty and len(hist) >= 1:
                    current_price = hist['Close'].iloc[-1]
                    prev_close = hist['Close'].iloc[-2] if len(hist) > 1 else hist['Open'].iloc[-1]
                    
                    # Calculate daily change
                    day_change_pct = ((current_price - prev_close) / prev_close) * 100
                    
                    result = {
                        'symbol': symbol,
                        'price': current_price,
                        'prev_close': prev_close,
                        'change_pct': day_change_pct
                    }
                    
                    # Get pre-market or after-hours data (use Yahoo's native change %)
                    if market_state in ['PRE', 'PREPRE']:
                        pre_price = info.get('preMarketPrice')
                        pre_change_pct = info.get('preMarketChangePercent', 0) or 0
                        if pre_price and pre_change_pct:
                            result['extended_price'] = pre_price
                            result['extended_change_pct'] = pre_change_pct
                            result['extended_type'] = 'pre'
                    elif market_state in ['POST', 'POSTPOST']:
                        post_price = info.get('postMarketPrice')
                        post_change_pct = info.get('postMarketChangePercent', 0) or 0
                        if post_price and post_change_pct:
                            result['extended_price'] = post_price
                            result['extended_change_pct'] = post_change_pct
                            result['extended_type'] = 'post'
                    elif market_state == 'CLOSED':
                        post_price = info.get('postMarketPrice')
                        post_change_pct = info.get('postMarketChangePercent', 0) or 0
                        if post_price and post_change_pct:
                            result['extended_price'] = post_price
                            result['extended_change_pct'] = post_change_pct
                            result['extended_type'] = 'post'
                    
                    results.append(result)
            except Exception as e:
                results.append({
                    'symbol': symbol,
                    'error': str(e)
                })
        
        # Sort by change % (most down to most up)
        results.sort(key=lambda x: x.get('extended_change_pct', x.get('change_pct', 0)))
        
        # Build message
        from datetime import datetime
        message = f"👀 *{watchlist_display_name.upper()}*\n"
        message += f"📅 {datetime.now().strftime('%b %d, %Y')}\n"
        message += f"{market_status}\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        rising_count = 0
        falling_count = 0
        
        for r in results:
            if 'error' in r:
                message += f"*{r['symbol']}* ❌ Error\n\n"
                continue
            
            # Use extended price change if available, otherwise regular
            if 'extended_change_pct' in r:
                display_pct = r['extended_change_pct']
            else:
                display_pct = r['change_pct']
            
            if display_pct >= 0:
                rising_count += 1
            else:
                falling_count += 1
            
            emoji = "🟢" if display_pct >= 0 else "🔴"
            arrow = "▲" if display_pct >= 0 else "▼"
            
            message += f"{emoji} *{r['symbol']}* {arrow} *{r['change_pct']:+.2f}%*\n"
            message += f"   ${r['price']:.2f}\n"
            
            # Show extended hours data if available
            if 'extended_price' in r:
                ext_arrow = "▲" if r['extended_change_pct'] >= 0 else "▼"
                if r['extended_type'] == 'pre':
                    message += f"   🌅 Pre: ${r['extended_price']:.2f} {ext_arrow} {r['extended_change_pct']:+.2f}%\n"
                else:
                    message += f"   🌙 AH: ${r['extended_price']:.2f} {ext_arrow} {r['extended_change_pct']:+.2f}%\n"
            
            message += "\n"
        
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += f"🟢 Rising: {rising_count} stocks\n"
        message += f"🔴 Falling: {falling_count} stocks\n"
        message += f"📊 Total: {len(results)} watchlist stocks"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def addholding(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Add a stock to portfolio - format: /addholding SYMBOL SHARES AVG_PRICE COMMISSION [note]"""
    user_id = update.effective_user.id
    
    if not is_authorized(user_id):
        await unauthorized_message(update)
        return
    
    if not context.args or len(context.args) < 4:
        # Start conversation flow
        pending_commands[user_id] = 'addholding_symbol'
        context.user_data['pending_command'] = 'addholding_symbol'
        await update.message.reply_text(
            "➕ *Add Stock to Portfolio*\n\n"
            "Enter the stock symbol (e.g. AAPL, NVDA):\n"
            "_(Type 'cancel' to cancel)_",
            parse_mode='Markdown'
        )
        return
    
    # Direct command with all args: /addholding SYMBOL SHARES PRICE COMMISSION [note]
    try:
        symbol = context.args[0].upper()
        shares = float(context.args[1])
        avg_price = float(context.args[2])
        commission = float(context.args[3])
        
        # Optional note - everything after the 4th argument
        note = ' '.join(context.args[4:]) if len(context.args) > 4 else None
        
        context.user_data['buy_pending'] = {'symbol': symbol, 'shares': shares, 'price': avg_price,
                                            'commission': commission, 'note': note}
        await _ask_buy_broker(update.message, context)
    except ValueError:
        await update.message.reply_text("❌ Invalid format.\nUse: /buy SYMBOL SHARES AVG_PRICE COMMISSION [note]\nExample: /buy AAPL 10 150.50 8 Good entry point, strong earnings")


async def _ask_buy_broker(message, context):
    p = context.user_data['buy_pending']
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("🌐 Interactive Brokers", callback_data=f"buybrk:{brk.IBKR}"),
         InlineKeyboardButton("🏦 אפליקציית הבנק", callback_data=f"buybrk:{brk.BANK}")],
        [InlineKeyboardButton("❌ ביטול", callback_data="buybrk:cancel")]])
    await message.reply_text(
        f"🏛 *דרך מה קנית?*\n\n{p['symbol']} · {p['shares']:g} מניות · ${p['price']:,.2f}",
        parse_mode='Markdown', reply_markup=keyboard)


async def buy_broker_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """buybrk:IBKR | buybrk:BANK | buybrk:cancel -- the last question of /buy."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    choice = (query.data or '').split(':')[-1]
    pending = context.user_data.pop('buy_pending', None)
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if choice not in brk.BROKERS or not pending:
        await query.message.reply_text("❌ Buy cancelled." if choice == 'cancel'
                                       else "ℹ️ This buy is no longer pending — send /buy again.")
        return
    await _do_addholding(_ReplyTarget(query.message), pending['symbol'], pending['shares'], pending['price'],
                         pending['commission'], pending.get('note'), broker=choice)


async def _do_addholding(update: Update, symbol: str, shares: float, avg_price: float, commission: float,
                         note: str = None, broker: str = brk.BANK):
    """Execute adding holding to portfolio; `broker` is where it was bought."""
    try:
        portfolio_data = _load_portfolio()
        
        # Verify stock exists
        stock = yf.Ticker(symbol)
        info = stock.info
        stock_name = info.get('shortName', symbol)
        current_price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
        
        if not current_price:
            await update.message.reply_text(f"❌ Could not find stock: {symbol}")
            return
        
        # Calculate total cost
        total_cost = (shares * avg_price) + commission
        
        # Check if symbol already exists
        existing_idx = None
        for i, h in enumerate(portfolio_data['holdings']):
            if h['symbol'] == symbol:
                existing_idx = i
                break
        
        if existing_idx is not None:
            # Update existing position (combine)
            old = portfolio_data['holdings'][existing_idx]
            old_commission = old.get('commission', 0)
            new_shares = old['shares'] + shares
            new_cost = old.get('total_cost', old['shares'] * old.get('purchase_price', 0)) + total_cost
            new_avg = (new_cost - old_commission - commission) / new_shares
            
            # Combine notes if both exist
            old_note = old.get('note', '')
            if note and old_note:
                combined_note = f"{old_note}\n[{datetime.now().strftime('%Y-%m-%d')}] {note}"
            elif note:
                combined_note = f"[{datetime.now().strftime('%Y-%m-%d')}] {note}"
            else:
                combined_note = old_note
            
            portfolio_data['holdings'][existing_idx] = {
                "symbol": symbol,
                "shares": new_shares,
                "purchase_price": round(new_avg, 2),
                "purchase_date": "Combined",
                "commission": old_commission + commission,
                "total_cost": round(new_cost, 2),
                "is_average_price": True,
                "note": combined_note if combined_note else None,
                "brokers": brk.after_buy(old, broker, shares),
            }
            action = "updated"
        else:
            # Add new holding
            new_holding = {
                "symbol": symbol,
                "shares": shares,
                "purchase_price": avg_price,
                "purchase_date": datetime.now().strftime("%Y-%m-%d"),
                "commission": commission,
                "total_cost": round(total_cost, 2),
                "is_average_price": False,
                "note": f"[{datetime.now().strftime('%Y-%m-%d')}] {note}" if note else None,
                "brokers": brk.after_buy(None, broker, shares),
            }
            portfolio_data['holdings'].append(new_holding)
            action = "added"
        
        # Subtract from that broker's cash and log the transaction
        cash_key = brk.CASH_KEY[broker]
        current_cash = portfolio_data.get(cash_key, 0)
        new_cash = max(0, current_cash - total_cost)
        portfolio_data[cash_key] = round(new_cash, 2)

        # Log the stock purchase in cash log with date
        purchase_date = datetime.now().strftime("%Y-%m-%d")
        _log_cash_transaction(
            portfolio_data,
            -total_cost,
            "stock_purchase",
            f"Bought {symbol}" + (" (Interactive)" if broker == brk.IBKR else ""),
            broker=broker,
        )
        
        # Save portfolio
        _save_portfolio(portfolio_data)
        
        # Calculate current P/L
        current_value = current_price * shares
        profit = current_value - total_cost
        profit_pct = (profit / total_cost) * 100
        
        # Build response message
        cash_msg = ""
        if current_cash > 0:
            cash_msg = f"\n💵 Cash ({brk.SHORT[broker]}): ${current_cash:,.2f} → ${new_cash:,.2f}"
        
        note_msg = ""
        if note:
            note_msg = f"\n\n📝 *Note:* _{note}_"
        
        await update.message.reply_text(
            f"✅ *{symbol} {action}!*\n\n"
            f"📊 *{stock_name}*\n"
            f"• Shares: {shares}\n"
            f"• Avg Price: ${avg_price:.2f}\n"
            f"• Commission: ${commission:.2f}\n"
            f"• Total Cost: ${total_cost:.2f}\n"
            f"• Broker: {brk.LABEL[broker]}{cash_msg}\n\n"
            f"💵 Current: ${current_price:.2f}\n"
            f"{'🟢' if profit >= 0 else '🔴'} P/L: ${profit:+,.2f} ({profit_pct:+.1f}%){note_msg}",
            parse_mode='Markdown'
        )
        
        # Track contribution toward financial goals and send notification
        try:
            from telegram.ext import Application as _App
            app = _App.builder().token(TELEGRAM_BOT_TOKEN).build() if not hasattr(update, '_app') else None
            # Use the bot from the context
            class _FakeApp:
                def __init__(self, bot):
                    self.bot = bot
            fake_app = _FakeApp(context.bot)
            await _track_goal_contribution(fake_app, 'buy', symbol, total_cost)
        except Exception as e:
            print(f"Goal tracking after buy error: {e}")
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def stocknotes(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View or edit notes for a stock: /stocknotes [SYMBOL] [new note]"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    portfolio_data = _load_portfolio()
    holdings = portfolio_data.get('holdings', [])
    
    if not holdings:
        await update.message.reply_text("❌ No holdings in portfolio!")
        return
    
    # No args - show all notes
    if not context.args:
        message = "📝 *PORTFOLIO NOTES*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        has_notes = False
        for h in holdings:
            note = h.get('note')
            if note:
                has_notes = True
                message += f"*{h['symbol']}*\n"
                message += f"_{note}_\n\n"
        
        if not has_notes:
            message += "_No notes found._\n\n"
            message += "💡 Add notes when buying:\n"
            message += "`/buy AAPL 10 150 8 Strong earnings expected`"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        return
    
    symbol = context.args[0].upper()
    
    # Find the holding
    holding = next((h for h in holdings if h['symbol'] == symbol), None)
    
    if not holding:
        await update.message.reply_text(f"❌ {symbol} not found in portfolio!")
        return
    
    # Just symbol - show note for that stock
    if len(context.args) == 1:
        note = holding.get('note')
        if note:
            await update.message.reply_text(
                f"📝 *Notes for {symbol}*\n\n_{note}_",
                parse_mode='Markdown'
            )
        else:
            await update.message.reply_text(
                f"📝 No notes for {symbol}\n\n"
                f"Add one: `/stocknotes {symbol} Your note here`",
                parse_mode='Markdown'
            )
        return
    
    # Symbol + new note - update/add note
    new_note = ' '.join(context.args[1:])
    date_prefix = f"[{datetime.now().strftime('%Y-%m-%d')}] "
    
    # Append to existing note or create new
    old_note = holding.get('note', '')
    if old_note:
        holding['note'] = f"{old_note}\n{date_prefix}{new_note}"
    else:
        holding['note'] = f"{date_prefix}{new_note}"
    
    _save_portfolio(portfolio_data)
    
    await update.message.reply_text(
        f"✅ Note added to *{symbol}*\n\n"
        f"📝 _{new_note}_",
        parse_mode='Markdown'
    )


def _load_portfolio():
    """Load portfolio data from file"""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    if os.path.exists(portfolio_file):
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {"free_cash": 0, "cash_log": [], "holdings": []}


def _save_portfolio(portfolio_data):
    """Save portfolio data to file"""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2)


# ============= ISRAELI PORTFOLIO (NIS) =============

def _load_israeli_portfolio():
    """Load Israeli portfolio data from file"""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    print(f"[DEBUG] Loading Israeli portfolio from: {portfolio_file}")
    if os.path.exists(portfolio_file):
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
            # Ensure all required fields exist
            if 'checking_account' not in data:
                data['checking_account'] = 0  # עובר ושב - liquid checking account
            if 'bank_reserves' not in data:
                data['bank_reserves'] = data.get('free_cash', 0)  # Bank savings
            if 'manual_prices' not in data:
                data['manual_prices'] = {}
            print(f"[DEBUG] Loaded: holdings={len(data.get('holdings', []))}, manual_prices={len(data.get('manual_prices', {}))}")
            return data
    return {"free_cash": 0, "checking_account": 0, "bank_reserves": 0, "cash_log": [], "holdings": [], "manual_prices": {}}


def _save_israeli_portfolio(portfolio_data):
    """Save Israeli portfolio data to file"""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    with open(portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2)


def _log_il_cash_transaction(portfolio_data, amount: float, trans_type: str, description: str):
    """Add a transaction to the Israeli portfolio cash log"""
    if 'cash_log' not in portfolio_data:
        portfolio_data['cash_log'] = []
    
    transaction = {
        "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "type": trans_type,
        "amount": amount,
        "description": description,
        "checking_balance": portfolio_data.get('checking_account', 0),
        "bank_balance": portfolio_data.get('bank_reserves', portfolio_data.get('free_cash', 0))
    }
    portfolio_data['cash_log'].append(transaction)


async def ilportfolio(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View Israeli portfolio - shows stocks added via /ilprice"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    try:
        portfolio_data = _load_israeli_portfolio()
        manual_prices = portfolio_data.get('manual_prices', {})
        checking = portfolio_data.get('checking_account', 0)
        try:
            main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
            with open(main_portfolio_file, 'r', encoding='utf-8') as f:
                _main_portfolio = json.load(f)
            bank_reserves = _main_portfolio.get('reserves', {}).get('ILS', 0)
        except Exception:
            bank_reserves = portfolio_data.get('bank_reserves', portfolio_data.get('free_cash', 0))
        
        if not manual_prices and checking == 0 and bank_reserves == 0:
            await update.message.reply_text(
                "🇮🇱 <b>תיק מניות ישראלי</b>\n\n"
                "📋 התיק ריק!\n\n"
                "השתמש ב- /ilprice להוספת מניה",
                parse_mode='HTML'
            )
            return
        
        # Get USD/ILS rate
        try:
            usd_ils = yf.Ticker("USDILS=X").info.get('regularMarketPrice', 3.6)
        except:
            usd_ils = 3.6
        
        total_cost = 0
        total_value = 0
        total_pl_shekel = 0
        stocks_list = []
        
        for name, data in manual_prices.items():
            purchase_shekel = data.get('purchase_price_shekel', 0)
            shares = data.get('shares', 0)
            commission = data.get('commission', 0)
            total_stock_cost = data.get('total_cost', purchase_shekel * shares + commission)
            current_shekel = data.get('current_price_shekel', 0)
            current_agorot = data.get('current_price_agorot', 0)
            current_stock_value = data.get('current_value', current_shekel * shares)
            
            # Always recalculate P/L from value - cost (don't trust stored values)
            pl_shekel = current_stock_value - total_stock_cost
            pl_percent = (pl_shekel / total_stock_cost * 100) if total_stock_cost > 0 else 0
            pl_usd = pl_shekel / usd_ils
            
            # Flag if price is 0 (data fetch failed)
            price_missing = (current_shekel == 0 and total_stock_cost > 0)
            
            updated_at = data.get('updated_at', '')
            
            stocks_list.append({
                'name': name,
                'purchase_shekel': purchase_shekel,
                'shares': shares,
                'commission': commission,
                'total_cost': total_stock_cost,
                'current_shekel': current_shekel,
                'current_agorot': current_agorot,
                'current_value': current_stock_value,
                'pl_shekel': pl_shekel,
                'pl_percent': pl_percent,
                'pl_usd': pl_usd,
                'updated_at': updated_at,
                'price_missing': price_missing
            })
            total_cost += total_stock_cost
            total_value += current_stock_value
        
        # Calculate total P/L directly from totals (not sum of individual P/L)
        total_pl_shekel = total_value - total_cost
        
        # Sort by P/L (losers first)
        stocks_list.sort(key=lambda x: x['pl_shekel'])
        
        total_pl_usd = total_pl_shekel / usd_ils
        total_pl_percent = (total_pl_shekel / total_cost * 100) if total_cost > 0 else 0
        
        # Build message
        msg = "🇮🇱 <b>תיק מניות ישראלי</b>\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        for s in stocks_list:
            emoji = "🟩" if s['pl_shekel'] >= 0 else "🔴"
            commission_line = f"  💳 עמלה: ₪{s['commission']:,.2f}\n" if s['commission'] > 0 else ""
            price_warning = "  ⚠️ <i>מחיר לא זמין!</i>\n" if s['price_missing'] else ""
            msg += f"<b>{s['name']}</b>\n"
            msg += f"  📊 {s['shares']} מניות @ ₪{s['purchase_shekel']:,.2f}\n"
            msg += f"{commission_line}"
            msg += f"  💰 עלות: ₪{s['total_cost']:,.2f}\n"
            msg += f"{price_warning}"
            msg += f"  💵 נוכחי: {s['current_agorot']:,.0f} אג׳ (₪{s['current_shekel']:,.2f})\n"
            msg += f"  💵 שווי: ₪{s['current_value']:,.2f}\n"
            msg += f"  {emoji} רווח/הפסד: ₪{s['pl_shekel']:+,.2f} (${s['pl_usd']:+,.2f})\n"
            msg += f"  {emoji} {s['pl_percent']:+.1f}%\n"
            if s['updated_at']:
                msg += f"  🕐 <i>{s['updated_at']}</i>\n"
            msg += "\n"
        
        msg += "━━━━━━━━━━━━━━━━━━━━\n"
        msg += f"📊 <b>עלות כוללת:</b> ₪{total_cost:,.2f}\n"
        msg += f"💵 <b>שווי נוכחי:</b> ₪{total_value:,.2f}\n\n"
        
        pl_emoji = "🟩" if total_pl_shekel >= 0 else "🔴"
        msg += f"{pl_emoji} <b>סה״כ רווח/הפסד:</b>\n"
        msg += f"{pl_emoji} ₪{total_pl_shekel:+,.2f} (${total_pl_usd:+,.2f})\n"
        msg += f"{pl_emoji} {total_pl_percent:+.1f}%\n\n"
        
        # Show cash accounts
        msg += "━━━━━━━━━━━━━━━━━━━━\n"
        msg += f"💳 <b>עו\"ש:</b> ₪{checking:,.2f}\n"
        msg += f"🏦 <b>בנק:</b> ₪{bank_reserves:,.2f}\n"
        total_liquid = checking + bank_reserves
        total_portfolio = total_value + total_liquid
        msg += f"💰 <b>סה״כ נזיל:</b> ₪{total_liquid:,.2f}\n"
        msg += f"🎯 <b>סה״כ תיק:</b> ₪{total_portfolio:,.2f}\n\n"
        
        msg += f"💵 <b>שער דולר:</b> ₪{usd_ils:.2f}\n"
        msg += f"📊 <b>מניות:</b> {len(stocks_list)}"
        
        await update.message.reply_text(msg, parse_mode='HTML')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def ilbuy(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Add a stock to Israeli portfolio - shows portfolio first"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    user_id = update.effective_user.id
    
    # Clear any stale state from previous operations
    context.user_data.pop('state', None)
    context.user_data.pop('ilbuy', None)
    context.user_data.pop('ilbuy_stocks', None)
    pending_commands.pop(user_id, None)
    
    # If full args provided, execute directly
    if context.args and len(context.args) >= 4:
        try:
            symbol = context.args[0].upper()
            shares = float(context.args[1])
            price = float(context.args[2])
            commission = float(context.args[3])
            await _do_ilbuy(update, symbol, shares, price, commission)
            return
        except ValueError:
            pass
    
    # Load portfolio to show existing stocks
    portfolio_data = _load_israeli_portfolio()
    manual_prices = portfolio_data.get('manual_prices', {})
    holdings = portfolio_data.get('holdings', [])
    
    # Combine all stocks
    all_stocks = {}
    for name, data in manual_prices.items():
        all_stocks[name] = {'source': 'manual', 'data': data}
    for h in holdings:
        symbol = h.get('symbol', h.get('name', ''))
        if symbol not in all_stocks:
            all_stocks[symbol] = {'source': 'holdings', 'data': h}
    
    msg = "🛒 <b>קנייה - תיק ישראלי</b>\n\n"
    
    if all_stocks:
        msg += "<b>המניות שלך:</b>\n"
        stock_list = list(all_stocks.keys())
        for i, name in enumerate(stock_list, 1):
            stock_data = all_stocks[name]
            if stock_data['source'] == 'manual':
                shares = stock_data['data'].get('shares', 0)
                # Handle both formats
                price = stock_data['data'].get('purchase_price_shekel', stock_data['data'].get('buying_price', 0))
            else:
                shares = stock_data['data'].get('shares', 0)
                price = stock_data['data'].get('purchase_price', 0)
            msg += f"{i}. {name} ({shares:.0f} יח׳ @ ₪{price:.2f})\n"
        
        msg += f"\n0. ➕ מניה חדשה\n"
        msg += "\n<b>בחר מספר או הקלד שם מניה חדשה:</b>"
        
        # Store stock list for selection
        context.user_data['ilbuy_stocks'] = stock_list
    else:
        msg += "אין מניות בתיק עדיין.\n\n"
        msg += "<b>הקלד שם/סימול המניה:</b>"
        context.user_data['ilbuy_stocks'] = []
    
    context.user_data['state'] = 'ilbuy_select'
    
    await update.message.reply_text(msg, parse_mode='HTML')


async def _handle_ilbuy_select(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle stock selection for ilbuy"""
    user_input = update.message.text.strip()
    
    if user_input.lower() in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('ilbuy', None)
        context.user_data.pop('ilbuy_stocks', None)
        context.user_data.pop('state', None)
        await update.message.reply_text("❌ הקנייה בוטלה")
        return
    
    stock_list = context.user_data.get('ilbuy_stocks', [])
    
    # Check if number entered
    try:
        num = int(user_input)
        if num == 0:
            # New stock
            context.user_data['state'] = 'ilbuy_symbol'
            await update.message.reply_text(
                "🆕 <b>מניה חדשה</b>\n\nהקלד שם/סימול המניה:",
                parse_mode='HTML'
            )
            return
        elif 1 <= num <= len(stock_list):
            # Selected existing stock
            context.user_data['ilbuy'] = {'symbol': stock_list[num - 1]}
            context.user_data['state'] = 'ilbuy_shares'
            await update.message.reply_text(
                f"📊 <b>{stock_list[num - 1]}</b>\n\nכמה יחידות לקנות?",
                parse_mode='HTML'
            )
            return
    except ValueError:
        pass
    
    # Treat as new stock name
    context.user_data['ilbuy'] = {'symbol': user_input.upper()}
    context.user_data['state'] = 'ilbuy_shares'
    await update.message.reply_text(
        f"📊 <b>{user_input.upper()}</b>\n\nכמה יחידות לקנות?",
        parse_mode='HTML'
    )


