async def _do_ilbuy(update: Update, symbol: str, shares: float, price: float, commission: float):
    """Execute adding holding to Israeli portfolio - checks both holdings and manual_prices"""
    try:
        portfolio_data = _load_israeli_portfolio()
        manual_prices = portfolio_data.get('manual_prices', {})
        
        # Keep original name for Hebrew stocks
        display_name = symbol.strip()
        clean_symbol = symbol.replace('.TA', '').replace(' ', '').upper()
        
        # Try to verify stock exists on TASE
        yahoo_symbol = f"{clean_symbol}.TA"
        stock_verified = False
        current_price = 0
        stock_name = display_name
        
        try:
            stock = yf.Ticker(yahoo_symbol)
            info = stock.info
            current_price_ila = info.get('currentPrice', info.get('regularMarketPrice', 0))
            current_price = current_price_ila / 100 if current_price_ila else 0
            if current_price:
                stock_name = info.get('shortName', display_name)
                stock_verified = True
        except:
            pass
        
        total_cost = (shares * price) + commission
        
        # Check if stock exists in manual_prices (by original name or clean symbol)
        existing_in_manual = None
        for name in manual_prices.keys():
            if name == display_name or name.upper() == display_name.upper() or name.replace(' ', '').upper() == clean_symbol:
                existing_in_manual = name
                break
        
        if existing_in_manual:
            # Update manual_prices entry - handle both old and new formats
            old = manual_prices[existing_in_manual]
            old_shares = old.get('shares', 0)
            # Handle both formats: buying_price (new) or purchase_price_shekel (old)
            old_price = old.get('buying_price', old.get('purchase_price_shekel', 0))
            old_commission = old.get('commission', 0)
            old_total = old.get('total_cost', (old_shares * old_price) + old_commission)
            
            new_shares = old_shares + shares
            new_total = old_total + total_cost
            new_avg = (old_total - old_commission + (shares * price)) / new_shares if new_shares > 0 else price
            
            # Preserve current price and recalculate P/L
            current_agorot = old.get('current_price_agorot', 0)
            current_shekel = old.get('current_price_shekel', 0)
            current_value = current_shekel * new_shares if current_shekel > 0 else 0
            pl_shekel = current_value - new_total if current_value > 0 else 0
            pl_percent = (pl_shekel / new_total * 100) if new_total > 0 and current_value > 0 else 0
            
            # Use purchase_price_shekel format for compatibility
            manual_prices[existing_in_manual] = {
                "purchase_price_shekel": round(new_avg, 2),
                "shares": new_shares,
                "total_cost": round(new_total, 2),
                "current_price_agorot": current_agorot,
                "current_price_shekel": current_shekel,
                "current_value": round(current_value, 2),
                "profit_loss_shekel": round(pl_shekel, 2),
                "pl_percent": round(pl_percent, 2),
                "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M")
            }
            portfolio_data['manual_prices'] = manual_prices
            action = "updated"
            final_name = existing_in_manual
        else:
            # Check holdings array
            existing_idx = None
            for i, h in enumerate(portfolio_data.get('holdings', [])):
                if h.get('symbol') == clean_symbol or h.get('name', '').upper() == display_name.upper():
                    existing_idx = i
                    break
            
            if existing_idx is not None:
                old = portfolio_data['holdings'][existing_idx]
                new_shares = old['shares'] + shares
                new_cost = old['total_cost'] + total_cost
                new_avg = (new_cost - old.get('commission', 0) - commission) / new_shares
                
                portfolio_data['holdings'][existing_idx] = {
                    "symbol": clean_symbol,
                    "name": stock_name,
                    "shares": new_shares,
                    "purchase_price": round(new_avg, 2),
                    "purchase_date": "Combined",
                    "commission": old.get('commission', 0) + commission,
                    "total_cost": round(new_cost, 2),
                    "verified": stock_verified
                }
                action = "updated"
                final_name = stock_name
            else:
                # Add to manual_prices (default for new stocks) - use compatible format
                manual_prices[display_name] = {
                    "purchase_price_shekel": price,
                    "shares": shares,
                    "total_cost": round(total_cost, 2),
                    "current_price_agorot": 0,
                    "current_price_shekel": 0,
                    "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M")
                }
                portfolio_data['manual_prices'] = manual_prices
                action = "added"
                final_name = display_name
        
        _save_israeli_portfolio(portfolio_data)
        
        # Deduct from עו"ש (ILS_checking in my_portfolio.json)
        main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        with open(main_portfolio_file, 'r', encoding='utf-8') as f:
            main_portfolio = json.load(f)
        
        reserves = main_portfolio.get('reserves', {})
        checking = reserves.get('ILS_checking', 0)
        new_checking = max(0, checking - total_cost)
        reserves['ILS_checking'] = round(new_checking, 2)
        main_portfolio['reserves'] = reserves
        
        with open(main_portfolio_file, 'w', encoding='utf-8') as f:
            json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
        
        # Log to checking_log
        _log_ils_checking_transaction(total_cost, "spend", f"קנייה: {final_name} ({shares:.0f} יח׳)", new_checking)
        
        cash_msg = ""
        if checking > 0:
            cash_msg = f"\n💳 עו\"ש: ₪{checking:,.2f} → ₪{new_checking:,.2f}"
        
        if stock_verified and current_price > 0:
            current_value = current_price * shares
            profit = current_value - total_cost
            profit_pct = (profit / total_cost) * 100 if total_cost > 0 else 0
            
            await update.message.reply_text(
                f"✅ <b>{final_name} {action}!</b>\n\n"
                f"🇮🇱 <b>{stock_name}</b>\n"
                f"• יחידות: {shares:.0f}\n"
                f"• מחיר: ₪{price:.2f}\n"
                f"• עמלה: ₪{commission:.2f}\n"
                f"• עלות: ₪{total_cost:.2f}{cash_msg}\n\n"
                f"💵 נוכחי: ₪{current_price:.2f}\n"
                f"{'🟩' if profit >= 0 else '🔴'} רווח: ₪{profit:+,.2f} ({profit_pct:+.1f}%)",
                parse_mode='HTML'
            )
        else:
            await update.message.reply_text(
                f"✅ <b>{final_name} {action}!</b>\n\n"
                f"🇮🇱 <b>{display_name}</b>\n"
                f"• יחידות: {shares:.0f}\n"
                f"• מחיר: ₪{price:.2f}\n"
                f"• עמלה: ₪{commission:.2f}\n"
                f"• עלות: ₪{total_cost:.2f}{cash_msg}",
                parse_mode='HTML'
            )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _do_ilbuy_simple(update: Update, name: str, total_value: float, commission: float):
    """Add unverified holding to Israeli portfolio (just name, value, commission)"""
    try:
        portfolio_data = _load_israeli_portfolio()
        
        display_name = name.strip()
        # Create a simple symbol from name (no spaces)
        clean_symbol = name.replace(' ', '').upper()[:20]  # Limit length
        
        total_cost = total_value + commission
        
        # Check if already exists
        existing_idx = None
        for i, h in enumerate(portfolio_data['holdings']):
            if h['symbol'] == clean_symbol:
                existing_idx = i
                break
        
        if existing_idx is not None:
            old = portfolio_data['holdings'][existing_idx]
            new_cost = old['total_cost'] + total_cost
            new_commission = old.get('commission', 0) + commission
            
            portfolio_data['holdings'][existing_idx] = {
                "symbol": clean_symbol,
                "name": display_name,
                "shares": 0,  # No shares for unverified
                "purchase_price": 0,
                "purchase_date": "Combined",
                "commission": new_commission,
                "total_cost": round(new_cost, 2),
                "verified": False
            }
            action = "updated"
        else:
            new_holding = {
                "symbol": clean_symbol,
                "name": display_name,
                "shares": 0,
                "purchase_price": 0,
                "purchase_date": datetime.now().strftime("%Y-%m-%d"),
                "commission": commission,
                "total_cost": round(total_cost, 2),
                "verified": False
            }
            portfolio_data['holdings'].append(new_holding)
            action = "added"
        
        # Deduct from bank reserves (not checking account)
        current_bank = portfolio_data.get('bank_reserves', portfolio_data.get('free_cash', 0))
        new_bank = max(0, current_bank - total_cost)
        portfolio_data['bank_reserves'] = round(new_bank, 2)
        
        _log_il_cash_transaction(portfolio_data, -total_cost, "stock_purchase", f"Bought {clean_symbol} from Bank")
        _save_israeli_portfolio(portfolio_data)
        
        cash_msg = ""
        if current_bank > 0:
            cash_msg = f"\n🏦 Bank: ₪{current_bank:,.2f} → ₪{new_bank:,.2f}"
        
        await update.message.reply_text(
            f"✅ <b>{action.upper()}!</b>\n\n"
            f"🇮🇱 <b>{display_name}</b>\n"
            f"• Value: ₪{total_value:,.2f}\n"
            f"• Commission: ₪{commission:.2f}\n"
            f"• Total: ₪{total_cost:,.2f}{cash_msg}",
            parse_mode='HTML'
        )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def ilsell(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Sell stock from Israeli portfolio - shows all stocks with inline buttons"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    # Load portfolio directly from file
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    
    try:
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
    except Exception as e:
        await update.message.reply_text(f"❌ Error loading portfolio: {str(e)}")
        return
    
    holdings = portfolio_data.get('holdings', [])
    manual_prices = portfolio_data.get('manual_prices', {})
    
    # Build list of all stocks
    all_stocks = []
    
    for h in holdings:
        all_stocks.append({
            'name': h.get('symbol', h.get('name', 'Unknown')),
            'shares': h.get('shares', 0),
            'source': 'holdings'
        })
    
    for name, data in manual_prices.items():
        all_stocks.append({
            'name': name,
            'shares': data.get('shares', 0),
            'source': 'manual_prices'
        })
    
    if not all_stocks:
        await update.message.reply_text(
            "🇮🇱 <b>אין מניות בתיק הישראלי</b>\n\n"
            "השתמש ב- /ilprice להוספת מניות",
            parse_mode='HTML'
        )
        return
    
    # If called with full args: /ilsell "stock name" shares price commission
    if context.args and len(context.args) >= 4:
        # Join first args for stock name if needed (for Hebrew names with spaces)
        try:
            # Try to find the stock by first arg
            stock_name = context.args[0]
            shares = float(context.args[1])
            price = float(context.args[2])
            commission = float(context.args[3])
            await _execute_ilsell(update, stock_name, shares, price, commission)
            return
        except:
            pass
    
    # Show all stocks
    msg = "🇮🇱 <b>מכירת מניה ישראלית</b>\n\n"
    msg += "<b>המניות שלך:</b>\n"
    
    for i, stock in enumerate(all_stocks, 1):
        msg += f"{i}. <b>{stock['name']}</b>: {stock['shares']} מניות\n"
    
    msg += "\n📝 לשימוש:\n"
    msg += "/ilsell [מספר] [כמות] [מחיר] [עמלה]\n"
    msg += "לדוגמה: /ilsell 1 100 3.50 25\n\n"
    msg += "או שלח את שם המניה ואפשר להמשיך משם"
    
    # Store stocks list for later use
    context.user_data['ilsell_stocks'] = all_stocks
    context.user_data['state'] = 'ilsell_select'
    
    await update.message.reply_text(msg, parse_mode='HTML')


async def _execute_ilsell(update: Update, stock_identifier: str, shares: float, price: float, commission: float):
    """Execute the sell operation for Israeli portfolio"""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    
    try:
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")
        return
    
    holdings = portfolio_data.get('holdings', [])
    manual_prices = portfolio_data.get('manual_prices', {})
    
    # Try to find by number first
    all_stocks = []
    for h in holdings:
        all_stocks.append({'name': h.get('symbol', ''), 'source': 'holdings', 'data': h})
    for name, data in manual_prices.items():
        all_stocks.append({'name': name, 'source': 'manual_prices', 'data': data})
    
    found_stock = None
    found_name = None
    
    # Check if identifier is a number
    try:
        idx = int(stock_identifier) - 1
        if 0 <= idx < len(all_stocks):
            found_stock = all_stocks[idx]
            found_name = found_stock['name']
    except ValueError:
        # Not a number, search by name
        for stock in all_stocks:
            if stock_identifier.lower() in stock['name'].lower() or stock['name'].lower() in stock_identifier.lower():
                found_stock = stock
                found_name = stock['name']
                break
    
    if not found_stock:
        await update.message.reply_text(f"❌ לא נמצאה מניה: {stock_identifier}")
        return
    
    # Get stock details
    if found_stock['source'] == 'manual_prices':
        stock_data = found_stock['data']
        current_shares = stock_data.get('shares', 0)
        purchase_price = stock_data.get('purchase_price_shekel', 0)
        total_cost = stock_data.get('total_cost', purchase_price * current_shares)
    else:
        stock_data = found_stock['data']
        current_shares = stock_data.get('shares', 0)
        purchase_price = stock_data.get('purchase_price', 0)
        total_cost = stock_data.get('total_cost', purchase_price * current_shares)
    
    if shares > current_shares:
        await update.message.reply_text(f"❌ יש לך רק {current_shares} מניות, לא ניתן למכור {shares}")
        return
    
    # Calculate
    proceeds = (shares * price) - commission
    cost_per_share = purchase_price
    cost_basis = shares * cost_per_share
    profit_loss = proceeds - cost_basis
    profit_pct = (profit_loss / cost_basis * 100) if cost_basis > 0 else 0
    
    # Update portfolio
    if found_stock['source'] == 'manual_prices':
        if shares >= current_shares:
            del portfolio_data['manual_prices'][found_name]
        else:
            remaining = current_shares - shares
            portfolio_data['manual_prices'][found_name]['shares'] = remaining
            portfolio_data['manual_prices'][found_name]['total_cost'] = remaining * cost_per_share
    else:
        # Find in holdings
        for i, h in enumerate(holdings):
            if h.get('symbol', '') == found_name:
                if shares >= current_shares:
                    portfolio_data['holdings'].pop(i)
                else:
                    remaining = current_shares - shares
                    portfolio_data['holdings'][i]['shares'] = remaining
                    portfolio_data['holdings'][i]['total_cost'] = remaining * cost_per_share
                break
    
    # Add to עו"ש in main portfolio (ILS_checking)
    main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(main_portfolio_file, 'r', encoding='utf-8') as f:
        main_portfolio = json.load(f)
    
    reserves = main_portfolio.get('reserves', {})
    current_checking = reserves.get('ILS_checking', 0)
    new_checking = current_checking + proceeds
    reserves['ILS_checking'] = round(new_checking, 2)
    main_portfolio['reserves'] = reserves
    
    with open(main_portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
    
    # Log to cash_log in israeli_portfolio
    if 'cash_log' not in portfolio_data:
        portfolio_data['cash_log'] = []
    portfolio_data['cash_log'].append({
        "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "type": "stock_sale",
        "amount": proceeds,
        "description": f"מכירת {found_name} → עו\"ש"
    })
    
    with open(portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2, ensure_ascii=False)
    
    # Log to checking_log for /illog
    _log_ils_checking_transaction(proceeds, "deposit", f"מכירה: {found_name} ({shares:.0f} יח׳)", new_checking)
    
    emoji = "🟩" if profit_loss >= 0 else "🔴"
    
    await update.message.reply_text(
        f"✅ <b>נמכר: {found_name}!</b>\n\n"
        f"📊 מניות: {shares}\n"
        f"💵 מחיר מכירה: ₪{price:.2f}\n"
        f"📋 עמלה: ₪{commission:.2f}\n"
        f"💰 תקבולים: ₪{proceeds:,.2f}\n\n"
        f"📊 עלות: ₪{cost_basis:,.2f}\n"
        f"{emoji} <b>רווח/הפסד: ₪{profit_loss:+,.2f} ({profit_pct:+.1f}%)</b>\n\n"
        f"💳 עו\"ש: ₪{current_checking:,.2f} → ₪{new_checking:,.2f}",
        parse_mode='HTML'
    )


async def _handle_ilsell_select(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle stock selection for ilsell"""
    user_input = update.message.text.strip()
    stock_list = context.user_data.get('ilsell_stocks', [])
    
    found_stock = None
    
    # Check if number entered
    try:
        num = int(user_input)
        if 1 <= num <= len(stock_list):
            found_stock = stock_list[num - 1]
    except ValueError:
        # Search by name
        for stock in stock_list:
            if user_input.lower() in stock['name'].lower() or stock['name'].lower() in user_input.lower():
                found_stock = stock
                break
    
    if not found_stock:
        await update.message.reply_text(f"❌ לא נמצאה מניה: {user_input}")
        return
    
    # Store selection and ask for shares
    context.user_data['ilsell'] = {
        'stock_name': found_stock['name'],
        'available_shares': found_stock['shares'],
        'source': found_stock['source']
    }
    context.user_data['state'] = 'ilsell_shares'
    
    await update.message.reply_text(
        f"📊 <b>{found_stock['name']}</b>\n"
        f"יש לך: {found_stock['shares']:.0f} מניות\n\n"
        f"כמה מניות למכור?",
        parse_mode='HTML'
    )


async def _handle_ilsell_shares(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle shares input for ilsell"""
    try:
        shares = float(update.message.text.replace(',', '').strip())
        available = context.user_data['ilsell'].get('available_shares', 0)
        
        if shares <= 0:
            await update.message.reply_text("❌ מספר מניות חייב להיות חיובי")
            return
        
        if shares > available:
            await update.message.reply_text(f"❌ יש לך רק {available:.0f} מניות")
            return
        
        context.user_data['ilsell']['shares'] = shares
        context.user_data['state'] = 'ilsell_price'
        
        stock_name = context.user_data['ilsell'].get('stock_name', '')
        await update.message.reply_text(
            f"📊 <b>{stock_name}</b> - מוכר {shares:.0f} מניות\n\n"
            f"מה מחיר המכירה ליחידה? (₪)",
            parse_mode='HTML'
        )
    except ValueError:
        await update.message.reply_text("❌ מספר לא תקין")


async def _handle_ilsell_price(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle price input for ilsell"""
    try:
        price = float(update.message.text.replace(',', '').replace('₪', '').strip())
        if price <= 0:
            await update.message.reply_text("❌ מחיר חייב להיות חיובי")
            return
        
        context.user_data['ilsell']['price'] = price
        context.user_data['state'] = 'ilsell_commission'
        
        stock_name = context.user_data['ilsell'].get('stock_name', '')
        shares = context.user_data['ilsell'].get('shares', 0)
        total = shares * price
        await update.message.reply_text(
            f"📊 <b>{stock_name}</b> - {shares:.0f} מניות @ ₪{price:.2f}\n"
            f"💰 סה״כ לפני עמלה: ₪{total:,.2f}\n\n"
            f"כמה עמלה? (₪)",
            parse_mode='HTML'
        )
    except ValueError:
        await update.message.reply_text("❌ מחיר לא תקין")


async def _handle_ilsell_commission(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle commission input for ilsell and execute the sell"""
    try:
        commission = float(update.message.text.replace(',', '').replace('₪', '').strip())
        if commission < 0:
            await update.message.reply_text("❌ עמלה לא יכולה להיות שלילית")
            return
        
        stock_name = context.user_data['ilsell'].get('stock_name', '')
        shares = context.user_data['ilsell'].get('shares', 0)
        price = context.user_data['ilsell'].get('price', 0)
        
        # Clear state
        context.user_data.pop('ilsell', None)
        context.user_data.pop('ilsell_stocks', None)
        context.user_data.pop('state', None)
        
        # Execute the sell
        await _execute_ilsell(update, stock_name, shares, price, commission)
        
    except ValueError:
        await update.message.reply_text("❌ עמלה לא תקינה")


async def ilcash(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View and manage Israeli portfolio cash accounts"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    user_id = update.effective_user.id
    
    # Read REAL balances from my_portfolio.json reserves (single source of truth)
    main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    try:
        with open(main_portfolio_file, 'r', encoding='utf-8') as f:
            main_portfolio = json.load(f)
    except:
        main_portfolio = {}
    reserves = main_portfolio.get('reserves', {})
    checking = reserves.get('ILS_checking', 0)
    bank_reserves = reserves.get('ILS', 0)
    
    # Get transaction history from checking_log (comprehensive)
    portfolio_data = _load_israeli_portfolio()
    checking_log = portfolio_data.get('checking_log', [])
    recent = checking_log[-10:] if checking_log else []
    
    if not context.args:
        # Show all cash accounts
        msg = f"🇮🇱 <b>Israeli Portfolio Cash</b>\n\n"
        msg += f"💳 <b>Checking (עו\"ש):</b> {ex.money(checking)}\n"
        if ex.overdraft_line(checking):
            msg += ex.overdraft_line(checking) + "\n"
        msg += f"🏦 <b>Bank Reserves:</b> ₪{bank_reserves:,.2f}\n"
        msg += f"💰 <b>Total:</b> ₪{checking + bank_reserves:,.2f}\n\n"
        
        if recent:
            msg += "📜 <b>Recent Activity:</b>\n"
            for t in reversed(recent):
                amt = t.get('amount', 0)
                t_type = t.get('type', '')
                if t_type in ('spend', 'reserve_to_bank', 'investment'):
                    emoji = "🔴"
                    display_amt = f"₪{amt:,.2f}-"
                elif t_type in ('deposit', 'reserve_deposit', 'savings_refund', 'savings_withdraw'):
                    emoji = "🟢"
                    display_amt = f"₪{amt:,.2f}+"
                else:
                    emoji = "🟢" if amt > 0 else "🔴"
                    display_amt = f"₪{abs(amt):,.2f}"
                date_str = t.get('date', '')[:10]
                note = t.get('note', t.get('description', ''))
                msg += f"{emoji} {date_str}: {display_amt}\n"
                msg += f"   <i>{note}</i>\n"
        
        msg += "\n📌 <b>Commands:</b>\n"
        msg += "/ilcash bank AMOUNT - Add to bank reserves\n"
        msg += "/ilcash check AMOUNT - Add to checking\n"
        msg += "/ilcash transfer AMOUNT - Bank → Checking\n"
        msg += "/ilcash all - View ALL transactions since day 1"
        
        await update.message.reply_text(msg, parse_mode='HTML')
        return
    
    try:
        # Parse command: /ilcash bank 5000 OR /ilcash check 1000 OR /ilcash transfer 500
        cmd = context.args[0].lower()
        
        if cmd == 'all':
            # Show FULL transaction history
            all_log = checking_log  # already loaded above
            if not all_log:
                await update.message.reply_text("📭 No transactions yet.")
                return
            
            # Build full report
            msgs = []
            current_msg = f"📋 <b>Full Transaction History ({len(all_log)} transactions)</b>\n"
            current_msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
            
            for i, t in enumerate(all_log, 1):
                amt = t.get('amount', 0)
                t_type = t.get('type', '')
                date_str = t.get('date', '')[:10]
                time_str = t.get('time', '')
                note = t.get('note', t.get('description', ''))
                bal = t.get('balance_after', 0)
                
                if t_type in ('spend', 'reserve_to_bank', 'investment'):
                    emoji = "🔴"
                    display_amt = f"₪{amt:,.2f}-"
                elif t_type in ('deposit', 'reserve_deposit', 'savings_refund', 'savings_withdraw'):
                    emoji = "🟢"
                    display_amt = f"₪{amt:,.2f}+"
                else:
                    emoji = "🟢" if amt > 0 else "🔴"
                    display_amt = f"₪{abs(amt):,.2f}"
                
                line = f"{emoji} <b>{i}.</b> {date_str} {time_str} | {display_amt}\n   <i>{note}</i> | bal: ₪{bal:,.2f}\n\n"
                
                if len(current_msg) + len(line) > 3800:
                    msgs.append(current_msg)
                    current_msg = line
                else:
                    current_msg += line
            
            if current_msg.strip():
                msgs.append(current_msg)
            
            # Add summary at the end
            total_deposits = sum(t.get('amount', 0) for t in all_log if t.get('type') in ('deposit', 'reserve_deposit'))
            total_spending = sum(t.get('amount', 0) for t in all_log if t.get('type') == 'spend')
            total_stock_buys = sum(t.get('amount', 0) for t in all_log if t.get('type') == 'spend' and 'קנייה' in t.get('note', ''))
            total_stock_sales = sum(t.get('amount', 0) for t in all_log if t.get('type') == 'deposit' and 'מכירה' in t.get('note', ''))
            total_to_bank = sum(t.get('amount', 0) for t in all_log if t.get('type') == 'reserve_to_bank')
            
            summary = f"\n━━━━━━━━━━━━━━━━━━━━\n"
            summary += f"📊 <b>Summary</b>\n"
            summary += f"🟢 Total deposits to עו\"ש: ₪{total_deposits:,.2f}\n"
            summary += f"🔴 Total spending: ₪{total_spending:,.2f}\n"
            summary += f"📈 Stock purchases: ₪{total_stock_buys:,.2f}\n"
            summary += f"📉 Stock sales: ₪{total_stock_sales:,.2f}\n"
            summary += f"🏦 Transfers to bank: ₪{total_to_bank:,.2f}\n"
            summary += f"\n💳 Current עו\"ש: ₪{checking:,.2f}\n"
            summary += f"🏦 Current Bank: ₪{bank_reserves:,.2f}"
            
            if len(msgs[-1]) + len(summary) > 4000:
                msgs.append(summary)
            else:
                msgs[-1] += summary
            
            for m in msgs:
                try:
                    await update.message.reply_text(m, parse_mode='HTML')
                except Exception:
                    await update.message.reply_text(m)
            return
        
        if cmd in ['bank', 'check', 'checking', 'transfer'] and len(context.args) >= 2:
            amount_str = context.args[1].replace('₪', '').replace(',', '')
            amount = float(amount_str)
            
            if cmd == 'bank':
                # Add to bank reserves, less the flat transfer fee
                bank_fee = bf.fee_for(amount)
                new_bank = round(bank_reserves + amount - bank_fee, 2)
                if bank_fee:
                    bf.append(main_portfolio, bf.DEPOSIT if amount > 0 else bf.WITHDRAW,
                              amount, "/ilcash bank")
                if new_bank < 0:
                    await update.message.reply_text(f"❌ Not enough in bank. Current: ₪{bank_reserves:,.2f}")
                    return
                reserves['ILS'] = round(new_bank, 2)
                trans_type = "deposit" if amount > 0 else "withdrawal"
                reserves.setdefault('log', []).append({
                    'date': datetime.now().strftime("%Y-%m-%d %H:%M"),
                    'currency': 'ILS',
                    'type': 'BANK',
                    'amount': amount,
                    'description': f"ILS bank {trans_type} via /ilcash",
                    'balance_after': new_bank,
                })
                main_portfolio['reserves'] = reserves
                with open(main_portfolio_file, 'w', encoding='utf-8') as f:
                    json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
                emoji = "🟢" if amount > 0 else "🔴"
                await update.message.reply_text(
                    f"✅ <b>Bank {trans_type.title()}!</b>\n\n"
                    f"{emoji} Amount: ₪{abs(amount):,.2f}\n"
                    f"🏦 Bank: ₪{bank_reserves:,.2f} → ₪{new_bank:,.2f}",
                    parse_mode='HTML'
                )
                
            elif cmd in ['check', 'checking']:
                # Add to checking account
                new_checking = checking + amount
                if new_checking < -ex.OVERDRAFT_LIMIT - 0.005:
                    await update.message.reply_text(ex.over_limit_text(checking, abs(amount)))
                    return
                reserves['ILS_checking'] = round(new_checking, 2)
                main_portfolio['reserves'] = reserves
                with open(main_portfolio_file, 'w', encoding='utf-8') as f:
                    json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
                trans_type = "deposit" if amount > 0 else "withdrawal"
                _log_ils_checking_transaction(amount, trans_type, f"Checking {trans_type}", new_checking)
                emoji = "🟢" if amount > 0 else "🔴"
                await update.message.reply_text(
                    f"✅ <b>Checking {trans_type.title()}!</b>\n\n"
                    f"{emoji} Amount: ₪{abs(amount):,.2f}\n"
                    f"💳 Checking: ₪{checking:,.2f} → ₪{new_checking:,.2f}",
                    parse_mode='HTML'
                )
                
            elif cmd == 'transfer':
                # Transfer from bank to checking
                if amount > bank_reserves:
                    await update.message.reply_text(f"❌ Not enough in bank. Current: ₪{bank_reserves:,.2f}")
                    return
                bank_fee = bf.fee_for(amount)
                new_bank = round(bank_reserves - amount, 2)
                new_checking = round(checking + amount - bank_fee, 2)
                reserves['ILS'] = new_bank
                reserves['ILS_checking'] = new_checking
                if bank_fee:
                    bf.append(main_portfolio, bf.WITHDRAW, amount, "/ilcash transfer")
                reserves.setdefault('log', []).append({
                    'date': datetime.now().strftime("%Y-%m-%d %H:%M"),
                    'currency': 'ILS',
                    'type': 'TRANSFER',
                    'amount': amount,
                    'description': f"Transfer from ILS bank reserve to checking via /ilcash",
                    'balance_after': new_checking,
                    'bank_after': new_bank,
                })
                main_portfolio['reserves'] = reserves
                with open(main_portfolio_file, 'w', encoding='utf-8') as f:
                    json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
                _log_ils_checking_transaction(amount, "reserve_deposit", "העברה מבנק לעו\"ש", new_checking)
                await update.message.reply_text(
                    f"✅ <b>Transferred!</b>\n\n"
                    f"💸 Amount: ₪{amount:,.2f}\n\n"
                    f"🏦 Bank: ₪{bank_reserves:,.2f} → ₪{new_bank:,.2f}\n"
                    f"💳 Checking: ₪{checking:,.2f} → ₪{new_checking:,.2f}",
                    parse_mode='HTML'
                )
        else:
            # Legacy: just amount - add to bank reserves
            amount_str = context.args[0].replace('₪', '').replace(',', '')
            amount = float(amount_str)
            bank_fee = bf.fee_for(amount)
            new_bank = round(bank_reserves + amount - bank_fee, 2)
            if bank_fee:
                bf.append(main_portfolio, bf.DEPOSIT if amount > 0 else bf.WITHDRAW, amount, "/ilcash")
            if new_bank < 0:
                await update.message.reply_text(f"❌ Not enough in bank. Current: ₪{bank_reserves:,.2f}")
                return
            reserves['ILS'] = round(new_bank, 2)
            trans_type = "deposit" if amount > 0 else "withdrawal"
            reserves.setdefault('log', []).append({
                'date': datetime.now().strftime("%Y-%m-%d %H:%M"),
                'currency': 'ILS',
                'type': 'BANK',
                'amount': amount,
                'description': f"ILS bank {trans_type} via /ilcash",
                'balance_after': new_bank,
            })
            main_portfolio['reserves'] = reserves
            with open(main_portfolio_file, 'w', encoding='utf-8') as f:
                json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
            emoji = "🟢" if amount > 0 else "🔴"
            await update.message.reply_text(
                f"✅ <b>Bank {trans_type.title()}!</b>\n\n"
                f"{emoji} Amount: ₪{abs(amount):,.2f}\n"
                f"🏦 Bank: ₪{bank_reserves:,.2f} → ₪{new_bank:,.2f}",
                parse_mode='HTML'
            )
            
    except ValueError:
        await update.message.reply_text(
            "❌ Invalid format.\n\n"
            "Use:\n"
            "/ilcash bank 5000 - Add to bank\n"
            "/ilcash check 1000 - Add to checking\n"
            "/ilcash transfer 500 - Bank → Checking"
        )


async def ildeposit(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Deposit money to עו\"ש (checking account) - tracks deposits"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    try:
        # Load main portfolio for current balance
        main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        try:
            with open(main_portfolio_file, 'r', encoding='utf-8') as f:
                main_portfolio = json.load(f)
        except:
            main_portfolio = {}
        
        reserves = main_portfolio.get('reserves', {})
        checking = reserves.get('ILS_checking', 0)
        
        # Start interactive flow
        context.user_data['ildeposit'] = {}
        context.user_data['state'] = 'ildeposit_amount'
        
        await update.message.reply_text(
            f"💰 <b>הפקדה לעוש</b>\n\n"
            f"יתרה נוכחית: <b>₪{checking:,.2f}</b>\n\n"
            f"כמה להפקיד? (שלח סכום)",
            parse_mode='HTML'
        )
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _handle_ildeposit_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle amount input for ildeposit"""
    try:
        amount_str = update.message.text.replace(',', '').replace('₪', '').strip()
        amount = float(amount_str)
        
        if amount <= 0:
            await update.message.reply_text("❌ הסכום חייב להיות חיובי")
            return
        
        context.user_data['ildeposit']['amount'] = amount
        context.user_data['state'] = 'ildeposit_note'
        
        await update.message.reply_text(
            f"💰 סכום: <b>₪{amount:,.2f}</b>\n\n"
            f"מאיפה הכסף? (הערה קצרה)",
            parse_mode='HTML'
        )
        
    except ValueError:
        await update.message.reply_text("❌ סכום לא תקין. שלח מספר.")


async def _handle_ildeposit_note(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle note input for ildeposit"""
    note = update.message.text.strip()
    
    if not note:
        await update.message.reply_text("❌ שלח הערה על ההפקדה")
        return
    
    amount = context.user_data['ildeposit'].get('amount', 0)
    
    # Load and update main portfolio
    main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(main_portfolio_file, 'r', encoding='utf-8') as f:
        main_portfolio = json.load(f)
    
    reserves = main_portfolio.get('reserves', {})
    checking = reserves.get('ILS_checking', 0)
    new_checking = checking + amount
    reserves['ILS_checking'] = round(new_checking, 2)
    main_portfolio['reserves'] = reserves
    
    # Save main portfolio
    with open(main_portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
    
    # Log to israeli portfolio deposit log
    _log_ils_checking_transaction(amount, "deposit", note, new_checking)
    
    # Clear state
    context.user_data.pop('ildeposit', None)
    context.user_data.pop('state', None)
    
    await update.message.reply_text(
        f"✅ <b>הפקדה נרשמה!</b>\n\n"
        f"💰 סכום: ₪{amount:,.2f}\n"
        f"📝 הערה: {note}\n"
        f"📅 תאריך: {datetime.now().strftime('%Y-%m-%d %H:%M')}\n\n"
        f"💳 עו\"ש: ₪{checking:,.2f} → ₪{new_checking:,.2f}",
        parse_mode='HTML'
    )


def _log_reserve_transaction(command: str, amount: float, currency: str, from_account: str, to_account: str, note: str = ""):
    """Log a reserve transaction to reserve_transactions.json"""
    log_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reserve_transactions.json")
    try:
        with open(log_file, 'r', encoding='utf-8') as f:
            transactions = json.load(f)
    except:
        transactions = []
    
    transactions.append({
        'date': datetime.now().strftime("%Y-%m-%d"),
        'time': datetime.now().strftime("%H:%M"),
        'command': command,
        'amount': amount,
        'currency': currency,
        'from': from_account,
        'to': to_account,
        'note': note
    })
    
    with open(log_file, 'w', encoding='utf-8') as f:
        json.dump(transactions, f, indent=2, ensure_ascii=False)


def _log_ils_checking_transaction(amount: float, trans_type: str, note: str, balance_after: float):
    """Log a transaction to the עו\"ש (ILS_checking) history in israeli_portfolio.json"""
    il_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    try:
        with open(il_portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
    except:
        portfolio_data = {}
    
    if 'checking_log' not in portfolio_data:
        portfolio_data['checking_log'] = []
    
    transaction = {
        "date": datetime.now().strftime("%Y-%m-%d"),
        "time": datetime.now().strftime("%H:%M"),
        "type": trans_type,  # "deposit" or "spend" or "reserve_deposit"
        "amount": amount,
        "note": note,
        "balance_after": round(balance_after, 2)
    }
    portfolio_data['checking_log'].append(transaction)
    
    with open(il_portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2, ensure_ascii=False)


async def receipt_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/receipt - send a photo (or PDF) of a receipt next; it is read and logged."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    context.user_data['state'] = 'receipt_photo'
    await update.message.reply_text(
        "📸 *שלח צילום של החשבונית* (או קובץ PDF)\n\n"
        "אסרוק את הפריטים, המחירים, המחיר לק\"ג, המע\"מ והסה\"כ, ואז אשאל איך שילמת.\n"
        "_cancel לביטול · עלות סריקה ≈ $0.03–0.08_", parse_mode='Markdown')


async def receipt_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A photo or an image/PDF file. Read as a receipt when one was asked for
    (/receipt, or during /ilspend), otherwise offer to."""
    if not is_authorized(update.effective_user.id):
        return
    message = update.message
    if message.photo:
        file_id, media_type = message.photo[-1].file_id, 'image/jpeg'
    elif message.document and (message.document.mime_type or '').startswith(('image/', 'application/pdf')):
        file_id = message.document.file_id
        media_type = message.document.mime_type or rcp.media_type_of(message.document.file_name)
    else:
        return
    if context.user_data.get('state') == 'prevrcpt_photos':
        await _collect_previous_photo(message, context, file_id, media_type)
        return
    if context.user_data.get('state') in ('receipt_photo', 'ilspend_card', 'ilspend_amount', 'ilspend_description'):
        context.user_data.pop('ilspend', None)
        context.user_data['state'] = None
        await _scan_receipt(message, context, file_id, media_type)
        return
    context.user_data['receipt_offer'] = {'file_id': file_id, 'media_type': media_type}
    await message.reply_text("🧾 לסרוק את זה כחשבונית ולרשום כהוצאה?", reply_markup=InlineKeyboardMarkup([[
        InlineKeyboardButton("🧾 כן, סרוק", callback_data="rcpt:scan"),
        InlineKeyboardButton("לא", callback_data="rcpt:no")]]))


async def _scan_receipt(message, context, file_id, media_type, previous=False, files=None):
    """Read the receipt (one photo, or up to MAX_RECEIPT_PHOTOS parts of one), suggest a
    category, then ask how it was paid -- or, for /previousreceipt, which logged
    purchase it belongs to."""
    if not anthropic_client:
        await message.reply_text("❌ ANTHROPIC_API_KEY לא מוגדר — אי אפשר לסרוק.")
        return
    files = [tuple(f) for f in (files or [(file_id, media_type)])]
    await message.reply_text("🔍 סורק את החשבונית..." if len(files) == 1
                             else f"🔍 סורק את החשבונית ({len(files)} צילומים)...")
    cats = ecat.load()
    try:
        blobs = []
        for fid, mt in files:
            tg_file = await context.bot.get_file(fid)
            blobs.append((bytes(await tg_file.download_as_bytearray()), mt))
        receipt, cost = await asyncio.to_thread(rcp.scan, anthropic_client, blobs[0][0], blobs[0][1],
                                                cats['categories'], blobs[1:])
    except Exception as e:
        _planner_log(f"receipt scan failed: {e}")
        await message.reply_text(f"❌ לא הצלחתי לקרוא את החשבונית: {e}\nאפשר לרשום ידנית עם /ilspend.")
        return
    try:
        api_spend.record_spend([{'name': 'Claude Opus 5.5 receipt', 'cost': cost}], 'receipt')
    except Exception as e:
        _planner_log(f"receipt spend log failed: {e}")
    if not receipt.get('is_receipt') or not receipt.get('total'):
        await message.reply_text("🤔 זה לא נראה כמו חשבונית שאפשר לקרוא. נסה צילום חד יותר, או /ilspend.")
        return
    context.user_data['receipt'] = {
        'data': receipt, 'file_id': files[0][0], 'media_type': files[0][1],
        'files': [list(f) for f in files], 'previous': previous,
        'category': ecat.suggest(cats, receipt.get('store_name'), receipt.get('expense_category')),
        'day': _previous_receipt_day(receipt) if previous else _receipt_day(receipt)}
    context.user_data['state'] = 'receipt_confirm'
    await _receipt_next_step(message, context, first=True)


MAX_RECEIPT_PHOTOS = 3


def _previous_receipt_day(receipt):
    """/previousreceipt keeps the receipt's own date, however old; never a future one."""
    today = _israel_today()
    try:
        day = datetime.strptime(receipt.get('date') or '', '%Y-%m-%d').date()
    except ValueError:
        return today.isoformat()
    return day.isoformat() if day <= today else today.isoformat()


async def _receipt_next_step(message, context, first=False, note=''):
    """The scanned receipt's next question, with its buttons."""
    pending = context.user_data['receipt']
    r = pending['data']
    day = pending['day']
    shown_day = f"{day[8:10]}/{day[5:7]}/{day[:4]}"
    category = pending.get('category') or ecat.UNCATEGORISED
    text = ''
    if first:
        text = rcp.format_receipt(r)
        if day != r.get('date'):
            text += f"\n_תאריך החשבונית {r.get('date') or '—'} מחוץ לטווח — יירשם {day}_"
        text += f"\n\n🏷 קטגוריה: *{category}* _(הצעה — אפשר לשנות)_"
    else:
        text = f"🏷 קטגוריה: *{category}* ✓" + (f"\n_{note}_" if note else '')
    rows = []
    if pending.get('previous') and not pending.get('as_new'):
        matches = rcp.match_candidates(_load_spend_entries(), r['total'], r.get('date'))
        if matches:
            text += ("\n\n📎 *מצאתי הוצאה רשומה עם הסכום הזה.* לצרף אליה את החשבונית?\n"
                     "_צירוף לא מוריד כסף שוב — ההוצאה כבר נרשמה._")
            for index, entry in matches:
                d = str(entry.get('date', ''))
                rows.append([InlineKeyboardButton(
                    f"📎 {d[8:10]}/{d[5:7]} ₪{float(entry.get('amount') or 0):,.2f} {str(entry.get('description', ''))[:20]}",
                    callback_data=f"prcpt:att:{index}:{int(round(float(entry.get('amount') or 0) * 100))}")])
        else:
            text += (f"\n\n🔎 לא מצאתי הוצאה רשומה של {ex.money(r['total'])} סביב {shown_day}.\n"
                     f"לרשום אותה עכשיו כהוצאה חדשה מ-{shown_day}?")
        rows.append([InlineKeyboardButton(f"➕ לא נרשמה — רשום כהוצאה מ-{shown_day}", callback_data="prcpt:new")])
    else:
        text += "\n\n💳 *איך שילמת?*\n_אפשר גם לשלוח סכום אחר אם הסה\"כ לא נכון_"
        rows.append([InlineKeyboardButton("💳 דביט", callback_data="rcpt:pay:debit"),
                     InlineKeyboardButton("🟦 ויזה", callback_data="rcpt:pay:visa"),
                     InlineKeyboardButton("💵 מזומן", callback_data="rcpt:pay:cash")])
    rows.append([InlineKeyboardButton("🏷 שנה קטגוריה", callback_data="rcat:menu"),
                 InlineKeyboardButton("❌ ביטול", callback_data="rcpt:no")])
    await _planner_reply(_ReplyTarget(message), text, reply_markup=InlineKeyboardMarkup(rows))


async def _save_receipt_images(context, pending, entry_id):
    """Every photo of the receipt next to the others; their file names."""
    names = []
    for part, (fid, mt) in enumerate(pending.get('files') or [[pending['file_id'], pending['media_type']]], 1):
        try:
            tg_file = await context.bot.get_file(fid)
            path = rcp.save_image(bytes(await tg_file.download_as_bytearray()), entry_id, mt, part)
            names.append(os.path.basename(path))
        except Exception as e:
            _planner_log(f"receipt image not saved: {e}")
    return names


def _stored_receipt(r, images):
    stored = {k: v for k, v in r.items() if k != 'is_receipt'}
    stored['image'] = images[0] if images else None
    if len(images) > 1:
        stored['images'] = images
    return stored


def _keep_category(store, category):
    """Learn the store's category (and a new name); None for 'no category'."""
    if not category or category == ecat.UNCATEGORISED:
        return None
    data = ecat.load()
    category = ecat.learn(data, store, category)
    ecat.save(data)
    return category


async def receipt_category_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """rcat:menu | rcat:new | rcat:<n> -- the category of the receipt being logged."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    pending = context.user_data.get('receipt')
    if not pending:
        await query.message.reply_text("ℹ️ החשבונית הזו כבר לא ממתינה — שלח אותה שוב.")
        return
    action = (query.data or '').split(':', 1)[1]
    if action == 'menu':
        names = ecat.load()['categories']
        pending['cat_list'] = list(names)
        buttons = [InlineKeyboardButton(('✅ ' if n == pending.get('category') else '') + n, callback_data=f"rcat:{i}")
                   for i, n in enumerate(names)]
        rows = [buttons[i:i + 2] for i in range(0, len(buttons), 2)]
        rows.append([InlineKeyboardButton("✏️ קטגוריה חדשה (כתוב)", callback_data="rcat:new")])
        try:
            await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(rows))
        except Exception:
            await query.message.reply_text("🏷 בחר קטגוריה:", reply_markup=InlineKeyboardMarkup(rows))
        return
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if action == 'new':
        context.user_data['state'] = 'rcpt_category'
        await query.message.reply_text("✏️ כתוב את שם הקטגוריה (למשל: מונית)\nמהפעם הבאה היא תופיע ככפתור.")
        return
    names = pending.get('cat_list') or ecat.load()['categories']
    if not action.isdigit() or int(action) >= len(names):
        await query.message.reply_text("ℹ️ הרשימה השתנתה — לחץ שוב על 🏷 שנה קטגוריה.")
        return
    pending['category'] = names[int(action)]
    context.user_data['state'] = 'receipt_confirm'
    await _receipt_next_step(query.message, context)


async def _handle_receipt_category_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A typed new category for the receipt being logged."""
    text = (update.message.text or '').strip()
    pending = context.user_data.get('receipt')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not pending:
        context.user_data.pop('receipt', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    name = ecat.clean(text)
    if not name:
        await update.message.reply_text("✏️ שלח שם קטגוריה (או cancel)")
        return
    data = ecat.load()
    known = ecat.find(data, name)
    pending['category'] = ecat.add(data, name)
    ecat.save(data)
    context.user_data['state'] = 'receipt_confirm'
    await _receipt_next_step(update.message, context,
                             note='' if known else 'קטגוריה חדשה — מעכשיו היא תופיע ככפתור')


async def previous_receipt_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/previousreceipt - a receipt for an earlier purchase: attach it to the logged
    expense, or log it as a new one on its own date."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    context.user_data.pop('receipt', None)
    context.user_data['prevrcpt'] = {'files': [], 'group': None}
    context.user_data['state'] = 'prevrcpt_photos'
    await update.message.reply_text(
        "🧾 *חשבונית להוצאה קודמת*\n\n"
        "שלח צילום של החשבונית — או 2 צילומים אם היא ארוכה (אפשר יחד, כאלבום).\n"
        "אסרוק אותה, אציע קטגוריה, ואחפש את ההוצאה שכבר רשמת כדי לצרף אליה — בלי לרשום פעמיים. "
        "אם היא עוד לא נרשמה, אפשר לרשום אותה בתאריך שלה.\n\n_cancel לביטול_",
        parse_mode='Markdown')


async def _collect_previous_photo(message, context, file_id, media_type):
    """Gather the photos of one receipt; scan on the button (or at the limit)."""
    pr = context.user_data.get('prevrcpt') or {'files': [], 'group': None}
    context.user_data['prevrcpt'] = pr
    pr['files'].append([file_id, media_type])
    if len(pr['files']) >= MAX_RECEIPT_PHOTOS:
        context.user_data.pop('prevrcpt', None)
        context.user_data['state'] = None
        await _scan_receipt(message, context, None, None, previous=True, files=pr['files'])
        return
    group = getattr(message, 'media_group_id', None)
    if group and group == pr.get('group'):
        return          # the rest of an album: the button under its first photo scans them all
    pr['group'] = group
    await message.reply_text(
        "📸 קיבלתי. עוד צילום של אותה חשבונית? פשוט שלח אותו.\nאו סרוק עכשיו:",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔍 סרוק", callback_data="prcpt:scan"),
                                            InlineKeyboardButton("❌ ביטול", callback_data="rcpt:no")]]))


async def _handle_prevrcpt_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('prevrcpt', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    await update.message.reply_text("📸 שלח צילום של החשבונית (או cancel)")


async def previous_receipt_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """prcpt:scan | prcpt:new | prcpt:att:<index>:<amount in agorot>"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    parts = (query.data or '').split(':')
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if parts[1] == 'scan':
        pr = context.user_data.pop('prevrcpt', None)
        if not pr or not pr.get('files'):
            await query.message.reply_text("ℹ️ שלח קודם צילום (/previousreceipt).")
            return
        context.user_data['state'] = None
        await _scan_receipt(query.message, context, None, None, previous=True, files=pr['files'])
        return
    pending = context.user_data.get('receipt')
    if not pending:
        await query.message.reply_text("ℹ️ החשבונית הזו כבר לא ממתינה — שלח אותה שוב.")
        return
    if parts[1] == 'new':
        pending['as_new'] = True
        await _receipt_next_step(query.message, context)
        return
    if parts[1] != 'att' or len(parts) < 4:
        return
    entries = _load_spend_entries()
    index, cents = int(parts[2]), int(parts[3])
    entry = entries[index] if 0 <= index < len(entries) else None
    if (not entry or int(round(float(entry.get('amount', 0) or 0) * 100)) != cents
            or isinstance(entry.get('receipt'), dict)):
        await query.message.reply_text("⚠️ ההוצאה השתנתה מאז — שלח שוב /previousreceipt.")
        return
    r = pending['data']
    entry_id = entry.get('id') or uuid.uuid4().hex[:10]
    images = await _save_receipt_images(context, pending, entry_id)
    store = r.get('store_name') or 'חשבונית'
    category = _keep_category(store, pending.get('category'))
    entry['id'] = entry_id
    entry['receipt'] = _stored_receipt(r, images)
    entry['store'] = store
    if category:
        ecat.assign(entry, category)
    _save_spend_entries(entries)
    context.user_data.pop('receipt', None)
    context.user_data['state'] = None
    d = str(entry.get('date', ''))
    await query.message.reply_text(
        f"📎 <b>החשבונית צורפה</b>\n\n"
        f"{d[8:10]}/{d[5:7]}/{d[:4]} · {ex.money(entry.get('amount'))} · {html.escape(str(entry.get('description', '')))}\n"
        f"🧾 {html.escape(store)} — {len(r.get('items') or [])} פריטים\n"
        f"🏷 קטגוריה: <b>{html.escape(category or ecat.UNCATEGORISED)}</b>\n\n"
        f"<i>לא ירד כסף — ההוצאה כבר הייתה רשומה. מסומנת 🧾 ב-/ilspendhistory</i>",
        parse_mode='HTML',
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
            "📖 להיסטוריה", callback_data=f"ilsphist:{ex.cycle_month_of(entry)}")]]))


def _receipt_day(receipt):
    """The receipt's own date when /ilspend could take it (this or last month, not
    the future); otherwise today."""
    today = _israel_today()
    try:
        day = datetime.strptime(receipt.get('date') or '', '%Y-%m-%d').date()
    except ValueError:
        return today.isoformat()
    first_prev = (today.replace(day=1) - timedelta(days=1)).replace(day=1)
    return day.isoformat() if first_prev <= day <= today else today.isoformat()


async def _handle_receipt_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """While a scanned receipt waits: a number corrects the total, cancel drops it."""
    text = (update.message.text or '').strip()
    pending = context.user_data.get('receipt')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not pending:
        context.user_data.pop('receipt', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    try:
        total = float(text.replace(',', '').replace('₪', '').strip())
        if total <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ לחץ על אמצעי התשלום, או שלח סכום מתוקן (למשל 245.90).")
        return
    pending['data']['total'] = round(total, 2)
    pending['data']['total_corrected'] = True
    await update.message.reply_text(f"✏️ הסה\"כ עודכן ל-₪{total:,.2f}. עכשיו לחץ איך שילמת.")


async def receipt_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """rcpt:scan | rcpt:no | rcpt:pay:<debit|visa|cash>"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    parts = (query.data or '').split(':')
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if parts[1] == 'scan':
        offer = context.user_data.pop('receipt_offer', None)
        if not offer:
            await query.message.reply_text("ℹ️ שלח את הצילום שוב.")
            return
        await _scan_receipt(query.message, context, offer['file_id'], offer['media_type'])
        return
    if parts[1] == 'no':
        context.user_data.pop('receipt_offer', None)
        context.user_data.pop('receipt', None)
        if context.user_data.get('state') == 'receipt_confirm':
            context.user_data['state'] = None
        await query.message.reply_text("👍 לא נרשם כלום.")
        return
    pending = context.user_data.get('receipt')
    card = {'debit': ex.DEBIT, 'visa': ex.VISA, 'cash': ex.CASH}.get(parts[-1])
    if not pending or not card:
        await query.message.reply_text("ℹ️ החשבונית הזו כבר לא ממתינה — שלח אותה שוב.")
        return
    r = pending['data']
    amount = round(float(r['total']), 2)
    if card == ex.DEBIT and not ex.can_debit(_checking_balance(), amount):
        await query.message.reply_text(ex.over_limit_text(_checking_balance(), amount)
                                       + "\nבחר ויזה / מזומן, או בטל.")
        return
    context.user_data.pop('receipt', None)
    context.user_data['state'] = None
    entry_id = uuid.uuid4().hex[:10]
    images = await _save_receipt_images(context, pending, entry_id)
    store = r.get('store_name') or 'חשבונית'
    description = f"{store} — חשבונית ({len(r.get('items') or [])} פריטים)"
    extra = {'id': entry_id, 'receipt': _stored_receipt(r, images), 'store': store}
    category = _keep_category(store, pending.get('category'))
    if category:
        ecat.assign(extra, category)
    await _record_spend(query.message, context, amount, description, card,
                        pending.get('day') or _receipt_day(r), extra=extra)


async def receipts_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/receipts [n] - scanned receipts, newest first; a number shows one in full."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    entries = _load_spend_entries()
    if context.args and str(context.args[0]).isdigit():
        await _planner_reply(update, rcp.format_receipt_detail(entries, int(context.args[0])))
        return
    await _planner_reply(update, rcp.format_receipts(entries))


async def prices_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/prices <item> - what you paid for it across receipts: per kilo, cheapest first."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    query = ' '.join(str(a) for a in (context.args or [])).strip()
    if not query:
        await update.message.reply_text("🔎 שלח: /prices <מוצר>, למשל /prices עגבניות")
        return
    await _planner_reply(update, rcp.format_prices(_load_spend_entries(), query))


def _canibuy_text(amount):
    """/canibuy: how big a purchase would be next to the עו"ש right now. Read-only."""
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    try:
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            checking = float(json.load(f).get('reserves', {}).get('ILS_checking', 0) or 0)
    except Exception:
        checking = 0.0
    after = round(checking - amount, 2)
    lines = [f"🤔 <b>בדיקה: קנייה של {ex.money(amount)}</b>", ""]
    if checking > 0:
        lines.append(f"📊 <b>{amount / checking * 100:.1f}%</b> מהעו\"ש שיש לך עכשיו")
    else:
        lines.append("📊 העו\"ש כבר במינוס — אין אחוז להשוות אליו")
    lines.append(f"🏦 עו\"ש: {ex.money(checking)} → <b>{ex.money(after)}</b>")
    pending = ex.total_of(ex.unreserved(ex.pending_visa(_load_spend_entries())))
    if pending:
        left = round(checking - pending, 2)
        charge = ex.next_charge_date(_israel_today()).strftime('%d/%m')
        if left > 0:
            lines.append(f"🟦 אחרי הוויזה שממתינה (₪{pending:,.2f}, יורדת ב-{charge}) נשארים {ex.money(left)} — "
                         f"הקנייה היא <b>{amount / left * 100:.1f}%</b> מזה")
        else:
            lines.append(f"🟦 הוויזה שממתינה (₪{pending:,.2f}, יורדת ב-{charge}) כבר מכסה את כל העו\"ש")
    if after < 0:
        if ex.can_debit(checking, amount):
            lines.append(f"⚠️ {'העו' + chr(34) + 'ש נשאר במינוס' if checking < 0 else 'זה מכניס את העו' + chr(34) + 'ש למינוס'}"
                         f" (מסגרת עד -₪{ex.OVERDRAFT_LIMIT:,.0f})")
        else:
            lines.append(f"⛔ זה עובר את מסגרת המינוס (-₪{ex.OVERDRAFT_LIMIT:,.0f})")
    lines += ["", "<i>רק בדיקה — שום דבר לא נרשם ולא ירד. לרישום: /ilspend</i>"]
    return "\n".join(lines)


def _visa_view():
    """/visa: every Visa purchase still waiting for its charge, the charge day and
    the days left. Returns (html text, keyboard or None)."""
    entries = _load_spend_entries()
    today = _israel_today()
    checking = _checking_balance()
    pending = ex.pending_visa(entries)
    lines = ["🟦 <b>ויזה — רכישות שממתינות לחיוב</b>", ""]

    def days_left(day):
        n = (day - today).days
        if n == 0:
            return "<b>היום</b>"
        if n == 1:
            return "<b>מחר</b>"
        return f"בעוד <b>{n}</b> ימים" if n > 0 else f"היה לפני {-n} ימים"

    groups = {}
    for e in pending:
        due = e.get('charge_date')
        if not due:
            day = ex.entry_date(e) or today
            due = ex.charge_date_for(day).strftime('%Y-%m-%d')
        groups.setdefault(due, []).append(e)
    if not groups:
        nxt = ex.next_charge_date(today)
        lines += ["אין רכישות בויזה שממתינות לחיוב.",
                  f"📆 החיוב הבא: {nxt.strftime('%d/%m/%Y')} — {days_left(nxt)}", ""]
    for due in sorted(groups):
        day = datetime.strptime(due, '%Y-%m-%d').date()
        rows = sorted(groups[due], key=lambda e: (e.get('date', ''), e.get('time', '')))
        lines.append(f"📆 <b>חיוב ב-{day.strftime('%d/%m/%Y')}</b> — {days_left(day)}")
        for i, e in enumerate(rows, 1):
            d = str(e.get('date', ''))
            lines.append(f"{i}. {'✅' if ex.is_reserved(e) else '⏳'} {d[8:10]}/{d[5:7]} · "
                         f"₪{float(e.get('amount', 0) or 0):,.2f} · {html.escape(str(e.get('description', '')))}")
        lines += [f"<b>סה\"כ: ₪{ex.total_of(rows):,.2f}</b> ({len(rows)} רכישות)", ""]

    lines.append(f"💳 עו\"ש עכשיו: <b>{ex.money(checking)}</b>")
    still = ex.total_of(ex.unreserved(pending))
    markup = None
    if pending and still:
        lines.append(f"⏳ עוד לא ירד מהעו\"ש: <b>₪{still:,.2f}</b> → אחרי החיוב: <b>{ex.money(checking - still)}</b>")
        markup = InlineKeyboardMarkup([[InlineKeyboardButton(
            f"⬇️ להוריד עכשיו מהעו\"ש (₪{still:,.2f})", callback_data="visares:go")]])
    elif pending:
        lines.append("✅ הכול כבר ירד מהעו\"ש — החיוב לא יוריד יותר כלום")

    charged = [e for e in entries
               if ex.card_of(e) == ex.VISA and e.get('charged') and not ex.is_cancelled(e)]
    if charged:
        last = max(str(e.get('charged_on') or e.get('charge_date') or '') for e in charged)
        batch = [e for e in charged if str(e.get('charged_on') or e.get('charge_date') or '') == last]
        if last:
            lines.append(f"🧾 החיוב הקודם: {last[8:10]}/{last[5:7]}/{last[:4]} — ₪{ex.total_of(batch):,.2f} ({len(batch)} רכישות)")
    if pending:
        lines += ["", "<i>✅ = ירד מהעו\"ש כבר בזמן הקנייה · ⏳ = ירד רק ביום החיוב</i>"]
    return "\n".join(lines), markup


async def _auto_categorise(targets, notify=None):
    """Give each (index or None, entry) a category with Claude and save it. Matched
    back by id (or index + amount + description) after the call, so a purchase logged
    meanwhile is not lost. Returns how many got one."""
    if not targets or not anthropic_client:
        return 0
    data = ecat.load()
    try:
        found, cost = await asyncio.to_thread(ecat.classify, anthropic_client, [e for _, e in targets],
                                              data['categories'])
    except Exception as e:
        _planner_log(f"auto category failed: {e}")
        return 0
    try:
        api_spend.record_spend([{'name': 'Claude Opus 5.5 categories', 'cost': cost}], 'categories')
    except Exception as e:
        _planner_log(f"category spend log failed: {e}")
    entries = _load_spend_entries()
    done = 0
    for pos, (index, wanted) in enumerate(targets):
        name = found.get(pos)
        if not name:
            continue
        if wanted.get('id'):
            entry = next((e for e in entries if e.get('id') == wanted['id']), None)
        else:
            entry = entries[index] if index is not None and 0 <= index < len(entries) else None
            if entry is not None and (entry.get('description') != wanted.get('description')
                                      or entry.get('amount') != wanted.get('amount')):
                entry = None
        if entry is None or ecat.clean(entry.get('category')):
            continue
        ecat.assign(entry, ecat.learn_description(data, entry.get('description'), name))
        done += 1
    if done:
        _save_spend_entries(entries)
        ecat.save(data)
        if notify:
            for _, wanted in targets:
                entry = next((e for e in entries if wanted.get('id') and e.get('id') == wanted['id']), None)
                alert = _budget_alert_for(entry) if entry else None
                if alert:
                    try:
                        await notify(alert, parse_mode='Markdown')
                    except Exception as e:
                        _planner_log(f"budget alert send failed: {e}")
    return done


def _category_months(today=None):
    """This spending month and the three before it, newest first."""
    key = ex.cycle_month_for(today or _israel_today())
    months = [key]
    for _ in range(3):
        months.append(ecat.previous_month(months[-1]))
    return months


async def categories_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/categories - this month per category, then each of the 3 months before."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    try:
        months = _category_months()
        entries = _load_spend_entries()
        missing = ecat.uncategorised(entries, months)
        note = ''
        if missing:
            wait = await update.message.reply_text(f"🤖 מסווג {len(missing)} הוצאות שעוד אין להן קטגוריה...")
            done = await _auto_categorise(missing)
            if done:
                note = (f"\n\n🤖 _סווגו אוטומטית {done} הוצאות. טעות? "
                        f"/ilspendhistory ← לחץ על הקטגוריה_")
            entries = _load_spend_entries()
        await _planner_reply(update, ecat.format_categories(entries, months[0]) + note)
    except Exception as e:
        _planner_log(f"/categories failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


def _category_target(entries, index, stamp):
    if index < 0 or index >= len(entries):
        return None
    entry = entries[index]
    if int(round(float(entry.get('amount', 0) or 0) * 100)) != stamp:
        return None
    return entry


async def history_category_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ilspcat:list:<month> | ilspcat:pick:<i>:<agorot> | ilspcat:set:<i>:<agorot>:<n> |
    ilspcat:new:<i>:<agorot> -- change the category of a purchase from /ilspendhistory."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    parts = (query.data or '').split(':')
    action = parts[1]
    entries = _load_spend_entries()
    if action == 'list':
        month_key = parts[2]
        rows = ex.indexed_month_entries(entries, month_key, cycle=True)[-30:]
        buttons = [[InlineKeyboardButton(
            f"{ex.money(e.get('amount'))} — {(e.get('description') or '')[:20]} · {ecat.category_of(e)[:14]}",
            callback_data=f"ilspcat:pick:{i}:{int(round(float(e.get('amount', 0) or 0) * 100))}")]
            for i, e in rows]
        buttons.append([InlineKeyboardButton("↩ Back", callback_data=f"ilsphist:{month_key}")])
        await query.edit_message_text("🏷 *לאיזו הוצאה לשנות קטגוריה?*", parse_mode='Markdown',
                                      reply_markup=InlineKeyboardMarkup(buttons))
        return
    index, stamp = int(parts[2]), int(parts[3])
    entry = _category_target(entries, index, stamp)
    if entry is None:
        await query.edit_message_text("⚠️ הרשימה השתנתה מאז שההודעה נשלחה.\nפתח מחדש עם /ilspendhistory")
        return
    data = ecat.load()
    if action == 'pick':
        names = data['categories']
        current = ecat.category_of(entry)
        buttons = [InlineKeyboardButton(('✅ ' if n == current else '') + n,
                                        callback_data=f"ilspcat:set:{index}:{stamp}:{i}")
                   for i, n in enumerate(names)]
        rows = [buttons[i:i + 2] for i in range(0, len(buttons), 2)]
        rows.append([InlineKeyboardButton("✏️ קטגוריה חדשה (כתוב)", callback_data=f"ilspcat:new:{index}:{stamp}")])
        rows.append([InlineKeyboardButton("↩ Back", callback_data=f"ilsphist:{ex.cycle_month_of(entry)}")])
        await query.edit_message_text(
            f"🏷 *{ex.money(entry.get('amount'))} — {ecat._esc(entry.get('description'))}*\n"
            f"קטגוריה עכשיו: *{ecat._esc(current)}*\n\nבחר קטגוריה:",
            parse_mode='Markdown', reply_markup=InlineKeyboardMarkup(rows))
        return
    if action == 'new':
        context.user_data['ilspcat'] = {'index': index, 'stamp': stamp}
        context.user_data['state'] = 'ilspcat_new'
        await query.edit_message_text("✏️ כתוב את שם הקטגוריה (למשל: מונית)\nמהפעם הבאה היא תופיע ככפתור.")
        return
    if action == 'set' and len(parts) > 4 and parts[4].isdigit() and int(parts[4]) < len(data['categories']):
        name = data['categories'][int(parts[4])]
        await _set_entry_category(entries, entry, data, name)
        month_key = ex.cycle_month_of(entry)
        await query.edit_message_text(
            _history_text(entries, month_key) + f"\n\n✅ _{ecat._esc(entry.get('description'))} → {ecat._esc(name)}_",
            parse_mode='Markdown', reply_markup=_history_keyboard(entries, month_key, _history_this_month()))


async def _set_entry_category(entries, entry, data, name):
    """Save the category, and remember it for this description (and store)."""
    ecat.assign(entry, ecat.learn_description(data, entry.get('description'), name))
    if entry.get('store'):
        ecat.learn(data, entry['store'], name)
    _save_spend_entries(entries)
    ecat.save(data)


async def _handle_history_category_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    target = context.user_data.pop('ilspcat', None)
    context.user_data['state'] = None
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not target:
        await update.message.reply_text("❌ בוטל.")
        return
    name = ecat.clean(text)
    entries = _load_spend_entries()
    entry = _category_target(entries, target['index'], target['stamp'])
    if not name or entry is None:
        await update.message.reply_text("⚠️ לא עודכן — פתח מחדש עם /ilspendhistory")
        return
    data = ecat.load()
    await _set_entry_category(entries, entry, data, name)
    await update.message.reply_text(
        f"✅ {entry.get('description', '')} → 🏷 {entry['category']}\n<i>מהפעם הבאה \"{entry['category']}\" תופיע ככפתור.</i>",
        parse_mode='HTML')


def _cg_rows(entries, state):
    """The purchases of state's category in its month: (index in entries, entry)."""
    return [(i, e) for i, e in ex.indexed_month_entries(entries, state['month'], cycle=True)
            if ecat.category_of(e) == state['cat']][:30]


def _cg_view(entries, state):
    """One category of one month, with tick boxes. Markdown text and buttons."""
    rows = _cg_rows(entries, state)
    chosen = {tuple(s) for s in state['sel']}
    total = sum(float(e.get('amount', 0) or 0) for _, e in rows)
    label = datetime.strptime(state['month'], '%Y-%m').strftime('%B %Y')
    lines = [f"🏷 *{ecat._esc(state['cat'])}* — {label}",
             f"💸 {ex.money(total)} · {len(rows)} רכישות"]
    lines += ecat._sub_lines(entries, state['month'], state['cat'])
    lines += ['', '_סמן הוצאה אחת או כמה (☑), ואז בחר לאן להעביר._']
    buttons = []
    for i, e in rows:
        key = (i, int(round(float(e.get('amount', 0) or 0) * 100)))
        d = str(e.get('date', ''))
        sub = f" › {ecat.sub_of(e)}" if ecat.sub_of(e) else ''
        buttons.append([InlineKeyboardButton(
            f"{'☑' if key in chosen else '⬜'} {d[8:10]}/{d[5:7]} {ex.money(e.get('amount'))} {(e.get('description') or '')[:18]}{sub[:14]}",
            callback_data=f"cg:t:{key[0]}:{key[1]}")])
    if rows:
        buttons.append([InlineKeyboardButton("⬜ נקה הכל" if len(chosen) == len(rows) else "☑ בחר הכל",
                                             callback_data="cg:all")])
    if chosen:
        buttons.append([InlineKeyboardButton(f"➡️ העבר לקטגוריה ({len(chosen)})", callback_data="cg:mv")])
        if state['cat'] != ecat.UNCATEGORISED:
            buttons.append([InlineKeyboardButton(f"📂 לתת-קטגוריה של {state['cat'][:20]} ({len(chosen)})",
                                                 callback_data="cg:sub")])
    buttons.append([InlineKeyboardButton("↩ חזרה", callback_data=f"ilsphist:{state['month']}")])
    return '\n'.join(lines), InlineKeyboardMarkup(buttons)


def _cg_move(entries, state, path):
    """Move the ticked purchases to path and learn it for their stores and
    descriptions. Returns how many moved (stale ticks are skipped)."""
    data = ecat.load()
    path = ecat.add_path(data, path)
    moved = 0
    for index, cents in state['sel']:
        if not (0 <= index < len(entries)):
            continue
        entry = entries[index]
        if int(round(float(entry.get('amount', 0) or 0) * 100)) != cents:
            continue
        ecat.assign(entry, path)
        ecat.learn_description(data, entry.get('description'), path)
        if entry.get('store'):
            ecat.learn(data, entry['store'], path)
        moved += 1
    if moved:
        _save_spend_entries(entries)
    ecat.save(data)
    return moved, path


def _cg_done_text(entries, month_key, moved, path):
    return (_history_text(entries, month_key)
            + f"\n\n✅ _הועברו {moved} הוצאות ל-{ecat._esc(path)} — הבוט יזכור את זה לפעם הבאה_")


async def category_group_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """cg:v:<month>:<n> open a category | cg:t:<i>:<agorot> tick | cg:all | cg:mv | cg:sub |
    cg:to:<n> move | cg:new / cg:subnew type a name | cg:back"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    parts = (query.data or '').split(':')
    action = parts[1]
    entries = _load_spend_entries()
    if action == 'v':
        month_key, n = parts[2], int(parts[3])
        cats = list(ecat.by_category(entries, month_key))
        if n >= len(cats):
            await query.answer("הרשימה השתנתה — פתח מחדש", show_alert=True)
            return
        context.user_data['cg'] = {'month': month_key, 'cat': cats[n], 'sel': []}
        await query.answer()
        text, markup = _cg_view(entries, context.user_data['cg'])
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=markup)
        return
    state = context.user_data.get('cg')
    if not state:
        await query.answer("פתח מחדש את /ilspendhistory", show_alert=True)
        return
    if action in ('t', 'all', 'back'):
        if action == 't':
            key = [int(parts[2]), int(parts[3])]
            state['sel'] = [s for s in state['sel'] if s != key] if key in state['sel'] else state['sel'] + [key]
        elif action == 'all':
            every = [[i, int(round(float(e.get('amount', 0) or 0) * 100))] for i, e in _cg_rows(entries, state)]
            state['sel'] = [] if len(state['sel']) == len(every) else every
        await query.answer()
        text, markup = _cg_view(entries, state)
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=markup)
        return
    if not state['sel']:
        await query.answer("סמן קודם הוצאה אחת לפחות", show_alert=True)
        return
    await query.answer()
    data = ecat.load()
    if action in ('mv', 'sub'):
        if action == 'mv':
            state['targets'] = [t for t in ecat.targets(data) if t != state['cat']]
            title = f"➡️ *לאן להעביר {len(state['sel'])} הוצאות?*"
            new = [InlineKeyboardButton("✏️ קטגוריה חדשה (כתוב)", callback_data="cg:new")]
        else:
            state['targets'] = [ecat.join_path(state['cat'], s) for s in ecat.subs_of(data, state['cat'])]
            title = (f"📂 *תת-קטגוריה של {ecat._esc(state['cat'])}*\n"
                     + ("_בחר אחת, או צור חדשה:_" if state['targets'] else "_עוד אין — צור אחת (למשל מונית):_"))
            new = [InlineKeyboardButton("✏️ תת-קטגוריה חדשה (כתוב)", callback_data="cg:subnew")]
        buttons = [InlineKeyboardButton(('   ↳ ' + ecat.split_path(t)[1]) if ecat.SEP in t and action == 'mv' else
                                        (ecat.split_path(t)[1] if action == 'sub' else t),
                                        callback_data=f"cg:to:{n}")
                   for n, t in enumerate(state['targets'])]
        rows = [buttons[i:i + 2] for i in range(0, len(buttons), 2)] + [new,
                [InlineKeyboardButton("↩ חזרה", callback_data="cg:back")]]
        await query.edit_message_text(title, parse_mode='Markdown', reply_markup=InlineKeyboardMarkup(rows))
        return
    if action in ('new', 'subnew'):
        context.user_data['state'] = 'cg_name'
        state['naming'] = 'sub' if action == 'subnew' else 'top'
        await query.edit_message_text(
            ("✏️ כתוב את שם התת-קטגוריה תחת " + state['cat'] + " (למשל: מונית)") if action == 'subnew'
            else "✏️ כתוב את שם הקטגוריה החדשה (למשל: סופר)")
        return
    if action == 'to':
        targets = state.get('targets') or []
        n = int(parts[2])
        if n >= len(targets):
            await query.edit_message_text("⚠️ הרשימה השתנתה — פתח מחדש עם /ilspendhistory")
            return
        moved, path = _cg_move(entries, state, targets[n])
        context.user_data.pop('cg', None)
        await query.edit_message_text(_cg_done_text(entries, state['month'], moved, path), parse_mode='Markdown',
                                      reply_markup=_history_keyboard(entries, state['month'], _history_this_month()))


async def _handle_category_group_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The typed name of a new category / sub-category for the ticked purchases."""
    text = (update.message.text or '').strip()
    state = context.user_data.get('cg')
    context.user_data['state'] = None
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not state or not state.get('sel'):
        context.user_data.pop('cg', None)
        await update.message.reply_text("❌ בוטל.")
        return
    name = ecat.clean(text)
    if not name:
        context.user_data['state'] = 'cg_name'
        await update.message.reply_text("✏️ שלח שם (או cancel)")
        return
    path = ecat.join_path(state['cat'], name) if state.get('naming') == 'sub' else name
    entries = _load_spend_entries()
    moved, path = _cg_move(entries, state, path)
    context.user_data.pop('cg', None)
    await _planner_reply(update, _cg_done_text(entries, state['month'], moved, path),
                         reply_markup=_history_keyboard(entries, state['month'], _history_this_month()))


def _planned_view():
    """/futureexpenses: the list by date, what to set aside, the future fund, and buttons."""
    data = pln.load()
    try:
        fund = float(ilf.read(_load_portfolio().get('reserves', {})).get(ilf.FUTURE, 0) or 0)
    except Exception as e:
        _planner_log(f"/futureexpenses: future fund unavailable ({e})")
        fund = None
    rows = [[InlineKeyboardButton(f"✅ קניתי: {item['name'][:20]}", callback_data=f"pln:done:{item['id']}"),
             InlineKeyboardButton("🏷", callback_data=f"pln:cat:{item['id']}"),
             InlineKeyboardButton("🗑", callback_data=f"pln:del:{item['id']}")] for item in pln.ordered(data)]
    rows.append([InlineKeyboardButton("➕ הוסף הוצאה עתידית", callback_data="pln:add")])
    return pln.format_list(data, fund, _israel_today()), InlineKeyboardMarkup(rows)


PLANNED_WHEN_ASK = ("📅 <b>מתי בערך תשלם את זה?</b>\n"
                    "• מספר חודשים — <code>6</code>\n"
                    "• חודש — <code>03/2027</code> או <code>מרץ 2027</code>\n"
                    "• תאריך — <code>15/03/2027</code>\n"
                    "<i>cancel לביטול</i>")
PLANNED_WHEN_SKIP = InlineKeyboardMarkup([[InlineKeyboardButton("⏭ לא יודע עדיין", callback_data="pln:nowhen")]])


async def _ai_planned_category(name):
    """Claude names the category from the description (an existing one when it fits,
    else a new one, which joins the list). 'אחר' when Claude is unavailable."""
    data = ecat.load()
    category = None
    if anthropic_client:
        try:
            found, cost = await asyncio.to_thread(ecat.classify, anthropic_client, [{'description': name}],
                                                  data['categories'])
            category = found.get(0)
            api_spend.record_spend([{'name': 'Claude Opus 5.5 categories', 'cost': cost}], 'categories')
        except Exception as e:
            _planner_log(f"future expense category failed: {e}")
    category = ecat.add(data, category or 'אחר')
    ecat.save(data)
    return category


async def _planned_finish(message, context, when=None, precision='month'):
    """Save the future expense being added, with Claude's category."""
    pending = context.user_data.pop('planned', None) or {}
    context.user_data['state'] = None
    if not pending.get('name') or not pending.get('cost'):
        await message.reply_text("ℹ️ ההוספה כבר לא פעילה — התחל שוב עם /futureexpenses")
        return
    category = await _ai_planned_category(pending['name'])
    data = pln.load()
    item = pln.add(data, pending['name'], pending['cost'], _israel_today(), when, precision, category)
    pln.save(data)
    need = pln.monthly_need(item, _israel_today())
    await message.reply_text(
        f"✅ <b>נוסף:</b> {html.escape(item['name'])} — ₪{item['cost']:,.2f}\n"
        f"📅 {pln.when_text(item)}" + (f" · לשים בצד ₪{need:,.2f} לחודש" if need is not None else "")
        + f"\n🏷 קטגוריה: <b>{html.escape(category)}</b> <i>(נבחרה אוטומטית)</i>",
        parse_mode='HTML',
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏷 שנה קטגוריה", callback_data=f"pln:cat:{item['id']}")]]))
    view, markup = _planned_view()
    await _planner_reply(_ReplyTarget(message), view, reply_markup=markup)


async def planned_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/futureexpenses (/planned) [description cost] - expected expenses: add one, or see the list."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    raw = ' '.join(context.args or []).strip()
    if raw:
        parsed = pln.parse_line(raw)
        if not parsed:
            await update.message.reply_text("❌ שלח תיאור ואז סכום, למשל: /futureexpenses קורס פייתון 3500")
            return
        context.user_data['planned'] = {'name': parsed[0], 'cost': parsed[1]}
        context.user_data['state'] = 'planned_when'
        await update.message.reply_text(f"🗓 <b>{html.escape(parsed[0])}</b> — ₪{parsed[1]:,.2f}\n\n" + PLANNED_WHEN_ASK,
                                        parse_mode='HTML', reply_markup=PLANNED_WHEN_SKIP)
        return
    text, markup = _planned_view()
    await _planner_reply(update, text, reply_markup=markup)


async def planned_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """pln:add | pln:nowhen | pln:done:<id> | pln:del:<id> | pln:cat:<id> | pln:setcat:<id>:<n>"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    parts = (query.data or '').split(':')
    action = parts[1]
    if action == 'add':
        await query.answer()
        context.user_data['state'] = 'planned_name'
        context.user_data['planned'] = {}
        await query.message.reply_text("🗓 <b>מה ההוצאה העתידית?</b> (תיאור)\n<i>למשל: קורס פייתון · cancel לביטול</i>",
                                       parse_mode='HTML')
        return
    if action == 'nowhen':
        await query.answer()
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        await _planned_finish(query.message, context)
        return
    data = pln.load()
    item = pln.find(data, parts[2]) if len(parts) > 2 else None
    if not item:
        await query.answer("כבר לא ברשימה", show_alert=True)
        return
    if action == 'cat':
        await query.answer()
        names = ecat.load()['categories']
        buttons = [InlineKeyboardButton(('✅ ' if n == item.get('category') else '') + n,
                                        callback_data=f"pln:setcat:{item['id']}:{i}") for i, n in enumerate(names)]
        await query.message.reply_text(
            f"🏷 <b>{html.escape(item['name'])}</b> — לאיזו קטגוריה?", parse_mode='HTML',
            reply_markup=InlineKeyboardMarkup([buttons[i:i + 2] for i in range(0, len(buttons), 2)]))
        return
    if action == 'setcat':
        names = ecat.load()['categories']
        n = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else -1
        if not 0 <= n < len(names):
            await query.answer("הרשימה השתנתה — נסה שוב", show_alert=True)
            return
        item['category'] = names[n]
        pln.save(data)
        await query.answer(f"🏷 {names[n]}")
        await query.edit_message_text(f"✅ {item['name']} → 🏷 {names[n]}")
        return
    item = pln.mark_done(data, parts[2], _israel_today()) if action == 'done' else pln.remove(data, parts[2])
    pln.save(data)
    await query.answer(("✅ סומן כנקנה — לרשום אותו: /ilspend" if action == 'done' else "🗑 נמחק"),
                       show_alert=action == 'done')
    text, markup = _planned_view()
    try:
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=markup)
    except Exception:
        await query.edit_message_text(text, reply_markup=markup)


async def _handle_planned_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The description, the cost, then when, of a new future expense."""
    text = (update.message.text or '').strip()
    state = context.user_data.get('state')
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('planned', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל.")
        return
    pending = context.user_data.setdefault('planned', {})
    if state == 'planned_name':
        name = pln.clean(text)
        if not name:
            await update.message.reply_text("✏️ שלח תיאור (או cancel)")
            return
        pending['name'] = name
        context.user_data['state'] = 'planned_cost'
        await update.message.reply_text(f"🗓 <b>{html.escape(name)}</b>\n\n💰 כמה זה יעלה? (₪)", parse_mode='HTML')
        return
    if state == 'planned_cost':
        cost = pln.parse_cost(text)
        if not cost:
            await update.message.reply_text("❌ שלח סכום, למשל 4500 (או cancel)")
            return
        pending['cost'] = cost
        context.user_data['state'] = 'planned_when'
        await update.message.reply_text(PLANNED_WHEN_ASK, parse_mode='HTML', reply_markup=PLANNED_WHEN_SKIP)
        return
    if text.lower() in pln.SKIP_WORDS:
        await _planned_finish(update.message, context)
        return
    parsed = pln.parse_when(text, _israel_today())
    if not parsed:
        await update.message.reply_text("❌ לא הבנתי מתי. שלח למשל 6 (חודשים), 03/2027, מרץ 2027 או 15/03/2027",
                                        reply_markup=PLANNED_WHEN_SKIP)
        return
    await _planned_finish(update.message, context, parsed[0], parsed[1])


