async def emergency_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/emergency [months] | /emergency spend <₪ a month> - how many months of spending
    the emergency fund covers; or how long the savings last at a monthly spending you pick."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    data = wl.load()
    if context.args and context.args[0].lower() in EMERGENCY_SPEND_WORDS:
        spend = pln.parse_cost(context.args[1]) if len(context.args) > 1 else None
        if spend:
            await _send_runway(update, spend)
            return
        context.user_data['state'] = 'emergency_spend'
        await update.message.reply_text("💭 <b>כמה תוציא בחודש?</b> (₪)\n<i>למשל 8000 · cancel לביטול</i>",
                                        parse_mode='HTML')
        return
    if context.args:
        try:
            months = float(context.args[0])
            if months < 0 or months > 60:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ שלח מספר חודשים, למשל /emergency 6 (או /emergency 0 לביטול היעד)")
            return
        data['emergency_months'] = months or None
        wl.save(data)
    await _planner_reply(update, wl.format_emergency(_emergency_fund(), _load_spend_entries(), _israel_today(),
                                                     data.get('emergency_months')), reply_markup=EMERGENCY_IF_BUTTON)


async def _take_networth_snapshot(today=None):
    """Value everything now, keep it as this month's snapshot. Returns (snap, previous)."""
    result, usd_ils, eur_ils = await asyncio.to_thread(_horizons_fetch)
    data = wl.load()
    snap = wl.snapshot(result, usd_ils, eur_ils, today or _israel_today())
    previous = [s for s in data['snapshots'] if s['month'] < snap['month']]
    wl.add_snapshot(data, snap)
    wl.save(data)
    return snap, (previous[-1] if previous else None)


async def networth_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/networth [save] - monthly snapshots of everything you own, and the trend."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("🔄 מחשב שווי נקי...")
    try:
        if context.args and context.args[0].lower() in ('save', 'שמור'):
            snap, prev = await _take_networth_snapshot()
            await _planner_reply(update, wl.format_snapshot(snap, prev) + "\n\n_נשמר כצילום של החודש._")
            return
        result, usd_ils, eur_ils = await asyncio.to_thread(_horizons_fetch)
        current = wl.snapshot(result, usd_ils, eur_ils, _israel_today())
        await _planner_reply(update, wl.format_history(wl.load()['snapshots'], current))
    except Exception as e:
        _planner_log(f"/networth failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


async def _send_networth_snapshot(app, today):
    """The 10th: this month's snapshot, once (remembered on disk)."""
    try:
        if any(s['month'] == today.strftime('%Y-%m') for s in wl.load()['snapshots']):
            return
        snap, prev = await _take_networth_snapshot(today)
        await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, text=wl.format_snapshot(snap, prev)
                                   + "\n\n_היסטוריה: /networth_", parse_mode='Markdown')
    except Exception as e:
        _planner_log(f"net worth snapshot failed: {e}")


def _usd_ils_quick():
    try:
        return float(yf.Ticker("USDILS=X").info.get('regularMarketPrice') or 0) or None
    except Exception:
        return None


async def fees_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/fees [rate <% a year>] - commissions and fees: this year and the last 12 months."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    data = wl.load()
    args = [a.lower() for a in (context.args or [])]
    if args and args[0] in ('rate', 'דמי'):
        try:
            pct = float(args[1].replace('%', ''))
            if pct < 0 or pct > 5:
                raise ValueError
        except (IndexError, ValueError):
            await update.message.reply_text("❌ שלח אחוז שנתי, למשל /fees rate 0.19 (או /fees rate 0 לביטול)")
            return
        data['fund_fee_pct'] = pct or None
        wl.save(data)
    portfolio = _load_portfolio()
    usd_ils = await asyncio.to_thread(_usd_ils_quick)
    if not usd_ils:
        rates = [c.get('fx_rate') for c in portfolio.get('cash_log') or [] if c.get('fx_rate')]
        usd_ils = float(rates[-1]) if rates else 3.6
    logs = portfolio.get('portfolio_log') or []
    stocks_usd = float(logs[-1].get('value') or 0) if logs else 0.0
    summary = wl.fee_summary(portfolio, usd_ils, _israel_today(), data.get('fund_fee_pct'))
    invested = stocks_usd * usd_ils + summary['bank_balance']
    await _planner_reply(update, wl.format_fees(summary, invested, data.get('fund_fee_pct'), usd_ils))


