async def budget_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/budget [category amount] - a monthly budget per category, warned at 80% and 100%."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    raw = ' '.join(context.args or []).strip()
    if raw:
        words = raw.split()
        amount = pln.parse_cost(words[-1]) if words[-1] not in ('0', '-') else 0
        name = ecat.clean(' '.join(words[:-1]))
        if amount is None or not name:
            await update.message.reply_text("❌ שלח קטגוריה ואז סכום, למשל: /budget סופר 1500 (0 = ביטול)")
            return
        data = ecat.load()
        name = ecat.set_budget(data, name, amount)
        ecat.save(data)
        await update.message.reply_text(f"✅ תקציב {name}: ₪{amount:,.2f} לחודש" if amount else f"🗑 התקציב של {name} בוטל")
    text, markup = _budget_view()
    await _planner_reply(update, text + "\n\n_לחץ על קטגוריה כדי לקבוע לה תקציב חודשי:_", reply_markup=markup)


async def budget_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """bdg:<n> -- set the budget of category n (typed next)."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    names = ecat.load()['categories']
    n = int((query.data or 'bdg:-1').split(':')[1])
    if not 0 <= n < len(names):
        await query.message.reply_text("⚠️ הרשימה השתנתה — פתח מחדש /budget")
        return
    context.user_data['budget_cat'] = names[n]
    context.user_data['state'] = 'budget_amount'
    await query.message.reply_text(f"💼 <b>תקציב חודשי ל{html.escape(names[n])}</b>\n\nכמה? (₪, 0 = ביטול · cancel)",
                                   parse_mode='HTML')


async def _handle_budget_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    name = context.user_data.get('budget_cat')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not name:
        context.user_data.pop('budget_cat', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל.")
        return
    amount = 0 if text.strip() in ('0', '-') else pln.parse_cost(text)
    if amount is None:
        await update.message.reply_text("❌ שלח סכום, למשל 1500 (0 = ביטול)")
        return
    context.user_data.pop('budget_cat', None)
    context.user_data['state'] = None
    data = ecat.load()
    name = ecat.set_budget(data, name, amount)
    ecat.save(data)
    await update.message.reply_text(f"✅ תקציב {name}: ₪{amount:,.2f} לחודש" if amount else f"🗑 התקציב של {name} בוטל")
    view, markup = _budget_view()
    await _planner_reply(update, view, reply_markup=markup)


def _budget_alert_for(entry):
    """The budget warning this purchase triggers, if any (current month only)."""
    try:
        cat = ecat.category_of(entry)
        month_key = ex.cycle_month_for(_israel_today())
        if cat == ecat.UNCATEGORISED or ex.cycle_month_of(entry) != month_key:
            return None
        data = ecat.load()
        text = ecat.budget_alert(data, _load_spend_entries(), month_key, cat)
        if text:
            ecat.save(data)
        return text
    except Exception as e:
        _planner_log(f"budget alert failed: {e}")
        return None


