# ------------------------------------------------------------------ the עו"ש between salaries

def _money_status(today=None):
    """(status, pay-period key, salary window) for the עו"ש right now."""
    today = today or _israel_today()
    plan = sp.load_plan()          # only the payments are needed: no inflation lookup
    start, period = mal.start_balance(plan)
    entries = _load_spend_entries()
    key = ex.cycle_month_for(today)
    this_total = ex.month_summary(entries, key, cycle=True)['total']
    last_total = ex.month_summary(entries, ecat.previous_month(key), cycle=True)['total']
    paid = any(p.get('month') == today.strftime('%Y-%m') for p in plan.get('payments') or [])
    window = mal.salary_window(today, paid)
    s = mal.status(start, _checking_balance(), this_total, last_total, today, window)
    s['top'] = list(ecat.by_category(entries, key).items())[:3]
    return s, (period or key), window


MUTE_SPEND = InlineKeyboardMarkup([[InlineKeyboardButton("🔕 הפסק להזכיר עד המשכורת", callback_data="mal:spend")]])
MUTE_NEG = InlineKeyboardMarkup([[InlineKeyboardButton("🔕 הפסק להזכיר", callback_data="mal:neg")]])


async def _check_money_alerts(send):
    """Right after money left the עו"ש: say so the moment it went negative, or a spending
    level (70/80/90/95% used, or past last month) was crossed."""
    try:
        today = _israel_today()
        s, period, window = _money_status(today)
        data = wl.load()
        st = mal.state(data)
        went_negative = mal.negative_crossing(st, s['checking'])
        crossed = mal.new_spend_crossing(st, period, s)
        wl.save(data)
        if went_negative:
            await send(mal.format_negative_alert(s['checking'], today, window, _emergency_fund(), first=True),
                       parse_mode='Markdown', reply_markup=MUTE_NEG)
        elif crossed:
            await send(mal.format_spend_alert(s, today, window, s['top'], first=True),
                       parse_mode='Markdown', reply_markup=MUTE_SPEND)
    except Exception as e:
        _planner_log(f"money alert failed: {e}")


async def _send_daily_money_alerts(app):
    """20:00 every day: a negative עו"ש, or one running low / past last month, until muted."""
    try:
        today = _israel_today()
        s, period, window = _money_status(today)
        data = wl.load()
        st = mal.state(data)
        if st.get('last_daily') == today.isoformat():
            return
        mal.negative_crossing(st, s['checking'])
        mal.new_spend_crossing(st, period, s)
        st['last_daily'] = today.isoformat()
        wl.save(data)
        if s['checking'] < 0 and not st.get('negative_muted'):
            await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown', reply_markup=MUTE_NEG,
                                       text=mal.format_negative_alert(s['checking'], today, window, _emergency_fund()))
        elif mal.spend_due(st, period, s):
            await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown', reply_markup=MUTE_SPEND,
                                       text=mal.format_spend_alert(s, today, window, s['top']))
    except Exception as e:
        _planner_log(f"daily money alert failed: {e}")


async def money_alert_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """mal:spend | mal:neg -- mute; mal:on -- back on."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    which = (query.data or '').split(':')[1]
    data = wl.load()
    st = mal.state(data)
    _, period, _ = _money_status()
    if which == 'spend':
        st['spend_muted'] = period
        note = "🔕 לא אזכיר על ההוצאות עד המשכורת הבאה."
    elif which == 'neg':
        st['negative_muted'] = True
        note = "🔕 לא אזכיר על המינוס עד שהעו\"ש יחזור לפלוס."
    else:
        st['spend_muted'] = None
        st['negative_muted'] = False
        note = "🔔 ההתראות חזרו."
    wl.save(data)
    await query.answer(note, show_alert=True)
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass


