# ------------------------------------------------------------------ last month in review

async def _spending_review_text(month_key, refresh=False):
    """Claude's review of one spending month (cached until its purchases change)."""
    entries = sorted(ex.month_summary(_load_spend_entries(), month_key, cycle=True)['entries'],
                     key=lambda e: (e.get('date', ''), e.get('time', '')))
    start, end = ex.cycle_range(month_key)
    rng = f"{start.strftime('%d/%m')}–{end.strftime('%d/%m')}"
    label = wl.month_label(month_key)
    if not entries:
        return f"🧐 <b>סקירת הוצאות — {label}</b>\n\nאין הוצאות רשומות בחודש הזה.", False
    total = round(sum(float(e.get('amount') or 0) for e in entries), 2)
    prev_total = ex.month_summary(_load_spend_entries(), ecat.previous_month(month_key), cycle=True)['total']
    data = wl.load()
    cached = data.setdefault('reviews', {}).get(month_key)
    if cached and not refresh and cached.get('total') == total and cached.get('count') == len(entries):
        result = cached['result']
        was = cached.get('cost')
        footer = ("🤖 Claude Opus 5.5 · מהזיכרון — בלי עלות נוספת"
                  + (f" (הניתוח המקורי עלה {_ai_cost_text(was)})" if was is not None else ""))
    else:
        if not anthropic_client:
            return "❌ ANTHROPIC_API_KEY לא מוגדר — אי אפשר לנתח.", False
        salary = sum(float(p.get('amount') or 0) for p in sp.load_plan().get('payments') or [] if p.get('month') == month_key)
        result, cost = await asyncio.to_thread(mal.review, anthropic_client, entries, label, total, prev_total,
                                               salary, ecat.budgets(ecat.load()))
        try:
            api_spend.record_spend([{'name': 'Claude Opus 5.5 spending review', 'cost': cost}], 'review')
        except Exception as e:
            _planner_log(f"review spend log failed: {e}")
        data['reviews'][month_key] = {'total': total, 'count': len(entries), 'result': result,
                                      'at': _israel_today().isoformat(), 'cost': round(cost, 4)}
        wl.save(data)
        footer = f"🤖 Claude Opus 5.5 · עלות הניתוח: {_ai_cost_text(cost)}"
    return mal.format_review(result, entries, label, rng, total, prev_total) + f"\n\n_{footer}_", True


def _ai_cost_text(usd):
    """'$0.034 (~₪0.10)' at the last dollar rate you converted at (else 3.6)."""
    rates = [c.get('fx_rate') for c in _load_portfolio().get('cash_log') or [] if c.get('fx_rate')]
    rate = float(rates[-1]) if rates else 3.6
    return f"${usd:.3f} (~₪{usd * rate:.2f})"


def _review_months(limit=5):
    """This spending month and the ones before it that have purchases, newest first."""
    current = ex.cycle_month_for(_israel_today())
    months = [k for k in ex.available_months(_load_spend_entries(), include=[current], cycle=True) if k <= current]
    return current, sorted(months, reverse=True)[:limit]


async def _send_review(target, key):
    """Review one month and post it, with a redo button."""
    await target.message.reply_text(f"🧐 מנתח את ההוצאות של {wl.month_label(key)}...")
    try:
        text, ok_ = await _spending_review_text(key)
    except Exception as e:
        _planner_log(f"/spendingreview failed: {e}")
        await target.message.reply_text(f"❌ לא הצלחתי לנתח: {e}")
        return
    if key == ex.cycle_month_for(_israel_today()):
        text = text.replace('\n', '\n_החודש עוד לא נגמר — עד עכשיו_\n', 1)
    await _planner_reply(target, text, reply_markup=InlineKeyboardMarkup([[
        InlineKeyboardButton("🔄 נתח שוב", callback_data=f"rev:{key}")]]) if ok_ else None)


