# ------------------------------------------------------------------ the week in US stocks

def _live_us_day():
    """Today so far for the US stocks: value, P/L since yesterday's close. Blocking.
    None when the market has not moved yet (closed, or not open today)."""
    stocks, value, prev_value = {}, 0.0, 0.0
    for h in _load_portfolio().get('holdings') or []:
        shares = float(h.get('shares') or 0)
        if not shares:
            continue
        try:
            info = yf.Ticker(h['symbol']).info
            price = float(info.get('regularMarketPrice') or info.get('currentPrice') or 0)
            prev = float(info.get('regularMarketPreviousClose') or info.get('previousClose') or 0)
        except Exception:
            return None
        if not price or not prev:
            return None
        held_before = stocks.get(h['symbol'], (0.0, price))[0]
        stocks[h['symbol']] = (held_before + shares, price)       # {symbol: (shares, price)}
        value += shares * price
        prev_value += shares * prev
    if not stocks or abs(value - prev_value) < 0.005:
        return None
    pl = value - prev_value
    return {'value': value, 'pl': pl, 'pct': pl / prev_value * 100 if prev_value else 0.0, 'stocks': stocks}


async def weeklypl_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/weeklypl - this week's US stocks: the start value, every day, today live, the total."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    today = _israel_today()
    w = wk.week(_load_portfolio().get('portfolio_log') or [], today)
    if not w:
        await update.message.reply_text("❌ אין עדיין צילומים יומיים של התיק.")
        return
    await update.message.reply_text("🔄 מחשב את השבוע...")
    live = None
    if today.weekday() < 5 and not any(d['date'] == today for d in w['days']):
        live = await asyncio.to_thread(_live_us_day)
    usd_ils = await asyncio.to_thread(_usd_ils_quick)
    await _planner_reply(update, wk.format_week(w, usd_ils, live, today))


async def _send_weekly_pl(app, today):
    """Saturday 10:00: the week that just ended (Friday's close is logged at 23:15)."""
    try:
        data = wl.load()
        monday = wk.week_start(today).isoformat()
        if data.get('weekly_sent') == monday:
            return
        w = wk.week(_load_portfolio().get('portfolio_log') or [], today)
        if not w or not w['days']:
            return
        usd_ils = await asyncio.to_thread(_usd_ils_quick)
        await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown',
                                   text=wk.format_week(w, usd_ils, None, today, auto=True))
        data['weekly_sent'] = monday
        wl.save(data)
    except Exception as e:
        _planner_log(f"weekly P/L failed: {e}")


