def _held_symbols():
    return sorted({h['symbol'].upper() for h in _load_portfolio().get('holdings') or [] if float(h.get('shares') or 0) > 0})


def _thesis_buttons(symbols):
    rows = [[InlineKeyboardButton(f"✏️ {s}", callback_data=f"ths:edit:{s}"),
             InlineKeyboardButton(f"📘 {s}", callback_data=f"ths:plan:{s}")] for s in symbols]
    return InlineKeyboardMarkup(rows)


PLAYBOOK_STEPS = [('ok', '✅ <b>מה תעשה אם הדוח שומר על התזה?</b>'),
                  ('weak', '⚠️ <b>מה תעשה אם התזה נחלשת?</b>'),
                  ('broken', '❌ <b>מה תעשה אם התזה נשברת?</b>')]


async def _ask_playbook(message, context):
    sym, i = context.user_data['playbook_sym'], context.user_data['playbook_i']
    k, q = PLAYBOOK_STEPS[i]
    current = ((th.load()['stocks'].get(sym) or {}).get('plan') or {}).get(k)
    await message.reply_text(
        f"📘 {sym} ({i + 1}/3)\n{q}\n<i>למשל: \"מחזיק\", \"חותך חצי\", \"מוכר הכול ומעביר ל-VTI\"</i>"
        + (f"\n\nעכשיו: {html.escape(current)}\n<i>(- כדי להשאיר)</i>" if current else "\n<i>(- כדי לדלג)</i>"),
        parse_mode='HTML')


async def _handle_playbook_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    sym = context.user_data.get('playbook_sym')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not sym:
        context.user_data['state'] = None
        context.user_data.pop('playbook_sym', None)
        await update.message.reply_text("❌ בוטל.")
        return
    i = context.user_data.get('playbook_i', 0)
    k = PLAYBOOK_STEPS[i][0]
    data = th.load()
    entry = data['stocks'].setdefault(sym, {'why': '', 'breaks': '', 'created': _israel_today().isoformat(), 'reviews': []})
    plan = entry.setdefault('plan', {})
    if text != '-':
        plan[k] = th.clean(text)
    entry['updated'] = _israel_today().isoformat()
    th.save(data)
    if i + 1 < len(PLAYBOOK_STEPS):
        context.user_data['playbook_i'] = i + 1
        await _ask_playbook(update.message, context)
        return
    context.user_data['state'] = None
    context.user_data.pop('playbook_sym', None)
    await _planner_reply(update, "✅ התוכנית נשמרה — אחרי כל דוח היא תופיע ליד העובדות.\n\n"
                         + th.format_thesis(sym, th.load()['stocks'].get(sym)))


