async def _earnings_jobs(app, now):
    """Daily: refresh the holdings' earnings dates; 10:00 remind the day before; 18:00 ask after."""
    try:
        today = now.date()
        data = th.load()
        held = _held_symbols()
        if data['earnings'].get('fetched') != today.isoformat() or set(held) - set(data['earnings'].get('dates') or {}):
            data['earnings'] = {'fetched': today.isoformat(), 'dates': await asyncio.to_thread(th.fetch_earnings, held)}
            th.save(data)
        if now.hour >= 10:
            for sym in th.due_reminders(data, today):
                e = data['earnings']['dates'][sym]
                text = th.format_reminder(sym, e, data['stocks'].get(sym))
                prediction = await _earnings_prediction(sym, e['date'], data['stocks'].get(sym))
                if prediction:
                    text += "\n\n" + ea.format_prediction(sym, prediction)
                await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown', text=text)
                data['reminded'][sym] = e['date']
                th.save(data)
        if now.hour >= 18:
            for sym in th.due_reviews(data, today):
                d = data['earnings']['dates'][sym]['date']
                await app.bot.send_message(
                    chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown',
                    text=th.format_review_question(sym, d, data['stocks'].get(sym)),
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(label, callback_data=f"ths:{key}:{sym}:{d}")
                                                        for key, label in th.VERDICTS.items()]]))
                data['asked'][sym] = d
                th.save(data)
    except Exception as e:
        _planner_log(f"earnings jobs failed: {e}")


# ------------------------------------------------------------------ /rebalance

async def rebalance_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/rebalance [VTI %] [steps] [new $] - buys and sells to reach the mix, in steps, with the tax estimate."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = list(context.args or [])
    try:
        pct = float(args[0].replace('%', '')) if args else 80.0
        steps = int(args[1]) if len(args) > 1 else 1
        new_money = float(args[2].replace('$', '').replace(',', '')) if len(args) > 2 else 0.0
        if not 1 <= pct <= 99 or not 1 <= steps <= 24 or new_money < 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ למשל: /rebalance 80 4 — 80% VTI, ב-4 שלבים (אפשר להוסיף כסף חדש: /rebalance 80 4 2000)")
        return
    await update.message.reply_text("🔄 מחשב לפי המחירים של היום...")
    try:
        shares, history = await _vti_data()
    except Exception as e:
        await update.message.reply_text(f"❌ לא הצלחתי להביא מחירים: {e}")
        return
    cost = {}
    for h in _load_portfolio().get('holdings') or []:
        s, sh = h['symbol'].upper(), float(h.get('shares') or 0)
        if sh > 0:
            prev = cost.get(s, (0.0, 0.0))
            cost[s] = (prev[0] + sh, prev[1] + sh * float(h.get('purchase_price') or 0))
    positions = {s: {'shares': shares[s], 'price': history[s][-1][1],
                     'cost': (cost[s][1] / cost[s][0]) if cost.get(s) and cost[s][0] else history[s][-1][1]}
                 for s in shares if history.get(s)}
    if vr.VTI not in positions:
        positions[vr.VTI] = {'shares': 0.0, 'price': history[vr.VTI][-1][1], 'cost': history[vr.VTI][-1][1]}
    p = rb.plan(positions, pct, steps, new_money)
    await _planner_reply(update, rb.format_plan(p, pct, steps, new_money))


# ------------------------------------------------------------------ earnings: predict, report, grade, learn

def _thesis_text(entry):
    if not entry or not entry.get('why'):
        return None
    return f"why: {entry['why']} | breaks if: {entry.get('breaks') or '-'}"


def _moves_text(rows):
    def r(days):
        cut = rows[-1][0] - timedelta(days=days)
        past = [c for d, c in rows if d <= cut]
        return (rows[-1][1] / past[-1] - 1) * 100 if past else None
    parts = [f"{label} {v:+.1f}%" for label, v in (("1m", r(30)), ("3m", r(91)), ("1y", r(365))) if v is not None]
    return ", ".join(parts) or "unknown"


async def _earnings_prediction(sym, day, thesis_entry):
    """Claude's prediction for tomorrow's report, kept for grading. None without Claude."""
    if not anthropic_client:
        return None
    token = os.getenv('FINNHUB_API_KEY')
    try:
        data = ea.load()
        k = ea.key(sym, day)
        if k in data['predictions']:
            return data['predictions'][k]

        def gather():
            rows = ea.closes(sym)
            today = _israel_today()
            return (ea.finnhub_calendar(sym, day, token), ea.past_reactions(sym, rows), _moves_text(rows),
                    ea.finnhub_news(sym, today - timedelta(days=7), today, token))
        cal, history, moves, news = await asyncio.to_thread(gather)
        prediction, cost = await asyncio.to_thread(ea.predict, anthropic_client, data, sym, day, cal, history, moves,
                                                   news, _thesis_text(thesis_entry))
        ea.save(data)
        api_spend.record_spend([{'name': 'Claude Opus 5.5 earnings prediction', 'cost': cost}], 'earnings')
        return prediction
    except Exception as e:
        _planner_log(f"earnings prediction {sym} failed: {e}")
        return None


async def _earnings_ai_jobs(app, now):
    """Every loop: a report as soon as results are out (checked every 30 min), then the grade
    once the session that reacted to it has closed."""
    if not anthropic_client:
        return
    token = os.getenv('FINNHUB_API_KEY')
    try:
        tdata = th.load()
        dates = tdata['earnings'].get('dates') or {}
        data = ea.load()
        today = now.date()
        for sym, e in dates.items():
            day = e.get('date')
            if not day or not (today - timedelta(days=4) <= date.fromisoformat(day) <= today):
                continue
            k = ea.key(sym, day)
            if k not in data['reports']:
                last = data['checked'].get(k)
                if last and now - datetime.fromisoformat(last) < timedelta(minutes=30):
                    continue
                data['checked'][k] = now.isoformat(timespec='minutes')
                ea.save(data)
                cal = await asyncio.to_thread(ea.finnhub_calendar, sym, day, token)
                if not cal or cal.get('epsActual') is None:
                    continue

                def early():
                    rows = ea.closes(sym, 30)
                    before = [c for d, c in rows if d < ea.reaction_day(day, cal.get('hour'))]
                    try:
                        info = yf.Ticker(sym).info
                        price = info.get('postMarketPrice') or info.get('preMarketPrice') or info.get('regularMarketPrice')
                    except Exception:
                        price = None
                    move = (float(price) / before[-1] - 1) if price and before else None
                    news = ea.finnhub_news(sym, date.fromisoformat(day) - timedelta(days=1), today + timedelta(days=1), token)
                    return move, news
                move, news = await asyncio.to_thread(early)
                r, cost = await asyncio.to_thread(ea.report, anthropic_client, data, sym, day, cal, move, news,
                                                  _thesis_text(tdata['stocks'].get(sym)))
                ea.save(data)
                api_spend.record_spend([{'name': 'Claude Opus 5.5 earnings report', 'cost': cost}], 'earnings')
                tdata['asked'][sym] = day                      # the report carries the thesis buttons
                th.save(tdata)
                await app.bot.send_message(
                    chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown',
                    text=ea.format_report(sym, r, data['predictions'].get(k)),
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(label, callback_data=f"ths:{v}:{sym}:{day}")
                                                        for v, label in th.VERDICTS.items()]]))
                continue
            if k in data['grades']:
                continue
            hour = (data['reports'][k].get('cal') or {}).get('hour')
            rd = ea.reaction_day(day, hour)
            if today < rd or (today == rd and (now.hour, now.minute) < (23, 30)):
                continue
            rows = await asyncio.to_thread(ea.closes, sym, 30)
            moved = ea.reaction(rows, day, hour)
            if moved is None:
                continue
            news = await asyncio.to_thread(ea.finnhub_news, sym, date.fromisoformat(day), today, token)
            g, cost = await asyncio.to_thread(ea.grade, anthropic_client, data, sym, day, moved, news)
            ea.save(data)
            if cost:
                api_spend.record_spend([{'name': 'Claude Opus 5.5 earnings grade', 'cost': cost}], 'earnings')
            await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, parse_mode='Markdown',
                                       text=ea.format_grade(sym, g, data['predictions'].get(k), data))

            async def send(text, **kw):
                await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, text=text, **kw)
            await _send_debrief(send, sym, day)
    except Exception as e:
        _planner_log(f"earnings AI jobs failed: {e}")


