# ------------------------------------------------------------------ /debrief

def _debrief_gather(sym, day, hour_hint=None, cal=None):
    """Everything the debrief needs, fetched in one go. Blocking."""
    import math as _m
    t = yf.Ticker(sym)
    info = t.info or {}
    rows = ea.closes(sym, 1200)
    er = []
    try:
        for ts, r in t.get_earnings_dates(limit=16).iterrows():
            rep_eps = r.get('Reported EPS')
            if rep_eps is None or (isinstance(rep_eps, float) and _m.isnan(rep_eps)):
                continue
            sp = r.get('Surprise(%)')
            er.append((ts, None if sp is None or (isinstance(sp, float) and _m.isnan(sp)) else float(sp)))
    except Exception:
        pass
    table = dbf.history_table(er, rows)
    match = next((x for x in table if x['date'] == day), None)
    hour = hour_hint or ('bmo' if any(ts.date().isoformat() == day and ts.hour < 12 for ts, _ in er) else 'amc')
    reaction = ea.reaction(rows, day, hour)
    rd = ea.reaction_day(day, hour)

    span = max(40, (_israel_today() - rd).days + 15)     # an older report needs older prices

    def change_on(symbol):
        r = ea.closes(symbol, span)
        on = [c for d, c in r if d == rd]
        before = [c for d, c in r if d < rd]
        return (on[0] / before[-1] - 1) * 100 if on and before else None
    sectors = dbf.sector_etfs(info)
    vti_rows = ea.closes('VTI', 60)
    tnx = ea.closes('^TNX', 60)
    oil = ea.closes('CL=F', 10)
    revisions = None
    try:
        ny = t.eps_trend.loc['+1y']
        if ny['7daysAgo']:
            revisions = (ny['current'] / ny['7daysAgo'] - 1) * 100
    except Exception:
        pass
    surprise = match['surprise'] if match else None
    if surprise is None and cal and cal.get('epsActual') is not None and cal.get('epsEstimate'):
        surprise = (cal['epsActual'] / cal['epsEstimate'] - 1) * 100
    return {'info': info, 'rows': rows, 'table': table, 'hour': hour, 'rd': rd,
            'reaction': None if reaction is None else reaction * 100, 'surprise': surprise,
            'market': change_on('VTI'), 'sectors': {s: change_on(s) for s in sectors},
            'vti_1m': (vti_rows[-1][1] / vti_rows[-22][1] - 1) * 100 if len(vti_rows) > 22 else None,
            'tnx': tnx[-1][1] if tnx else None, 'tnx_1m': (tnx[-1][1] - tnx[-22][1]) if len(tnx) > 22 else None,
            'oil': oil[-1][1] if oil else None, 'revisions': revisions,
            # the headlines around the report, not today's
            'news': ea.finnhub_news(sym, date.fromisoformat(day) - timedelta(days=1),
                                    min(_israel_today() + timedelta(days=1), rd + timedelta(days=4)),
                                    os.getenv('FINNHUB_API_KEY'))}


async def _send_debrief(send, sym, day=None):
    """The debrief and the options for SYM's report on `day` (the latest one if None)."""
    data = ea.load()
    if not day:
        keys = sorted((k for k in data['reports'] if k.startswith(sym + ':')), key=lambda k: k.split(':')[1])
        day = keys[-1].split(':')[1] if keys else None
    if not day:
        dates = (th.load()['earnings'].get('dates') or {}).get(sym) or {}
        day = dates.get('date') if dates.get('date') and dates['date'] <= _israel_today().isoformat() else None
    rep_ = data['reports'].get(ea.key(sym, day)) if day else None
    cal = (rep_ or {}).get('cal')
    try:
        if day is None:
            # no report on record: the last one in its history
            def last_day():
                import math as _m
                for ts, r in yf.Ticker(sym).get_earnings_dates(limit=8).iterrows():
                    v = r.get('Reported EPS')
                    if v is not None and not (isinstance(v, float) and _m.isnan(v)):
                        return ts.date().isoformat()
            day = await asyncio.to_thread(last_day)
            if not day:
                await send(f"❌ לא מצאתי דוח של {sym}.")
                return
        g = await asyncio.to_thread(_debrief_gather, sym, day, (cal or {}).get('hour'), cal)
    except Exception as e:
        _planner_log(f"/debrief {sym} gather failed: {e}")
        await send(f"❌ לא הצלחתי לאסוף נתונים ל-{sym}: {e}")
        return
    f = dbf.fit(g['table'], g['surprise'], g['reaction'], exclude_date=day)
    tdata = th.load()
    entry = tdata['stocks'].get(sym) or {}
    reviews = [r for r in entry.get('reviews') or [] if r.get('earnings') == day]
    verdict = reviews[-1]['verdict'] if reviews else (rep_ or {}).get('thesis_verdict')
    verdict = verdict if verdict in th.VERDICTS else None
    analysis = {}
    if anthropic_client:
        def fmt(x, suffix='%'):
            return 'unknown' if x is None else f"{x:+.1f}{suffix}"
        ctx = {
            'symbol': sym,
            'report': json.dumps({k: (cal or {}).get(k) for k in ('epsActual', 'epsEstimate', 'revenueActual', 'revenueEstimate')}
                                 if cal else {'eps_surprise_pct': g['surprise']}, ensure_ascii=False)
                      + ((' · bot summary: ' + ' | '.join(rep_.get('summary') or [])) if rep_ else ''),
            'reaction': fmt(g['reaction']), 'reaction_day': str(g['rd']), 'market': fmt(g['market']),
            'sector_moves': ', '.join(f"{k} {fmt(v)}" for k, v in g['sectors'].items()) or 'unknown',
            'price': g['rows'][-1][1] if g['rows'] else 'unknown', 'fpe': g['info'].get('forwardPE'),
            'target': g['info'].get('targetMeanPrice'), 'revisions': fmt(g['revisions']),
            'vti_1m': fmt(g['vti_1m']), 'tnx': 'unknown' if g['tnx'] is None else f"{g['tnx']:.2f}%",
            'tnx_change': fmt(g['tnx_1m'], ' pts'), 'oil': 'unknown' if g['oil'] is None else f"${g['oil']:.0f}",
            'news': json.dumps(g['news'][:10], ensure_ascii=False), 'table': json.dumps(g['table'][:10], ensure_ascii=False),
            'fit': json.dumps(f, ensure_ascii=False, default=str)}
        try:
            analysis, cost = await asyncio.to_thread(dbf.ask, anthropic_client, ctx)
            api_spend.record_spend([{'name': 'Claude Opus 5.5 earnings debrief', 'cost': cost}], 'earnings')
        except Exception as e:
            _planner_log(f"/debrief {sym} Claude failed: {e}")
    verdict_text = (f"🧭 התזה שלך: {th.VERDICTS[verdict]}" if verdict else None)
    await send(dbf.format_debrief(sym, analysis, f, g['reaction'], verdict_text), parse_mode='Markdown')

    # the options in numbers
    portfolio = _load_portfolio()
    shares = sum(float(h.get('shares') or 0) for h in portfolio.get('holdings') or [] if h['symbol'].upper() == sym)
    if not shares:
        return
    cost_total = sum(float(h.get('shares') or 0) * float(h.get('purchase_price') or 0)
                     for h in portfolio.get('holdings') or [] if h['symbol'].upper() == sym)
    price = g['rows'][-1][1]
    logs = portfolio.get('portfolio_log') or []
    us_total = float(logs[-1].get('value') or 0) if logs else shares * price
    rows = dbf.options(shares, price, cost_total / shares, us_total, float(portfolio.get('tax_shield_balance') or 0))
    destinations = None
    try:
        today = _israel_today()
        if today not in _VTI_LONG:
            _VTI_LONG.clear()
            _VTI_LONG[today] = await asyncio.to_thread(vr.fetch_long, [vr.VTI] + [s for s, _ in vr.DEFENSIVE])
        long = _VTI_LONG[today]
        destinations = [(s, name, vr.path_stats(long[s], today, long.get(vr.VTI))) for s, name in dbf.DESTINATIONS if long.get(s)]
    except Exception as e:
        _planner_log(f"/debrief destinations failed: {e}")
    await send(dbf.format_options(sym, rows, price, float(portfolio.get('tax_shield_balance') or 0),
                                  entry.get('plan') or {}, verdict, destinations), parse_mode='Markdown')


