def _monthly_spend_basis():
    """(₪ a month, where it comes from): /setplan's expected spending, else the real average."""
    plan = sp.load_plan()
    if plan.get('expected_spend'):
        return float(plan['expected_spend']), 'ההוצאה הצפויה מ-/setplan'
    avg, used = wl.average_spending(_load_spend_entries(), _israel_today())
    return avg, f"ממוצע {len(used)} החודשים האחרונים"


async def fi_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/fi - financial independence: the number, how far along, years to get there."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    spend, spend_basis = _monthly_spend_basis()
    if not spend:
        await update.message.reply_text("❌ אין עדיין הוצאה חודשית — קבע ב-/setplan או רשום הוצאות.")
        return
    snaps = wl.load()['snapshots']
    if snaps:
        current, current_basis = float(snaps[-1].get('liquid') or 0), f"צילום /networth {snaps[-1]['date']}"
    else:
        await update.message.reply_text("🔄 מחשב שווי (אין עדיין צילום /networth)...")
        result, _, _ = await asyncio.to_thread(_horizons_fetch)
        current, current_basis = float(result['liquid']), 'שווי נזיל עכשיו'
    rows = wl.savings_rows(sp.load_plan())
    if rows:
        monthly, saving_basis = sum(r['saved'] for r in rows[-3:]) / len(rows[-3:]), 'ממוצע מ-/savingsrate'
    else:
        plan = sp.load_plan()
        monthly = max(0.0, float((plan.get('salary') or {}).get('amount') or 0) - spend)
        saving_basis = 'הכנסה פחות הוצאה'
    await _planner_reply(update, fim.format_fi(spend * 12, spend_basis + ' × 12', current, monthly, saving_basis, current_basis))


