    spend, _ = _monthly_spend_basis()
    if not salary or not spend:
        await target.message.reply_text("❌ חסרה הכנסה או הוצאה חודשית — קבע ב-/setplan.")
        return
    keren = float(plan.get('keren_self_monthly') or 0)
    emergency = _emergency_fund()
    w = fim.whatif(salary, spend, keren, emergency, drop, months)
