async def visa_reserve_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """visares:go -- take older Visa purchases (logged before set-aside existed) off the עו"ש now."""
    query = update.callback_query
    await query.answer()
    if not is_authorized(query.from_user.id):
        return
    try:
        entries = _load_spend_entries()
        rows = ex.unreserved(ex.pending_visa(entries))
        amount = ex.total_of(rows)
        if rows:
            before = _checking_balance()
            after = round(before - amount, 2)
            _set_checking_balance(after)
            for e in rows:                      # the same objects as in `entries`
                e['reserved'] = True
            _save_spend_entries(entries)
            _log_ils_checking_transaction(amount, "spend", f"ויזה נשמרה בצד ({len(rows)} רכישות)", after)
        text, markup = _visa_view()
        if rows:
            text = f"✅ ירד מהעו\"ש: {ex.money(before)} → <b>{ex.money(after)}</b>\n\n" + text
        await query.edit_message_text(text, parse_mode='HTML', reply_markup=markup)
    except Exception as e:
        _planner_log(f"/visa set-aside failed: {e}")
        await query.edit_message_text(f"❌ Error: {e}")


