async def _canibuy_reply(update, context, raw):
    try:
        amount = float(raw.replace('₪', '').replace(',', '').strip())
    except ValueError:
        amount = 0
    if amount <= 0:
        context.user_data['state'] = 'canibuy_amount'
        await update.message.reply_text("❌ שלח סכום בשקלים, למשל 250 (או cancel)")
        return
    context.user_data.pop('state', None)
    await update.message.reply_text(_canibuy_text(amount), parse_mode='HTML')


async def _handle_canibuy_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('state', None)
        await update.message.reply_text("בוטל.")
        return
    await _canibuy_reply(update, context, text)


