async def ilspend(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Spend money from עו\"ש (checking account) - tracks purchases"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    try:
        # Load main portfolio to get ILS_checking balance
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        try:
            with open(portfolio_file, 'r', encoding='utf-8') as f:
                portfolio_data = json.load(f)
        except:
            portfolio_data = {}
        
        reserves = portfolio_data.get('reserves', {})
        checking = reserves.get('ILS_checking', 0)
        
        # Card first: it decides whether this leaves /ilcash now or on the 10th.
        pending = ex.total_of(ex.pending_visa(_load_spend_entries()))

        context.user_data['ilspend'] = {}
        context.user_data['state'] = 'ilspend_card'

        await update.message.reply_text(
            f"💳 <b>הוצאה מעוש</b>\n\n"
            f"יתרה נוכחית: <b>{ex.money(checking)}</b>\n"
            f"<i>עם מסגרת המינוס אפשר להוציא עד {ex.money(max(0.0, ex.room(checking)))}</i>\n"
            + (f"🟦 ויזה ממתינה: <b>₪{pending:,.2f}</b>\n" if pending else "")
            + f"💵 מזומן: <b>₪{_cash_balance():,.2f}</b>\n"
            + f"\nאיך שילמת?\n"
            f"<b>1</b> = 💳 דביט (יורד מיד מהעו\"ש)\n"
            f"<b>2</b> = 🟦 ויזה (יורד מהעו\"ש כבר עכשיו ונשמר לחיוב ב-{ex.charge_date_for(_israel_today()).strftime('%d/%m')})\n"
            f"<b>3</b> = 💵 מזומן (יורד מהמזומן)\n\n"
            f"📸 <i>או שלח צילום של החשבונית — הבוט יסרוק את הפריטים</i>\n"
            f"<i>שלח cancel לביטול</i>",
            parse_mode='HTML'
        )
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _handle_ilspend_card(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Which card paid: 1 = debit (leaves /ilcash now), 2 = visa (2nd of next month)."""
    text = (update.message.text or '').strip().lower()

    if text in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('ilspend', None)
        context.user_data.pop('state', None)
        await update.message.reply_text("❌ בוטל")
        return

    card = ex.CARD_BY_DIGIT.get(text)
    if not card and text in ('debit', 'דביט'):
        card = ex.DEBIT
    if not card and text in ('visa', 'ויזה'):
        card = ex.VISA
    if not card and text in ('cash', 'מזומן'):
        card = ex.CASH
    if not card:
        await update.message.reply_text("❌ שלח 1 (דביט), 2 (ויזה) או 3 (מזומן)")
        return

    today = _israel_today()
    context.user_data['ilspend']['card'] = card
    context.user_data['ilspend']['date'] = today.strftime('%Y-%m-%d')
    context.user_data['state'] = 'ilspend_amount'

    if card == ex.VISA:
        charge_day = ex.charge_date_for(today)
        extra = f"\n<i>יחויב ב-{charge_day.strftime('%d/%m/%Y')}</i>"
    elif card == ex.CASH:
        extra = f"\n<i>יורד מהמזומן (₪{_cash_balance():,.2f})</i>"
    else:
        extra = "\n<i>יורד מיד מהעו\"ש</i>"

    # The date buttons are optional: the amount can be sent straight away and the
    # purchase is dated today unless a different day is tapped.
    await update.message.reply_text(
        f"{ex.CARD_EMOJI[card]} <b>{ex.CARD_LABEL[card]}</b>{extra}\n\n"
        f"📅 תאריך: <b>{today.strftime('%d/%m/%Y')}</b> (היום)\n"
        f"<i>אפשר לבחור יום אחר, גם מהחודש הקודם (◀️):</i>\n\n"
        f"כמה הוצאת? (שלח סכום)",
        parse_mode='HTML',
        reply_markup=_ilspend_date_keyboard(today)
    )


HEBREW_MONTHS = ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט',
                 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר']


def _ilspend_months(today):
    """(current 'YYYY-MM', previous 'YYYY-MM', last day of the previous month)."""
    prev_last = today.replace(day=1) - timedelta(days=1)
    return today.strftime('%Y-%m'), prev_last.strftime('%Y-%m'), prev_last


def _ilspend_date_keyboard(today, show_month=None, selected=None):
    """The days that can be picked: this month up to today (today marked ·N·), or,
    one tap away, every day of the previous month. A picked day shows as [N]."""
    current, previous, prev_last = _ilspend_months(today)
    show = show_month if show_month in (current, previous) else current
    if show == current:
        year, month, last = today.year, today.month, today.day
    else:
        year, month, last = prev_last.year, prev_last.month, prev_last.day
    rows, row = [], []
    for day in range(1, last + 1):
        this = datetime(year, month, day).date()
        if selected is not None and this == selected:
            label = f"[{day}]"
        elif this == today:
            label = f"·{day}·"
        else:
            label = str(day)
        row.append(InlineKeyboardButton(
            label, callback_data=f"ilspdate:{year:04d}-{month:02d}-{day:02d}"))
        if len(row) == 7:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    if show == current:
        rows.append([InlineKeyboardButton(f"◀️ {HEBREW_MONTHS[prev_last.month - 1]} (חודש קודם)",
                                          callback_data=f"ilspdate:month:{previous}")])
    else:
        rows.append([InlineKeyboardButton(f"▶️ {HEBREW_MONTHS[today.month - 1]} (החודש)",
                                          callback_data=f"ilspdate:month:{current}")])
    return InlineKeyboardMarkup(rows)


async def _ilspend_date_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Backdate the purchase being entered."""
    query = update.callback_query
    chosen = query.data.split(':', 1)[1]

    pending = context.user_data.get('ilspend')
    if pending is None:
        await query.answer("אין הוצאה פעילה. שלח /ilspend", show_alert=True)
        return

    today = _israel_today()
    current, previous, _ = _ilspend_months(today)
    try:
        selected = datetime.strptime(pending.get('date', ''), '%Y-%m-%d').date()
    except ValueError:
        selected = None

    if chosen.startswith('month:'):
        # Only flips which month's days are shown; the chosen date stays as it was.
        await query.answer()
        try:
            await query.edit_message_reply_markup(
                reply_markup=_ilspend_date_keyboard(today, chosen.split(':', 1)[1], selected))
        except Exception:
            pass
        return

    try:
        day = datetime.strptime(chosen, '%Y-%m-%d').date()
    except ValueError:
        await query.answer("תאריך לא תקין", show_alert=True)
        return
    # A button from an old message could point outside the window: never in the
    # future, never before the previous month.
    if day > today or day.strftime('%Y-%m') not in (current, previous):
        await query.answer("אפשר לבחור רק מהחודש הזה או מהחודש הקודם", show_alert=True)
        return

    pending['date'] = chosen
    await query.answer(f"תאריך: {day.strftime('%d/%m/%Y')}")
    card = pending.get('card', ex.DEBIT)
    note = ''
    if card == ex.VISA:
        charge = ex.charge_date_for(day)
        note = f"\n<i>יורד מהעו\"ש כבר עכשיו ונשמר לחיוב ב-{charge.strftime('%d/%m/%Y')}</i>"
    month_note = ''
    if day.strftime('%Y-%m') == previous:
        month_note = f"\n📌 יירשם בהוצאות של {HEBREW_MONTHS[day.month - 1]}"
        if card in (ex.DEBIT, ex.VISA):
            month_note += "\n<i>הכסף יורד מהעו\"ש עכשיו (כי עדיין לא נרשם)</i>"
    try:
        await query.edit_message_text(
            f"{ex.CARD_EMOJI[card]} <b>{ex.CARD_LABEL[card]}</b>{note}\n\n"
            f"📅 תאריך: <b>{day.strftime('%d/%m/%Y')}</b>{month_note}\n\n"
            f"כמה הוצאת? (שלח סכום)",
            parse_mode='HTML',
            reply_markup=_ilspend_date_keyboard(today, day.strftime('%Y-%m'), day))
    except Exception:
        pass


async def _handle_ilspend_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle amount input for ilspend"""
    try:
        text = update.message.text.strip().lower()

        # Check for cancel
        if text in ['cancel', 'ביטול', 'בטל']:
            context.user_data.pop('ilspend', None)
            context.user_data.pop('state', None)
            await update.message.reply_text("❌ בוטל")
            return
        
        amount_str = update.message.text.replace(',', '').replace('₪', '').strip()
        amount = float(amount_str)
        
        if amount <= 0:
            await update.message.reply_text("❌ הסכום חייב להיות חיובי")
            return
        
        # Check balance from main portfolio
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        
        reserves = portfolio_data.get('reserves', {})
        checking = reserves.get('ILS_checking', 0)
        
        # Each method draws on a different pot: debit on עו"ש, cash on cash in
        # hand, Visa on nothing yet because it is collected on the 2nd.
        card = context.user_data.get('ilspend', {}).get('card', ex.DEBIT)
        # The עו"ש may go into overdraft, down to -OVERDRAFT_LIMIT; only past that is refused.
        if card == ex.DEBIT and not ex.can_debit(checking, amount):
            await update.message.reply_text(ex.over_limit_text(checking, amount))
            return
        if card == ex.CASH and amount > _cash_balance():
            await update.message.reply_text(
                f"❌ אין מספיק מזומן!\n"
                f"יתרה: ₪{_cash_balance():,.2f}\n"
                f"מבוקש: ₪{amount:,.2f}\n\n"
                f"אפשר להוסיף מזומן עם /ilcashdeposit"
            )
            return
        
        context.user_data['ilspend']['amount'] = amount
        context.user_data['state'] = 'ilspend_description'
        
        await update.message.reply_text(
            f"💰 סכום: <b>₪{amount:,.2f}</b>\n\n"
            f"מה קנית? (תיאור קצר)",
            parse_mode='HTML'
        )
        
    except ValueError:
        await update.message.reply_text("❌ סכום לא תקין. שלח מספר.")


async def _handle_ilspend_description(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle description input for ilspend"""
    description = update.message.text.strip()
    
    # Check for cancel
    if description.lower() in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('ilspend', None)
        context.user_data.pop('state', None)
        await update.message.reply_text("❌ בוטל")
        return
    
    if not description:
        await update.message.reply_text("❌ שלח תיאור של הקנייה")
        return
    
    amount = context.user_data['ilspend'].get('amount', 0)

    # Reachable only if the amount step was skipped or rejected; without this a
    # description sent at the wrong moment records a ₪0.00 purchase.
    if not amount or amount <= 0:
        context.user_data.pop('ilspend', None)
        context.user_data.pop('state', None)
        await update.message.reply_text("❌ לא נקלט סכום תקין. התחל מחדש עם /ilspend")
        return

    card = context.user_data.get('ilspend', {}).get('card', ex.DEBIT)
    spend_date = context.user_data.get('ilspend', {}).get('date')
    await _record_spend(update.message, context, amount, description, card, spend_date)


async def _record_spend(message, context, amount, description, card, spend_date=None, extra=None):
    """Log one purchase and move the money the way its card does: debit leaves the
    עו"ש now, cash leaves the cash in hand, Visa waits for its charge day. Used by
    /ilspend and by a scanned receipt. Returns the spending_log entry."""
    # Load main portfolio to update ILS_checking
    main_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(main_portfolio_file, 'r', encoding='utf-8') as f:
        main_portfolio = json.load(f)
    
    reserves = main_portfolio.get('reserves', {})
    checking = reserves.get('ILS_checking', 0)

    # Debit leaves עו"ש now, cash leaves the cash in hand now. Visa also leaves the
    # עו"ש now (your choice): the money is set aside so the charge on the 10th
    # finds it already gone and the עו"ש does not suddenly drop into overdraft.
    new_cash = reserves.get('ILS_cash', 0)
    if card in (ex.DEBIT, ex.VISA):
        new_checking = round(checking - amount, 2)
        reserves['ILS_checking'] = new_checking
        main_portfolio['reserves'] = reserves
        with open(main_portfolio_file, 'w', encoding='utf-8') as f:
            json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
    elif card == ex.CASH:
        new_checking = checking
        new_cash = round(float(reserves.get('ILS_cash', 0) or 0) - amount, 2)
        reserves['ILS_cash'] = new_cash
        main_portfolio['reserves'] = reserves
        with open(main_portfolio_file, 'w', encoding='utf-8') as f:
            json.dump(main_portfolio, f, indent=2, ensure_ascii=False)
    else:
        new_checking = checking
    
    # Load israeli portfolio for spending log
    il_portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")
    try:
        with open(il_portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
    except:
        portfolio_data = {}
    
    # Add to spending log (legacy)
    if 'spending_log' not in portfolio_data:
        portfolio_data['spending_log'] = []
    
    # Whatever day was tapped, defaulting to today when none was.
    spend_date = spend_date or _israel_today().strftime("%Y-%m-%d")
    try:
        spend_day = datetime.strptime(spend_date, "%Y-%m-%d").date()
    except ValueError:
        spend_day = _israel_today()
        spend_date = spend_day.strftime("%Y-%m-%d")

    transaction = {
        "id": uuid.uuid4().hex[:10],          # lets the recurring question find it
        "date": spend_date,
        "time": datetime.now().strftime("%H:%M"),
        "amount": amount,
        "description": description,
        "card": card,
        "balance_after": round(new_checking, 2),
        "checking_before": round(float(checking or 0), 2),   # for "% of the עו\"ש"
    }
    if card == ex.VISA:
        # Billed off the purchase date, not today - a backdated buy can belong to
        # the cycle that is already closing.
        charge_day = ex.charge_date_for(spend_day)
        transaction["charged"] = False
        transaction["charge_date"] = charge_day.strftime("%Y-%m-%d")
        transaction["reserved"] = True       # already off the עו"ש; the charge must not take it again
    if extra:
        transaction.update(extra)       # e.g. the scanned receipt
    if not transaction.get('category'):
        try:
            known = ecat.remembered(ecat.load(), transaction)
            if known:
                ecat.assign(transaction, known)
        except Exception as e:
            _planner_log(f"category lookup failed: {e}")
    portfolio_data['spending_log'].append(transaction)

    # Save israeli portfolio (spending log)
    with open(il_portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2, ensure_ascii=False)

    # checking_log mirrors real movements only, so a Visa purchase is not logged
    # here today - the charge on the 2nd writes a single entry for the whole lot.
    if card == ex.DEBIT:
        _log_ils_checking_transaction(amount, "spend", description, new_checking)
    elif card == ex.VISA:
        _log_ils_checking_transaction(
            amount, "spend", f"ויזה (נשמר לחיוב {transaction['charge_date'][8:10]}/{transaction['charge_date'][5:7]}): {description}",
            new_checking)
    
    # Clear state
    context.user_data.pop('ilspend', None)
    context.user_data.pop('state', None)
    
    if card == ex.CASH:
        tail = (f"💵 מזומן: ₪{float(reserves.get('ILS_cash', 0) or 0) + amount:,.2f} "
                f"→ ₪{new_cash:,.2f}\n"
                f"💳 עו\"ש לא השתנה: ₪{checking:,.2f}")
    elif card == ex.DEBIT:
        tail = f"💳 עו\"ש: {ex.money(checking)} → {ex.money(new_checking)}"
        if ex.overdraft_line(new_checking):
            tail += "\n" + ex.overdraft_line(new_checking)
    else:
        charge_day = datetime.strptime(transaction['charge_date'], '%Y-%m-%d')
        # Already off the עו"ש. One entered after its charge day is marked charged
        # at once (with any older Visa still due, whose money comes off now).
        settled = _settle_due_visa()
        tail = (f"🟦 ויזה — ירד כבר עכשיו מהעו\"ש ונשמר לחיוב ב-{charge_day.strftime('%d/%m/%Y')}\n"
                f"💳 עו\"ש: {ex.money(checking)} → {ex.money(new_checking)}")
        if settled and settled.get('deducted'):
            tail += (f"\n🧾 ירדו גם {ex.money(settled['deducted'])} של ויזה ישנה שיום החיוב שלה עבר\n"
                     f"💳 עו\"ש: {ex.money(settled['before'])} → {ex.money(settled['after'])}")
        elif settled:
            tail += "\n✅ יום החיוב כבר עבר — סומן כחויב"
        waiting = ex.pending_visa(_load_spend_entries())
        if waiting:
            tail += f"\n🧾 ויזה שממתינה לחיוב: ₪{ex.total_of(waiting):,.2f} (/visa)"
        after_all = settled['after'] if settled else new_checking
        if ex.overdraft_line(after_all):
            tail += "\n" + ex.overdraft_line(after_all)

    # How big this purchase was next to the עו"ש as it stood just before it.
    share = (f"📊 <b>{amount / checking * 100:.1f}%</b> מהעו\"ש שהיה לפני הקנייה"
             if checking and checking > 0 else "📊 העו\"ש היה במינוס לפני הקנייה")
    if card in (ex.DEBIT, ex.VISA):
        share += f" ({ex.money(checking)} → {ex.money(new_checking)})"
    else:
        share += f" (₪{checking:,.2f} — שולם במזומן, העו\"ש לא זז)"
    if transaction.get('category'):
        share += f"\n🏷 קטגוריה: {html.escape(ecat.path_of(transaction))}"

    await message.reply_text(
        f"✅ <b>הוצאה נרשמה!</b>\n\n"
        f"💸 סכום: ₪{amount:,.2f}\n"
        f"📝 תיאור: {description}\n"
        f"{ex.CARD_EMOJI[card]} כרטיס: {ex.CARD_LABEL[card]}\n"
        f"📅 תאריך: {transaction['date']} {transaction['time']}\n\n"
        f"{share}\n"
        f"{tail}",
        parse_mode='HTML'
    )

    if transaction.get('category'):
        alert = _budget_alert_for(transaction)
        if alert:
            await message.reply_text(alert, parse_mode='Markdown')
    if card in (ex.DEBIT, ex.VISA):
        await _check_money_alerts(message.reply_text)

    # Will it be charged again next month? Asked for every purchase; one tap.
    known = rc.find_active(rc.load(), description)
    hint = (f"\n<i>כבר קיים חיוב חוזר בשם הזה ({ex.money(known['amount'])}) — כן יקשר אליו.</i>" if known else "")
    await message.reply_text(
        f"🔁 <b>זה חיוב חוזר?</b>\n"
        f"<i>מנוי / הוראת קבע שיחויב שוב אוטומטית בחודש הבא</i>{hint}",
        parse_mode='HTML',
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("🔁 כן, חוזר כל חודש", callback_data=f"recur:yes:{transaction['id']}"),
            InlineKeyboardButton("לא, חד-פעמי", callback_data=f"recur:no:{transaction['id']}")],
            [InlineKeyboardButton("➕ להוסיף עוד הוצאה", callback_data="ilspmore")]]))
    if not transaction.get('category') and anthropic_client:
        # A new kind of purchase: Claude picks the category in the background.
        asyncio.create_task(_auto_categorise([(None, transaction)], notify=message.reply_text))
    return transaction


