# SAVINGS GOALS - /savings command
# ═══════════════════════════════════════════════════════════════

SAVINGS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "savings_goals.json")

def _load_savings():
    """Load savings goals from file"""
    try:
        with open(SAVINGS_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {"goals": [], "history": []}

def _save_savings(data):
    """Save savings goals to file"""
    with open(SAVINGS_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)


async def savings(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Savings goals manager - set targets, deposit money, track progress"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    data = _load_savings()
    goals = data.get('goals', [])
    
    # Build the goals list display
    if not goals:
        goals_text = "<i>אין יעדי חיסכון עדיין</i>\n"
    else:
        goals_text = ""
        for i, g in enumerate(goals, 1):
            saved = g.get('saved', 0)
            target = g.get('target', 0)
            remaining = max(target - saved, 0)
            pct = (saved / target * 100) if target > 0 else 0
            bar_filled = int(pct / 10)
            bar_empty = 10 - bar_filled
            bar = "█" * bar_filled + "░" * bar_empty
            status_icon = "✅" if remaining <= 0 else "🎯"
            goals_text += (
                f"{status_icon} <b>{i}. {g['name']}</b>\n"
                f"   {bar} {pct:.0f}%\n"
                f"   💰 ₪{saved:,.2f} / ₪{target:,.2f}"
            )
            if remaining > 0:
                goals_text += f"  (חסרים ₪{remaining:,.2f})"
            else:
                goals_text += f"  ✅ הושג!"
            goals_text += "\n\n"
    
    # Get checking balance
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    try:
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        checking = portfolio_data.get('reserves', {}).get('ILS_checking', 0)
    except:
        checking = 0
    
    total_saved = sum(g.get('saved', 0) for g in goals)
    
    await update.message.reply_text(
        f"🐷 <b>יעדי חיסכון</b>\n"
        f"━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{goals_text}"
        f"━━━━━━━━━━━━━━━━━━━━━\n"
        f"🏦 סך הכל חסכונות: <b>₪{total_saved:,.2f}</b>\n"
        f"💳 יתרת עו\"ש: <b>₪{checking:,.2f}</b>\n\n"
        f"<b>פקודות:</b>\n"
        f"• שלח <b>new</b> - יעד חדש\n"
        f"• שלח <b>deposit</b> - הפקדה ליעד\n"
        f"• שלח <b>withdraw</b> - משיכה מיעד\n"
        f"• שלח <b>calc</b> - מחשבון חיסכון\n"
        f"• שלח <b>delete</b> - מחיקת יעד\n"
        f"• שלח <b>cancel</b> - ביטול",
        parse_mode='HTML'
    )
    
    context.user_data['state'] = 'savings_menu'


async def _handle_savings_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle savings menu selection"""
    text = update.message.text.strip().lower()
    
    if text in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('state', None)
        context.user_data.pop('savings', None)
        await update.message.reply_text("❌ בוטל")
        return
    
    if text == 'new':
        context.user_data['state'] = 'savings_new_name'
        await update.message.reply_text(
            "🆕 <b>יעד חיסכון חדש</b>\n\n"
            "מה השם של היעד?\n"
            "<i>(למשל: אייפון, חופשה, מחשב, PS5)</i>",
            parse_mode='HTML'
        )
    elif text == 'deposit':
        data = _load_savings()
        goals = data.get('goals', [])
        if not goals:
            await update.message.reply_text("❌ אין יעדים. שלח <b>new</b> ליצירת יעד חדש.", parse_mode='HTML')
            return
        
        goals_list = ""
        for i, g in enumerate(goals, 1):
            remaining = max(g['target'] - g.get('saved', 0), 0)
            goals_list += f"<b>{i}</b>. {g['name']} (חסרים ₪{remaining:,.2f})\n"
        
        context.user_data['state'] = 'savings_deposit_select'
        await update.message.reply_text(
            f"💰 <b>הפקדה ליעד</b>\n\n"
            f"בחר יעד (שלח מספר):\n{goals_list}",
            parse_mode='HTML'
        )
    elif text == 'withdraw':
        data = _load_savings()
        goals = data.get('goals', [])
        if not goals:
            await update.message.reply_text("❌ אין יעדים.")
            return
        
        goals_list = ""
        for i, g in enumerate(goals, 1):
            saved = g.get('saved', 0)
            goals_list += f"<b>{i}</b>. {g['name']} (₪{saved:,.2f} נחסכו)\n"
        
        context.user_data['state'] = 'savings_withdraw_select'
        await update.message.reply_text(
            f"↩️ <b>משיכה מיעד</b>\n\n"
            f"בחר יעד (שלח מספר):\n{goals_list}",
            parse_mode='HTML'
        )
    elif text == 'calc':
        data = _load_savings()
        goals = data.get('goals', [])
        if not goals:
            await update.message.reply_text("❌ אין יעדים.")
            return
        
        goals_list = ""
        for i, g in enumerate(goals, 1):
            remaining = max(g['target'] - g.get('saved', 0), 0)
            goals_list += f"<b>{i}</b>. {g['name']} (חסרים ₪{remaining:,.2f})\n"
        
        context.user_data['state'] = 'savings_calc_select'
        await update.message.reply_text(
            f"🧮 <b>מחשבון חיסכון</b>\n\n"
            f"בחר יעד (שלח מספר):\n{goals_list}",
            parse_mode='HTML'
        )
    elif text == 'delete':
        data = _load_savings()
        goals = data.get('goals', [])
        if not goals:
            await update.message.reply_text("❌ אין יעדים למחיקה.")
            return
        
        goals_list = ""
        for i, g in enumerate(goals, 1):
            goals_list += f"<b>{i}</b>. {g['name']} (₪{g.get('saved', 0):,.2f} / ₪{g['target']:,.2f})\n"
        
        context.user_data['state'] = 'savings_delete_select'
        await update.message.reply_text(
            f"🗑️ <b>מחיקת יעד</b>\n\n"
            f"בחר יעד למחיקה (שלח מספר):\n{goals_list}\n"
            f"⚠️ אם יש כסף ביעד, הוא יחזור לעו\"ש",
            parse_mode='HTML'
        )
    else:
        await update.message.reply_text(
            "❌ לא הבנתי. שלח: <b>new</b>, <b>deposit</b>, <b>withdraw</b>, <b>calc</b>, <b>delete</b> או <b>cancel</b>",
            parse_mode='HTML'
        )


