async def _handle_savings_new_target(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle new goal target amount"""
    text = update.message.text.strip()
    
    if text.lower() in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('state', None)
        context.user_data.pop('savings', None)
        await update.message.reply_text("❌ בוטל")
        return
    
    try:
        amount = float(text.replace(',', '').replace('₪', '').strip())
        if amount <= 0:
            await update.message.reply_text("❌ הסכום חייב להיות חיובי")
            return
    except ValueError:
        await update.message.reply_text("❌ סכום לא תקין. שלח מספר.")
        return
    
    name = context.user_data.get('savings', {}).get('name', 'Unknown')
    
    # Create the goal
    data = _load_savings()
    new_goal = {
        "name": name,
        "target": round(amount, 2),
        "saved": 0,
        "created": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "deposits": []
    }
    data['goals'].append(new_goal)
    _save_savings(data)
    
    # Clear state
    context.user_data.pop('state', None)
    context.user_data.pop('savings', None)
    
    await update.message.reply_text(
        f"✅ <b>יעד חיסכון נוצר!</b>\n\n"
        f"🎯 יעד: <b>{name}</b>\n"
        f"💰 סכום נדרש: <b>₪{amount:,.2f}</b>\n"
        f"📅 נוצר: {new_goal['created']}\n\n"
        f"💡 השתמש ב- /savings → deposit כדי להפקיד כסף\n"
        f"🧮 השתמש ב- /savings → calc למחשבון חיסכון",
        parse_mode='HTML'
    )


