async def _handle_savings_deposit_select(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle goal selection for deposit"""
    text = update.message.text.strip()
    
    if text.lower() in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('state', None)
        context.user_data.pop('savings', None)
        await update.message.reply_text("❌ בוטל")
        return
    
    try:
        idx = int(text) - 1
        data = _load_savings()
        goals = data.get('goals', [])
        if idx < 0 or idx >= len(goals):
            await update.message.reply_text(f"❌ שלח מספר בין 1 ל-{len(goals)}")
            return
    except ValueError:
        await update.message.reply_text("❌ שלח מספר")
        return
    
    goal = goals[idx]
    remaining = max(goal['target'] - goal.get('saved', 0), 0)
    
    # Get checking balance
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    try:
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        checking = portfolio_data.get('reserves', {}).get('ILS_checking', 0)
    except:
        checking = 0
    
    context.user_data['savings'] = {'goal_index': idx}
    context.user_data['state'] = 'savings_deposit_amount'
    
    await update.message.reply_text(
        f"💰 <b>הפקדה ל-{goal['name']}</b>\n\n"
        f"🎯 יעד: ₪{goal['target']:,.2f}\n"
        f"✅ נחסך: ₪{goal.get('saved', 0):,.2f}\n"
        f"📌 חסרים: ₪{remaining:,.2f}\n"
        f"💳 יתרת עו\"ש: ₪{checking:,.2f}\n\n"
        f"כמה להפקיד? (שלח סכום)\n"
        f"<i>הכסף יצא מהעו\"ש</i>",
        parse_mode='HTML'
    )


async def _handle_savings_deposit_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle deposit amount to savings goal"""
    text = update.message.text.strip()
    
    if text.lower() in ['cancel', 'ביטול', 'בטל']:
        context.user_data.pop('state', None)
        context.user_data.pop('savings', None)
        await update.message.reply_text("❌ בוטל")
        return
    
    try:
        amount = float(text.replace(',', '').replace('₪', '').strip())
        if amount <= 0:
            await update.message.reply_text("❌ הסכום חייב להיות חיובי")
            return
    except ValueError:
        await update.message.reply_text("❌ סכום לא תקין. שלח מספר.")
        return
    
    # Check balance
    portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(portfolio_file, 'r', encoding='utf-8') as f:
        portfolio_data = json.load(f)
    
    reserves = portfolio_data.get('reserves', {})
    checking = reserves.get('ILS_checking', 0)

    if not ex.can_debit(checking, amount):
        await update.message.reply_text(ex.over_limit_text(checking, amount))
        return
    
    idx = context.user_data.get('savings', {}).get('goal_index', 0)
    data = _load_savings()
    goals = data.get('goals', [])
    
    if idx >= len(goals):
        await update.message.reply_text("❌ שגיאה - יעד לא נמצא")
        context.user_data.pop('state', None)
        context.user_data.pop('savings', None)
        return
    
    goal = goals[idx]
    
    # Deduct from checking
    new_checking = checking - amount
    reserves['ILS_checking'] = round(new_checking, 2)
    portfolio_data['reserves'] = reserves
    with open(portfolio_file, 'w', encoding='utf-8') as f:
        json.dump(portfolio_data, f, indent=2, ensure_ascii=False)
    
    # Add to goal
    old_saved = goal.get('saved', 0)
    goal['saved'] = round(old_saved + amount, 2)
    goal['deposits'].append({
        "date": datetime.now().strftime("%Y-%m-%d"),
        "time": datetime.now().strftime("%H:%M"),
        "amount": round(amount, 2),
        "balance_after": goal['saved']
    })
    data['goals'][idx] = goal
    
    # Log in history
    data['history'].append({
        "date": datetime.now().strftime("%Y-%m-%d"),
        "time": datetime.now().strftime("%H:%M"),
        "type": "deposit",
        "goal": goal['name'],
        "amount": round(amount, 2),
        "goal_total": goal['saved'],
        "checking_after": round(new_checking, 2)
    })
    _save_savings(data)
    
    # Also log to checking_log
    _log_ils_checking_transaction(amount, "savings_deposit", f"חיסכון: {goal['name']}", new_checking)
    
    remaining = max(goal['target'] - goal['saved'], 0)
    pct = (goal['saved'] / goal['target'] * 100) if goal['target'] > 0 else 0
    bar_filled = int(pct / 10)
    bar_empty = 10 - bar_filled
    bar = "█" * bar_filled + "░" * bar_empty
    
    result_msg = (
        f"✅ <b>הפקדה לחיסכון בוצעה!</b>\n\n"
        f"🎯 יעד: <b>{goal['name']}</b>\n"
        f"💰 הפקדה: ₪{amount:,.2f}\n"
        f"📊 {bar} {pct:.0f}%\n"
        f"✅ נחסך: ₪{goal['saved']:,.2f} / ₪{goal['target']:,.2f}\n"
    )
    
    if remaining > 0:
        result_msg += f"📌 <b>חסרים עוד ₪{remaining:,.2f}</b>\n"
    else:
        result_msg += f"🎉 <b>הגעת ליעד! מזל טוב!</b>\n"
    
    result_msg += f"\n💳 עו\"ש: ₪{checking:,.2f} → ₪{new_checking:,.2f}"
    
    await update.message.reply_text(result_msg, parse_mode='HTML')
    
    # Clear state
    context.user_data.pop('state', None)
    context.user_data.pop('savings', None)


