async def custom_sell(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Sell stock from custom portfolio: /psell <portfolio> <symbol> <shares> <price>"""
    if len(context.args) < 4:
        await update.message.reply_text(
            "Usage: /psell <portfolio> <symbol> <shares> <price>\n"
            "Example: /psell Growth AAPL 5 160.00"
        )
        return
    
    portfolio_name = context.args[0]
    symbol = context.args[1].upper()
    
    try:
        shares = float(context.args[2])
        price = float(context.args[3])
    except ValueError:
        await update.message.reply_text("❌ Invalid number format")
        return
    
    index = _load_custom_portfolios_index()
    existing_names = {p['name'].lower(): p['name'] for p in index['portfolios']}
    
    if portfolio_name.lower() not in existing_names:
        await update.message.reply_text(f"❌ Portfolio '{portfolio_name}' not found.")
        return
    
    actual_name = existing_names[portfolio_name.lower()]
    data = _load_custom_portfolio(actual_name)
    holdings = data.get('holdings', [])
    
    existing = next((h for h in holdings if h['symbol'] == symbol), None)
    
    if not existing:
        await update.message.reply_text(f"❌ {symbol} not found in {actual_name}")
        return
    
    if shares > existing['shares']:
        await update.message.reply_text(f"❌ You only have {existing['shares']:.0f} shares of {symbol}")
        return
    
    proceeds = shares * price
    buy_price = existing['purchase_price']
    cost_basis = shares * buy_price
    profit = proceeds - cost_basis
    profit_pct = (profit / cost_basis * 100) if cost_basis > 0 else 0
    
    # Update holding
    if shares == existing['shares']:
        holdings.remove(existing)
    else:
        existing['shares'] -= shares
        existing['total_cost'] = existing['shares'] * existing['purchase_price']
    
    # Add proceeds to cash
    data['free_cash'] = data.get('free_cash', 0) + proceeds
    data['holdings'] = holdings
    
    _save_custom_portfolio(actual_name, data)
    
    emoji = "🟢" if profit >= 0 else "🔴"
    msg = f"✅ Sold *{symbol}* from *{actual_name}*\n\n"
    msg += f"📉 {shares:.0f} shares @ ${price:.2f}\n"
    msg += f"💵 Proceeds: ${proceeds:,.2f}\n"
    msg += f"{emoji} P/L: ${profit:+,.2f} ({profit_pct:+.1f}%)\n"
    msg += f"💰 New cash: ${data['free_cash']:,.2f}"
    
    await update.message.reply_text(msg, parse_mode='Markdown')

