async def custom_today(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Today's performance for custom portfolio: /ptoday <portfolio>"""
    if not context.args:
        await update.message.reply_text("Usage: /ptoday <portfolio_name>")
        return
    
    portfolio_name = ' '.join(context.args)  # Support multi-word names
    index = _load_custom_portfolios_index()
    existing_names = {p['name'].lower(): p['name'] for p in index['portfolios']}
    
    if portfolio_name.lower() not in existing_names:
        await update.message.reply_text(f"❌ Portfolio '{portfolio_name}' not found.")
        return
    
    actual_name = existing_names[portfolio_name.lower()]
    data = _load_custom_portfolio(actual_name)
    holdings = data.get('holdings', [])
    
    if not holdings:
        await update.message.reply_text(f"📋 No holdings in {actual_name}")
        return
    
    await update.message.reply_text(f"⏳ Loading {actual_name} daily performance...")
    
    total_day_pl = 0
    lines = []
    
    for holding in holdings:
        symbol = holding['symbol']
        shares = holding['shares']
        
        try:
            ticker = yf.Ticker(symbol)
            info = ticker.info
            price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
            prev_close = info.get('previousClose') or info.get('regularMarketPreviousClose', price)
            
            day_change = (price - prev_close) * shares
            day_pct = ((price - prev_close) / prev_close * 100) if prev_close > 0 else 0
            total_day_pl += day_change
            
            emoji = "🟢" if day_change >= 0 else "🔴"
            lines.append((day_change, f"{emoji} *{symbol}*: {day_change:+,.2f} ({day_pct:+.1f}%)"))
        except:
            continue
    
    lines.sort(key=lambda x: x[0], reverse=True)
    
    msg = f"📊 *{actual_name} - Today's Performance*\n"
    msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
    
    for _, line in lines:
        msg += line + "\n"
    
    msg += "\n━━━━━━━━━━━━━━━━━━━━\n"
    emoji = "📈" if total_day_pl >= 0 else "📉"
    msg += f"{emoji} *Total: ${total_day_pl:+,.2f}*"
    
    await update.message.reply_text(msg, parse_mode='Markdown')

async def delete_portfolio(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Delete a custom portfolio: /pdelete <portfolio>"""
    if not context.args:
        await update.message.reply_text("Usage: /pdelete <portfolio_name>")
        return
    
    portfolio_name = ' '.join(context.args)  # Support multi-word names
    index = _load_custom_portfolios_index()
    existing_names = {p['name'].lower(): p['name'] for p in index['portfolios']}
    
    if portfolio_name.lower() not in existing_names:
        await update.message.reply_text(f"❌ Portfolio '{portfolio_name}' not found.")
        return
    
    actual_name = existing_names[portfolio_name.lower()]
    
    # Remove from index
    index['portfolios'] = [p for p in index['portfolios'] if p['name'].lower() != portfolio_name.lower()]
    _save_custom_portfolios_index(index)
    
    # Delete file
    filepath = _get_custom_portfolio_file(actual_name)
    if os.path.exists(filepath):
        os.remove(filepath)
    
    await update.message.reply_text(f"🗑️ Portfolio '*{actual_name}*' deleted.", parse_mode='Markdown')


async def _send_long_text(update, text: str, parse_mode: str = None, chunk_limit: int = 3800):
    """Send `text` to the user, chunking on line boundaries if it exceeds Telegram's limit."""
    if len(text) <= 4000:
        await update.message.reply_text(text, parse_mode=parse_mode)
        return
    chunks = []
    current = ""
    for line in text.split('\n'):
        if len(current) + len(line) + 1 > chunk_limit:
            chunks.append(current)
            current = line
        else:
            current = (current + '\n' + line) if current else line
    if current:
        chunks.append(current)
    for chunk in chunks:
        await update.message.reply_text(chunk, parse_mode=parse_mode)


def _usd_cash_total(portfolio_data):
    """All USD cash of the main portfolio: the bank's (free_cash) + Interactive's."""
    return round(sum(brk.cash(portfolio_data or {}).values()), 2)


def _log_cash_transaction(portfolio_data, amount: float, trans_type: str, description: str,
                          broker: str = None):
    """Add a transaction to the cash log (balance_after = that broker's USD cash)."""
    if 'cash_log' not in portfolio_data:
        portfolio_data['cash_log'] = []

    transaction = {
        "date": _us_market_date().strftime("%Y-%m-%d %H:%M"),
        "type": trans_type,  # "deposit", "withdrawal", "stock_purchase"
        "amount": amount,
        "description": description,
        "balance_after": portfolio_data.get(brk.CASH_KEY.get(broker or brk.BANK, 'free_cash'), 0)
    }
    if broker:
        transaction['broker'] = broker
    portfolio_data['cash_log'].append(transaction)


def _log_sold_stock(portfolio_data, symbol: str, shares: float, buy_price: float,
                    sell_price: float, buy_date: str, sell_date: str,
                    holding_period: str, cost_basis: float, proceeds: float,
                    buy_commission: float, sell_commission: float,
                    profit_loss: float, profit_pct: float, tax_withheld: float = 0,
                    tax_shield_earned: float = 0, tax_shield_used: float = 0):
    """Log a sold stock to the sold history"""
    if 'sold_history' not in portfolio_data:
        portfolio_data['sold_history'] = []

    total_commission = buy_commission + sell_commission

    sold_record = {
        "symbol": symbol,
        "shares": shares,
        "buy_price": round(buy_price, 2),
        "sell_price": round(sell_price, 2),
        "buy_date": buy_date,
        "sell_date": sell_date,
        "holding_period": holding_period,
        "cost_basis": round(cost_basis, 2),
        "proceeds": round(proceeds, 2),
        "buy_commission": round(buy_commission, 2),
        "sell_commission": round(sell_commission, 2),
        "total_commission": round(total_commission, 2),
        "profit_loss": round(profit_loss, 2),
        "profit_pct": round(profit_pct, 2),
        "tax_withheld": round(tax_withheld, 2),
        "tax_shield_earned": round(tax_shield_earned, 2),
        "tax_shield_used": round(tax_shield_used, 2),
        "result": "profit" if profit_loss >= 0 else "loss"
    }
    portfolio_data['sold_history'].append(sold_record)


async def cash(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View current free cash balance"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    try:
        args = [str(a).strip().lower() for a in (context.args or [])]
        if args and args[0] == 'set':
            await _cash_set(update, args[1:])
            return
        portfolio_data = _load_portfolio()
        per_broker = brk.cash(portfolio_data)
        current_cash = _usd_cash_total(portfolio_data)

        # Get recent transactions
        cash_log = portfolio_data.get('cash_log', [])
        recent = cash_log[-5:] if cash_log else []

        message = f"💵 *Free Cash Balance*\n\n"
        for b in brk.BROKERS:
            message += f"{brk.SHORT[b]}: ${per_broker[b]:,.2f}\n"
        message += f"💰 *Total Current Cash: ${current_cash:,.2f}*\n\n"
        
        if recent:
            message += "📜 *Recent Activity:*\n"
            for t in reversed(recent):
                emoji = "🟢" if t['amount'] > 0 else "🔴"
                balance_after = t.get('balance_after', 0)
                where = f" · {brk.SHORT[t['broker']]}" if t.get('broker') in brk.SHORT else ""
                message += f"{emoji} {t['date'][:10]}: ${t['amount']:+,.2f}{where}\n"
                message += f"   _{t['description']}_\n"
                message += f"   💵 Balance: ${balance_after:,.2f}\n"
        
        message += "\n📌 Use /addcash to deposit (₪ → $)\n"
        message += "📌 `/cash set interactive 28.16` — match a broker's real balance\n"
        message += "📌 Use /cashlog for full history"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _cash_set(update, args):
    """/cash set <interactive|bank> <amount>: set a broker's USD cash to its real
    balance; the difference is written to the cash log as an adjustment."""
    names = {'interactive': brk.IBKR, 'ibkr': brk.IBKR, 'ib': brk.IBKR, 'bank': brk.BANK, 'בנק': brk.BANK}
    try:
        broker = names[args[0]]
        amount = round(float(args[1].replace('$', '').replace(',', '')), 2)
        if amount < 0:
            raise ValueError
    except (IndexError, KeyError, ValueError):
        await update.message.reply_text("❌ Example: /cash set interactive 28.16  (or: /cash set bank 100)")
        return
    portfolio = _load_portfolio()
    key = brk.CASH_KEY[broker]
    before = round(float(portfolio.get(key, 0) or 0), 2)
    diff = round(amount - before, 2)
    if abs(diff) < 0.005:
        await update.message.reply_text(f"✅ {brk.SHORT[broker]} cash is already ${amount:,.2f}.")
        return
    portfolio[key] = amount
    _log_cash_transaction(portfolio, diff, 'adjustment',
                          f"{brk.LABEL[broker]} cash set to the real balance (${before:,.2f} → ${amount:,.2f})",
                          broker=broker)
    _save_portfolio(portfolio)
    await update.message.reply_text(
        f"✅ *{brk.SHORT[broker]} cash: ${before:,.2f} → ${amount:,.2f}* ({'+' if diff >= 0 else '-'}${abs(diff):,.2f})\n"
        f"💰 Total cash now: ${_usd_cash_total(portfolio):,.2f}\n_Logged in /cashlog as an adjustment._",
        parse_mode='Markdown')


async def addcash(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Convert ILS -> USD. /addcash [usd] [rate] [note] -- asks what is missing:
    the amount, where (Interactive / bank), the commission in $, the rate, a note."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    user_id = update.effective_user.id

    if not context.args:
        portfolio = _load_portfolio()
        il_checking = portfolio.get('reserves', {}).get('ILS_checking', 0)
        cash = brk.cash(portfolio)
        pending_commands[user_id] = 'addcash'
        await update.message.reply_text(
            f"💵 *Convert ILS → USD*\n\n"
            f"💳 /ilcash עו\"ש available: ₪{il_checking:,.2f}\n"
            f"💰 /cash now: {brk.SHORT[brk.IBKR]} ${cash[brk.IBKR]:,.2f} · {brk.SHORT[brk.BANK]} ${cash[brk.BANK]:,.2f}\n\n"
            f"How many USD are you buying? (e.g. `1000`):",
            parse_mode='Markdown'
        )
        return

    data = {}
    try:
        data['amount'] = float(context.args[0].replace('$', '').replace(',', ''))
    except ValueError:
        await update.message.reply_text("❌ Invalid amount. Example: /addcash 1000 3.65")
        return
    if data['amount'] <= 0:
        await update.message.reply_text("❌ Amount must be positive")
        return
    if len(context.args) >= 2:
        try:
            data['rate'] = float(context.args[1].replace('₪', '').replace(',', ''))
        except ValueError:
            await update.message.reply_text("❌ Invalid rate. Example: /addcash 1000 3.65")
            return
        if data['rate'] <= 0:
            await update.message.reply_text("❌ Rate must be positive")
            return
    if len(context.args) > 2:
        data['note'] = ' '.join(context.args[2:]).strip()
    await _addcash_next(update.message, user_id, data)


ADDCASH_DEFAULT_COMMISSION = {brk.IBKR: 3.28}     # Interactive's conversion fee, in $


def _addcash_last_commission(broker):
    last = (_load_portfolio().get('fx_commission_last') or {}).get(broker)
    return float(last) if last is not None else ADDCASH_DEFAULT_COMMISSION.get(broker)


async def _addcash_next(message, user_id, data):
    """Ask the first thing still missing; once nothing is, do the conversion."""
    amount = data['amount']
    if 'broker' not in data:
        pending_commands[user_id] = dict(data, cmd='addcash_broker')
        await message.reply_text(
            f"💵 Buying *${amount:,.2f}* — where?",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🌐 Interactive Brokers", callback_data=f"cashbrk:{brk.IBKR}"),
                 InlineKeyboardButton("🏦 הבנק", callback_data=f"cashbrk:{brk.BANK}")],
                [InlineKeyboardButton("❌ Cancel", callback_data="cashbrk:cancel")]]))
        return
    if 'commission' not in data:
        pending_commands[user_id] = dict(data, cmd='addcash_commission')
        last = _addcash_last_commission(data['broker'])
        row = []
        if last:
            row.append(InlineKeyboardButton(f"${last:g} (like last time)", callback_data=f"cashfee:{last:g}"))
        row.append(InlineKeyboardButton("$0 — none", callback_data="cashfee:0"))
        await message.reply_text(
            f"{brk.SHORT[data['broker']]} · *${amount:,.2f}*\n\n"
            f"💸 What was the conversion commission, in $? (e.g. `3.28`, or `0`)",
            parse_mode='Markdown', reply_markup=InlineKeyboardMarkup([row]))
        return
    if 'rate' not in data:
        pending_commands[user_id] = dict(data, cmd='addcash_rate')
        await message.reply_text(
            f"💵 Buying *${amount:,.2f}* · commission ${data['commission']:,.2f}\n\n"
            f"💱 What's the conversion rate? (₪ per $, e.g. `3.65`):",
            parse_mode='Markdown')
        return
    if True:                      # both brokers are paid for out of the עו"ש
        ils_needed = round(amount * data['rate'], 2)
        il_checking = _load_portfolio().get('reserves', {}).get('ILS_checking', 0)
        if ils_needed > il_checking:
            pending_commands.pop(user_id, None)
            await message.reply_text(
                f"❌ Not enough in /ilcash עו\"ש.\n"
                f"Need ₪{ils_needed:,.2f}, available ₪{il_checking:,.2f}\n"
                f"Try again with /addcash.")
            return
    if 'note' not in data:
        pending_commands[user_id] = dict(data, cmd='addcash_note')
        net = amount - data['commission']
        await message.reply_text(
            f"💵 ₪{amount * data['rate']:,.2f} → *${amount:,.2f}* @ {data['rate']} ₪/$"
            + (f"\n💸 commission ${data['commission']:,.2f} → you get *${net:,.2f}*" if data['commission'] else "")
            + "\n\n📝 Add a note? (or send `-` to skip):",
            parse_mode='Markdown')
        return
    pending_commands.pop(user_id, None)
    try:
        await _do_addcash(_ReplyTarget(message), amount, data['rate'], data['note'] or None,
                          broker=data['broker'], commission=data['commission'])
    except ValueError as e:
        await message.reply_text(f"❌ {e}")


async def addcash_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """cashbrk:IBKR|BANK|cancel and cashfee:<$> -- the buttons of /addcash."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    kind, value = (query.data or ':').split(':', 1)
    user_id = query.from_user.id
    pending = pending_commands.get(user_id)
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    want = {'cashbrk': 'addcash_broker', 'cashfee': 'addcash_commission'}.get(kind)
    if value == 'cancel' or not isinstance(pending, dict) or pending.get('cmd') != want:
        if value == 'cancel' and isinstance(pending, dict) and str(pending.get('cmd', '')).startswith('addcash'):
            pending_commands.pop(user_id, None)
        await query.message.reply_text("❌ Cancelled" if value == 'cancel'
                                       else "ℹ️ This conversion is no longer pending — send /addcash again.")
        return
    data = {k: v for k, v in pending.items() if k != 'cmd'}
    if kind == 'cashbrk':
        if value not in brk.BROKERS:
            return
        data['broker'] = value
    else:
        data['commission'] = round(float(value), 2)
    await _addcash_next(query.message, user_id, data)


async def _do_addcash(update, amount: float, rate: float, note: str = None,
                      broker: str = brk.BANK, commission: float = 0.0):
    """Convert ILS -> USD: the shekels leave the עו\"ש (logged as an investment in
    the עו\"ש log -- not spending, never in /ilspend), and the dollars, less the
    $ commission, land in that broker's cash (bank or Interactive).
    Raises ValueError if the עו\"ש is short or the commission is too big."""
    ils_spent = round(amount * rate, 2)
    commission = round(float(commission or 0), 2)
    if commission < 0 or commission >= amount:
        raise ValueError(f"Commission ${commission:,.2f} doesn't fit a ${amount:,.2f} conversion.")
    received = round(amount - commission, 2)

    portfolio = _load_portfolio()
    reserves = portfolio.setdefault('reserves', {})
    il_checking = reserves.get('ILS_checking', 0)
    if True:
        if ils_spent > il_checking:
            raise ValueError(
                f'Not enough in /ilcash עו"ש. Need ₪{ils_spent:,.2f} '
                f'(${amount:,.2f} × {rate}), available ₪{il_checking:,.2f}.'
            )
        new_checking = round(il_checking - ils_spent, 2)
        reserves['ILS_checking'] = new_checking

    cash_key = brk.CASH_KEY[broker]
    current_cash = portfolio.get(cash_key, 0)
    new_cash = round(current_cash + received, 2)
    portfolio[cash_key] = new_cash
    portfolio.setdefault('fx_commission_last', {})[broker] = commission

    note_suffix = f" - {note}" if note else ""
    where = (" at Interactive" if broker == brk.IBKR else '') + ' from עו"ש'
    _log_cash_transaction(
        portfolio, received, 'deposit',
        f'FX{where}: ${amount:,.2f} @ {rate} ₪/$ = ₪{ils_spent:,.2f}'
        + (f', commission ${commission:,.2f}' if commission else '') + note_suffix,
        broker=broker,
    )
    if commission:
        portfolio['cash_log'][-1]['fx_commission'] = commission
    portfolio['cash_log'][-1].update({'fx_rate': rate, 'fx_ils': ils_spent, 'fx_usd': amount})
    _save_portfolio(portfolio)

    # A move between your own pockets: in the עו"ש log as an investment, which
    # /illog and /expenses do not count as spending.
    _log_ils_checking_transaction(
        amount=ils_spent,
        trans_type='investment',
        note=(f'המרה לדולרים{" ב-Interactive" if broker == brk.IBKR else ""}: '
              f'${amount:,.2f} @ {rate} ₪/$ → /cash{note_suffix}'),
        balance_after=new_checking,
    )

    note_line = f"\n📝 Note: _{note}_" if note else ""
    ils_line = f"🔴 Debited from עו\"ש: *₪{ils_spent:,.2f}* @ {rate} ₪/$\n"
    await update.message.reply_text(
        f"✅ *ILS → USD conversion* · {brk.LABEL[broker]}\n\n"
        f"🟢 Added to /cash: *${received:,.2f}*"
        + (f" (${amount:,.2f} − ${commission:,.2f} commission)" if commission else "") + "\n"
        + ils_line + "\n"
        f"💰 {brk.SHORT[broker]} cash: ${current_cash:,.2f} → *${new_cash:,.2f}*\n"
        + f"💳 /ilcash עו\"ש: ₪{il_checking:,.2f} → *₪{new_checking:,.2f}*\n"
        + f"📅 Date: {datetime.now().strftime('%Y-%m-%d')}{note_line}",
        parse_mode='Markdown'
    )


async def cashlog(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View full cash transaction history"""
    try:
        portfolio_data = _load_portfolio()
        cash_log = portfolio_data.get('cash_log', [])
        current_cash = _usd_cash_total(portfolio_data)
        
        if not cash_log:
            await update.message.reply_text(
                "📜 *Cash Log*\n\n"
                "No transactions recorded yet.\n"
                f"💰 Current Balance: ${current_cash:,.2f}",
                parse_mode='Markdown'
            )
            return
        
        message = "📜 *Cash Transaction History*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        # Show last 15 transactions (most recent first)
        for t in reversed(cash_log[-15:]):
            if t['amount'] > 0:
                emoji = "🟢"
            else:
                emoji = "🔴"
            
            message += f"{emoji} *{t['date']}*\n"
            message += f"   {t['description']}" + (f" · {brk.SHORT[t['broker']]}" if t.get('broker') in brk.SHORT else "") + "\n"
            message += f"   Amount: ${t['amount']:+,.2f}\n"
            message += f"   Balance: ${t['balance_after']:,.2f}\n\n"
        
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += f"💰 *Current Balance: ${current_cash:,.2f}*"

        await update.message.reply_text(message, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


FUN_SPENDING_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fun_spending.json')


def _load_fun_spending():
    try:
        if os.path.exists(FUN_SPENDING_FILE):
            with open(FUN_SPENDING_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
    except Exception:
        pass
    return {'balance': 0.0, 'log': []}


def _save_fun_spending(data):
    with open(FUN_SPENDING_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def _days_until_next_eighth(now_dt=None):
    now_dt = now_dt or datetime.now()
    today = now_dt.date()
    if today.day < 8:
        year, month = today.year, today.month
    else:
        if today.month == 12:
            year, month = today.year + 1, 1
        else:
            year, month = today.year, today.month + 1
    target = datetime(year, month, 8).date()
    return (target - today).days


def _period_start_for_date(d):
    """Return the 8th-anchored period-start date that contains date d."""
    if d.day >= 8:
        return datetime(d.year, d.month, 8).date()
    if d.month == 1:
        return datetime(d.year - 1, 12, 8).date()
    return datetime(d.year, d.month - 1, 8).date()


def _period_end_for_start(start):
    """Last day of the period starting on `start` (day before next 8th)."""
    if start.month == 12:
        next_8 = datetime(start.year + 1, 1, 8).date()
    else:
        next_8 = datetime(start.year, start.month + 1, 8).date()
    return next_8 - timedelta(days=1)


def _period_label(start):
    end = _period_end_for_start(start)
    if start.year == end.year:
        return f"{start.strftime('%b %d')} → {end.strftime('%b %d, %Y')}"
    return f"{start.strftime('%b %d, %Y')} → {end.strftime('%b %d, %Y')}"


def _parse_log_date(s):
    try:
        return datetime.strptime(s, '%Y-%m-%d %H:%M').date()
    except Exception:
        return None


def _compute_period_stats(spend_entries):
    cash_count = visa_count = unknown_count = 0
    cash_total = visa_total = unknown_total = 0.0
    for t in spend_entries:
        amt = abs(t.get('amount', 0))
        method = t.get('payment_method')
        if method == 'cash':
            cash_count += 1
            cash_total += amt
        elif method == 'visa':
            visa_count += 1
            visa_total += amt
        else:
            unknown_count += 1
            unknown_total += amt
    return {
        'cash_count': cash_count, 'cash_total': round(cash_total, 2),
        'visa_count': visa_count, 'visa_total': round(visa_total, 2),
        'unknown_count': unknown_count, 'unknown_total': round(unknown_total, 2),
        'total_count': cash_count + visa_count + unknown_count,
        'total_amt': round(cash_total + visa_total + unknown_total, 2),
    }


def _bar(percent, width=10):
    filled = int(round(percent * width / 100))
    filled = max(0, min(width, filled))
    return '█' * filled + '░' * (width - filled)


def _format_period_chart(stats, label):
    msg = f"\n━━━━━━━━━━━━━━━━━━━━\n📊 *{label}*\n━━━━━━━━━━━━━━━━━━━━\n"
    msg += f"💵 Cash: {stats['cash_count']} purchases — ₪{stats['cash_total']:,.2f}\n"
    msg += f"💳 Visa: {stats['visa_count']} purchases — ₪{stats['visa_total']:,.2f}\n"
    if stats['unknown_count']:
        msg += f"❓ Other: {stats['unknown_count']} purchases — ₪{stats['unknown_total']:,.2f}\n"
    msg += f"\n*Total:* {stats['total_count']} purchases — *₪{stats['total_amt']:,.2f}*\n"
    if stats['total_amt'] > 0:
        pc_cash = stats['cash_total'] / stats['total_amt'] * 100
        pc_visa = stats['visa_total'] / stats['total_amt'] * 100
        msg += "\n_Spend distribution:_\n"
        msg += f"💵 `{_bar(pc_cash)}` {pc_cash:5.1f}%\n"
        msg += f"💳 `{_bar(pc_visa)}` {pc_visa:5.1f}%\n"
    return msg


async def fun_spending(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Fun money pool. /fun_spending to view, /fun_spending add <amount> [note], /fun_spending log"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    data = _load_fun_spending()
    args = context.args or []

    if args and args[0].lower() == 'add':
        if len(args) < 2:
            await _start_fun_add_interactive(update, context)
            return
        try:
            amount = float(args[1].replace('₪', '').replace('$', '').replace(',', ''))
        except ValueError:
            await update.message.reply_text("❌ Invalid amount.")
            return
        if amount <= 0:
            await update.message.reply_text("❌ Amount must be positive.")
            return

        note = ' '.join(args[2:]).strip() if len(args) > 2 else ''
        try:
            new_balance, new_checking = _do_fun_add(amount, note)
        except ValueError as e:
            await update.message.reply_text(f"❌ {e}")
            return

        days = _days_until_next_eighth()
        per_day = new_balance / days if days > 0 else new_balance

        await update.message.reply_text(
            f"✅ *Added ₪{amount:,.2f} to fun spending*\n\n"
            f"💸 Fun balance: *₪{new_balance:,.2f}*\n"
            f'💰 /ilcash עו"ש now: ₪{new_checking:,.2f}\n'
            f"📅 Days until next 8th: {days}\n"
            f"📊 Daily allowance: ₪{per_day:,.2f}",
            parse_mode='Markdown'
        )
        return

    if args and args[0].lower() == 'log':
        log = data.get('log', [])
        if not log:
            await update.message.reply_text("📜 No fun spending activity yet.")
            return
        header = "📜 *Fun Spending Log*\n━━━━━━━━━━━━━━━━━━━━\n\n"

        current_period_start = _period_start_for_date(datetime.now().date())
        period_spends = [
            t for t in log
            if t.get('type') == 'spend'
            and (_parse_log_date(t.get('date', '')) or datetime.min.date()) >= current_period_start
        ]
        chart = _format_period_chart(
            _compute_period_stats(period_spends),
            f"Current Period — {_period_label(current_period_start)}"
        )
        footer = chart + f"\n💸 Current balance: *₪{data.get('balance', 0):,.2f}*"
        blocks = []
        for t in reversed(log):
            emoji = "🟢" if t['amount'] > 0 else "🔴"
            block = f"{emoji} *{t['date']}*\n"
            block += f"   {t['description']}\n"
            block += f"   Amount: ₪{t['amount']:+,.2f}\n"
            method = t.get('payment_method')
            if method:
                method_emoji = '💵' if method == 'cash' else '💳'
                block += f"   {method_emoji} {method.capitalize()}\n"
            block += f"   Balance: ₪{t['balance_after']:,.2f}\n\n"
            blocks.append(block)
        CHUNK_LIMIT = 3800
        chunks = []
        current = header
        for block in blocks:
            if len(current) + len(block) > CHUNK_LIMIT:
                chunks.append(current)
                current = ""
            current += block
        if len(current) + len(footer) > CHUNK_LIMIT:
            chunks.append(current)
            chunks.append(footer.strip())
        else:
            chunks.append(current + footer)
        for chunk in chunks:
            await update.message.reply_text(chunk, parse_mode='Markdown')
        return

    if args and args[0].lower() in ('history', 'monthly'):
        log = data.get('log', [])
        spends = [t for t in log if t.get('type') == 'spend']
        if not spends:
            await update.message.reply_text("📭 No spending periods yet.")
            return

        groups = {}
        for t in spends:
            d = _parse_log_date(t.get('date', ''))
            if not d:
                continue
            ps = _period_start_for_date(d)
            groups.setdefault(ps, []).append(t)

        header = "📊 *Monthly Spending History*\n━━━━━━━━━━━━━━━━━━━━\n"
        blocks = []
        for ps in sorted(groups.keys(), reverse=True):
            stats = _compute_period_stats(groups[ps])
            blocks.append(_format_period_chart(stats, _period_label(ps)))

        CHUNK_LIMIT = 3800
        chunks = []
        current = header
        for block in blocks:
            if len(current) + len(block) > CHUNK_LIMIT:
                chunks.append(current)
                current = ""
            current += block
        if current:
            chunks.append(current)

        for chunk in chunks:
            await update.message.reply_text(chunk, parse_mode='Markdown')
        return

    balance = data.get('balance', 0)
    days = _days_until_next_eighth()
    per_day = balance / days if days > 0 else balance
    msg = "💸 *Fun Spending*\n━━━━━━━━━━━━━━━━━━━━\n\n"
    msg += f"💰 Balance: *₪{balance:,.2f}*\n"
    msg += f"📅 Days until next 8th: *{days}*\n"
    msg += f"📊 Daily allowance: *₪{per_day:,.2f}*\n\n"
    msg += "📌 `/fun_spending_add` to transfer from /ilcash (interactive)\n"
    msg += "📌 `/fun_spending add <amount> [note]` one-shot\n"
    msg += "📌 `/spend_casual <amount> <description>` to spend\n"
    msg += "📌 `/fun_spending log` for full activity\n"
    msg += "📌 `/fun_spending history` for monthly breakdowns"
    await update.message.reply_text(msg, parse_mode='Markdown')


async def spend_casual(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Spend from fun pool. Usage: /spend_casual <amount> <description>"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "❌ Usage: `/spend_casual <amount> <description>`\nExample: `/spend_casual 45 coffee`",
            parse_mode='Markdown'
        )
        return
    try:
        amount = float(args[0].replace('₪', '').replace('$', '').replace(',', ''))
    except ValueError:
        await update.message.reply_text("❌ Invalid amount.")
        return
    if amount <= 0:
        await update.message.reply_text("❌ Amount must be positive.")
        return

    description = ' '.join(args[1:]).strip()
    data = _load_fun_spending()
    balance = data.get('balance', 0)
    if amount > balance:
        await update.message.reply_text(
            f"❌ Not enough in fun pool. Available: ₪{balance:,.2f}"
        )
        return

    context.user_data['pending_spend'] = {'amount': amount, 'description': description}
    keyboard = [[
        InlineKeyboardButton("💵 Cash", callback_data="spend_pay:cash"),
        InlineKeyboardButton("💳 Visa", callback_data="spend_pay:visa"),
    ]]
    await update.message.reply_text(
        f"🛍️ *Confirm Purchase*\n\n"
        f"Amount: *₪{amount:,.2f}*\n"
        f"📝 {description}\n\n"
        f"How did you pay?",
        parse_mode='Markdown',
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def _handle_spend_payment(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Inline-button callback for /spend_casual payment-method selection."""
    query = update.callback_query
    await query.answer()

    pending = context.user_data.get('pending_spend')
    if not pending:
        await query.edit_message_text("❌ Spend session expired. Run /spend_casual again.")
        return

    method = query.data.split(':', 1)[1]
    method_emoji = '💵' if method == 'cash' else '💳'
    method_label = 'Cash' if method == 'cash' else 'Visa'

    amount = pending['amount']
    description = pending['description']

    data = _load_fun_spending()
    balance = data.get('balance', 0)
    if amount > balance:
        await query.edit_message_text(f"❌ Not enough in fun pool. Available: ₪{balance:,.2f}")
        context.user_data.pop('pending_spend', None)
        return

    new_balance = round(balance - amount, 2)
    data['balance'] = new_balance
    data.setdefault('log', []).append({
        'date': datetime.now().strftime('%Y-%m-%d %H:%M'),
        'type': 'spend',
        'amount': -amount,
        'description': description,
        'payment_method': method,
        'balance_after': new_balance,
    })
    _save_fun_spending(data)
    context.user_data.pop('pending_spend', None)

    days = _days_until_next_eighth()
    per_day = new_balance / days if days > 0 else new_balance

    await query.edit_message_text(
        f"🔴 *Spent ₪{amount:,.2f}* {method_emoji}\n\n"
        f"📝 {description}\n"
        f"💳 Payment: {method_label}\n"
        f"💸 Fun balance: *₪{new_balance:,.2f}*\n"
        f"📅 Days until next 8th: {days}\n"
        f"📊 New daily allowance: ₪{per_day:,.2f}",
        parse_mode='Markdown'
    )


def _do_fun_add(amount: float, note: str):
    """Deduct `amount` from עו"ש (reserves.ILS_checking), mirror in checking_log,
    and add to the fun pool. Returns (new_fun_balance, new_il_checking).
    Raises ValueError if insufficient funds."""
    portfolio = _load_portfolio()
    reserves = portfolio.setdefault('reserves', {})
    il_checking = reserves.get('ILS_checking', 0)
    if not ex.can_debit(il_checking, amount):
        raise ValueError(f'Past the overdraft limit of /ilcash (עו"ש). You can move up to '
                         f'{ex.money(max(0.0, ex.room(il_checking)))}')

    new_checking = round(il_checking - amount, 2)
    reserves['ILS_checking'] = new_checking
    _save_portfolio(portfolio)

    _log_ils_checking_transaction(
        amount=amount,
        trans_type='spend',
        note=f"Transfer to fun spending{' - ' + note if note else ''}",
        balance_after=new_checking,
    )

    data = _load_fun_spending()
    new_balance = round(data.get('balance', 0) + amount, 2)
    data['balance'] = new_balance
    data.setdefault('log', []).append({
        'date': datetime.now().strftime('%Y-%m-%d %H:%M'),
        'type': 'add',
        'amount': amount,
        'description': note or 'Transfer from /ilcash',
        'balance_after': new_balance,
    })
    _save_fun_spending(data)
    return new_balance, new_checking


