async def _handle_fun_add_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip()
    try:
        amount = float(text.replace('₪', '').replace('$', '').replace(',', ''))
    except ValueError:
        await update.message.reply_text("❌ Invalid number. Send a number like `120` or type /cancel.", parse_mode='Markdown')
        return
    if amount <= 0:
        await update.message.reply_text("❌ Amount must be positive. Try again or /cancel.")
        return

    portfolio = _load_portfolio()
    il_checking = portfolio.get('reserves', {}).get('ILS_checking', 0)
    if amount > il_checking:
        await update.message.reply_text(
            f'❌ Not enough in /ilcash (עו"ש). Available: ₪{il_checking:,.2f}\n'
            f"Send a smaller amount or /cancel."
        )
        return

    context.user_data['fun_add_amount'] = amount
    context.user_data['state'] = 'fun_add_note'
    await update.message.reply_text(
        f"💸 Transferring *₪{amount:,.2f}* from עו\"ש.\n\n"
        f"📝 Why this amount? Send a short description (or `-` to skip):",
        parse_mode='Markdown'
    )


async def _handle_fun_add_note(update: Update, context: ContextTypes.DEFAULT_TYPE):
    note_in = update.message.text.strip()
    note = '' if note_in == '-' else note_in
    amount = context.user_data.pop('fun_add_amount', None)
    context.user_data.pop('state', None)
    if amount is None:
        await update.message.reply_text("❌ Session lost. Run /fun_spending_add again.")
        return

    try:
        new_balance, new_checking = _do_fun_add(amount, note)
    except ValueError as e:
        await update.message.reply_text(f"❌ {e}")
        return

    days = _days_until_next_eighth()
    per_day = new_balance / days if days > 0 else new_balance
    note_line = f"📝 _{note}_\n" if note else ""
    await update.message.reply_text(
        f"✅ *Added ₪{amount:,.2f} to fun spending*\n\n"
        f"{note_line}"
        f"💸 Fun balance: *₪{new_balance:,.2f}*\n"
        f'💰 /ilcash עו"ש now: ₪{new_checking:,.2f}\n'
        f"📅 Days until next 8th: {days}\n"
        f"📊 Daily allowance: ₪{per_day:,.2f}",
        parse_mode='Markdown'
    )


async def commission_report(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show total commission paid, sorted by month"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    try:
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        sold_history = portfolio_data.get('sold_history', [])
        
        # Collect all commissions with dates
        commission_entries = []
        
        # From current holdings (buy commissions)
        for h in holdings:
            commission = h.get('commission', 0)
            if commission > 0:
                purchase_date = h.get('purchase_date', '')
                if purchase_date and purchase_date != 'Combined':
                    commission_entries.append({
                        'date': purchase_date,
                        'symbol': h['symbol'],
                        'type': 'BUY',
                        'amount': commission
                    })
                else:
                    # For combined holdings, use current date as fallback
                    commission_entries.append({
                        'date': datetime.now().strftime('%Y-%m-%d'),
                        'symbol': h['symbol'],
                        'type': 'BUY',
                        'amount': commission
                    })
        
        # From sold history (buy + sell commissions)
        for s in sold_history:
            buy_comm = s.get('buy_commission', 0)
            sell_comm = s.get('sell_commission', s.get('commission', 0))
            
            if buy_comm > 0:
                commission_entries.append({
                    'date': s.get('buy_date', s.get('sell_date', '')),
                    'symbol': s['symbol'],
                    'type': 'BUY',
                    'amount': buy_comm
                })
            if sell_comm > 0:
                commission_entries.append({
                    'date': s.get('sell_date', ''),
                    'symbol': s['symbol'],
                    'type': 'SELL',
                    'amount': sell_comm
                })
        
        # Currency conversions (/addcash): the $ commission on each.
        for t in portfolio_data.get('cash_log', []):
            fee = float(t.get('fx_commission') or 0)
            if fee > 0:
                commission_entries.append({
                    'date': str(t.get('date', ''))[:10],
                    'symbol': 'המרה ₪→$' + (' Interactive' if t.get('broker') == brk.IBKR else ''),
                    'type': 'FX',
                    'amount': fee
                })

        if not commission_entries:
            await update.message.reply_text(
                "💸 *Commission Report*\n\n"
                "No stock commission data found.\n"
                "Commissions are tracked when you buy/sell stocks."
                + bf.format_section(bf.load()),
                parse_mode='Markdown'
            )
            return
        
        # Group by month
        monthly_data = {}
        total_commission = 0
        
        for entry in commission_entries:
            date_str = entry['date']
            amount = entry['amount']
            total_commission += amount
            
            if date_str and len(date_str) >= 7:
                month_key = date_str[:7]  # YYYY-MM format
            else:
                month_key = 'Unknown'
            
            if month_key not in monthly_data:
                monthly_data[month_key] = {
                    'total': 0,
                    'entries': []
                }
            
            monthly_data[month_key]['total'] += amount
            monthly_data[month_key]['entries'].append(entry)
        
        # Sort months (newest first)
        sorted_months = sorted(monthly_data.keys(), reverse=True)
        
        # Build message
        message = "💸 *COMMISSION REPORT*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        message += f"📊 *Total Commissions Paid: ${total_commission:,.2f}*\n\n"
        
        message += "📅 *By Month:*\n"
        message += "─────────────────\n"
        
        for month in sorted_months:
            data = monthly_data[month]
            # Format month nicely
            if month != 'Unknown':
                try:
                    month_display = datetime.strptime(month, '%Y-%m').strftime('%B %Y')
                except:
                    month_display = month
            else:
                month_display = 'Unknown Date'
            
            message += f"\n📆 *{month_display}*: ${data['total']:,.2f}\n"
            
            # Show individual transactions for the month
            for entry in data['entries']:
                emoji = {'BUY': "🟢", 'FX': "💱"}.get(entry['type'], "🔴")
                message += f"   {emoji} {entry['symbol']} ({entry['type']}): ${entry['amount']:.2f}\n"
        
        message += "\n━━━━━━━━━━━━━━━━━━━━\n"
        message += f"💰 *Grand Total: ${total_commission:,.2f}*"
        # ILS bank fees are shekels - kept out of the dollar total on purpose.
        message += bf.format_section(bf.load())
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ===================== SAVINGS ALLOCATION PLANNER =====================
# Plans how each month's pay is split across the three savings buckets.
# Everything here is read-only against the money ledgers: it reports the split,
# and recording it stays with /addreserve, /ilcash and friends.

def _planner_fx_sync():
    """USD/EUR -> ILS, with the same fallback rates used elsewhere in the bot."""
    try:
        usd = yf.Ticker("USDILS=X").info.get('regularMarketPrice') or 3.6
    except Exception:
        usd = 3.6
    try:
        eur = yf.Ticker("EURILS=X").info.get('regularMarketPrice') or 3.9
    except Exception:
        eur = 3.9
    return {'USDILS': float(usd), 'EURILS': float(eur)}


def _apply_live_float(plan, today=None):
    """Fill in last month's real spending when the float follows it.

    The target is then last month's total (debit, Visa and cash; currency
    purchases excluded) plus the buffer. A month with nothing logged falls back
    to the average of the months that have entries, and with no history at all
    the fixed figures stand in."""
    cfg = dict((plan or {}).get('float') or {})
    if cfg.get('mode') != sp.FLOAT_AUTO:
        return plan
    today = today or _israel_today()
    previous = (today.replace(day=1) - timedelta(days=1)).strftime('%Y-%m')
    entries = _load_spend_entries()
    summary = ex.month_summary(entries, previous)
    cfg.pop('last_month_spend', None)
    if summary['count']:
        cfg.update(last_month_spend=summary['total'], basis_month=previous, basis='last_month')
    else:
        guess = ex.predict(entries, today.strftime('%Y-%m'))
        if guess.get('months'):
            cfg.update(last_month_spend=guess['average'], basis_month=previous, basis='average')
    plan['float'] = cfg
    return plan


def _load_plan():
    """The savings plan, with the float target worked out from real spending and
    the overall target grown by inflation (both recomputed on every load)."""
    return _apply_inflation(_apply_live_float(sp.load_plan()))


def _apply_inflation(plan):
    """Set target['amount_nominal']: the /plantarget amount (today's money) in
    shekels of the plan's last month, from the cached CPI -- no network here."""
    target = plan.get('target') or {}
    target.pop('amount_nominal', None)
    target.pop('inflation', None)
    if not target.get('amount') or target.get('currency', 'ILS') != 'ILS':
        return plan
    months = sorted((plan.get('months') or {}).keys())
    if not months:
        return plan
    try:
        adj = infl.adjust(infl.load(), float(target['amount']), months[-1])
        if adj and abs(adj['extra']) >= 0.01:
            target['amount_nominal'] = adj['nominal']
            target['inflation'] = adj
    except Exception as e:
        _planner_log(f"inflation adjustment skipped: {e}")
    return plan


def _plan_months_left(plan, today=None):
    key = (today or _israel_today()).strftime('%Y-%m')
    return len([m for m in (plan.get('months') or {}) if m >= key])


async def inflation_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/inflation [on|off|refresh|rate X|rate auto|base YYYY-MM] - Israel's CPI and the plan target."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = [str(a).strip().lower() for a in (context.args or [])]
    state = infl.load()
    today = _israel_today()
    note = ''
    try:
        if args and args[0] in ('on', 'off'):
            state['enabled'] = args[0] == 'on'
            note = '✅ ההתאמה לאינפלציה %s.\n\n' % ('פעילה' if state['enabled'] else 'כבויה')
        elif args and args[0] == 'rate' and len(args) > 1:
            if args[1] == 'auto':
                state['rate_override'] = None
                note = '✅ השיעור לעתיד: לפי 12 החודשים האחרונים.\n\n'
            else:
                rate = float(args[1].replace('%', ''))
                if not -5 <= rate <= 30:
                    raise ValueError
                state['rate_override'] = rate
                note = '✅ השיעור לעתיד: %.1f%% לשנה.\n\n' % rate
        elif args and args[0] == 'base' and len(args) > 1:
            if not any(r['month'] == args[1] for r in state.get('series') or []):
                await update.message.reply_text("❌ אין מדד לחודש הזה. שלח למשל /inflation base 2026-08")
                return
            state['base_month'] = args[1]
            note = '✅ היעד נחשב מעכשיו בכוח קנייה של %s.\n\n' % infl.month_label(args[1])
        elif args and args[0] not in ('refresh',):
            raise ValueError
    except ValueError:
        await update.message.reply_text(
            "❌ /inflation · /inflation on|off · /inflation rate 2.5 · /inflation rate auto · /inflation base 2026-08")
        return
    if not state.get('series') or (args and args[0] == 'refresh') or infl.needs_check(state, today):
        try:
            await asyncio.to_thread(infl.refresh, state, today)
        except Exception as e:
            _planner_log(f"CPI fetch failed: {e}")
            if not state.get('series'):
                await update.message.reply_text(f"❌ לא הצלחתי להביא את המדד מהלמ\"ס: {e}")
                return
            note += '_⚠️ לא הצלחתי לרענן מהלמ"ס — מוצגים הנתונים השמורים._\n\n'
    infl.save(state)
    plan = _load_plan()
    adj = (plan.get('target') or {}).get('inflation')
    credit = await _inflation_credit_now(plan) if adj else 0.0
    await _planner_reply(update, note + infl.format_report(state, adj, _plan_months_left(plan, today),
                                                           ils_credit=credit))


async def _inflation_credit_now(plan):
    """How much of the inflation extra the CPI-linked ILS bank fund covers by the
    plan's end, from the projected balances (0 if it cannot be worked out)."""
    try:
        fx = await asyncio.to_thread(_planner_fx_sync)
        balances = await _planner_balances()
        key = _israel_today().strftime('%Y-%m')
        months = [m for m in sorted(plan.get('months') or {}) if m >= key]
        steps = sp.project_timeline(plan, balances, fx, months) if months else []
        return sp.inflation_credit(plan, steps[-1]['balances'] if steps else balances)
    except Exception as e:
        _planner_log(f"inflation credit failed: {e}")
        return 0.0


async def _check_inflation(app, today):
    """Daily from the 14th until the new CPI is out; then one message on what changed."""
    state = infl.load()
    if not infl.needs_check(state, today):
        return
    before = (_load_plan().get('target') or {}).get('inflation')
    try:
        new = await asyncio.to_thread(infl.refresh, state, today)
    except Exception as e:
        _planner_log(f"CPI check failed: {e}")
        state['fetched'] = today.isoformat()        # try again tomorrow, not every 5 minutes
        infl.save(state)
        return
    infl.save(state)
    row = infl.latest(state)
    if not new or not row or state.get('notified_month') == row['month']:
        return
    plan = _load_plan()
    after = (plan.get('target') or {}).get('inflation')
    lines = ['📈 *מדד המחירים ל%s פורסם*' % infl.month_label(row['month']), '',
             'החודש: *%+.1f%%* · 12 חודשים: *%+.1f%%*' % (row['pct_month'], row['pct_year'])]
    if after:
        lines += ['', infl.format_adjustment(after)]
        if before:
            diff = after['nominal'] - before['nominal']
            lines.append('   _לעומת %s לפני המדד (%s%s)_' % (
                sp.money(before['nominal'], 'ILS'), '+' if diff >= 0 else '-', sp.money(abs(diff), 'ILS')))
        left = _plan_months_left(plan, today)
        if left:
            credit = await _inflation_credit_now(plan)
            if credit:
                lines.append('   🏦 החיסכון הבנקאי ₪ צמוד מדד — מכסה לבד ≈%s' % sp.money(credit, 'ILS'))
            lines.append('   💡 ≈%s לחודש נוספים כדי לשמור על כוח הקנייה'
                         % sp.money(max(0.0, after['extra'] - credit) / left, 'ILS'))
        lines.append('_/plan ו-/salarytogoal כבר מעודכנים. פירוט: /inflation_')
    try:
        await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, text='\n'.join(lines), parse_mode='Markdown')
        state['notified_month'] = row['month']
        infl.save(state)
    except Exception as e:
        _planner_log(f"inflation message failed: {e}")


async def _planner_balances():
    """Where each bucket stands right now, in its own currency."""
    data = _load_portfolio()
    reserves_data = data.get('reserves', {}) or {}

    ils_bank = float(reserves_data.get('ILS', 0) or 0)
    eur_total = (float(reserves_data.get('EUR', 0) or 0)
                 + float(reserves_data.get('EUR_cash', 0) or 0))
    # Same field /ilcash reports as Checking (עו"ש) - the living-expenses float.
    checking = float(reserves_data.get('ILS_checking', 0) or 0)

    usd_stocks = _usd_cash_total(data)
    try:
        result = await asyncio.to_thread(_fetch_portfolio_data_sync, data.get('holdings', []))
        usd_stocks += float(result[2] or 0)          # total_value
    except Exception as e:
        print(f"Planner: could not price holdings ({e})")

    # The EUR savings also hold the shekel קרן כספית bought for euros, counted at today's rate.
    eur_fund = ef.balance(data)
    if eur_fund:
        eur_total += eur_fund / await asyncio.to_thread(_eur_ils_cached)

    funds = ilf.read(reserves_data)
    return {sp.BUCKETS[0]: funds[ilf.EMERGENCY], sp.BUCKETS[1]: funds[ilf.FUTURE],
            'EUR': eur_total, 'USD_STOCKS': usd_stocks, sp.CHECKING: checking, sp.EUR_FUND: eur_fund}


_EURILS_CACHE = {'at': None, 'rate': None}


def _eur_ils_cached():
    """EUR->ILS, fetched at most every 10 minutes (the balances are read often)."""
    now = datetime.now()
    if _EURILS_CACHE['rate'] and _EURILS_CACHE['at'] and (now - _EURILS_CACHE['at']).total_seconds() < 600:
        return _EURILS_CACHE['rate']
    try:
        rate = float(yf.Ticker("EURILS=X").info.get('regularMarketPrice') or 0) or 3.9
    except Exception:
        rate = _EURILS_CACHE['rate'] or 3.9
    _EURILS_CACHE.update(at=now, rate=rate)
    return rate


async def _planner_snapshot(balances=None):
    """Every aspect of the money as it stands right now, for /plan.

    /plan used to project from four bucket balances, which quietly ignored
    physical cash, a Visa charge already committed, the locked study fund, what
    is actually being spent each month, the fees paid to move money, purchase
    goals and any running trip. All of it is gathered here so the plan is read
    against the real position; nothing in this function writes.
    """
    balances = balances if balances is not None else await _planner_balances()
    data = _load_portfolio()
    reserves_data = data.get('reserves', {}) or {}
    today = _israel_today()

    snap = {
        'checking': float(reserves_data.get('ILS_checking', 0) or 0),
        'cash': 0.0,
        'emergency': float(balances.get(sp.BUCKETS[0], 0) or 0),
        'future': float(balances.get(sp.BUCKETS[1], 0) or 0),
        'eur_bank': float(reserves_data.get('EUR', 0) or 0),
        'eur_cash': float(reserves_data.get('EUR_cash', 0) or 0),
        'eur_fund': ef.balance(data),
        'usd_free': _usd_cash_total(data),
        'usd_holdings': 0.0,
        'usd_pl': None,
    }

    try:
        snap['cash'] = _cash_balance()
    except Exception as e:
        _planner_log(f'snapshot: cash unavailable ({e})')

    # Stocks: priced live, but a dead feed must not take /plan down with it.
    try:
        result = await asyncio.to_thread(_fetch_portfolio_data_sync, data.get('holdings', []))
        snap['usd_holdings'] = float(result[2] or 0)
        cost = float(result[1] or 0)
        if cost:
            snap['usd_pl'] = round(snap['usd_holdings'] - cost, 2)
    except Exception as e:
        _planner_log(f'snapshot: holdings not priced ({e})')
        # Fall back to whatever _planner_balances already managed to price, so the
        # stocks line is never silently reported as empty.
        priced = float(balances.get('USD_STOCKS', 0) or 0) - snap['usd_free']
        snap['usd_holdings'] = max(0.0, round(priced, 2))

    # Spending: this month so far, the average behind it, and the Visa bill that
    # is already committed but has not left the account yet.
    try:
        entries = _load_spend_entries()
        month_key = today.strftime('%Y-%m')
        summary = ex.month_summary(entries, month_key)
        snap['spend_month_key'] = month_key
        snap['spend_month'] = float(summary.get('total', 0) or 0)
        snap['spend_count'] = int(summary.get('count', 0) or 0)
        snap['spend_predict'] = ex.predict(entries, month_key)
        pending = ex.pending_visa(entries)
        # Only what has not been set aside yet still has to leave the עו"ש.
        snap['pending_visa'] = ex.total_of(ex.unreserved(pending))
        snap['visa_charge_date'] = ex.next_charge_date(today) if pending else None
    except Exception as e:
        _planner_log(f'snapshot: expenses unavailable ({e})')
        snap['pending_visa'] = 0.0

    try:
        state = kr.load()
        snap['keren'] = {
            'balance': float(state.get('balance', 0) or 0),
            'monthly': float(state.get('monthly', 0) or 0),
            'unlock': kr.unlock_date(state).strftime('%d.%m.%Y'),
            'months_left': kr.months_until_unlock(state, today),
            'locked': kr.is_locked(state, today),
        }
    except Exception as e:
        _planner_log(f'snapshot: keren unavailable ({e})')

    try:
        entries = bf.load()
        snap['fees'] = {
            'total': bf.total(entries),
            'count': len(entries),
            'month': bf.monthly_totals(entries).get(today.strftime('%Y-%m'), 0.0),
        }
    except Exception as e:
        _planner_log(f'snapshot: fees unavailable ({e})')

    try:
        goals = _load_goals().get('goals', []) or []
        snap['purchases'] = [{'name': g.get('name', 'item'),
                              'cost': float(g.get('target', 0) or 0)}
                             for g in goals if g.get('type') == 'purchase']
    except Exception as e:
        _planner_log(f'snapshot: purchase goals unavailable ({e})')

    try:
        running = tp.active_trip(tp.load_all(), today)
        if running:
            running_totals = tp.totals(running)
            end = tp._as_date(running.get('end'))
            snap['trip'] = {
                'name': running.get('name', ''),
                'currency': running.get('currency', ''),
                'spent_ils': running_totals.get('ils_total', 0),
                'cash_left': tp.cash_balance(running),
                'eur_left': snap['eur_bank'],
                'days_left': max(0, (end - today).days) if end else None,
            }
    except Exception as e:
        _planner_log(f'snapshot: trip unavailable ({e})')

    return snap


PLANNER_LOG = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'planner_debug.log')
ERROR_LOG = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'errors.log')


def _planner_log(message):
    """The bot runs windowless under pythonw, so stdout goes nowhere.
    Planner trouble has to land in a file or it is invisible."""
    try:
        with open(PLANNER_LOG, 'a', encoding='utf-8') as fh:
            fh.write(f"{datetime.now():%Y-%m-%d %H:%M:%S}  {message}\n")
    except Exception:
        pass


async def _planner_reply(update, text, reply_markup=None):
    """Markdown when it parses, plain text when it does not.

    A Markdown failure must not swallow the message: if the retry also fails the
    error is logged rather than lost, which is how /setplan went silent before.

    Anything past Telegram's 4096-character limit is split on blank lines, since
    /plan now reports the whole position and outgrows a single message. Buttons,
    if any, go on the last part, under the end of what they refer to.
    """
    parts = _planner_chunks(text)
    for index, part in enumerate(parts):
        markup = reply_markup if index == len(parts) - 1 else None
        try:
            await update.message.reply_text(part, parse_mode='Markdown', reply_markup=markup)
            continue
        except Exception as markdown_error:
            _planner_log(f"markdown reply failed ({markdown_error}); retrying as plain text")
        try:
            await update.message.reply_text(part, reply_markup=markup)
        except Exception as plain_error:
            _planner_log(f"plain reply ALSO failed: {plain_error}")
            raise


def _planner_chunks(text, limit=3800):
    """Split on blank lines first so a section is never cut in half, falling back
    to single lines for a block that is itself too long."""
    if len(text) <= limit:
        return [text]
    parts, current = [], ''
    for block in text.split('\n\n'):
        if len(block) > limit:                     # one oversized block: by line
            for line in block.split('\n'):
                if len(current) + len(line) + 1 > limit:
                    parts.append(current)
                    current = line
                else:
                    current = (current + '\n' + line) if current else line
            continue
        if len(current) + len(block) + 2 > limit:
            parts.append(current)
            current = block
        else:
            current = (current + '\n\n' + block) if current else block
    if current:
        parts.append(current)
    return [p for p in parts if p.strip()]


LAST_PLAN_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'last_plan.json')


def _save_last_plan(text):
    """Keep exactly what /plan just calculated, so /showplan can show it later
    without recalculating from a situation that has since moved."""
    payload = {'saved_at': datetime.now(ZoneInfo('Asia/Jerusalem')).strftime('%Y-%m-%d %H:%M'),
               'text': text}
    with open(LAST_PLAN_FILE, 'w', encoding='utf-8') as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)


def _load_last_plan():
    try:
        with open(LAST_PLAN_FILE, 'r', encoding='utf-8') as fh:
            saved = json.load(fh)
        return saved if saved.get('text') else None
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None


def _age_text(saved_at):
    """'3 hours ago' for the saved plan, so stale numbers look stale."""
    try:
        then = datetime.strptime(saved_at, '%Y-%m-%d %H:%M').replace(
            tzinfo=ZoneInfo('Asia/Jerusalem'))
        minutes = int((datetime.now(ZoneInfo('Asia/Jerusalem')) - then).total_seconds() // 60)
    except (ValueError, TypeError):
        return ''
    if minutes < 2:
        return 'just now'
    if minutes < 120:
        return f'{minutes} minutes ago'
    if minutes < 48 * 60:
        return f'{minutes // 60} hours ago'
    return f'{minutes // (24 * 60)} days ago'


async def _build_plan_text():
    """Everything /plan shows, from the data as it is right now."""
    plan = _load_plan()
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    # The snapshot is what makes /plan read against the real position instead
    # of four bucket balances; if any one ledger is unreadable the plan still
    # prints, just without that section.
    snapshot = await _planner_snapshot(balances)

    # What salary the goals above require. A failure here must not cost the
    # user the plan itself, so it only drops that block.
    salary_text = ''
    try:
        salary_state = sgl.load_state()
        salary_text = sgl.format_block(
            sgl.compute(plan, balances, fx, salary_state['config']))
    except Exception as e:
        _planner_log(f"/plan salary block failed: {e}")
    return sp.format_plan(plan, balances, fx, snapshot, salary_text)


async def savings_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/plan - show the allocation plan and where it lands."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("📅 Building your plan...")
    try:
        text = await _build_plan_text()
        # /plan (and a finished /allocated) write this: /showplan shows that copy.
        try:
            _save_last_plan(text)
        except Exception as e:
            _planner_log(f"could not save the plan for /showplan: {e}")
        await _planner_reply(update, text)
    except Exception as e:
        _planner_log(f"/plan failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


async def show_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/showplan - the plan from the last time /plan was run, as it was then."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    # First, live: next month's planned allocation, the goals and the pay needed.
    try:
        upcoming = await _showplan_next_month_block()
        if upcoming:
            await _planner_reply(update, upcoming)
    except Exception as e:
        _planner_log(f"/showplan next-month block failed: {e}")
    saved = _load_last_plan()
    if not saved:
        await update.message.reply_text(
            "📌 No saved plan yet.\n\nRun /plan once: it calculates from your "
            "current situation and saves the result, and from then on /showplan "
            "shows that saved version.")
        return
    age = _age_text(saved.get('saved_at', ''))
    head = (f"📌 *Saved plan* — calculated {saved.get('saved_at', '?')}"
            + (f" _({age})_" if age else "")
            + "\n_Not recalculated: this is exactly what /plan showed then. "
              "Run /plan for today's numbers._\n\n")
    tail = ''
    if 'with inflation' not in saved['text']:
        # Saved before /inflation existed: keep it as it was, and add what
        # inflation does to the target and the salary needed, worked out now.
        try:
            tail = await _showplan_inflation_block()
        except Exception as e:
            _planner_log(f"/showplan inflation block failed: {e}")
    try:
        extra = [wl.savings_line(_load_plan()),
                 wl.emergency_line(_emergency_fund(), _load_spend_entries(), _israel_today())]
        extra = [x for x in extra if x]
        if extra:
            tail += '\n\n' + '\n'.join(extra)
    except Exception as e:
        _planner_log(f"/showplan savings lines failed: {e}")
    # Past months always come from the records as they are now (not the copy).
    try:
        history = al.format_history(_load_plan(), current_month=sp.month_key())
        if history:
            tail += '\n\n' + history
    except Exception as e:
        _planner_log(f"/showplan history failed: {e}")
    await _planner_reply(update, head + saved['text'] + tail)


def _next_plan_month(plan, today=None):
    """The first planned month (from this one on) whose allocation is not recorded."""
    current = (today or _israel_today()).strftime('%Y-%m')
    done = {p.get('month') for p in plan.get('payments') or [] if p.get('actual')}
    return next((m for m in sorted(plan.get('months') or {}) if m >= current and m not in done), None)


async def _showplan_next_month_block():
    plan = _load_plan()
    month = _next_plan_month(plan)
    if not month:
        return ("📅 *אין חודש מתוכנן קדימה* — כל החודשים בתוכנית כבר הוקצו.\n"
                "בנה תוכנית חדשה עם /setplan.")
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    step = sp.next_month_preview(plan, balances, fx, month)
    if not step:
        return ''
    salary = None
    try:
        salary = sgl.compute(plan, balances, fx, sgl.load_state()['config'])
    except Exception as e:
        _planner_log(f"/showplan salary block failed: {e}")
    return sp.format_next_month(plan, balances, fx, month, step, salary)


async def _showplan_inflation_block():
    plan = _load_plan()
    adj = (plan.get('target') or {}).get('inflation')
    if not adj:
        return ''
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    res = sgl.compute(plan, balances, fx, sgl.load_state()['config'])
    lines = ['', '', '━' * 20, '📈 *INFLATION* _(calculated now — not in the saved plan above)_',
             infl.format_adjustment(adj)]
    if res.get('need_net') is not None:
        diff = res['need_net'] - res['current_net']
        lines += ['', '💼 *Salary needed with inflation* — %s' % sgl._basis_text(res).replace('_', ''),
                  '   Net: *%s* / month  _(now %s, %s%s)_' % (
                      sp.money(res['need_net'], 'ILS'), sp.money(res['current_net'], 'ILS'),
                      '+' if diff >= 0 else '-', sp.money(abs(diff), 'ILS')),
                  '   Gross: *≈ %s*' % sp.money(res['need_gross'], 'ILS')]
    lines.append('_The saved plan above used %s without inflation. Run /plan to save a version with it._'
                 % sp.money(adj['real'], 'ILS'))
    return '\n'.join(lines)


async def set_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/setplan - bare opens the wizard, or takes args for the fast path."""
    import traceback
    _planner_log(f"/setplan user={getattr(update.effective_user, 'id', None)} "
                 f"args={getattr(context, 'args', None)}")
    try:
        return await _set_plan_inner(update, context)
    except Exception as e:
        _planner_log("set_plan CRASHED:\n" + traceback.format_exc())
        try:
            await update.message.reply_text(f"❌ /setplan failed: {e}")
        except Exception:
            pass
        return ConversationHandler.END


async def _set_plan_inner(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_authorized(update.effective_user.id):
        _planner_log("blocked: user not in ALLOWED_USER_IDS")
        await unauthorized_message(update)
        return ConversationHandler.END

    args = context.args or []
    usage = ("*Set your monthly split*\n\n"
             "`/setplan all emg=30 fut=20 eur=20 usd=30`  - all 12 months\n"
             "`/setplan 2026-10 emg=40 fut=20 eur=20 usd=20`  - one month\n"
             "`/setplan edit`  - pick a month and change its split with buttons\n\n"
             "Shorthand: `/setplan all 30/20/20/30`\n"
             "_(🛟emergency / 🎯future / 💶EUR (קרן כספית) / 📈stocks)_\n"
             "Anything under 100% stays unallocated for spending.")
    if not args:
        return await _plan_wizard_start(update, context)

    scope, rest = args[0], args[1:]
    if scope.lower() in ('edit', 'change', 'שנה'):
        plan = _load_plan()
        if not _plan_edit_months(plan):
            await update.message.reply_text("אין חודשים בתוכנית — שלח /setplan")
        else:
            await update.message.reply_text("✏️ *איזה חודש לשנות?*\n_החלוקה הנוכחית ליד כל חודש: 🛟/🎯/💶/📈_",
                                            parse_mode='Markdown', reply_markup=_plan_edit_list_markup(plan))
        return ConversationHandler.END
    if scope.lower() in ('keren', 'קרן'):
        try:
            amount = ks.parse_monthly(rest[0] if rest else '')
        except ValueError:
            await update.message.reply_text(f"❌ שלח סכום בין 0 ל-{ks.MAX_MONTHLY:,.0f}, למשל /setplan keren 1714")
            return ConversationHandler.END
        plan = _load_plan()
        plan['keren_self_monthly'] = amount
        sp.save_plan(plan)
        await update.message.reply_text(
            f"✅ {ks.LABEL}: ₪{amount:,.2f} בחודש — יורד מכל משכורת לפני החלוקה באחוזים." if amount
            else f"✅ {ks.LABEL}: בוטל (לא מפקידים).")
        return ConversationHandler.END
    try:
        if scope.lower() in ('all', 'six', '6'):
            months = sp.upcoming_months(sp.PLAN_HORIZON)
        else:
            sp.month_name(scope)                      # validates YYYY-MM
            months = [scope]
        alloc = sp.parse_allocation(rest)
    except ValueError as e:
        await _planner_reply(update, f"❌ {e}\n\n{usage}")
        return

    plan = _load_plan()
    for key in months:
        plan['months'][key] = alloc
    sp.save_plan(plan)

    try:
        fx = await asyncio.to_thread(_planner_fx_sync)
        balances = await _planner_balances()
        await _planner_reply(update, sp.format_plan(plan, balances, fx))
    except Exception as e:
        await update.message.reply_text(f"✅ Saved {len(months)} month(s), but projection failed: {e}")


# --- step-by-step planner wizard -------------------------------------------
# Bare /setplan walks month by month with buttons, the way /reserves does,
# instead of making you remember an argument format.

PLAN_MONTH = 200
PLAN_CUSTOM = 201
PLAN_TARGET = 202
PLAN_GOAL_ILS = 203
PLAN_GOAL_EUR = 204
PLAN_KEREN = 205
PLAN_INCOME = 206
PLAN_SPEND = 207
PLAN_MONTH_INCOME = 208
PLAN_CONFIRM = 209


def _parse_goal(text):
    """A goal amount, or None for 'no goal'. Raises ValueError on nonsense."""
    cleaned = (text or '').strip().replace(',', '').replace('₪', '').replace('€', '')
    if cleaned in ('-', '0', ''):
        return None
    value = float(cleaned)
    if value < 0:
        raise ValueError('שלילי')
    return value


def _plan_keyboard(step_index):
    rows, row = [], []
    for triple in sp.PRESETS:
        # Built from the tuple's own length: presets gained a fourth bucket and a
        # fixed '%d-%d-%d' silently broke every button.
        row.append(InlineKeyboardButton(
            sp.preset_label(triple),
            callback_data='pset:' + '-'.join(str(int(x)) for x in triple)))
        if len(row) == 3:
            rows.append(row)
            row = []
    if row:
        rows.append(row)

    extra = []
    if step_index > 0:
        extra.append(InlineKeyboardButton("↩️ Same as last", callback_data="pset:same"))
    extra.append(InlineKeyboardButton("✏️ Custom", callback_data="pset:custom"))
    rows.append(extra)
    rows.append([InlineKeyboardButton("⏭ Skip month", callback_data="pset:skip"),
                 InlineKeyboardButton("❌ Cancel", callback_data="pset:cancel")])
    return InlineKeyboardMarkup(rows)


def _plan_goal_view(wiz):
    """Just the goals, shaped the way savings_planner expects a plan (and the future expenses' need)."""
    return {'goals': {k: v for k, v in (wiz.get('goals') or {}).items() if v},
            'future_need': (wiz.get('cfg') or {}).get('future_need') or 0}


def _future_need():
    """What /futureexpenses asks to set aside each month (items with a date)."""
    try:
        today = _israel_today()
        return round(sum(pln.monthly_need(i, today) or 0 for i in pln.load()['items']), 2)
    except Exception as e:
        _planner_log(f"future need failed: {e}")
        return 0.0


def _plan_temp(wiz):
    return {'salary': {'amount': wiz['salary']},
            'month_income': dict(wiz.get('incomes') or {}),
            'months': {k: v for k, v in wiz['chosen'].items() if v},
            'float': wiz.get('cfg'),
            'goals': (wiz.get('goals') or {}),
            'keren_self_monthly': (wiz.get('cfg') or {}).get('keren_self') or 0,
            'expected_spend': wiz.get('spend') or 0}


def _plan_running(wiz):
    """Balances as they stand after the months chosen so far, checking included."""
    done = wiz['months'][:wiz['index']]
    steps = sp.project_timeline(_plan_temp(wiz), wiz['balances'], wiz['fx'], done)
    if not steps:
        return dict(wiz['balances'])
    running = dict(steps[-1]['balances'])
    running[sp.CHECKING] = steps[-1]['checking_end']
    return running


def _plan_last_step(wiz):
    done = wiz['months'][:wiz['index']]
    steps = sp.project_timeline(_plan_temp(wiz), wiz['balances'], wiz['fx'], done)
    return steps[-1] if steps and steps[-1]['month'] == done[-1] else None


async def _plan_wizard_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    import traceback
    _planner_log("wizard: start")
    await update.message.reply_text("📅 Reading your balances...")
    try:
        plan = _load_plan()
        _planner_log(f"wizard: plan loaded, salary={(plan.get('salary') or {}).get('amount')}")
        fx = await asyncio.to_thread(_planner_fx_sync)
        _planner_log(f"wizard: fx={fx}")
        balances = await _planner_balances()
        _planner_log(f"wizard: balances={ {k: round(v, 2) for k, v in balances.items()} }")
    except Exception as e:
        _planner_log("wizard: load FAILED:\n" + traceback.format_exc())
        await update.message.reply_text(f"❌ Could not load your data: {e}")
        return ConversationHandler.END

    # A fresh /setplan replaces the previous plan outright, and starts from next
    # month - this month's pay has usually been dealt with already.
    # Once this month's allocation is recorded (/allocated), it is done: the new
    # plan starts with next month.
    start = sp.month_key()
    if any(p.get('month') == start and p.get('actual') for p in plan.get('payments') or []):
        start = sp.shift_month(start, 1)
    months = sp.upcoming_months(sp.PLAN_HORIZON, start)
    context.user_data['plan_wizard'] = {
        'months': months, 'index': 0, 'chosen': {},
        'balances': balances, 'fx': fx,
        'salary': (plan.get('salary') or {}).get('amount') or 0,
        'cfg': dict(sp.float_config(plan), future_need=_future_need()),
        'goals': dict(sp.goals_of(plan)),
    }
    wiz = context.user_data['plan_wizard']

    await _planner_reply(update, sp.format_wizard_intro(
        balances, fx, wiz['salary'], len(months), wiz['cfg'], start=months[0]))
    await _planner_reply(update,
        "\U0001F4BC *ההכנסה הרגילה שלך*\n\n"
        "כמה אתה מרוויח נטו בחודש רגיל (מה שנכנס לחשבון)?\n"
        "_לפני כל חודש אשאל שוב — אם בחודש מסוים יהיה שונה, תעדכן שם_\n"
        + (f"עכשיו בתוכנית: *{sp.money(wiz['salary'], 'ILS')}*\n" if wiz['salary'] else "")
        + "\nשלח סכום" + (", או *-* כדי להשאיר" if wiz['salary'] else "")
        + "\n_ככה כל חודש יראה כמה כסף בדיוק הולך לכל מקום_")
    return PLAN_INCOME


async def plan_income_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    text = (update.message.text or '').strip().replace(',', '').replace('₪', '')
    if text not in ('-', '') or not wiz['salary']:
        try:
            amount = float(text)
            if amount <= 0 or amount > 1_000_000:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ שלח סכום חודשי נטו, למשל 9000" + (" (או - כדי להשאיר)" if wiz['salary'] else ""))
            return PLAN_INCOME
        wiz['salary'] = round(amount, 2)
    await update.message.reply_text(f"✅ הכנסה צפויה: ₪{wiz['salary']:,.2f} בחודש")
    current = float(_load_plan().get('expected_spend') or 0)
    await _planner_reply(update,
        "\U0001F4B3 *הוצאות חודשיות מהעו\"ש*\n\n"
        "כמה אתה מצפה להוציא בחודש מהעו\"ש (אוכל, תחבורה, בילויים...)?\n"
        + (f"עכשיו בתוכנית: *{sp.money(current, 'ILS')}*\n" if current else "")
        + f"החודש שעבר הוצאת: {sp.money(wiz['cfg'].get('monthly_spend', 0), 'ILS')}\n"
        + "\nשלח סכום (למשל 1500)" + (", או *-* כדי להשאיר" if current else "")
        + "\n_הסכום הזה יישאר בעו\"ש בכל חודש — רק מה שמעבר לו ייחלק_")
    return PLAN_SPEND


async def plan_spend_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    text = (update.message.text or '').strip().replace(',', '').replace('₪', '')
    current = float(_load_plan().get('expected_spend') or 0)
    if text in ('-', '') and current:
        spend = current
    else:
        try:
            spend = float(text)
            if spend <= 0 or spend > 100_000:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ שלח סכום חודשי, למשל 1500" + (" (או - כדי להשאיר)" if current else ""))
            return PLAN_SPEND
    wiz['spend'] = round(spend, 2)
    # Each payday is assumed to find the עו"ש spent down by this much, so every month
    # first puts the spending back -- then the keren, then the split.
    target = max(float(wiz['cfg'].get('target') or 0), wiz['spend'])
    wiz['cfg'] = dict(wiz['cfg'], monthly_spend=wiz['spend'], target=target, planned_spend=wiz['spend'])
    wiz['balances'] = dict(wiz['balances'], **{sp.CHECKING: round(target - wiz['spend'], 2)})
    await update.message.reply_text(f"✅ הוצאה צפויה: ₪{wiz['spend']:,.2f} בחודש — נשארת בעו\"ש לפני כל חלוקה")
    return await _ask_emergency_goal(update, wiz)


async def _ask_emergency_goal(update, wiz):
    balances = wiz['balances']
    previous = wiz['goals'].get('ILS_EMERGENCY') or 0
    await _planner_reply(update,
        "🛟 *יעד לקרן חירום*\n\n"
        "כמה אתה רוצה שיהיה בקרן החירום בסוף?\n"
        f"יתרה נוכחית: *{sp.money(balances.get('ILS_EMERGENCY', 0), 'ILS')}*\n"
        + (f"יעד קודם: {sp.money(previous, 'ILS')}\n" if previous else "")
        + "\nשלח סכום, או *-* אם אין יעד")
    return PLAN_GOAL_ILS


async def plan_goal_ils_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    try:
        wiz['goals']['ILS_EMERGENCY'] = _parse_goal(update.message.text)
    except ValueError:
        await update.message.reply_text("❌ שלח מספר, למשל 60000 (או - ללא יעד)")
        return PLAN_GOAL_ILS

    previous = wiz['goals'].get('EUR') or 0
    fund = float(wiz['balances'].get(sp.EUR_FUND, 0) or 0)
    await _planner_reply(update,
        "💶 *יעד לחיסכון באירו*\n\n"
        "כמה אירו אתה רוצה שיהיה בסוף?\n"
        f"יתרה נוכחית: *{sp.money(wiz['balances'].get('EUR', 0), 'EUR')}*"
        + (f" _(כולל {sp.money(fund, 'ILS')} ב{ef.LABEL})_" if fund else "") + "\n"
        f"_החלק של 💶 בכל חודש נקנה בשקלים ב{ef.LABEL} ומומר ליורו רק כשצריך._\n"
        + (f"יעד קודם: {sp.money(previous, 'EUR')}\n" if previous else "")
        + "\nשלח סכום, או *-* אם אין יעד")
    return PLAN_GOAL_EUR


async def plan_goal_eur_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    try:
        wiz['goals']['EUR'] = _parse_goal(update.message.text)
    except ValueError:
        await update.message.reply_text("❌ שלח מספר, למשל 12000 (או - ללא יעד)")
        return PLAN_GOAL_EUR

    current = float(_load_plan().get('keren_self_monthly') or 0)
    await _planner_reply(update,
        f"{ks.EMOJI} *{ks.LABEL}*\n"
        "_קרן פרטית שאתה מפקיד אליה בעצמך — נפרדת מקרן ההשתלמות של העבודה_\n\n"
        f"כמה להפקיד בכל חודש? (עד *{ks.money(ks.MAX_MONTHLY)}* — התקרה המוכרת)\n"
        + (f"בתוכנית עכשיו: {ks.money(current)}\n" if current else "")
        + "\nשלח סכום, או *-* אם לא מפקידים\n"
          "_יורד מכל משכורת לפני החלוקה באחוזים_")
    return PLAN_KEREN


async def plan_keren_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    try:
        wiz['keren_self'] = ks.parse_monthly(update.message.text)
    except ValueError:
        await update.message.reply_text(f"❌ שלח סכום בין 0 ל-{ks.MAX_MONTHLY:,.0f} (או - אם לא מפקידים)")
        return PLAN_KEREN
    wiz['cfg'] = dict(wiz['cfg'], keren_self=wiz['keren_self'])
    if wiz['keren_self']:
        await update.message.reply_text(f"✅ {ks.LABEL}: ₪{wiz['keren_self']:,.2f} בחודש — יורד מכל משכורת לפני האחוזים.")
    return await _plan_months_prompt(update, wiz)


def _month_income_question(wiz):
    """(text, keyboard): this month's expected income, before its split."""
    month = wiz['months'][wiz['index']]
    earlier = [wiz['incomes'][m] for m in wiz['months'][:wiz['index']] if m in (wiz.get('incomes') or {})]
    default = earlier[-1] if earlier else wiz.get('salary') or 0
    text = (f"\U0001F4BC *כמה הכנסה צפויה ב-{sp.heb_month(month)}?* ({wiz['index'] + 1}/{len(wiz['months'])})\n"
            "_נטו — מה שייכנס לחשבון. שלח סכום, או לחץ:_")
    rows = []
    if default:
        rows.append([InlineKeyboardButton(f"✅ ₪{default:,.0f} ({'כמו בחודש הקודם' if earlier else 'ההכנסה הרגילה'})",
                                          callback_data="pinc:same")])
    rows.append([InlineKeyboardButton("⏭ לדלג על החודש", callback_data="pinc:skip"),
                 InlineKeyboardButton("❌ ביטול", callback_data="pinc:cancel")])
    wiz['income_default'] = default
    return text, InlineKeyboardMarkup(rows)


def _month_split_prompt(wiz):
    """(text, keyboard): the month's split, with the money of the income just given."""
    month = wiz['months'][wiz['index']]
    text = sp.format_wizard_prompt(month, wiz['index'] + 1, len(wiz['months']), _plan_running(wiz), wiz['fx'],
                                   wiz.get('cfg'), _plan_goal_view(wiz), salary=wiz['incomes'].get(month))
    return text, _plan_keyboard(wiz['index'])


async def _plan_months_prompt(update, wiz):
    """The goals so far, then the first month's income."""
    wiz.setdefault('incomes', {})
    summary = sp.goal_lines(_plan_goal_view(wiz), wiz['balances'])
    if summary:
        await _planner_reply(update, "🎯 *היעדים שלך:*\n" + "\n".join(summary))
    text, keyboard = _month_income_question(wiz)
    await _planner_reply(update, text, reply_markup=keyboard)
    return PLAN_MONTH_INCOME


async def _after_month_income(message, context, amount):
    """Keep this month's income and show its split."""
    wiz = context.user_data['plan_wizard']
    wiz['incomes'][wiz['months'][wiz['index']]] = round(float(amount), 2)
    text, keyboard = _month_split_prompt(wiz)
    try:
        await message.reply_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        await message.reply_text(text, reply_markup=keyboard)
    return PLAN_MONTH


async def plan_month_income_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ התהליך פג. שלח /setplan שוב")
        return ConversationHandler.END
    text = (update.message.text or '').strip().replace(',', '').replace('₪', '')
    if text == '-' and wiz.get('income_default'):
        return await _after_month_income(update.message, context, wiz['income_default'])
    try:
        amount = float(text)
        if amount < 0 or amount > 1_000_000:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ שלח סכום נטו לחודש, למשל 11500 (או לחץ על הכפתור)")
        return PLAN_MONTH_INCOME
    return await _after_month_income(update.message, context, amount)


async def plan_month_income_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """pinc:same | pinc:skip | pinc:cancel"""
    query = update.callback_query
    await query.answer()
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await query.edit_message_text("⌛ That planner session expired. Run /setplan again.")
        return ConversationHandler.END
    choice = query.data.split(':', 1)[1]
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if choice == 'cancel':
        context.user_data.pop('plan_wizard', None)
        await query.message.reply_text("❌ Planning cancelled. Nothing was saved.")
        return ConversationHandler.END
    if choice == 'skip':
        text, keyboard, done = await _plan_advance(wiz, None)
        try:
            await query.message.reply_text(text, parse_mode='Markdown', reply_markup=keyboard)
        except Exception:
            await query.message.reply_text(text, reply_markup=keyboard)
        if done:
            summary = await _plan_finish(wiz)
            context.user_data.pop('plan_wizard', None)
            await _planner_reply(_ReplyTarget(query.message), summary, _plan_edit_button())
            return ConversationHandler.END
        return PLAN_MONTH_INCOME
    return await _after_month_income(query.message, context, wiz.get('income_default') or 0)


async def _plan_advance(wiz, alloc):
    """Record this month's choice and move on. Returns (text, keyboard, done)."""
    key = wiz['months'][wiz['index']]
    wiz['chosen'][key] = alloc
    wiz['index'] += 1

    goal_view = _plan_goal_view(wiz)
    if alloc:
        step = _plan_last_step(wiz)
        done_text = (sp.format_month_done(step, wiz['fx'], goal_view) if step
                     else f"✅ {key} set.")
    else:
        done_text = f"⏭ {sp.month_name(key)} — nothing set aside."

    if wiz['index'] >= len(wiz['months']):
        return done_text, None, True

    question, keyboard = _month_income_question(wiz)
    return done_text + "\n\n" + question, keyboard, False


async def _plan_finish(wiz):
    """Persist the chosen months and build the closing summary."""
    plan = _load_plan()
    # A new plan replaces the old one rather than layering on top of it, so a
    # shorter or shifted plan cannot leave stale months behind.
    plan['months'] = {key: alloc for key, alloc in wiz['chosen'].items() if alloc}
    plan['goals'] = {k: v for k, v in (wiz.get('goals') or {}).items() if v}
    if 'keren_self' in wiz:
        plan['keren_self_monthly'] = wiz['keren_self']
    if wiz.get('salary'):
        plan['salary'] = dict(plan.get('salary') or {}, amount=wiz['salary'], currency='ILS')
    if wiz.get('spend'):
        plan['expected_spend'] = wiz['spend']
    plan['month_income'] = {k: v for k, v in (wiz.get('incomes') or {}).items() if wiz['chosen'].get(k)}
    sp.save_plan(plan)
    return sp.format_summary(plan, wiz['balances'], wiz['fx'], wiz['months'])


async def plan_month_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await query.edit_message_text("⌛ That planner session expired. Run /setplan again.")
        return ConversationHandler.END

    choice = query.data.split(':', 1)[1]

    if choice == 'cancel':
        context.user_data.pop('plan_wizard', None)
        await query.edit_message_text("❌ Planning cancelled. Nothing was saved.")
        return ConversationHandler.END

    if choice == 'custom':
        await query.edit_message_text(_custom_split_prompt(wiz), parse_mode='Markdown')
        return PLAN_CUSTOM

    if choice == 'skip':
        alloc = None
    elif choice == 'same':
        previous = wiz['months'][wiz['index'] - 1] if wiz['index'] else None
        alloc = wiz['chosen'].get(previous)
        if not alloc:
            await query.answer("No previous month to copy.", show_alert=True)
            return PLAN_MONTH
    else:
        try:
            alloc = sp.validate_allocation(
                sp.preset_alloc(tuple(int(x) for x in choice.split('-'))))
        except ValueError as e:
            await query.answer(str(e), show_alert=True)
            return PLAN_MONTH

    text, keyboard, done = await _plan_advance(wiz, alloc)
    try:
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        await query.edit_message_text(text, reply_markup=keyboard)

    if done:
        summary = await _plan_finish(wiz)
        context.user_data.pop('plan_wizard', None)
        await _planner_reply(_ReplyTarget(query.message), summary, _plan_edit_button())
        return ConversationHandler.END
    return PLAN_MONTH_INCOME


async def plan_custom_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    wiz = context.user_data.get('plan_wizard')
    if not wiz:
        await update.message.reply_text("⌛ That planner session expired. Run /setplan again.")
        return ConversationHandler.END

    try:
        alloc = sp.parse_allocation((update.message.text or '').split())
    except ValueError as e:
        await _planner_reply(update, f"❌ {e}\n\nTry again, e.g. `30 20 20 30`\n"
                                     "_(🛟emergency / 🎯future / 💶EUR (קרן כספית) / 📈stocks)_")
        return PLAN_CUSTOM

    # A typed split is easy to get wrong (30 0 0 70 vs 30 0 70 0), so show what
    # it does and let it be confirmed or changed before the month is recorded.
    wiz['pending'] = alloc
    text, keyboard = _custom_confirm_prompt(wiz, alloc)
    try:
        await update.message.reply_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        await update.message.reply_text(text, reply_markup=keyboard)
    return PLAN_CONFIRM


def _custom_split_prompt(wiz):
    return (f"✏️ Type the split for *{sp.month_name(wiz['months'][wiz['index']])}*\n\n"
            "Examples:  `30 20 20 30`   or   `emg=30 fut=20 eur=20 usd=30`\n"
            "_Order is 🛟emergency / 🎯future / 💶EUR (קרן כספית) / 📈stocks._")


def _custom_confirm_prompt(wiz, alloc):
    """(text, keyboard): what the typed split does to the month, nothing saved yet."""
    trial = dict(wiz, chosen=dict(wiz['chosen']), index=wiz['index'] + 1)
    trial['chosen'][wiz['months'][wiz['index']]] = alloc
    step = _plan_last_step(trial)
    body = (sp.format_month_done(step, wiz['fx'], _plan_goal_view(wiz)).replace('✅', '📝', 1) if step
            else f"{sp.month_name(wiz['months'][wiz['index']])}: {alloc}")
    text = ("👀 *לפני שמירה — לאשר את החלוקה?*\n\n" + body
            + "\n\n_עוד לא נשמר. ✅ לאשר, או ✏️ לשנות._")
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ לאשר", callback_data="pcf:ok")],
        [InlineKeyboardButton("✏️ להקליד חלוקה אחרת", callback_data="pcf:retype"),
         InlineKeyboardButton("🔘 לבחור מהכפתורים", callback_data="pcf:presets")],
        [InlineKeyboardButton("❌ ביטול", callback_data="pcf:cancel")]])
    return text, keyboard


async def plan_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """pcf:ok | pcf:retype | pcf:presets | pcf:cancel — after a typed split."""
    query = update.callback_query
    await query.answer()
    wiz = context.user_data.get('plan_wizard')
    if not wiz or not wiz.get('pending'):
        await query.edit_message_text("⌛ That planner session expired. Run /setplan again.")
        return ConversationHandler.END
    choice = query.data.split(':', 1)[1]

    if choice == 'cancel':
        context.user_data.pop('plan_wizard', None)
        await query.edit_message_text("❌ Planning cancelled. Nothing was saved.")
        return ConversationHandler.END
    if choice == 'retype':
        wiz.pop('pending', None)
        await query.edit_message_text(_custom_split_prompt(wiz), parse_mode='Markdown')
        return PLAN_CUSTOM
    if choice == 'presets':
        wiz.pop('pending', None)
        text, keyboard = _month_split_prompt(wiz)
        try:
            await query.edit_message_text(text, parse_mode='Markdown', reply_markup=keyboard)
        except Exception:
            await query.edit_message_text(text, reply_markup=keyboard)
        return PLAN_MONTH

    text, keyboard, done = await _plan_advance(wiz, wiz.pop('pending'))
    try:
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        await query.edit_message_text(text, reply_markup=keyboard)
    if done:
        summary = await _plan_finish(wiz)
        context.user_data.pop('plan_wizard', None)
        await _planner_reply(_ReplyTarget(query.message), summary, _plan_edit_button())
        return ConversationHandler.END
    return PLAN_MONTH_INCOME


async def plan_target_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Typed reply to a bare /plantarget."""
    raw = (update.message.text or '').strip().split()
    try:
        amount = float(raw[0].replace(',', '').replace('₪', ''))
        if amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Give a positive number, e.g. 150000")
        return PLAN_TARGET

    plan = _load_plan()
    plan['target'] = {'amount': amount, 'currency': 'ILS',
                      'label': ' '.join(raw[1:]).strip() or None}
    sp.save_plan(plan)
    await _planner_reply(update, f"✅ Target set to *{sp.money(amount, 'ILS')}*.\n"
                                 "Now build the months with /setplan")
    return ConversationHandler.END


async def cancel_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data.pop('plan_wizard', None)
    await update.message.reply_text("❌ Cancelled. Nothing was saved.")
    return ConversationHandler.END


# --- changing one month after the plan is built ------------------------------
# The finished plan carries a button; it (or /setplan edit) lists the months, and
# a month's new split is previewed before it replaces the old one.

def _plan_edit_button():
    return InlineKeyboardMarkup([[InlineKeyboardButton("✏️ לשנות חלוקה של חודש מסוים", callback_data="pedit:list")]])


def _alloc_short(alloc):
    return '/'.join(str(int(round(float((alloc or {}).get(b, 0) or 0)))) for b in sp.BUCKETS) if alloc else 'דילוג'


def _plan_edit_months(plan):
    """Every month from the plan's first to its last, skipped ones included."""
    keys = sorted(k for k in (plan.get('months') or {}) if k >= sp.month_key())
    if not keys:
        return []
    months, key = [], keys[0]
    while key <= keys[-1]:
        months.append(key)
        key = sp.shift_month(key, 1)
    return months


def _plan_edit_list_markup(plan):
    rows, row = [], []
    for key in _plan_edit_months(plan):
        alloc = (plan.get('months') or {}).get(key)
        row.append(InlineKeyboardButton(f"{sp.heb_month(key)} · {_alloc_short(alloc)}", callback_data=f"pedit:m:{key}"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("✖️ סגור", callback_data="pedit:close")])
    return InlineKeyboardMarkup(rows)


def _plan_edit_month_markup(key):
    rows, row = [], []
    for triple in sp.PRESETS:
        row.append(InlineKeyboardButton(sp.preset_label(triple),
                                        callback_data=f"pedit:p:{key}:" + '-'.join(str(int(x)) for x in triple)))
        if len(row) == 3:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("✏️ להקליד חלוקה", callback_data=f"pedit:t:{key}"),
                 InlineKeyboardButton("⏭ בלי חלוקה", callback_data=f"pedit:skip:{key}")])
    rows.append([InlineKeyboardButton("↩️ לרשימת החודשים", callback_data="pedit:list")])
    return InlineKeyboardMarkup(rows)


async def _plan_edit_preview(message, context, key, alloc):
    """What the month does with the new split, before it is saved."""
    plan = _load_plan()
    old = (plan.get('months') or {}).get(key)
    context.user_data['plan_edit'] = {'month': key, 'alloc': alloc}
    text = f"👀 *{sp.heb_month(key)}: {_alloc_short(old)} → {_alloc_short(alloc)}*\n_עוד לא נשמר._"
    if alloc:
        try:
            fx = await asyncio.to_thread(_planner_fx_sync)
            balances = await _planner_balances()
            trial = dict(plan, months=dict(plan.get('months') or {}, **{key: alloc}))
            done = [m for m in _plan_edit_months(trial) if m <= key]
            steps = sp.project_timeline(trial, balances, fx, done)
            if steps and steps[-1]['month'] == key:
                goals = {'goals': sp.goals_of(plan), 'future_need': _future_need()}
                text += "\n\n" + sp.format_month_done(steps[-1], fx, goals).replace('✅', '📝', 1)
        except Exception as e:
            _planner_log(f"plan edit preview failed: {e}")
    else:
        text += "\n\n⏭ בחודש הזה לא ייחסך כלום לפי התוכנית."
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton("✅ לשמור", callback_data=f"pedit:ok:{key}"),
                                      InlineKeyboardButton("↩️ לבחור אחרת", callback_data=f"pedit:m:{key}")]])
    await _planner_reply(_ReplyTarget(message), text, keyboard)


async def plan_edit_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """pedit:list | pedit:m:<month> | pedit:p:<month>:<a-b-c-d> | pedit:t:<month> | pedit:skip:<month>
    | pedit:ok:<month> | pedit:close"""
    query = update.callback_query
    await query.answer()
    if not is_authorized(query.from_user.id):
        return
    parts = query.data.split(':')
    action = parts[1]
    key = parts[2] if len(parts) > 2 else None
    plan = _load_plan()

    if action == 'close':
        context.user_data.pop('plan_edit', None)
        await query.edit_message_reply_markup(reply_markup=None)
        return
    if action == 'list':
        if not _plan_edit_months(plan):
            await query.message.reply_text("אין חודשים בתוכנית — /setplan")
            return
        await query.message.reply_text("✏️ *איזה חודש לשנות?*\n_החלוקה הנוכחית ליד כל חודש: 🛟/🎯/💶/📈_",
                                       parse_mode='Markdown', reply_markup=_plan_edit_list_markup(plan))
        return
    if action == 'm':
        context.user_data.pop('plan_edit', None)
        context.user_data['state'] = None
        income = (plan.get('month_income') or {}).get(key) or (plan.get('salary') or {}).get('amount') or 0
        await query.message.reply_text(
            f"✏️ *{sp.heb_month(key)}*\nעכשיו: *{_alloc_short((plan.get('months') or {}).get(key))}*"
            f"  _(הכנסה צפויה ₪{float(income):,.0f})_\n\n"
            "בחר חלוקה חדשה (🛟חירום/🎯עתידיות/💶יורו-קרן כספית/📈מניות), או הקלד:",
            parse_mode='Markdown', reply_markup=_plan_edit_month_markup(key))
        return
    if action == 'p':
        try:
            alloc = sp.validate_allocation(sp.preset_alloc(tuple(int(x) for x in parts[3].split('-'))))
        except (ValueError, IndexError):
            await query.message.reply_text("❌ חלוקה לא תקינה")
            return
        await _plan_edit_preview(query.message, context, key, alloc)
        return
    if action == 'skip':
        await _plan_edit_preview(query.message, context, key, None)
        return
    if action == 't':
        context.user_data['plan_edit'] = {'month': key}
        context.user_data['state'] = 'plan_edit_text'
        await query.message.reply_text(
            f"✏️ הקלד את החלוקה ל*{sp.heb_month(key)}*\nלמשל `30 20 20 30` או `emg=30 usd=70`\n"
            "_(🛟חירום / 🎯עתידיות / 💶יורו-קרן כספית / 📈מניות) · cancel לביטול_", parse_mode='Markdown')
        return
    if action == 'ok':
        pending = context.user_data.get('plan_edit') or {}
        if pending.get('month') != key or 'alloc' not in pending:
            await query.message.reply_text("⌛ השינוי הזה כבר לא פעיל — בחר שוב את החודש")
            return
        context.user_data.pop('plan_edit', None)
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        if pending['alloc']:
            plan['months'][key] = pending['alloc']
        else:
            plan['months'].pop(key, None)
        sp.save_plan(plan)
        await query.message.reply_text(f"✅ {sp.heb_month(key)} נשמר: {_alloc_short(pending['alloc'])}")
        try:
            fx = await asyncio.to_thread(_planner_fx_sync)
            balances = await _planner_balances()
            months = sorted(k for k in plan['months'] if k >= sp.month_key())
            await _planner_reply(_ReplyTarget(query.message), sp.format_summary(plan, balances, fx, months),
                                 _plan_edit_button())
        except Exception as e:
            _planner_log(f"plan edit summary failed: {e}")
        return


async def _handle_plan_edit_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A typed split for the month being changed."""
    text = (update.message.text or '').strip()
    key = (context.user_data.get('plan_edit') or {}).get('month')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not key:
        context.user_data['state'] = None
        context.user_data.pop('plan_edit', None)
        await update.message.reply_text("❌ בוטל — התוכנית לא השתנתה.")
        return
    try:
        alloc = sp.parse_allocation(text.split())
    except ValueError as e:
        await _planner_reply(update, f"❌ {e}\n\nלמשל `30 20 20 30` _(🛟/🎯/💶/📈)_ · cancel לביטול")
        return
    context.user_data['state'] = None
    await _plan_edit_preview(update.message, context, key, alloc)


async def _plan_stale_button(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A preset button tapped after the session already ended."""
    query = update.callback_query
    await query.answer("That planner session has ended.", show_alert=True)
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass


async def set_salary(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/salary <amount> - expected monthly pay, used for projections."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = context.args or []
    if not args:
        plan = _load_plan()
        current = (plan.get('salary') or {}).get('amount')
        msg = (f"💼 Expected pay: *{sp.money(current, 'ILS')}* / month"
               if current else "💼 No expected pay set.")
        await _planner_reply(update, msg + "\n\nSet it with `/salary 12000`")
        return
    try:
        amount = float(str(args[0]).replace(',', '').replace('₪', ''))
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Give a positive number, e.g. /salary 12000")
        return

    plan = _load_plan()
    plan['salary'] = {'amount': amount, 'currency': 'ILS'}
    sp.save_plan(plan)
    await _planner_reply(update,
                         f"✅ Expected pay set to *{sp.money(amount, 'ILS')}* / month.\n"
                         "See the effect with /plan")


async def set_il_float(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ilfloat <target> [monthly_spend] - the /ilcash living-expenses float."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    plan = _load_plan()
    cfg = sp.float_config(plan)
    args = context.args or []

    if not args:
        balances = await _planner_balances()
        now = balances.get(sp.CHECKING, 0)
        short = sp.topup_needed(now, cfg['target'])
        mode = ("🔄 *Automatic:* last month's spending + buffer" if cfg.get('mode') == sp.FLOAT_AUTO
                else "📌 *Fixed*")
        await _planner_reply(update,
            f"💳 *Checking float (/ilcash)*\n\n"
            f"{mode}\n"
            f"Target: *{sp.money(cfg['target'], 'ILS')}*  _({sp.float_basis_text(cfg)})_\n\n"
            f"Right now: *{ex.money(now)}*"
            + (f" — *{sp.money(short, 'ILS')}* short\n" if short else " — at target\n")
            + "\n`/ilfloat auto` — last month's spending + ₪1,000 (or `/ilfloat auto 1500` for another buffer)"
            + "\n`/ilfloat 3000 2000` — a fixed target")
        return

    if str(args[0]).lower() in ('auto', 'אוטומטי'):
        try:
            buffer = float(str(args[1]).replace(',', '').replace('₪', '')) if len(args) > 1 else sp.DEFAULT_FLOAT_BUFFER
            if buffer < 0:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ The buffer must be a positive number, e.g. /ilfloat auto 1000")
            return
        plan['float'] = {'mode': sp.FLOAT_AUTO, 'buffer': buffer}
        sp.save_plan(plan)
        cfg = sp.float_config(_load_plan())
        await _planner_reply(update,
            f"✅ The /ilcash target now follows your spending: *{sp.money(cfg['target'], 'ILS')}*\n"
            f"_({sp.float_basis_text(cfg)})_\n\n"
            "It updates by itself every month. See /plan")
        return

    try:
        target = float(str(args[0]).replace(',', '').replace('₪', ''))
        spend = (float(str(args[1]).replace(',', '').replace('₪', ''))
                 if len(args) > 1 else cfg['monthly_spend'])
        if target < 0 or spend < 0:
            raise ValueError("Amounts cannot be negative.")
        if spend > target:
            raise ValueError("Monthly spend cannot exceed the float target.")
    except ValueError as e:
        msg = str(e) if 'cannot' in str(e) else "Give numbers, e.g. /ilfloat 3000 2000"
        await update.message.reply_text(f"❌ {msg}")
        return

    plan['float'] = {'target': target, 'monthly_spend': spend}
    sp.save_plan(plan)
    await _planner_reply(update,
        f"✅ Checking float set to *{sp.money(target, 'ILS')}*\n"
        f"({sp.money(spend, 'ILS')} expected spend + "
        f"{sp.money(target - spend, 'ILS')} buffer)\n\n"
        "This is refilled before anything is saved. See /plan")


async def set_plan_target(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/plantarget <amount> [label] - the planner's overall savings target."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = context.args or []
    if not args:
        plan = _load_plan()
        target = plan.get('target') or {}
        msg = (f"🎯 Current target: *{sp.money(target['amount'], target.get('currency', 'ILS'))}*"
               if target.get('amount') else "🎯 No target set yet.")
        await _planner_reply(update, msg + "\n\nHow much do you want to reach overall?\n"
                                           "Type a number, e.g. `150000 Brasil fund`\n"
                                           "_or /cancel to leave it._")
        return PLAN_TARGET
    try:
        amount = float(str(args[0]).replace(',', '').replace('₪', ''))
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Give a positive number, e.g. /plantarget 150000")
        return

    plan = _load_plan()
    plan['target'] = {'amount': amount, 'currency': 'ILS',
                      'label': ' '.join(args[1:]).strip() or None}
    sp.save_plan(plan)
    await _planner_reply(update,
                         f"✅ Target set to *{sp.money(amount, 'ILS')}*.\n"
                         "See how close you land with /plan")


SALARY_USAGE = ("*Salary to goal*\n\n"
                "`/salarytogoal` — what you need to earn to reach your goals\n"
                "`/salarytogoal log` — every payment vs its goal\n"
                "`/salarytogoal whatif` — where you'd end up at ±5/10/15/20% pay (preview)\n"
                "`/salarytogoal goal` — the pay your goal needs, and ±5–30% around it (preview)\n"
                "`/salarytogoal earn 7000` — if you earn ₪7,000 net: what goes into each pot every month, "
                "where it ends, and % of each goal\n\n"
                "*Settings*\n"
                "`/salarytogoal gross 8200` — your real current gross, to calibrate\n"
                "`/salarytogoal basis all` — demand every bucket goal too\n"
                "`/salarytogoal basis target` — the total target only (default)\n"
                "`/salarytogoal points 2.75` · `pension 6` · `keren 2.5`")


def _setting_number(raw):
    return float(str(raw).replace(',', '').replace('₪', '').replace('%', '').strip())


def _apply_salary_setting(state, plan, args):
    """Change one salary-goal setting. Returns what was done, or raises
    ValueError with a reason the user can act on."""
    name, raw = args[0], args[1]
    cfg = state['config']

    if name == 'basis':
        if raw in ('all', 'everything'):
            cfg['basis'] = 'all'
            return "Now demanding every goal, bucket goals included."
        if raw in ('target', 'auto'):
            cfg['basis'] = 'auto'
            return "Now calculating against the total target."
        raise ValueError("basis takes `target` or `all`")

    if name == 'gross':
        if raw in ('0', 'clear', 'reset', 'off'):
            cfg['gross_now'] = cfg['net_now'] = None
            return "Calibration cleared, back to the tax-model estimate."
        gross = _setting_number(raw)
        net = float((plan.get('salary') or {}).get('amount') or 0)
        if not net:
            raise ValueError("set your net pay first with /salary")
        if gross <= net:
            raise ValueError(f"gross must be higher than your net pay "
                             f"({sp.money(net, 'ILS')})")
        cfg['gross_now'], cfg['net_now'] = gross, net
        return (f"Calibrated: gross {sp.money(gross, 'ILS')} ↔ net "
                f"{sp.money(net, 'ILS')}. Estimates now follow your real pay slip.")

    value = _setting_number(raw)
    if name == 'points':
        if not 0 <= value <= 10:
            raise ValueError("credit points are between 0 and 10")
        cfg['points'] = value
        return f"Credit points set to {value:g}."
    if name in ('pension', 'keren'):
        share = value / 100 if value > 1 else value
        if not 0 <= share <= 0.25:
            raise ValueError(f"{name} is a percentage between 0 and 25")
        cfg[name] = share
        return f"{name} deposit set to {share * 100:g}% of gross."
    raise ValueError("unknown setting")


async def salary_to_goal(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/salarytogoal - the monthly pay the plan's goals require, gross and net."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = [str(a).strip().lower() for a in (context.args or [])]
    try:
        state = sgl.load_state()
        if args and args[0] in ('log', 'history', 'יומן'):
            await _planner_reply(update, sgl.format_log(state))
            return
        if args and args[0] in SALARY_WHATIF_WORDS:
            await _send_salary_what_if(update.message, state)
            return
        if args and args[0] in SALARY_GOALPAY_WORDS:
            await _send_salary_around_goal(update.message, state)
            return
        if args and args[0] in SALARY_EARN_WORDS:
            if len(args) > 1:
                try:
                    net = _parse_net_pay(args[1])
                except ValueError as e:
                    await update.message.reply_text(f"❌ {e}")
                    return
                await _send_salary_earn(update.message, net, state)
            else:
                await _ask_salary_earn(update.message, context)
            return

        plan = _load_plan()
        note = ''
        if args:
            if len(args) < 2 or args[0] not in ('gross', 'basis', 'points', 'pension', 'keren'):
                await _planner_reply(update, SALARY_USAGE)
                return
            note = _apply_salary_setting(state, plan, args)
            sgl.save_state(state)

        await update.message.reply_text("💼 Calculating...")
        fx = await asyncio.to_thread(_planner_fx_sync)
        balances = await _planner_balances()
        result = sgl.compute(plan, balances, fx, state['config'])
        text = sgl.format_report(result)
        await _planner_reply(update, (f"✅ {note}\n\n" if note else '') + text,
                             reply_markup=_salary_what_if_button() if result else None)
    except ValueError as e:
        await _planner_reply(update, f"❌ {e}\n\n{SALARY_USAGE}")
    except Exception as e:
        _planner_log(f"/salarytogoal failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


SALARY_WHATIF_WORDS = ('whatif', 'what-if', 'what_if', 'preview', 'scenarios', 'מהאם')
SALARY_GOALPAY_WORDS = ('goal', 'goalpay', 'needed', 'price', 'יעד')
SALARY_EARN_WORDS = ('earn', 'if', 'אם', 'ארוויח')


def _parse_net_pay(text):
    raw = str(text or '').replace(',', '').replace('₪', '').strip()
    try:
        net = float(raw.split()[0])
    except (ValueError, IndexError):
        raise ValueError("שלח סכום נטו לחודש, למשל 7000")
    if not 500 <= net <= 200000:
        raise ValueError("סכום נטו לא סביר — שלח למשל 7000")
    return net


async def _ask_salary_earn(message, context):
    context.user_data['state'] = 'salary_earn'
    await message.reply_text("💭 *כמה תרוויח נטו בחודש?*\nשלח סכום, למשל `7000`\n_cancel לביטול_",
                             parse_mode='Markdown')


async def _send_salary_earn(message, net, state=None):
    """What earning `net` a month does, from the next month still to allocate to
    the plan's end. Reads the plan and balances, writes nothing."""
    state = state or sgl.load_state()
    plan = _load_plan()
    start = _next_plan_month(plan)
    months = [m for m in sorted(plan.get('months') or {}) if start and m >= start]
    await message.reply_text("💭 מחשב...")
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    result = sgl.earn(plan, balances, fx, net, months, state['config'])
    await _planner_reply(_ReplyTarget(message), sgl.format_earn(result),
                         reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
                             "💭 סכום אחר", callback_data="sgoal:earn")]]))


async def _handle_salary_earn_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל.")
        return
    try:
        net = _parse_net_pay(text)
    except ValueError as e:
        await update.message.reply_text(f"❌ {e}")
        return
    context.user_data['state'] = None
    await _send_salary_earn(update.message, net)


def _salary_what_if_button():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🎯 The pay my goal needs, ±5–30%", callback_data="sgoal:goal")],
        [InlineKeyboardButton("📊 My current pay, ±5–20%", callback_data="sgoal:whatif")],
        [InlineKeyboardButton("💭 What if I earn… (net)", callback_data="sgoal:earn")]])


async def _send_salary_around_goal(message, state=None):
    """The pay the goal needs and ±5..30% around it. Reads the plan, writes nothing."""
    state = state or sgl.load_state()
    plan = _load_plan()
    await message.reply_text("🎯 Working out the pay your goal needs...")
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    bundle = sgl.around_goal(plan, balances, fx, state['config'])
    await _planner_reply(_ReplyTarget(message), sgl.format_around_goal(bundle))


async def _send_salary_what_if(message, state=None):
    """The ±5/10/15/20% preview. Reads the plan and balances, writes nothing."""
    state = state or sgl.load_state()
    plan = _load_plan()
    await message.reply_text("📊 Running the scenarios...")
    fx = await asyncio.to_thread(_planner_fx_sync)
    balances = await _planner_balances()
    preview = sgl.what_if(plan, balances, fx, state['config'])
    await _planner_reply(_ReplyTarget(message), sgl.format_what_if(preview))


async def salary_goal_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The button under /salarytogoal."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    if query.data == "sgoal:earn":
        await _ask_salary_earn(query.message, context)
        return
    action = {"sgoal:whatif": _send_salary_what_if, "sgoal:goal": _send_salary_around_goal}.get(query.data)
    if action is None:
        return
    try:
        await action(query.message)
    except Exception as e:
        _planner_log(f"/salarytogoal preview failed: {e}")
        await query.message.reply_text(f"❌ Error: {e}")


async def _send_salary_goal_reminder(app, key):
    """1st of the month: what this month's pay has to be to stay on track.

    Recalculated from where the balances stand today for the months still ahead,
    so a month that fell short makes the next requirement honest instead of
    repeating a figure that is no longer enough. The figure is pinned for the
    month, and /payment later judges the pay against exactly what was sent here.
    """
    try:
        plan = _load_plan()
        if not (plan.get('months') or {}).get(key):
            return
        fx = await asyncio.to_thread(_planner_fx_sync)
        balances = await _planner_balances()
        state = sgl.load_state()
        result = sgl.compute(plan, balances, fx, state['config'], from_month=key)
        text = sgl.format_reminder(key, result,
                                   (plan.get('salary') or {}).get('amount'))
        if not text:
            return
        sgl.remember_month_goal(state, key, result)
        sgl.save_state(state)
        await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, text=text,
                                   parse_mode='Markdown')
    except Exception as e:
        _planner_log(f"salary goal reminder failed: {e}")


PAYMENT_SOURCES_PROMPT = (
    "🧾 *ממה מורכב התשלום?*\n\n"
    "כתוב סכום ותיאור לכל חלק, מופרד בפסיקים, למשל:\n"
    "`7000 משכורת, 2000 החזר, 1500 מכירה`\n\n"
    "_שלח - לדלג, או cancel לביטול._")


async def payment(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/payment [amount] [YYYY-MM] - asks what the payment is made of, then splits
    it by the plan. Without an amount the parts' total is the payment."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    args = context.args or []
    amount = None
    key = sp.month_key()
    for arg in args:
        text = str(arg).replace(',', '').replace('₪', '')
        if re.fullmatch(r'\d{4}-\d{2}', text):
            key = text
            continue
        try:
            amount = float(text)
        except ValueError:
            await update.message.reply_text("❌ Give a positive number, e.g. /payment 12000")
            return
        if amount <= 0:
            await update.message.reply_text("❌ Give a positive number, e.g. /payment 12000")
            return

    plan = _load_plan()
    if not plan.get('months', {}).get(key):
        await _planner_reply(update,
                             f"❌ No allocation set for `{key}`.\n\n"
                             f"Set one with /setplan, or `/setplan {key} emg=30 fut=20 eur=20 usd=30`")
        return

    context.user_data['payment'] = {'key': key, 'amount': amount}
    earlier = [p for p in plan.get('payments') or [] if p.get('month') == key]
    if earlier:
        # Sending /payment again usually means a correction, not a second salary.
        # Counting it twice would inflate the month's total against the salary goal.
        context.user_data['state'] = None
        last = earlier[-1]
        lines = [f"⚠️ *כבר נרשם תשלום ל-{sp.month_name(key)}*", ""]
        lines += [f"• {sp.money(p['amount'], 'ILS')} — {p['date']}"
                  + (" (נרשמה הקצאה)" if p.get('actual') else "") for p in earlier]
        lines += ["", "זה *תיקון* של התשלום האחרון, או *תשלום נוסף* באותו חודש (למשל בונוס)?"]
        if last.get('actual'):
            lines.append("_החלפה תמחק גם את ההקצאה שנרשמה לו ב-/allocated._")
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton(f"🔁 מחליף את {sp.money(last['amount'], 'ILS')}", callback_data="paydup:replace")],
            [InlineKeyboardButton("➕ תשלום נוסף", callback_data="paydup:add")],
            [InlineKeyboardButton("❌ ביטול", callback_data="paydup:cancel")]])
        context.user_data['payment']['replace_offer'] = last['date']
        await _planner_reply(update, "\n".join(lines), reply_markup=keyboard)
        return
    await _ask_payment_sources(update, context)


async def _ask_payment_sources(update, context):
    pending = context.user_data['payment']
    amount, key = pending.get('amount'), pending['key']
    context.user_data['state'] = 'payment_sources'
    head = (f"💰 תשלום של *{sp.money(amount, 'ILS')}* ל-{sp.month_name(key)}\n\n"
            if amount else f"💰 תשלום ל-{sp.month_name(key)} — הסכום יהיה סך החלקים\n\n")
    if pending.get('replace'):
        head += f"_🔁 יחליף את התשלום מ-{pending['replace']}._\n\n"
    await _planner_reply(update, head + PAYMENT_SOURCES_PROMPT)


async def payment_duplicate_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The buttons shown when a month already has a payment: paydup:replace | add | cancel"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    choice = (query.data or '').split(':')[-1]
    pending = context.user_data.get('payment')
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if choice == 'cancel' or not pending or not pending.get('replace_offer'):
        context.user_data.pop('payment', None)
        await query.message.reply_text("❌ בוטל — שום דבר לא נרשם." if choice == 'cancel'
                                       else "ℹ️ הבקשה הזו כבר לא פעילה — שלח /payment מחדש.")
        return
    stamp = pending.pop('replace_offer')
    if choice == 'replace':
        pending['replace'] = stamp
    await _ask_payment_sources(_ReplyTarget(query.message), context)


async def _handle_payment_sources(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The answer to 'what is the payment made of?'."""
    text = (update.message.text or '').strip()
    pending = context.user_data.get('payment') or {}
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('payment', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — שום דבר לא נרשם.")
        return

    amount = pending.get('amount')
    if text.lower() in ('ok', 'אישור', 'כן') and pending.get('proposed'):
        # Confirmed: the parts' total becomes the payment.
        sources = pending['proposed']
        amount = round(sum(s['amount'] for s in sources), 2)
    elif text in ('-', 'דלג', 'skip'):
        if not amount:
            await update.message.reply_text("❌ בלי סכום ב-/payment צריך לכתוב את החלקים, למשל: 7000 משכורת, 2000 החזר")
            return
        sources = []
    else:
        try:
            sources = sp.parse_sources(text)
        except ValueError as e:
            await _planner_reply(update, f"❌ לא הבנתי: {e}\n\n" + PAYMENT_SOURCES_PROMPT)
            return
        total = round(sum(s['amount'] for s in sources), 2)
        if amount is None:
            amount = total
        elif abs(total - amount) > 0.5:
            pending['proposed'] = sources
            diff = total - amount
            await _planner_reply(update,
                f"⚠️ *החלקים לא מסתכמים לתשלום*\n\n"
                f"החלקים: *{sp.money(total, 'ILS')}*\n"
                f"התשלום: *{sp.money(amount, 'ILS')}*\n"
                f"הפרש: *{('+' if diff > 0 else '-')}{sp.money(abs(diff), 'ILS')}*\n\n"
                f"שלח את הפירוט שוב, או *ok* כדי שהתשלום יהיה {sp.money(total, 'ILS')}.")
            return

    context.user_data['state'] = None
    pending.pop('proposed', None)
    pending.update(amount=amount, sources=sources)
    await _ask_payment_in_checking(update, context)


async def _ask_payment_in_checking(update, context):
    """A salary usually lands in the עו"ש before it is split. If it already has, the
    /ilcash balance includes the payment, and the top-up must be worked out from the
    balance without it -- otherwise the payment looks like money already there."""
    pending = context.user_data['payment']
    balances = await _planner_balances()
    checking = float(balances.get(sp.CHECKING, 0) or 0)
    without = round(checking - pending['amount'], 2)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"✅ כן, כבר בעו\"ש (בלעדיו: {sp.money(without, 'ILS')})", callback_data="payin:yes")],
        [InlineKeyboardButton("⏳ עוד לא נכנס", callback_data="payin:no")],
        [InlineKeyboardButton("❌ ביטול", callback_data="payin:cancel")]])
    await _planner_reply(update,
        f"💳 *התשלום כבר נכנס לעו\"ש?*\n\n"
        f"/ilcash מראה עכשיו *{sp.money(checking, 'ILS')}*.\n"
        f"אם התשלום של {sp.money(pending['amount'], 'ILS')} כבר בפנים, היתרה בלעדיו היא "
        f"*{sp.money(without, 'ILS')}*, וההשלמה לעו\"ש תחושב ממנה.",
        reply_markup=keyboard)


async def payment_in_checking_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """payin:yes | payin:no | payin:cancel -- the last question of /payment."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    choice = (query.data or '').split(':')[-1]
    pending = context.user_data.get('payment')
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if choice == 'cancel' or not pending or 'sources' not in pending:
        context.user_data.pop('payment', None)
        await query.message.reply_text("❌ בוטל — שום דבר לא נרשם." if choice == 'cancel'
                                       else "ℹ️ הבקשה הזו כבר לא פעילה — שלח /payment מחדש.")
        return
    context.user_data.pop('payment', None)
    await _finish_payment(_ReplyTarget(query.message), pending['key'], pending['amount'], pending['sources'],
                          replace=pending.get('replace'), in_checking=(choice == 'yes'))


async def _finish_payment(update, key, amount, sources, replace=None, in_checking=False):
    """Split the payment by the plan, record it, and judge it against the salary goal.

    `replace` is the stamp of an earlier payment this one corrects: it is taken
    out of the plan and the salary log first, so the month counts it once.
    `in_checking` means the payment is already part of the /ilcash balance."""
    plan = _load_plan()
    alloc = plan.get('months', {}).get(key)
    if not alloc:
        await update.message.reply_text(f"❌ No allocation set for {key}.")
        return
    replaced = None
    if replace:
        # Stamps are to the minute, so search from the end: the offer was the newest.
        payments = plan.get('payments') or []
        index = next((i for i in range(len(payments) - 1, -1, -1)
                      if payments[i].get('date') == replace and payments[i].get('month') == key), None)
        if index is not None:
            replaced = payments[index]
            plan['payments'].pop(index)
            try:
                salary_state = sgl.load_state()
                if sgl.drop_payment(salary_state, replaced['month'], replaced['amount'], replaced['date']):
                    sgl.save_state(salary_state)
            except Exception as e:
                _planner_log(f"salary goal: could not drop replaced payment: {e}")
    try:
        fx = await asyncio.to_thread(_planner_fx_sync)
        balances = await _planner_balances()
        cfg = sp.float_config(plan)

        # Refill /ilcash from its real balance, send any unused expense budget
        # straight to the ILS bank, then split whatever is genuinely left.
        checking_now = float(balances.get(sp.CHECKING, 0) or 0)
        checking_base = round(checking_now - amount, 2) if in_checking else checking_now
        bd = sp.payment_breakdown(amount, alloc, checking_base, cfg)
        if in_checking:
            bd['in_checking'] = True
            bd['checking_shown'] = checking_now

        stamp = datetime.now().strftime('%Y-%m-%d %H:%M')
        plan['payments'].append({
            'month': key, 'date': stamp, 'in_checking': bool(in_checking),
            'alloc': dict(alloc),          # the plan as it was, kept for /showplan's history
            'amount': amount, 'sources': sources, 'checking_before': checking_base,
            'float_target': cfg['target'],
            'refill': bd['refill'], 'excess': bd['excess'], 'base': bd['base'],
            'keren_self': bd.get('keren_self', 0.0),
            'split': bd['split'], 'unallocated': bd['unallocated'],
        })
        sp.save_plan(plan)
        text = sp.format_payment(key, bd, alloc, fx)
        if sources:
            text = sp.format_sources(sources, amount) + "\n\n" + text
        text += "\n\n_💳 /ilcash target %s: %s_" % (sp.money(cfg['target'], 'ILS'), sp.float_basis_text(cfg))
        text += "\n_📝 After you move the money: /allocated records what really went where._"
        if replaced is not None:
            text = (f"🔁 _Replaced the payment of {sp.money(replaced['amount'], 'ILS')} "
                    f"from {replaced['date']}._\n\n") + text
        await _planner_reply(update, text)

        # Did this payment meet the month's salary goal? Logged either way. The
        # split above has already been recorded, so nothing here may fail it.
        try:
            salary_state = sgl.load_state()
            fallback = None
            if key not in salary_state['months']:
                # No figure was announced on the 1st (bot off, month added late),
                # so work one out now from the balances as they stood.
                fallback = sgl.compute(plan, balances, fx, salary_state['config'],
                                       from_month=key)
            entry = sgl.record_payment(salary_state, key, amount, fallback)
            if entry:
                entry['payment'] = stamp          # lets a later correction find it
                if sources:
                    entry['sources'] = sources
                sgl.save_state(salary_state)
                verdict = sgl.format_verdict(entry)
                if len(sources) > 1:
                    verdict += ("\n_The goal is judged on the whole payment (%s), since the plan "
                                "splits all of it._" % " + ".join(
                                    "%s %s" % (sp.money(s['amount'], 'ILS'), s['label'].replace('_', ' ').replace('*', ''))
                                    for s in sources))
                await _planner_reply(update, verdict)
        except Exception as e:
            _planner_log(f"salary goal check failed: {e}")
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {e}")


async def banklog(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/banklog [N|all] - the ILS bank savings, transaction by transaction."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    arg = str(context.args[0]).strip().lower() if context.args else ''
    limit = 15
    if arg in ('all', 'הכל', 'הכול'):
        limit = None
    elif arg:
        try:
            limit = max(1, int(arg))
        except ValueError:
            await update.message.reply_text("❌ /banklog · /banklog 30 · /banklog all")
            return
    reserves = _load_portfolio().get('reserves') or {}
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton("📈 עדכון רווח/הפסד בקרן", callback_data="bankpl:start")]])
    await _planner_reply(update, bl.format_log(reserves, limit), reply_markup=keyboard)


async def bankpl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/bankpl [value | +change | -change] [note] - book the fund's P/L into the ILS bank savings."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    text = ' '.join(str(a) for a in (context.args or [])).strip()
    if text:
        await _bankpl_take(update.message, context, text)
        return
    await _bankpl_ask(update.message, context)


async def _bankpl_ask(message, context):
    context.user_data['state'] = 'bankpl_amount'
    context.user_data.pop('bankpl', None)
    await _planner_reply(_ReplyTarget(message), bl.format_pl_prompt(_load_portfolio().get('reserves') or {}))


async def _bankpl_take(message, context, text):
    """Read the answer and show what will change; nothing is saved before ✅."""
    reserves = _load_portfolio().get('reserves') or {}
    try:
        mode, number, note = bl.parse_pl(text)
    except ValueError as e:
        context.user_data['state'] = 'bankpl_amount'
        await message.reply_text(f"❌ {e}")
        return
    change = bl.pl_change(mode, number, reserves.get('ILS', 0))
    context.user_data['state'] = None
    if abs(change) < 0.01:
        await message.reply_text("✅ אין שינוי — השווי באפליקציה כבר זהה לבוט.")
        return
    context.user_data['bankpl'] = {'mode': mode, 'number': number, 'note': note}
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton("✅ עדכן", callback_data="bankpl:ok"),
                                      InlineKeyboardButton("❌ ביטול", callback_data="bankpl:cancel")]])
    await _planner_reply(_ReplyTarget(message),
                         bl.format_pl_preview(reserves, change, bl.pl_split(reserves, change), note),
                         reply_markup=keyboard)


async def _handle_bankpl_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data['state'] = None
        context.user_data.pop('bankpl', None)
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    await _bankpl_take(update.message, context, text)


async def bankpl_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """bankpl:start | bankpl:ok | bankpl:cancel"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    action = (query.data or '').split(':')[-1]
    await query.answer()
    if action == 'start':
        await _bankpl_ask(query.message, context)
        return
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    pending = context.user_data.pop('bankpl', None)
    if action != 'ok' or not pending:
        await query.message.reply_text("❌ בוטל — לא נרשם כלום." if action == 'cancel'
                                       else "ℹ️ העדכון הזה כבר לא פעיל — שלח /bankpl מחדש.")
        return

    # Worked out again from the balance as it is now: a value from the app is
    # matched against the current balance, even if something moved meanwhile.
    portfolio_data = _load_portfolio()
    reserves = portfolio_data.setdefault('reserves', {})
    change = bl.pl_change(pending['mode'], pending['number'], reserves.get('ILS', 0))
    if abs(change) < 0.01:
        await query.message.reply_text("✅ אין שינוי — השווי כבר זהה לבוט.")
        return
    split = bl.pl_split(reserves, change)
    before = float(reserves.get('ILS', 0) or 0)
    ilf.apply_change(reserves, to_emergency=split[ilf.EMERGENCY], to_future=split[ilf.FUTURE])
    after = float(reserves['ILS'])
    reserves.setdefault('log', []).append(
        bl.pl_entry(change, split, after, pending['note'], datetime.now().strftime('%Y-%m-%d %H:%M')))
    _save_portfolio(portfolio_data)
    _planner_log(f"bankpl: {change:+.2f} split={split} ILS {before} -> {after}")
    word = 'רווח' if change >= 0 else 'הפסד'
    await query.message.reply_text(
        f"✅ *נרשם {word} בקרן: {'+' if change >= 0 else '-'}₪{abs(change):,.2f}*\n\n"
        f"🏦 חיסכון בנקאי: ₪{before:,.2f} → *₪{after:,.2f}*\n"
        f"_נשמר ביומן — /banklog_", parse_mode='Markdown')


async def ibkr(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ibkr [all|deposit|withdraw] - shekels moved to / from Interactive Brokers (log only)."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    arg = str(context.args[0]).strip().lower() if context.args else ''
    if arg in ('deposit', 'הפקדה', 'in'):
        await _ibkr_start(update.message, context, ibl.DEPOSIT)
        return
    if arg in ('withdraw', 'משיכה', 'out'):
        await _ibkr_start(update.message, context, ibl.WITHDRAW)
        return
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("➕ הפקדה", callback_data="ibkr:dep"),
        InlineKeyboardButton("➖ משיכה", callback_data="ibkr:wd")]])
    await _planner_reply(update, ibl.format_log(ibl.load(), None if arg in ('all', 'הכל', 'הכול') else 20),
                         reply_markup=keyboard)


async def _ibkr_start(message, context, kind):
    context.user_data['ibkr'] = {'kind': kind}
    context.user_data['state'] = 'ibkr_amount'
    emoji, name = ibl.KIND[kind]
    await message.reply_text(
        f"{emoji} *{name}*\n\nכמה ₪? (אפשר להוסיף הערה אחרי הסכום, למשל `5000 הפקדה ראשונה`)\n"
        f"_cancel לביטול · העו\"ש לא משתנה_", parse_mode='Markdown')


async def _ibkr_ask_date(message, context):
    today = _israel_today()
    yesterday = today - timedelta(days=1)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"היום ({today:%d/%m})", callback_data=f"ibkr:day:{today.isoformat()}"),
         InlineKeyboardButton(f"אתמול ({yesterday:%d/%m})", callback_data=f"ibkr:day:{yesterday.isoformat()}")],
        [InlineKeyboardButton("❌ ביטול", callback_data="ibkr:cancel")]])
    pending = context.user_data['ibkr']
    await message.reply_text(
        f"📅 *באיזה תאריך?*\n\n{ibl.KIND[pending['kind']][1]}: ₪{pending['amount']:,.2f}\n"
        f"_לחץ, או שלח תאריך — למשל 1/10 או 01/10/2026_",
        parse_mode='Markdown', reply_markup=keyboard)


async def _ibkr_save(message, context, day):
    pending = context.user_data.pop('ibkr')
    context.user_data['state'] = None
    entry = ibl.add(pending['kind'], pending['amount'], day, pending.get('note', ''))
    t = ibl.totals(ibl.load())
    emoji, name = ibl.KIND[entry['kind']]
    await message.reply_text(
        f"✅ *נרשם*\n\n{emoji} {name}: *₪{entry['amount_ils']:,.2f}* · {day:%d/%m/%Y}"
        + (f"\n📝 {entry['note']}" if entry['note'] else "")
        + f"\n\n🌐 נטו ב-Interactive: *₪{t['net']:,.2f}* (הופקד ₪{t['deposited']:,.2f} · נמשך ₪{t['withdrawn']:,.2f})"
        + "\n_רישום בלבד — העו\"ש לא השתנה. יומן: /ibkr_", parse_mode='Markdown')


async def _handle_ibkr_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Typed answers to /ibkr: the amount, then the date."""
    text = (update.message.text or '').strip()
    pending = context.user_data.get('ibkr')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not pending:
        context.user_data.pop('ibkr', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    try:
        if context.user_data.get('state') == 'ibkr_amount':
            pending['amount'], pending['note'] = ibl.parse_amount(text)
            context.user_data['state'] = 'ibkr_date'
            await _ibkr_ask_date(update.message, context)
            return
        day = ibl.parse_date(text, _israel_today())
    except ValueError as e:
        await update.message.reply_text(f"❌ {e}")
        return
    await _ibkr_save(update.message, context, day)


async def ibkr_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ibkr:dep | ibkr:wd | ibkr:day:YYYY-MM-DD | ibkr:cancel"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    parts = (query.data or '').split(':')
    await query.answer()
    if parts[1] in ('dep', 'wd'):
        await _ibkr_start(query.message, context, ibl.DEPOSIT if parts[1] == 'dep' else ibl.WITHDRAW)
        return
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    pending = context.user_data.get('ibkr')
    if parts[1] == 'cancel' or not pending or context.user_data.get('state') != 'ibkr_date':
        context.user_data.pop('ibkr', None)
        if context.user_data.get('state') in ('ibkr_amount', 'ibkr_date'):
            context.user_data['state'] = None
        await query.message.reply_text("❌ בוטל — לא נרשם כלום." if parts[1] == 'cancel'
                                       else "ℹ️ הבקשה הזו כבר לא פעילה — שלח /ibkr מחדש.")
        return
    await _ibkr_save(query.message, context, datetime.strptime(parts[2], '%Y-%m-%d').date())


_PAYMENT_FOOTER = '_Nothing was recorded._ Log it with /addreserve, /ilcash or /addcash.'


async def allocate(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/allocate [balance] [YYYY-MM] - what to move where this month, by the plan.

    No number: the split /payment worked out for the month's payment, or, before
    one is recorded, a preview from the plan's salary against today's /ilcash.
    With a number: that is the עו"ש balance now, the month's money already in it;
    the split is worked out from it. Records nothing."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    month, amount = sp.month_key(), None
    for arg in context.args or []:
        text = str(arg).replace(',', '').replace('₪', '')
        if re.fullmatch(r'\d{4}-\d{2}', text):
            month = text
            continue
        try:
            amount = float(text)               # a balance: zero or overdraft is fine
        except ValueError:
            await update.message.reply_text("❌ Give the עו\"ש balance, e.g. /allocate 8287.94 (or /allocate 2026-11)")
            return

    plan = _load_plan()
    alloc = plan.get('months', {}).get(month)
    if not alloc:
        await _planner_reply(update, f"❌ No allocation set for `{month}`. Set one with /setplan.")
        return
    fx = await asyncio.to_thread(_planner_fx_sync)
    payments = [p for p in plan.get('payments') or [] if p.get('month') == month]

    if payments and amount is None:
        parts = []
        for p in payments:
            text = sp.format_payment(month, al.breakdown_from_record(p), alloc, fx)
            status = (f"✅ _ההקצאה בפועל נרשמה ב-{p['actual']['recorded']} — /allocated log_" if p.get('actual')
                      else "📝 _אחרי שהעברת את הכסף: /allocated כדי לרשום מה הלך לאן._")
            parts.append(f"📋 *ההקצאה המומלצת — {sp.month_name(month)}*\n"
                         f"_לפי התשלום של {sp.money(p['amount'], 'ILS')} שנרשם {p['date']}_\n\n"
                         + text.replace(_PAYMENT_FOOTER, status))
        if len(payments) > 1:
            parts.append(f"ℹ️ _נרשמו {len(payments)} תשלומים ל-{sp.month_name(month)}; כל אחד מחולק בנפרד._")
        await _planner_reply(update, "\n\n".join(parts))
        return

    # The month's money: what /payment recorded, else the plan's salary.
    if payments:
        paid, source = round(sum(float(p['amount']) for p in payments), 2), 'התשלום שנרשם'
    else:
        salary = plan.get('salary') or {}
        if not (salary.get('amount') and salary.get('currency', 'ILS') == 'ILS'):
            await update.message.reply_text(
                f"ℹ️ עוד לא נרשם תשלום ל-{sp.month_name(month)} ואין משכורת בתוכנית.\n"
                f"כשהכסף מגיע: /payment")
            return
        paid, source = float(salary['amount']), 'המשכורת בתוכנית'

    balances = await _planner_balances()
    live = float(balances.get(sp.CHECKING, 0) or 0)
    cfg = sp.float_config(plan)
    target_line = "_💳 /ilcash target %s: %s_\n" % (sp.money(cfg['target'], 'ILS'), sp.float_basis_text(cfg))
    if amount is not None:
        # `amount` is the עו"ש balance right now, with the month's money already in it.
        # What was there before the money came in (negative = overdraft) shrinks or
        # grows what can go out; the target stays in the עו"ש.
        before = round(amount - paid, 2)
        bd = sp.payment_breakdown(paid, alloc, before, cfg)
        bd['in_checking'], bd['checking_shown'] = True, amount
        head = (f"🔮 *לפי היתרה בעו\"ש — {sp.month_name(month)}*\n"
                f"_עו\"ש עכשיו: {sp.money(amount, 'ILS')} · {source}: {sp.money(paid, 'ILS')} → "
                f"לפני התשלום: {sp.money(before, 'ILS')}_\n"
                f"_להקצאה: {sp.money(max(amount - cfg['target'], 0), 'ILS')} "
                f"(היתרה פחות {sp.money(cfg['target'], 'ILS')} שנשארים בעו\"ש)_\n\n")
        footer = target_line
        if abs(amount - live) >= 0.01:
            footer += "_ℹ️ בבוט /ilcash מראה %s (הפרש %s%s)._\n" % (
                sp.money(live, 'ILS'), '+' if amount > live else '-', sp.money(abs(amount - live), 'ILS'))
        footer += "_🔮 תצוגה בלבד — כלום לא נרשם._"
    else:
        bd = sp.payment_breakdown(paid, alloc, live, cfg)
        head = (f"🔮 *תצוגה מקדימה — {sp.month_name(month)}*\n"
                f"_עוד לא נרשם תשלום לחודש הזה. לפי {source}: {sp.money(paid, 'ILS')}_\n\n")
        footer = (target_line + "_🔮 תצוגה בלבד — כלום לא נרשם. מניח שהכסף עוד לא בעו\"ש. "
                  "אם כבר נכנס: /allocate <היתרה בעו\"ש>._")
    text = sp.format_payment(month, bd, alloc, fx)
    await _planner_reply(update, head + text.replace(_PAYMENT_FOOTER, footer))


async def allocated(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/allocated [YYYY-MM] | /allocated log - record what was really moved after /payment."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = [str(a).strip().lower() for a in (context.args or [])]
    plan = _load_plan()
    if args and args[0] in ('log', 'history', 'יומן'):
        await _planner_reply(update, al.format_log(plan))
        return

    month = next((a for a in args if re.fullmatch(r'\d{4}-\d{2}', a)), None)
    index, payment_row = al.latest_payment(plan, month or sp.month_key())
    if payment_row is None and month is None:
        index, payment_row = al.latest_payment(plan)        # the newest payment of any month
    if payment_row is None:
        await update.message.reply_text(
            f"ℹ️ אין תשלום רשום{(' ל-' + month) if month else ''}. קודם /payment, אחר כך /allocated.")
        return

    fx = await asyncio.to_thread(_planner_fx_sync)
    steps = al.suggestion_steps(payment_row)
    context.user_data['allocated'] = {'stamp': payment_row['date'], 'month': payment_row['month'],
                                      'steps': steps, 'i': 0, 'phase': 'amount', 'partial': None,
                                      'actual': {}, 'fx': fx, 'payment': payment_row}
    context.user_data['state'] = 'allocated_amount'
    again = ("\n_כבר נרשמה הקצאה לתשלום הזה (%s) — הרישום החדש יחליף אותה._"
             % payment_row['actual']['recorded'] if payment_row.get('actual') else '')
    await _planner_reply(update,
        f"📝 *רישום ההקצאה בפועל*\n"
        f"תשלום של {sp.money(payment_row['amount'], 'ILS')} ל-{sp.month_name(payment_row['month'])} "
        f"(נרשם {payment_row['date']}).\n"
        f"אשאל כמה העברת לקרן חירום, להוצאות עתידיות, ליורו ולדולר (כולל השער), "
        f"ובסוף כמה נשאר בעו\"ש.{again}")
    await _alloc_ask(update.message, context)


def _alloc_rate(state, step):
    return state['fx'].get(al.FX_KEY[step['ccy']]) if step['ccy'] in al.FX_KEY else None


async def _alloc_send(message, text, keyboard):
    try:
        await message.reply_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        await message.reply_text(text, reply_markup=keyboard)


async def _alloc_ask(message, context):
    """Ask whatever the current phase needs: an amount, its rate, or the עו"ש left."""
    state = context.user_data['allocated']
    i, steps, phase = state['i'], state['steps'], state['phase']
    cancel = [InlineKeyboardButton("❌ ביטול", callback_data="alloc:cancel")]
    total = len(steps) + 1                       # the עו"ש question comes last
    if phase == 'left':
        calc = state['calc']
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton(f"✅ כמו שחושב ({sp.money(calc['expected'], 'ILS')})", callback_data=f"alloc:left:{i}")],
            cancel])
        await _alloc_send(message, al.format_checking_step(state['month'], calc, steps, state['actual'], total, total),
                          keyboard)
        return
    step = steps[i]
    market = _alloc_rate(state, step)
    if phase == 'rate':
        rows = [[InlineKeyboardButton(f"📈 שער השוק היום ({market:.4g})", callback_data=f"alloc:mkt:{i}")]] if market else []
        await _alloc_send(message, al.format_rate_step(step, state['partial'], market), InlineKeyboardMarkup(rows + [cancel]))
        return
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"✅ כמו שהומלץ ({sp.money(step['ils'], 'ILS')})", callback_data=f"alloc:ok:{i}"),
         InlineKeyboardButton("0 — לא הועבר", callback_data=f"alloc:zero:{i}")],
        cancel])
    await _alloc_send(message, al.format_step(step, i + 1, total, state['month'], market), keyboard)


async def _alloc_take(message, context, got):
    """Keep one finished answer, then ask the next step -- or, after the last, the עו"ש."""
    state = context.user_data['allocated']
    state['actual'][state['steps'][state['i']]['key']] = got
    state['i'] += 1
    state['phase'], state['partial'] = 'amount', None
    if state['i'] >= len(state['steps']):
        state['phase'] = 'left'
        state['calc'] = al.checking_left(state['payment'], state['steps'], state['actual'])
    await _alloc_ask(message, context)


async def _alloc_partial(message, context, partial):
    """A euro/dollar amount: done if its rate came with it, else ask for the rate."""
    state = context.user_data['allocated']
    if partial['rate'] is not None:
        await _alloc_take(message, context, al.with_rate(partial, partial['rate'], 'yours'))
        return
    state['phase'], state['partial'] = 'rate', partial
    await _alloc_ask(message, context)


async def _alloc_finish(message, context, balance):
    """Record the moves and the עו"ש balance reported for after them."""
    state = context.user_data.pop('allocated')
    context.user_data['state'] = None
    plan = _load_plan()
    index, payment_row = al.find_payment(plan, state['stamp'])
    if payment_row is None:
        await message.reply_text("❌ התשלום הזה כבר לא נמצא בתוכנית (אולי /setplan החליף אותה). לא נרשם כלום.")
        return
    credited_before = float((payment_row.get('actual') or {}).get('keren_self_credited') or 0)
    # Like the keren: only the difference from an earlier record of this payment is credited.
    old_actual = payment_row.get('actual') or {}
    eur_fund_before = float(old_actual.get('eur_fund_credited') or 0)
    summary = al.record(payment_row, state['steps'], state['actual'], state['fx'],
                        checking=dict(state['calc'], actual=balance))
    keren_now = float((state['actual'].get(al.KEREN_SELF) or {}).get('ils') or 0)
    summary['keren_self_credited'] = keren_now
    eur_fund_now = float((state['actual'].get('EUR') or {}).get('ils') or 0)
    summary['eur_fund_credited'] = eur_fund_now
    sp.save_plan(plan)
    if abs(eur_fund_now - eur_fund_before) >= 0.01:
        try:
            data = _load_portfolio()
            st = ef.deposit(data, eur_fund_now - eur_fund_before, _israel_today(), f"/allocated {state['month']}")
            _save_portfolio(data)
            eur_fund_note = f"\n\n{ef.EMOJI} *{ef.LABEL}:* +{ef.money(eur_fund_now - eur_fund_before)} → *{ef.money(st['balance'])}*"
        except Exception as e:
            _planner_log(f"eur_fund deposit failed: {e}")
            eur_fund_note = ''
    else:
        eur_fund_note = ''
    if abs(keren_now - credited_before) >= 0.01:
        try:
            kst = ks.load()
            ks.deposit(kst, keren_now - credited_before, _israel_today(), f"/allocated {state['month']}")
            ks.save(kst)
        except Exception as e:
            _planner_log(f"keren_self deposit failed: {e}")
    text = al.format_summary(state['month'], summary, state['steps']) + eur_fund_note

    # The עו"ש is set to the balance you just reported (it is what the bank shows),
    # minus Visa purchases already set aside: the bank has not collected them yet.
    reported = balance
    set_aside = ex.total_of([e for e in ex.pending_visa(_load_spend_entries()) if ex.is_reserved(e)])
    balance = round(reported - set_aside, 2)
    if set_aside:
        text += (f"\n\n🟦 בבנק {ex.money(reported)}, פחות {ex.money(set_aside)} ויזה שכבר נשמרה בצד "
                 f"(הבנק יחייב אותה ב-{ex.next_charge_date(_israel_today()).strftime('%d/%m')})")
    before = round(float(_checking_balance() or 0), 2)
    diff = round(balance - before, 2)
    if abs(diff) >= 0.01:
        _set_checking_balance(balance)
        _log_ils_checking_transaction(diff, 'adjustment', f'עדכון יתרה לפי /allocated ({sp.month_name(state["month"])})',
                                      balance)
        text += f"\n\n💳 *עו\"ש עודכן:* {ex.money(before)} → *{ex.money(balance)}*"
    else:
        text += f"\n\n💳 עו\"ש כבר על {ex.money(balance)} — לא היה צריך לעדכן."

    # /showplan now shows the plan as it stands after this allocation.
    try:
        _save_last_plan(await _build_plan_text())
        text += "\n📌 _/showplan עודכן לפי המצב החדש._"
    except Exception as e:
        _planner_log(f"/allocated could not refresh /showplan: {e}")
    await _planner_reply(_ReplyTarget(message), text)


async def _handle_allocated_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A typed answer to the current /allocated question."""
    text = (update.message.text or '').strip()
    state = context.user_data.get('allocated')
    if text.lower() in ('cancel', 'ביטול', 'בטל') or not state:
        context.user_data.pop('allocated', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל — לא נרשם כלום.")
        return
    try:
        if state['phase'] == 'left':
            await _alloc_finish(update.message, context, al.parse_balance(text))
            return
        step = state['steps'][state['i']]
        if state['phase'] == 'rate':
            got = al.with_rate(state['partial'], al.parse_rate(text), 'yours')
            await _alloc_take(update.message, context, got)
            return
        got = al.parse_amount(text, step)
    except ValueError as e:
        await update.message.reply_text(f"❌ {e}")
        return
    if step['ccy'] == 'ILS':
        await _alloc_take(update.message, context, got)
    else:
        await _alloc_partial(update.message, context, got)


# Which button belongs to which question; a button of an answered one does nothing.
_ALLOC_PHASE_OF = {'ok': 'amount', 'zero': 'amount', 'mkt': 'rate', 'left': 'left'}


async def allocated_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """The buttons of /allocated: alloc:ok|zero|mkt|left:<step> | alloc:cancel"""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    parts = (query.data or '').split(':')
    state = context.user_data.get('allocated')
    if len(parts) > 1 and parts[1] == 'cancel':
        context.user_data.pop('allocated', None)
        if context.user_data.get('state') == 'allocated_amount':
            context.user_data['state'] = None
        await query.answer()
        try:
            await query.edit_message_text("❌ בוטל — לא נרשם כלום.")
        except Exception:
            pass
        return
    if not state:
        await query.answer("אין רישום פעיל — שלח /allocated", show_alert=True)
        return
    try:
        action, index = parts[1], int(parts[2])
    except (IndexError, ValueError):
        await query.answer()
        return
    if index != state['i'] or _ALLOC_PHASE_OF.get(action) != state['phase']:
        # A button from a question already answered: tapping it again must not record twice.
        await query.answer("השלב הזה כבר נענה", show_alert=True)
        return
    market = None if action == 'left' else _alloc_rate(state, state['steps'][index])
    if action == 'mkt' and not market:
        await query.answer("אין שער שוק כרגע — שלח את השער", show_alert=True)
        return
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if action == 'left':
        await _alloc_finish(query.message, context, state['calc']['expected'])
        return
    step = state['steps'][index]
    if action == 'mkt':
        await _alloc_take(query.message, context, al.with_rate(state['partial'], market, 'market'))
    elif action == 'zero':
        await _alloc_take(query.message, context, al.nothing(step))
    elif step['ccy'] == 'ILS':
        await _alloc_take(query.message, context, al.as_suggested(step))
    else:
        await _alloc_partial(query.message, context, al.suggested_partial(step))


async def _send_allocation_reminder(app, key, index, total):
    """One month-start nudge. Silent when the month has no allocation planned."""
    try:
        plan = _load_plan()
        alloc = plan.get('months', {}).get(key)
        if not alloc:
            return
        fx = await asyncio.to_thread(_planner_fx_sync)
        salary = (plan.get('salary') or {}).get('amount')
        cfg = sp.float_config(plan)
        balances = await _planner_balances()
        topup = sp.topup_needed(balances.get(sp.CHECKING, 0), cfg['target'])
        if salary:
            topup = min(topup, float(salary))
        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=sp.format_reminder(key, alloc, salary, index, total, fx,
                                    topup=topup, target=cfg['target']),
            parse_mode='Markdown')
    except Exception as e:
        print(f"Allocation reminder error: {e}")


async def _monthly_allocation_task(app):
    """Three allocation reminders on the 1st: 09:00, 14:00 and 20:00 Israel time."""
    import pytz

    await asyncio.sleep(60)
    israel_tz = pytz.timezone('Asia/Jerusalem')
    slots = [(9, 1), (14, 2), (20, 3)]
    current_month = None
    sent = set()

    print("📅 Monthly allocation task started - 1st of month at 09:00/14:00/20:00 Israel")

    while True:
        try:
            now = datetime.now(israel_tz)
            key = sp.month_key(now)
            if key != current_month:          # new month, reminders arm again
                current_month = key
                sent = set()

            if now.day == 1:
                for hour, index in slots:
                    if now.hour == hour and now.minute <= 10 and index not in sent:
                        await _send_allocation_reminder(app, key, index, len(slots))
                        if index == 1:
                            await _send_salary_goal_reminder(app, key)
                        sent.add(index)
                        print(f"📅 Allocation reminder {index}/3 sent at {now.strftime('%H:%M')}")

            await asyncio.sleep(120)
        except Exception as e:
            print(f"Monthly allocation task error: {e}")
            await asyncio.sleep(120)


# ===================== EXPENSE TRACKING =====================
# /ilspend records purchases on two cards. Debit leaves /ilcash at once; Visa is
# collected in one lump on the 2nd of the following month, so it is tracked as a
# pending claim and only deducted once the charge is confirmed.

def _il_portfolio_path():
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "israeli_portfolio.json")


def _israel_today():
    return datetime.now(ZoneInfo('Asia/Jerusalem')).date()


def _load_spend_entries():
    """Every /ilspend record, oldest first."""
    try:
        with open(_il_portfolio_path(), 'r', encoding='utf-8') as fh:
            return (json.load(fh) or {}).get('spending_log') or []
    except Exception as e:
        _planner_log(f"could not read spending_log: {e}")
        return []


def _save_spend_entries(entries):
    """Write the spend log back, leaving everything else in the file alone."""
    path = _il_portfolio_path()
    try:
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh)
    except Exception:
        data = {}
    data['spending_log'] = entries
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(data, fh, indent=2, ensure_ascii=False)


def _checking_balance():
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "my_portfolio.json"), 'r', encoding='utf-8') as fh:
            return float((json.load(fh).get('reserves') or {}).get('ILS_checking', 0) or 0)
    except Exception as e:
        _planner_log(f"could not read ILS_checking: {e}")
        return 0.0


def _cash_balance():
    """Physical shekels in hand - a separate pot from the checking account."""
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "my_portfolio.json"), 'r', encoding='utf-8') as fh:
            return float((json.load(fh).get('reserves') or {}).get('ILS_cash', 0) or 0)
    except Exception as e:
        _planner_log(f"could not read ILS_cash: {e}")
        return 0.0


async def ilcashdeposit(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ilcashdeposit <amount> - record cash received into cash on hand."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    args = context.args or []
    current = _cash_balance()
    if not args:
        await _planner_reply(update,
            f"💵 *מזומן ביד*\n\nיתרה נוכחית: *{ex.money(current)}*\n\n"
            "להוספה: `/ilcashdeposit 200`\n"
            "להורדה: `/ilcashdeposit -50`\n"
            "_לא נוגע בעו\"ש._")
        return

    try:
        amount = float(str(args[0]).replace(',', '').replace('₪', ''))
        if amount == 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ שלח מספר, למשל /ilcashdeposit 200")
        return

    new_cash = round(current + amount, 2)
    if new_cash < 0:
        await update.message.reply_text(
            f"❌ אין מספיק מזומן.\nיתרה: {ex.money(current)}")
        return

    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh)
        reserves = data.get('reserves', {})
        reserves['ILS_cash'] = new_cash
        note = ' '.join(args[1:]).strip()
        reserves.setdefault('log', []).append({
            'date': datetime.now().strftime("%Y-%m-%d %H:%M"),
            'currency': 'ILS', 'type': 'CASH', 'amount': round(amount, 2),
            'description': (f"מזומן {'הופקד' if amount > 0 else 'נמשך'} "
                            f"₪{abs(amount):,.2f}" + (f" ({note})" if note else "")),
            'balance_after': new_cash,
        })
        data['reserves'] = reserves
        with open(path, 'w', encoding='utf-8') as fh:
            json.dump(data, fh, indent=2, ensure_ascii=False)

        await _planner_reply(update,
            f"✅ *מזומן עודכן*\n\n"
            f"{'➕' if amount > 0 else '➖'} {ex.money(abs(amount))}\n"
            f"💵 מזומן: {ex.money(current)} → *{ex.money(new_cash)}*\n"
            + (f"📝 {note}\n" if note else "")
            + "\n_העו\"ש לא השתנה._")
    except Exception as e:
        _planner_log(f"/ilcashdeposit failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


async def recurring_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """recur:yes|no:<spend id> after /ilspend · rcchk:yes|no:<item id> on the 15-day check."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    kind, answer_, ref = (query.data or '::').split(':', 2)
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    today = _israel_today()
    data = rc.load()

    if kind == 'rcchk':
        item = rc.find(data, ref)
        if not item or item['status'] != rc.ACTIVE:
            await query.message.reply_text("ℹ️ החיוב הזה כבר לא פעיל — /recurring")
            return
        rc.answer(item, answer_ == 'yes', today)
        rc.save(data)
        if answer_ == 'yes':
            await query.message.reply_text(
                f"✅ נרשם: עדיין משתמש ב-{item['name']}.\nאשאל שוב ב-{rc._d(item['next_check'])}. יומן: /recurring")
        else:
            await query.message.reply_text(
                f"⛔ נרשם: {item['name']} הופסק ({ex.money(item['amount'])} לחודש פחות).\n"
                f"לא אשאל עליו יותר. אל תשכח לבטל את החיוב עצמו מול החברה/הבנק. יומן: /recurring")
        return

    if answer_ != 'yes':
        await query.message.reply_text("👍 נרשם כהוצאה חד-פעמית.")
        return
    entries = _load_spend_entries()
    entry = next((e for e in entries if e.get('id') == ref), None)
    if entry is None:
        await query.message.reply_text("❌ לא מצאתי את ההוצאה (אולי נמחקה).")
        return
    item, created = rc.mark(data, entry, today)
    entry['recurring'], entry['recurring_id'] = True, item['id']
    rc.save(data)
    _save_spend_entries(entries)
    await query.message.reply_text(
        (f"🔁 <b>נרשם כחיוב חוזר:</b> {entry.get('description', '')} — {ex.money(entry.get('amount'))} לחודש\n"
         f"אשאל {rc.RENEW_NOTICE_DAYS} ימים לפני כל חידוש אם אתה עדיין משתמש בו "
         f"(חידוש הבא: {rc._d(rc.next_renewal(item, today).isoformat())}).")
        if created else
        (f"🔁 <b>קושר לחיוב החוזר הקיים:</b> {item['name']}\n"
         f"<i>הסכום עודכן ל-{ex.money(item['amount'])}.</i>")
        + "\n<i>הכול ב-/recurring · מסומן 🔁 ב-/ilspendhistory</i>",
        parse_mode='HTML')


async def recurring_list(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/recurring - recurring payments, what they cost a month, and the check-in log."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await _planner_reply(update, rc.format_list(rc.load(), _israel_today()))


async def _send_recurring_checks(app, today):
    """5 days before each subscription renews: still using it?"""
    data = rc.load()
    for item in rc.due(data, today):
        try:
            await app.bot.send_message(
                chat_id=TELEGRAM_CHAT_ID, text=rc.format_question(item, today), parse_mode='Markdown',
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("✅ עדיין משתמש", callback_data=f"rcchk:yes:{item['id']}"),
                    InlineKeyboardButton("⛔ לא, הפסקתי", callback_data=f"rcchk:no:{item['id']}")]]))
            rc.asked(item, today)
        except Exception as e:
            _planner_log(f"recurring check for {item.get('name')} failed: {e}")
    rc.save(data)


def _set_checking_balance(value):
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
    with open(path, 'r', encoding='utf-8') as fh:
        data = json.load(fh)
    reserves = data.get('reserves', {})
    reserves['ILS_checking'] = round(float(value), 2)
    data['reserves'] = reserves
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(data, fh, indent=2, ensure_ascii=False)


def _expenses_view(entries, key):
    """One month of /expenses (one Visa cycle: the 10th to the 9th) and its ◀ ▶ buttons."""
    today = _israel_today()
    this_month = ex.cycle_month_for(today)
    text = ex.format_month_summary(entries, key, ex.predict(entries, key, cycle=True), cycle=True)
    text += '\n\n' + ecat.format_block(entries, key)
    pending = ex.pending_visa(entries)
    if pending and key == this_month:
        charge_day = ex.next_charge_date(today)
        text += ('\n\n🟦 *Visa pending: %s* (%d purchases)\n   charged %s'
                 % (ex.money(ex.total_of(pending)), len(pending),
                    charge_day.strftime('%d/%m/%Y')))
        set_aside = ex.total_of([e for e in pending if ex.is_reserved(e)])
        if set_aside:
            text += '\n   ✅ %s already off the עו"ש · /visa' % ex.money(set_aside)
    prev_m, next_m = ex.neighbour_months(entries, key, include=[this_month], cycle=True)
    nav = []
    if prev_m:
        nav.append(InlineKeyboardButton(f"◀ {datetime.strptime(prev_m, '%Y-%m').strftime('%b %Y')}",
                                        callback_data=f"expm:{prev_m}"))
    if next_m:
        nav.append(InlineKeyboardButton(f"{datetime.strptime(next_m, '%Y-%m').strftime('%b %Y')} ▶",
                                        callback_data=f"expm:{next_m}"))
    return text, (InlineKeyboardMarkup([nav]) if nav else None)


async def expenses_report(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/expenses - this month's spending (the 10th to the 9th), plus what the Visa still owes."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    try:
        entries = _load_spend_entries()
        text, markup = _expenses_view(entries, ex.cycle_month_for(_israel_today()))
        await _planner_reply(update, text, reply_markup=markup)
    except Exception as e:
        _planner_log(f"/expenses failed: {e}")
        await update.message.reply_text(f"❌ Error: {e}")


async def expenses_month_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """expm:<YYYY-MM> -- the ◀ ▶ buttons of /expenses."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    key = (query.data or '').split(':', 1)[-1]
    if not re.fullmatch(r'\d{4}-\d{2}', key):
        return
    text, markup = _expenses_view(_load_spend_entries(), key)
    try:
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=markup)
    except Exception:
        await query.edit_message_text(text, reply_markup=markup)


def _history_keyboard(entries, month_key, this_month):
    prev_m, next_m = ex.neighbour_months(entries, month_key, include=[this_month], cycle=True)
    nav = []
    if prev_m:
        nav.append(InlineKeyboardButton(
            f"◀ {datetime.strptime(prev_m, '%Y-%m').strftime('%b %Y')}",
            callback_data=f"ilsphist:{prev_m}"))
    if next_m:
        nav.append(InlineKeyboardButton(
            f"{datetime.strptime(next_m, '%Y-%m').strftime('%b %Y')} ▶",
            callback_data=f"ilsphist:{next_m}"))

    rows = [nav] if nav else []
    # One button per scanned purchase, numbered as in the list above.
    for number, (_, entry) in enumerate(ex.indexed_month_entries(entries, month_key, cycle=True), 1):
        if isinstance(entry.get('receipt'), dict) and entry.get('id'):
            label = f"🧾 {number}. {(entry.get('store') or entry['receipt'].get('store_name') or 'חשבונית')[:22]} · {ex.money(entry.get('amount'))}"
            rows.append([InlineKeyboardButton(label, callback_data=f"ilsprcpt:{entry['id']}")])
    # One button per category of the month: open it, pick purchases, move them.
    cats = list(ecat.by_category(entries, month_key).items())[:12]
    buttons = [InlineKeyboardButton(f"🏷 {c[:18]} · {ex.money(v)}", callback_data=f"cg:v:{month_key}:{n}")
               for n, (c, v) in enumerate(cats)]
    rows += [buttons[i:i + 2] for i in range(0, len(buttons), 2)]
    rows.append([InlineKeyboardButton("📊 All months", callback_data="ilsphist:all"),
                 InlineKeyboardButton("🗑 בטל הוצאה", callback_data=f"ilspdel:list:{month_key}")])
    return InlineKeyboardMarkup(rows)


async def history_receipt_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ilsprcpt:<spend id> -- a scanned purchase in /ilspendhistory: its receipt and photo."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    entry_id = (query.data or '').split(':', 1)[-1]
    entry = next((e for e in _load_spend_entries() if e.get('id') == entry_id), None)
    if not entry or not isinstance(entry.get('receipt'), dict):
        await query.message.reply_text("❌ לא מצאתי את החשבונית (אולי ההוצאה נמחקה).")
        return
    receipt = entry['receipt']
    card = ex.CARD_LABEL.get(ex.card_of(entry), '')
    await _planner_reply(_ReplyTarget(query.message),
        rcp.format_receipt(receipt) + f"\n_נרשם {entry.get('date', '')} · {card} · 🏷 {ecat.category_of(entry)}"
        + (f" · שולם {ex.money(entry.get('amount'))}" if abs(float(entry.get('amount') or 0) - float(receipt.get('total') or 0)) >= 0.01 else '')
        + "_")
    names = receipt.get('images') or ([receipt['image']] if receipt.get('image') else [])
    paths = [os.path.join(rcp.DIR, n) for n in names if os.path.exists(os.path.join(rcp.DIR, n))]
    if not paths:
        await query.message.reply_text("📷 _הצילום עצמו לא נשמר עבור החשבונית הזו._", parse_mode='Markdown')
        return
    for path in paths:
        try:
            with open(path, 'rb') as fh:
                if path.lower().endswith('.pdf'):
                    await query.message.reply_document(fh, filename=os.path.basename(path))
                else:
                    await query.message.reply_photo(fh)
        except Exception as e:
            _planner_log(f"receipt image send failed: {e}")
            await query.message.reply_text(f"❌ לא הצלחתי לשלוח את הצילום: {e}")


def _history_text(entries, month_key):
    """A month here is one Visa cycle (the 10th to the 9th; October 2026 ran
    03/10-09/11), and recurring payments are marked 🔁."""
    data = rc.load()
    text = ex.format_history(entries, month_key, ex.predict(entries, month_key, cycle=True),
                             cycle=True, recurring=lambda e: rc.status_of(data, e))
    block = ecat.share_block(entries, month_key)
    if block and len(text) + len(block) < 3900:      # one Telegram message
        text += '\n\n' + block
    return text


def _history_this_month():
    return ex.cycle_month_for(_israel_today())


