def _refund_for(entry):
    """What goes back to /ilcash when a purchase is cancelled.

    A debit already left the account, and so did a Visa charge that has been
    settled, and a Visa purchase set aside when it was bought. An older Visa
    purchase still pending never moved any money, so cancelling it just removes
    the future claim.
    """
    amount = float(entry.get('amount', 0) or 0)
    if ex.card_of(entry) == ex.DEBIT or entry.get('charged') or ex.is_reserved(entry):
        return round(amount, 2)
    return 0.0


async def _cancel_spend_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Pick a purchase, confirm, then reverse it."""
    query = update.callback_query
    await query.answer()

    parts = query.data.split(':')
    action = parts[1]
    entries = _load_spend_entries()
    this_month = _history_this_month()

    if action == 'list':
        month_key = parts[2]
        rows = ex.indexed_month_entries(entries, month_key, cycle=True)[-20:]
        if not rows:
            await query.answer("אין הוצאות לבטל בחודש הזה", show_alert=True)
            return
        # The amount rides along as a fingerprint: deleting a record shifts every
        # later index, so a button from an older message could otherwise point at
        # the wrong purchase.
        buttons = [[InlineKeyboardButton(
            f"{ex.money(e.get('amount'))} — {(e.get('description') or '')[:24]}",
            callback_data=f"ilspdel:pick:{i}:{int(round(float(e.get('amount', 0) or 0) * 100))}")]
            for i, e in rows]
        buttons.append([InlineKeyboardButton(
            "↩ Back", callback_data=f"ilsphist:{month_key}")])
        await query.edit_message_text(
            "🗑 *איזו הוצאה לבטל?*\n\n_בחר הוצאה - תתבקש לאשר._",
            parse_mode='Markdown', reply_markup=InlineKeyboardMarkup(buttons))
        return

    index = int(parts[2])
    stamp = int(parts[3]) if len(parts) > 3 else None
    if index < 0 or index >= len(entries):
        await query.edit_message_text("❌ ההוצאה לא נמצאה.")
        return
    entry = entries[index]

    # Refuse if the row at this index is not the one the button was made for.
    if stamp is not None and int(round(float(entry.get('amount', 0) or 0) * 100)) != stamp:
        await query.edit_message_text(
            "⚠️ הרשימה השתנתה מאז שההודעה נשלחה.\nפתח מחדש עם /ilspendhistory")
        return
    token = f"{index}:{stamp}" if stamp is not None else f"{index}"

    if action == 'pick':
        refund = _refund_for(entry)
        note = (f"💳 יחזור לעו\"ש: *{ex.money(refund)}*" if refund
                else "🟦 ויזה שטרם חויבה — לא יוחזר כסף, רק תוסר החבות")
        await query.edit_message_text(
            f"🗑 *לבטל את ההוצאה?*\n\n"
            f"{ex.money(entry.get('amount'))} — {entry.get('description', '')}\n"
            f"📅 {entry.get('date', '')}  {ex.CARD_EMOJI[ex.card_of(entry)]} "
            f"{ex.CARD_LABEL[ex.card_of(entry)]}\n\n{note}",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ כן, בטל (עם החזר)",
                                      callback_data=f"ilspdel:yes:{token}")],
                [InlineKeyboardButton("📈 זו השקעה - בלי החזר",
                                      callback_data=f"ilspdel:inv:{token}")],
                [InlineKeyboardButton("🗑 מחק לגמרי",
                                      callback_data=f"ilspdel:del:{token}")],
                [InlineKeyboardButton("↩ לא", callback_data=f"ilsphist:{ex.cycle_month_of(entry)}")]]))
        return

    if action == 'del':
        # Hard delete: the record goes, the money comes back, and nothing is
        # written anywhere. Used when the entry should never have existed.
        try:
            refund = _refund_for(entry)
            before = _checking_balance()
            after = before
            if refund:
                after = round(before + refund, 2)
                _set_checking_balance(after)

            month_key = ex.cycle_month_of(entry)
            removed = entries.pop(index)
            _save_spend_entries(entries)

            tail = (f"💳 עו\"ש: {ex.money(before)} → *{ex.money(after)}*" if refund
                    else "🟦 ויזה שטרם חויבה — העו\"ש לא השתנה.")
            await query.edit_message_text(
                f"🗑 *נמחק לגמרי*\n\n"
                f"{ex.money(removed.get('amount'))} — {removed.get('description', '')}\n\n"
                f"{tail}\n\n_לא נרשם בשום יומן._",
                parse_mode='Markdown',
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
                    "↩ להיסטוריה", callback_data=f"ilsphist:{month_key}")]]))
        except Exception as e:
            _planner_log(f"hard delete failed: {e}")
            await query.edit_message_text(f"❌ לא הצלחתי למחוק: {e}")
        return

    if action == 'inv':
        # Buying EUR/USD or funding the bank savings drains /ilcash but is not
        # spending. Reclassifying must NOT refund - the shekels really did leave.
        if ex.is_investment(entry):
            await query.edit_message_text("ℹ️ כבר מסומן כהשקעה.")
            return
        entry['kind'] = ex.INVESTMENT
        _save_spend_entries(entries)
        await query.edit_message_text(
            f"📈 *סומן כהשקעה*\n\n"
            f"{ex.money(entry.get('amount'))} — {entry.get('description', '')}\n\n"
            f"_לא נספר יותר כהוצאה. העו\"ש לא השתנה._",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
                "↩ להיסטוריה", callback_data=f"ilsphist:{ex.cycle_month_of(entry)}")]]))
        return

    if action != 'yes':
        return

    if ex.is_cancelled(entry):
        await query.edit_message_text("ℹ️ ההוצאה כבר בוטלה.")
        return

    try:
        refund = _refund_for(entry)
        before = _checking_balance()
        after = before
        if refund:
            after = round(before + refund, 2)
            _set_checking_balance(after)
            _log_ils_checking_transaction(
                refund, "deposit",
                f"ביטול הוצאה: {entry.get('description', '')}", after)

        entry['cancelled'] = True
        entry['cancelled_on'] = _israel_today().strftime('%Y-%m-%d')
        _save_spend_entries(entries)

        tail = (f"💳 עו\"ש: {ex.money(before)} → *{ex.money(after)}*" if refund
                else "🟦 החבות בויזה הוסרה. העו\"ש לא השתנה.")
        await query.edit_message_text(
            f"✅ *ההוצאה בוטלה*\n\n"
            f"{ex.money(entry.get('amount'))} — {entry.get('description', '')}\n\n{tail}",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
                "↩ להיסטוריה", callback_data=f"ilsphist:{ex.cycle_month_of(entry)}")]]))
    except Exception as e:
        _planner_log(f"cancel spend failed: {e}")
        await query.edit_message_text(f"❌ לא הצלחתי לבטל: {e}")


