async def eurfund_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/eurfund [add|take|set <amount>] - the shekel קרן כספית kept for euros."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    args = context.args or []
    data = _load_portfolio()
    if args:
        action = args[0].lower()
        try:
            if action not in ('add', 'take', 'set') or len(args) < 2:
                raise ValueError
            amount = float(args[1].replace(',', '').replace('₪', ''))
            if amount < 0:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ למשל: /eurfund add 500 · /eurfund take 500 · /eurfund set 5230")
            return
        before = ef.balance(data)
        if action == 'set':
            ef.set_balance(data, amount, _israel_today())
        elif action == 'take':
            if amount > before + 0.005:
                await update.message.reply_text(f"❌ יש בקרן רק {ef.money(before)}")
                return
            ef.deposit(data, -amount, _israel_today(), 'הומר ליורו / נמשך')
        else:
            ef.deposit(data, amount, _israel_today(), 'הפקדה')
        _save_portfolio(data)
        await _planner_reply(update, f"✅ {ef.EMOJI} {ef.LABEL}: {ef.money(before)} → *{ef.money(ef.balance(data))}*"
                             + ("\n_המרת ליורו? רשום את היורו שקיבלת ב-/addreserve._" if action == 'take' else ''))
    reserves = data.get('reserves', {}) or {}
    plan = _load_plan()
    months = plan.get('months') or {}
    pct = float(months[sorted(months)[-1]].get('EUR') or 0) if months else None
    rate = await asyncio.to_thread(_eur_ils_cached)
    await _planner_reply(update, ef.format_status(ef.load(data), float(reserves.get('EUR', 0) or 0),
                                                  float(reserves.get('EUR_cash', 0) or 0), rate, pct))


