async def _send_trip_summary(app, trip):
    try:
        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=tp.format_summary(trip, _eur_bank_balance()),
            parse_mode='Markdown')
        trip['closed'] = True
        data = tp.load_all()
        for stored in data.get('trips', []):
            if stored.get('name') == trip.get('name') and stored.get('start') == trip.get('start'):
                stored['closed'] = True
        tp.save_all(data)
    except Exception as e:
        _planner_log(f"trip summary failed: {e}")


async def convert_value(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/convert - what is an amount worth in shekels. Checks only, moves nothing."""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    args = context.args or []
    if len(args) >= 2:
        currency, raw = args[1].upper(), args[0]
        await _do_convert(update, raw, currency)
        return

    context.user_data['convert'] = {}
    context.user_data['state'] = 'convert_currency'
    await update.message.reply_text(
        "💱 <b>בדיקת שווי</b>\n\n"
        "איזה מטבע?\n"
        "<b>1</b> = 🇷🇴 RON (לאו)\n"
        "<b>2</b> = 💶 EUR (אירו)\n"
        "<b>3</b> = 💵 USD (דולר)\n\n"
        "<i>בדיקה בלבד — לא יירד כלום. שלח cancel לביטול</i>",
        parse_mode='HTML')


async def _handle_convert_currency(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('convert', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל.")
        return

    chosen = {'1': 'RON', '2': 'EUR', '3': 'USD'}.get(text)
    if not chosen:
        upper = text.upper()
        if upper.isalpha() and 2 <= len(upper) <= 4:
            chosen = upper
    if not chosen:
        await update.message.reply_text("❌ שלח 1 (RON), 2 (EUR) או 3 (USD)")
        return

    context.user_data['convert']['currency'] = chosen
    context.user_data['state'] = 'convert_amount'
    await update.message.reply_text(
        f"💱 <b>{chosen}</b>\n\n💰 כמה?",
        parse_mode='HTML')


async def _handle_convert_amount(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל'):
        context.user_data.pop('convert', None)
        context.user_data['state'] = None
        await update.message.reply_text("❌ בוטל.")
        return

    currency = (context.user_data.get('convert') or {}).get('currency', 'EUR')
    context.user_data.pop('convert', None)
    context.user_data['state'] = None
    await _do_convert(update, text, currency)


async def _do_convert(update, raw_amount, currency):
    try:
        amount = float(str(raw_amount).replace(',', '').replace('₪', ''))
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ שלח מספר, למשל 250")
        return

    try:
        boi = await asyncio.to_thread(tp.boi_rates)
        per_usd = None
        if currency not in ('EUR', 'USD'):
            # Reuse the active trip's rate when there is one, so a checked figure
            # matches what a real purchase would be booked at.
            data = tp.load_all()
            trip = tp.active_trip(data, _israel_today()) or tp.latest_trip(data)
            if trip and trip.get('currency') == currency:
                per_usd, _ = await asyncio.to_thread(tp.usd_rate_for, trip)
            else:
                per_usd = await asyncio.to_thread(tp.market_usd_rate, currency)
        row = tp.value_in_ils(amount, currency, boi, per_usd)
    except Exception as e:
        _planner_log(f"/convert failed: {e}")
        await update.message.reply_text(f"❌ לא הצלחתי להמיר: {e}")
        return

    await _planner_reply(update, tp.format_value(row))


async def _check_purchase_goals(app):
    """Announce a purchase goal the moment the future-expenses fund covers it.

    Each goal is announced once; the flag resets if the fund drops back below,
    so a later recovery is reported again rather than staying silent forever.
    """
    try:
        data = _load_goals()
        purchases = [g for g in data.get('goals', []) if g.get('type') == 'purchase']
        if not purchases:
            return

        balances = await _planner_balances()
        fund = float(balances.get('ILS_FUTURE', 0) or 0)
        changed = False

        for goal in purchases:
            cost = float(goal.get('target', 0) or 0)
            affordable = fund >= cost > 0
            if affordable and not goal.get('notified'):
                goal['notified'] = True
                changed = True
                since = goal.get('created', '')
                await app.bot.send_message(
                    chat_id=TELEGRAM_CHAT_ID,
                    text=(f"🟢 *אפשר לקנות!*\n\n"
                          f"🛒 *{goal.get('name')}*\n"
                          f"💰 {sp.money(cost, 'ILS')}\n\n"
                          f"🎯 בקרן הוצאות עתידיות: *{sp.money(fund, 'ILS')}*\n"
                          f"_יישאר {sp.money(fund - cost, 'ILS')} אחרי הקנייה._\n\n"
                          + (f"_נוסף ב-{since}_" if since else "")),
                    parse_mode='Markdown')
            elif not affordable and goal.get('notified'):
                goal['notified'] = False       # dropped back; allow a fresh alert
                changed = True

        if changed:
            _save_goals(data)
    except Exception as e:
        _planner_log(f"purchase goal check failed: {e}")


