def _israel_now():
    return datetime.now(ZoneInfo('Asia/Jerusalem'))


def _settle_due_visa(now=None):
    """Deduct every Visa purchase whose charge day has come from the עו"ש.

    Called by the daily loop (so a charge lands on its day, and is caught up if
    the bot was down), and by /ilspend (so a purchase entered after its charge
    date comes off at once). The bank collects the Visa whether or not the balance
    covers it, so this records what happens and the overdraft rules only warn.
    Returns what was done, or None when nothing was due.
    """
    now = now or _israel_now()
    entries = _load_spend_entries()
    due = []
    for entry in ex.pending_visa(entries, on_or_before=ex.settle_cutoff(now)):
        try:
            float(entry.get('amount'))
        except (TypeError, ValueError):
            # One unreadable record must not block every good charge behind it.
            _planner_log(f"visa charge: skipped a record with an unreadable amount: {entry}")
            continue
        due.append(entry)
    if not due:
        return None
    total = ex.total_of(due)
    # Purchases set aside when bought already left the עו"ש; only the rest comes off now.
    deducted = ex.total_of(ex.unreserved(due))
    before = _checking_balance()
    after = round(before - deducted, 2)
    if deducted:
        _set_checking_balance(after)
    stamp = now.strftime('%Y-%m-%d')
    for entry in due:                       # the same objects as in `entries`
        entry['charged'] = True
        entry['charged_on'] = stamp
    _save_spend_entries(entries)
    if deducted:
        _log_ils_checking_transaction(deducted, "spend", f"Visa charge ({len(due)} purchases)", after)
    _planner_log(f"visa charge applied: {total} over {len(due)} purchases ({deducted} deducted now), {before} -> {after}")
    return {'total': round(total, 2), 'deducted': deducted, 'rows': [dict(e) for e in due],
            'before': before, 'after': after}


async def _send_visa_charge(app, today=None):
    """Deduct what is due and tell the user. Safe to call as often as you like."""
    try:
        result = _settle_due_visa()
        if result:
            await app.bot.send_message(chat_id=TELEGRAM_CHAT_ID, text=ex.format_visa_settled(result),
                                       parse_mode='Markdown')
        return result
    except Exception as e:
        _planner_log(f"visa charge failed: {e}")
        return None


async def _visa_charge_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Apply the Visa charge to /ilcash, but only on an explicit tap."""
    query = update.callback_query
    await query.answer()

    if query.data.endswith(':later'):
        await query.edit_message_text("⏳ Left as pending. It will still be waiting in /expenses.")
        return

    try:
        entries = _load_spend_entries()
        today = _israel_today()
        due = ex.pending_visa(entries, on_or_before=today)
        total = ex.total_of(due)
        if not total:
            upcoming = ex.pending_visa(entries)
            if upcoming:
                nxt = ex.next_charge_date(today)
                await query.edit_message_text(
                    f"🟦 Nothing due yet — {ex.money(ex.total_of(upcoming))} "
                    f"is collected on {nxt.strftime('%d/%m/%Y')}.")
            else:
                await query.edit_message_text("🟦 Nothing pending — already settled.")
            return

        deducted = ex.total_of(ex.unreserved(due))     # set-aside ones already left
        before = _checking_balance()
        after = round(before - deducted, 2)
        if deducted:
            _set_checking_balance(after)

        for entry in due:                      # same objects as in `entries`
            entry['charged'] = True
            entry['charged_on'] = today.strftime('%Y-%m-%d')
        _save_spend_entries(entries)

        if deducted:
            _log_ils_checking_transaction(
                deducted, "spend", f"Visa charge ({len(due)} purchases)", after)

        await query.edit_message_text(
            f"✅ *Visa charge applied*\n\n"
            f"🟦 {ex.money(total)} over {len(due)} purchases\n"
            + (f"✅ {ex.money(total - deducted)} was already taken off when you bought\n" if total - deducted else "")
            + f"💳 /ilcash: {ex.money(before)} → *{ex.money(after)}*"
            + (("\n\n" + ex.overdraft_line(after)
                + ("\n⛔ Past the overdraft limit — move money with /withdrawreserve."
                   if after < -ex.OVERDRAFT_LIMIT else "")) if after < 0 else ""),
            parse_mode='Markdown')
    except Exception as e:
        _planner_log(f"visa charge apply failed: {e}")
        await query.edit_message_text(f"❌ Could not apply the charge: {e}")


