async def _auto_calculate_and_log_total(app):
    """Capture /today plus total assets and save both to total_log.json."""
    try:
        # This is the exact calculation displayed by /today, run silently after
        # the US market close. It is stored directly instead of reconstructed
        # later from total/reserve changes.
        try:
            today_performance = await _capture_today_performance_for_totallog()
        except Exception as e:
            print(f"Could not capture /today performance: {e}")
            today_performance = None

        # Get exchange rates
        try:
            usd_ils = yf.Ticker("USDILS=X").info.get('regularMarketPrice', 3.6)
        except:
            usd_ils = 3.6
        
        try:
            eur_ils = yf.Ticker("EURILS=X").info.get('regularMarketPrice', 3.9)
        except:
            eur_ils = 3.9
        
        # 1. US Portfolio (my_portfolio) - stocks + free_cash
        us_stocks_usd = 0
        us_cash_usd = 0
        try:
            portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
            if os.path.exists(portfolio_file):
                with open(portfolio_file, 'r', encoding='utf-8') as f:
                    us_data = json.load(f)
                
                us_cash_usd = _usd_cash_total(us_data)
                us_holdings = us_data.get('holdings', [])
                
                for h in us_holdings:
                    symbol = h['symbol']
                    shares = h['shares']
                    try:
                        stock = yf.Ticker(symbol)
                        price = stock.info.get('regularMarketPrice', stock.info.get('currentPrice', h['purchase_price']))
                        us_stocks_usd += shares * price
                    except:
                        us_stocks_usd += shares * h['purchase_price']
        except:
            pass
        
        us_total_usd = us_stocks_usd + us_cash_usd
        us_total_nis = us_total_usd * usd_ils
        
        # 2. Israeli Portfolio (from manual_prices in /ilportfolio)
        il_total_nis = 0
        try:
            il_data = _load_israeli_portfolio()
            manual_prices = il_data.get('manual_prices', {})
            
            for name, data in manual_prices.items():
                current_value = data.get('current_value', 0)
                il_total_nis += current_value
        except:
            pass
        
        # 3. Reserves - ILS and EUR only
        reserves_ils = 0
        reserves_eur_in_nis = 0
        eur_amount = 0
        try:
            portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
            if os.path.exists(portfolio_file):
                with open(portfolio_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                reserves_data = data.get('reserves', {})
                
                reserves_ils = reserves_data.get('ILS', 0) + reserves_data.get('ILS_cash', 0)
                eur_amount = reserves_data.get('EUR', 0) + reserves_data.get('EUR_cash', 0)
                reserves_eur_in_nis = eur_amount * eur_ils
        except:
            pass
        
        # Grand total in NIS
        grand_total = us_total_nis + il_total_nis + reserves_ils + reserves_eur_in_nis
        
        stored_stock_performance = None
        if today_performance:
            stored_stock_performance = {
                'source': '/today',
                'market_date': today_performance.get('date'),
                'change_usd': round(float(today_performance.get('change_usd', 0)), 6),
                'change_pct': round(float(today_performance.get('change_pct', 0)), 6),
                'stocks_value_usd': round(float(today_performance.get('stocks_value_usd', 0)), 6),
                'captured_at': datetime.now().strftime('%H:%M'),
            }

        # Log the total value, exact /today result, and component snapshot.
        _log_total_value(
            grand_total,
            breakdown={
                'us_stocks_usd': round(us_stocks_usd, 2),
                'us_cash_usd': round(us_cash_usd, 2),
                'us_total_nis': round(us_total_nis, 2),
                'il_stocks_nis': round(il_total_nis, 2),
                'stocks_total_nis': round((us_stocks_usd * usd_ils) + il_total_nis, 2),
                'reserves_ils': round(reserves_ils, 2),
                'reserves_eur': round(eur_amount, 2),
                'reserves_eur_nis': round(reserves_eur_in_nis, 2),
            },
            rates={'USD_ILS': round(usd_ils, 6), 'EUR_ILS': round(eur_ils, 6)},
            stock_performance=stored_stock_performance,
        )
        
        # Send notification
        import pytz
        israel_tz = pytz.timezone('Asia/Jerusalem')
        now = datetime.now(israel_tz)
        
        msg = f"💰 *סיכום יומי - סה״כ נכסים*\n"
        msg += f"━━━━━━━━━━━━━━━━━━━━\n\n"
        msg += f"📅 {now.strftime('%Y-%m-%d')} | {now.strftime('%H:%M')}\n\n"
        msg += f"💎 *סה״כ: ₪{grand_total:,.0f}*\n\n"
        msg += f"📊 פירוט:\n"
        msg += f"  🇺🇸 פורטפוליו: ₪{us_total_nis:,.0f}\n"
        msg += f"  🇮🇱 ישראלי: ₪{il_total_nis:,.0f}\n"
        msg += f"  🏦 רזרבות: ₪{(reserves_ils + reserves_eur_in_nis):,.0f}\n\n"
        msg += f"✅ נשמר ב `/totallog`"
        
        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=msg,
            parse_mode='Markdown'
        )
        
    except Exception as e:
        print(f"Auto total log error: {e}")


