# ILS BANK RESERVE MONITOR - Alert if below ₪17,000
# ═══════════════════════════════════════════════════════════════

ILS_BANK_MIN_THRESHOLD = 17000
_ILS_BANK_ALERT_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), '.ils_bank_alert_sent')

def _was_ils_bank_alert_sent_today():
    """Check if ILS bank alert was already sent today (persists across restarts)"""
    try:
        if os.path.exists(_ILS_BANK_ALERT_FILE):
            with open(_ILS_BANK_ALERT_FILE, 'r') as f:
                last_date = f.read().strip()
            return last_date == datetime.now().strftime('%Y-%m-%d')
    except:
        pass
    return False

def _mark_ils_bank_alert_sent():
    """Mark that ILS bank alert was sent today"""
    try:
        with open(_ILS_BANK_ALERT_FILE, 'w') as f:
            f.write(datetime.now().strftime('%Y-%m-%d'))
    except:
        pass

def _clear_ils_bank_alert_flag():
    """Clear the alert flag (e.g. when balance goes above threshold)"""
    try:
        if os.path.exists(_ILS_BANK_ALERT_FILE):
            os.remove(_ILS_BANK_ALERT_FILE)
    except:
        pass

async def _check_ils_bank_reserve(app, source: str = "periodic"):
    """Check if ILS bank reserve is below threshold and send alert"""
    
    try:
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        
        reserves = portfolio_data.get('reserves', {})
        ils_bank = reserves.get('ILS', 0)
        
        if ils_bank < ILS_BANK_MIN_THRESHOLD:
            # For periodic checks, only alert once per day (survives restarts)
            if source == "periodic" and _was_ils_bank_alert_sent_today():
                return
            
            deficit = ILS_BANK_MIN_THRESHOLD - ils_bank
            pct = (ils_bank / ILS_BANK_MIN_THRESHOLD) * 100
            
            msg = (
                f"🚨 <b>התראת יתרת בנק!</b>\n"
                f"━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"🏦 יתרת בנק (שקלים): <b>₪{ils_bank:,.2f}</b>\n"
                f"⚠️ מתחת לסף של ₪{ILS_BANK_MIN_THRESHOLD:,}\n"
                f"📉 חסרים: <b>₪{deficit:,.2f}</b>\n"
                f"📊 {pct:.0f}% מהסף\n\n"
            )
            
            if source == "transaction":
                msg += f"💡 <i>נשלח אחרי פעולה שהורידה את היתרה</i>"
            else:
                msg += f"💡 <i>בדיקה תקופתית</i>"
            
            await app.bot.send_message(
                chat_id=TELEGRAM_CHAT_ID,
                text=msg,
                parse_mode='HTML'
            )
            
            _mark_ils_bank_alert_sent()
            print(f"🚨 ILS bank alert sent: ₪{ils_bank:,.2f} < ₪{ILS_BANK_MIN_THRESHOLD:,}")
        else:
            # Reset flag if above threshold
            _clear_ils_bank_alert_flag()
            
    except Exception as e:
        print(f"ILS bank check error: {e}")


async def _ils_bank_monitor_task(app):
    """Background task to check ILS bank reserve every 6 hours"""
    
    # Wait 2 minutes for bot to be ready
    await asyncio.sleep(120)
    
    print("🏦 ILS bank reserve monitor started (threshold: ₪17,000)")
    
    # Initial check
    await _check_ils_bank_reserve(app, "periodic")
    
    while True:
        try:
            # Check every 6 hours
            await asyncio.sleep(21600)
            
            await _check_ils_bank_reserve(app, "periodic")
            
        except Exception as e:
            print(f"ILS bank monitor error: {e}")
            await asyncio.sleep(300)


