# /morning - Daily Morning Briefing
# ═══════════════════════════════════════════════════════════════

async def morning(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Daily morning briefing - portfolio, market, movers, earnings"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("☀️ *Preparing your morning briefing...*", parse_mode='Markdown')

    try:
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])

        # --- 1. Market Indices ---
        indices = {'^GSPC': 'S&P 500', '^IXIC': 'NASDAQ', '^DJI': 'Dow Jones', '^VIX': 'VIX'}
        idx_lines = []
        idx_data = await asyncio.to_thread(
            yf.download, list(indices.keys()), period='2d', group_by='ticker', progress=False, threads=True
        )
        for sym, name in indices.items():
            try:
                if len(indices) == 1:
                    df = idx_data
                else:
                    df = idx_data[sym]
                if df.empty or len(df) < 2:
                    continue
                prev = float(df['Close'].iloc[-2])
                curr = float(df['Close'].iloc[-1])
                chg = ((curr - prev) / prev) * 100 if prev else 0
                arrow = "🟢" if chg >= 0 else "🔴"
                if sym == '^VIX':
                    arrow = "😰" if curr > 25 else "😌"
                idx_lines.append(f"{arrow} *{name}*: {curr:,.2f} ({chg:+.2f}%)")
            except:
                pass

        # --- 2. Portfolio Summary ---
        total_value = 0
        total_cost = 0
        day_pl = 0
        movers = []

        if holdings:
            symbol_data = {}
            for h in holdings:
                s = h['symbol']
                if s not in symbol_data:
                    symbol_data[s] = {'shares': 0, 'cost': 0}
                symbol_data[s]['shares'] += h['shares']
                symbol_data[s]['cost'] += h['total_cost']

            symbols_list = list(symbol_data.keys())
            batch = await asyncio.to_thread(
                yf.download, symbols_list, period='5d', group_by='ticker', progress=False, threads=True
            )

            for sym in symbols_list:
                try:
                    if len(symbols_list) == 1:
                        df = batch
                    else:
                        df = batch[sym]
                    if df.empty:
                        continue
                    price = float(df['Close'].dropna().iloc[-1])
                    prev = float(df['Close'].dropna().iloc[-2]) if len(df['Close'].dropna()) >= 2 else price
                    shares = symbol_data[sym]['shares']
                    cost = symbol_data[sym]['cost']
                    val = price * shares
                    total_value += val
                    total_cost += cost
                    change_pct = ((price - prev) / prev) * 100 if prev else 0
                    day_change = (price - prev) * shares
                    day_pl += day_change
                    movers.append({'symbol': sym, 'pct': change_pct, 'day_pl': day_change, 'price': price})
                except:
                    pass

        # --- 3. Top movers ---
        movers.sort(key=lambda x: x['pct'])
        biggest_loser = movers[0] if movers else None
        biggest_winner = movers[-1] if movers else None

        # --- 4. Upcoming earnings (next 7 days) ---
        earnings_soon = []
        if holdings:
            unique_symbols = list(set(h['symbol'] for h in holdings))
            for sym in unique_symbols:
                try:
                    ticker = yf.Ticker(sym)
                    cal = ticker.calendar
                    if isinstance(cal, dict):
                        edates = cal.get('Earnings Date', [])
                        if edates:
                            from datetime import date
                            edate = edates[0]
                            if hasattr(edate, 'date'):
                                edate = edate.date()
                            elif isinstance(edate, str):
                                edate = datetime.strptime(edate, '%Y-%m-%d').date()
                            diff = (edate - date.today()).days
                            if 0 <= diff <= 7:
                                earnings_soon.append((sym, edate, diff))
                except:
                    pass

        # --- 5. Build message ---
        msg = "☀️ *MORNING BRIEFING*\n"
        msg += f"📅 {datetime.now().strftime('%A, %B %d %Y')}\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        msg += "📈 *Market Overview:*\n"
        for line in idx_lines:
            msg += f"  {line}\n"
        msg += "\n"

        if holdings:
            overall_pl = total_value - total_cost
            overall_pct = (overall_pl / total_cost * 100) if total_cost else 0
            day_emoji = "🟢" if day_pl >= 0 else "🔴"
            msg += "💼 *Portfolio Snapshot:*\n"
            msg += f"  💰 Total Value: *${total_value:,.2f}*\n"
            msg += f"  {day_emoji} Day P/L: *${day_pl:+,.2f}*\n"
            msg += f"  📊 Overall P/L: *${overall_pl:+,.2f}* ({overall_pct:+.1f}%)\n"
            msg += f"  💵 Free Cash: *${_usd_cash_total(portfolio_data):,.2f}*\n\n"

            if biggest_winner and biggest_winner['pct'] != 0:
                msg += "🏆 *Today's Movers:*\n"
                msg += f"  🚀 Best: *{biggest_winner['symbol']}* {biggest_winner['pct']:+.2f}% (${biggest_winner['day_pl']:+,.2f})\n"
                if biggest_loser and biggest_loser['symbol'] != biggest_winner['symbol']:
                    msg += f"  📉 Worst: *{biggest_loser['symbol']}* {biggest_loser['pct']:+.2f}% (${biggest_loser['day_pl']:+,.2f})\n"
                msg += "\n"

        if earnings_soon:
            earnings_soon.sort(key=lambda x: x[2])
            msg += "📅 *Upcoming Earnings:*\n"
            for sym, edate, days in earnings_soon:
                when = "TODAY!" if days == 0 else f"in {days}d"
                msg += f"  ⚠️ *{sym}* - {edate.strftime('%b %d')} ({when})\n"
            msg += "\n"

        # ILS Bank check
        reserves = portfolio_data.get('reserves', {})
        ils_bank = reserves.get('ILS', 0)
        if ils_bank < ILS_BANK_MIN_THRESHOLD:
            msg += f"⚠️ *ILS Bank Alert:* ₪{ils_bank:,.0f} (below ₪{ILS_BANK_MIN_THRESHOLD:,}!)\n\n"

        msg += f"🕐 Generated: {datetime.now().strftime('%H:%M')}\n"
        msg += "_Have a great trading day!_ 🎯"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error generating morning briefing: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /fear - Fear & Greed Index
# ═══════════════════════════════════════════════════════════════

async def fear(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show Fear & Greed Index and market sentiment indicators"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("😱 *Calculating Fear & Greed...*", parse_mode='Markdown')

    try:
        import requests

        # --- Gather sentiment data ---
        # 1. VIX (Fear gauge)
        vix_ticker = yf.Ticker('^VIX')
        vix_hist = vix_ticker.history(period='5d')
        vix = float(vix_hist['Close'].iloc[-1]) if not vix_hist.empty else 20.0
        vix_prev = float(vix_hist['Close'].iloc[-2]) if len(vix_hist) >= 2 else vix

        # 2. S&P 500 vs 125-day MA (Market Momentum)
        sp500 = yf.Ticker('^GSPC')
        sp_hist = sp500.history(period='6mo')
        sp_price = float(sp_hist['Close'].iloc[-1]) if not sp_hist.empty else 0
        sp_ma125 = float(sp_hist['Close'].tail(125).mean()) if len(sp_hist) >= 125 else sp_price
        momentum_pct = ((sp_price - sp_ma125) / sp_ma125 * 100) if sp_ma125 else 0

        # 3. S&P 500 vs 52-week high (Market Strength)
        sp_52w_high = float(sp_hist['Close'].max()) if not sp_hist.empty else sp_price
        from_high_pct = ((sp_price - sp_52w_high) / sp_52w_high * 100) if sp_52w_high else 0

        # 4. Market breadth - compare advancing vs declining (use sector ETFs)
        breadth_etfs = ['XLK', 'XLF', 'XLV', 'XLE', 'XLI', 'XLP', 'XLY', 'XLU', 'XLB', 'XLRE', 'XLC']
        breadth_data = await asyncio.to_thread(
            yf.download, breadth_etfs, period='5d', group_by='ticker', progress=False, threads=True
        )
        advancing = 0
        declining = 0
        for etf in breadth_etfs:
            try:
                df = breadth_data[etf]
                if len(df) >= 2:
                    curr_p = float(df['Close'].iloc[-1])
                    prev_p = float(df['Close'].iloc[-2])
                    if curr_p > prev_p:
                        advancing += 1
                    else:
                        declining += 1
            except:
                pass
        breadth_ratio = advancing / max(advancing + declining, 1) * 100

        # 5. Put/Call ratio proxy - VIX relative to its 50-day average
        vix_50ma = float(vix_hist['Close'].mean()) if len(vix_hist) >= 2 else vix
        # Use a wider window for more accuracy
        vix_long = yf.Ticker('^VIX').history(period='3mo')
        if not vix_long.empty:
            vix_50ma = float(vix_long['Close'].tail(50).mean())

        # 6. Safe haven demand - Gold vs S&P 500 performance
        gold = yf.Ticker('GLD')
        gold_hist = gold.history(period='1mo')
        gold_1m_return = 0
        if len(gold_hist) >= 20:
            gold_1m_return = ((float(gold_hist['Close'].iloc[-1]) / float(gold_hist['Close'].iloc[0])) - 1) * 100
        sp_1m_return = 0
        if len(sp_hist) >= 20:
            sp_1m_return = ((float(sp_hist['Close'].iloc[-1]) / float(sp_hist['Close'].iloc[-20])) - 1) * 100
        safe_haven_diff = gold_1m_return - sp_1m_return  # positive = more fear

        # 7. Junk bond demand - HYG vs TLT
        hyg = yf.Ticker('HYG')
        tlt = yf.Ticker('TLT')
        hyg_hist = hyg.history(period='1mo')
        tlt_hist = tlt.history(period='1mo')
        junk_spread = 0
        if len(hyg_hist) >= 20 and len(tlt_hist) >= 20:
            hyg_ret = ((float(hyg_hist['Close'].iloc[-1]) / float(hyg_hist['Close'].iloc[0])) - 1) * 100
            tlt_ret = ((float(tlt_hist['Close'].iloc[-1]) / float(tlt_hist['Close'].iloc[0])) - 1) * 100
            junk_spread = hyg_ret - tlt_ret  # positive = greed, negative = fear

        # --- Calculate composite score (0-100) ---
        scores = []

        # VIX score (low VIX = greed, high = fear)
        if vix < 12:
            vix_score = 95  # Extreme greed
        elif vix < 17:
            vix_score = 75
        elif vix < 22:
            vix_score = 50
        elif vix < 30:
            vix_score = 25
        else:
            vix_score = 5  # Extreme fear
        scores.append(('VIX Level', vix_score, f"{vix:.1f}"))

        # Momentum score
        if momentum_pct > 8:
            mom_score = 90
        elif momentum_pct > 4:
            mom_score = 75
        elif momentum_pct > 0:
            mom_score = 55
        elif momentum_pct > -4:
            mom_score = 35
        else:
            mom_score = 10
        scores.append(('S&P Momentum', mom_score, f"{momentum_pct:+.1f}% vs 125MA"))

        # Distance from 52W high
        if from_high_pct > -2:
            high_score = 85
        elif from_high_pct > -5:
            high_score = 65
        elif from_high_pct > -10:
            high_score = 40
        else:
            high_score = 15
        scores.append(('52W High Dist', high_score, f"{from_high_pct:+.1f}%"))

        # Breadth score
        breadth_score = breadth_ratio
        scores.append(('Mkt Breadth', breadth_score, f"{advancing}/{advancing+declining} sectors up"))

        # Safe haven (negative diff = greed)
        if safe_haven_diff < -3:
            sh_score = 85
        elif safe_haven_diff < 0:
            sh_score = 60
        elif safe_haven_diff < 3:
            sh_score = 40
        else:
            sh_score = 15
        scores.append(('Safe Haven', sh_score, f"Gold vs S&P: {safe_haven_diff:+.1f}%"))

        # Junk bond demand
        if junk_spread > 2:
            jb_score = 85
        elif junk_spread > 0:
            jb_score = 65
        elif junk_spread > -2:
            jb_score = 40
        else:
            jb_score = 15
        scores.append(('Junk Bonds', jb_score, f"HYG-TLT: {junk_spread:+.1f}%"))

        # VIX trend (falling = greed)
        vix_change = vix - vix_prev
        if vix_change < -2:
            vt_score = 85
        elif vix_change < 0:
            vt_score = 65
        elif vix_change < 2:
            vt_score = 45
        else:
            vt_score = 15
        scores.append(('VIX Trend', vt_score, f"{vix_change:+.1f} pts"))

        # Composite
        composite = sum(s[1] for s in scores) / len(scores)

        # Label
        if composite >= 80:
            label = "🟢 EXTREME GREED"
            advice = "Market may be overheated. Be cautious with new buys."
        elif composite >= 60:
            label = "🟢 GREED"
            advice = "Market is optimistic. Good time but watch for pullbacks."
        elif composite >= 45:
            label = "🟡 NEUTRAL"
            advice = "Market is balanced. Follow your strategy."
        elif composite >= 25:
            label = "🔴 FEAR"
            advice = "Opportunities may arise. Watch for oversold stocks."
        else:
            label = "🔴 EXTREME FEAR"
            advice = "Strong buying opportunity for long-term investors!"

        # Build gauge
        gauge_pos = int(composite / 5)
        gauge = "░" * gauge_pos + "⬤" + "░" * (20 - gauge_pos)

        msg = "😱 *FEAR & GREED INDEX*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
        msg += f"  FEAR `{gauge}` GREED\n"
        msg += f"  Score: *{composite:.0f}/100* — {label}\n\n"

        msg += "📊 *Component Breakdown:*\n"
        for name, score, detail in scores:
            if score >= 60:
                emoji = "🟢"
            elif score >= 40:
                emoji = "🟡"
            else:
                emoji = "🔴"
            bar_len = int(score / 10)
            bar = "█" * bar_len + "░" * (10 - bar_len)
            msg += f"  {emoji} *{name}*\n"
            msg += f"     `{bar}` {score:.0f} — {detail}\n"

        msg += f"\n💡 *Takeaway:* {advice}\n"
        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /diversity - Portfolio Diversification Analysis
# ═══════════════════════════════════════════════════════════════

async def diversity(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Detailed diversification analysis with recommendations"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("🔍 *Analyzing portfolio diversification...*", parse_mode='Markdown')

    try:
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])

        if not holdings:
            await update.message.reply_text("❌ No stocks in portfolio!")
            return

        # Aggregate holdings
        symbol_data = {}
        for h in holdings:
            s = h['symbol']
            if s not in symbol_data:
                symbol_data[s] = {'shares': 0, 'cost': 0}
            symbol_data[s]['shares'] += h['shares']
            symbol_data[s]['cost'] += h['total_cost']

        # Fetch info for all holdings
        stock_info = {}
        total_value = 0
        for sym, data in symbol_data.items():
            try:
                ticker = yf.Ticker(sym)
                info = ticker.info
                price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
                if not price:
                    hist = ticker.history(period='1d')
                    if not hist.empty:
                        price = float(hist['Close'].iloc[-1])
                val = price * data['shares']
                total_value += val
                stock_info[sym] = {
                    'value': val,
                    'sector': info.get('sector', 'Unknown'),
                    'industry': info.get('industry', 'Unknown'),
                    'market_cap': info.get('marketCap', 0),
                    'country': info.get('country', 'Unknown'),
                    'beta': info.get('beta', 1.0),
                }
            except:
                stock_info[sym] = {'value': symbol_data[sym]['cost'], 'sector': 'Unknown', 'industry': 'Unknown', 'market_cap': 0, 'country': 'Unknown', 'beta': 1.0}
                total_value += symbol_data[sym]['cost']

        if total_value == 0:
            await update.message.reply_text("❌ Could not calculate portfolio value!")
            return

        # -- Sector concentration --
        sectors = {}
        for sym, info in stock_info.items():
            sec = info['sector']
            sectors[sec] = sectors.get(sec, 0) + info['value']

        sorted_sectors = sorted(sectors.items(), key=lambda x: x[1], reverse=True)
        top_sector_pct = (sorted_sectors[0][1] / total_value * 100) if sorted_sectors else 0

        # -- Market cap distribution --
        cap_buckets = {'Mega (>200B)': 0, 'Large (10-200B)': 0, 'Mid (2-10B)': 0, 'Small (<2B)': 0}
        for sym, info in stock_info.items():
            cap = info['market_cap']
            if cap > 200e9:
                cap_buckets['Mega (>200B)'] += info['value']
            elif cap > 10e9:
                cap_buckets['Large (10-200B)'] += info['value']
            elif cap > 2e9:
                cap_buckets['Mid (2-10B)'] += info['value']
            else:
                cap_buckets['Small (<2B)'] += info['value']

        # -- Single stock concentration --
        stock_pcts = [(sym, info['value'] / total_value * 100) for sym, info in stock_info.items()]
        stock_pcts.sort(key=lambda x: x[1], reverse=True)

        # -- Beta analysis --
        weighted_beta = sum(info['beta'] * info['value'] for info in stock_info.values() if info['beta']) / total_value if total_value else 1.0

        # -- Geographic distribution --
        countries = {}
        for sym, info in stock_info.items():
            c = info['country']
            countries[c] = countries.get(c, 0) + info['value']

        # -- Diversification Score (0-100) --
        d_score = 100
        # Penalize sector concentration
        if top_sector_pct > 50:
            d_score -= 25
        elif top_sector_pct > 35:
            d_score -= 15
        elif top_sector_pct > 25:
            d_score -= 5

        # Penalize few sectors
        if len(sectors) <= 2:
            d_score -= 20
        elif len(sectors) <= 3:
            d_score -= 10

        # Penalize single stock concentration
        if stock_pcts and stock_pcts[0][1] > 30:
            d_score -= 20
        elif stock_pcts and stock_pcts[0][1] > 20:
            d_score -= 10

        # Penalize few stocks
        num_stocks = len(stock_info)
        if num_stocks < 5:
            d_score -= 15
        elif num_stocks < 8:
            d_score -= 5

        # Bonus for good cap distribution
        cap_categories_used = sum(1 for v in cap_buckets.values() if v > 0)
        if cap_categories_used >= 3:
            d_score += 5

        # Penalize high beta
        if weighted_beta > 1.5:
            d_score -= 10
        elif weighted_beta > 1.2:
            d_score -= 5

        d_score = max(0, min(100, d_score))

        # Grade
        if d_score >= 80:
            grade = "A — Excellent"
            grade_emoji = "🟢"
        elif d_score >= 60:
            grade = "B — Good"
            grade_emoji = "🟢"
        elif d_score >= 40:
            grade = "C — Fair"
            grade_emoji = "🟡"
        elif d_score >= 20:
            grade = "D — Poor"
            grade_emoji = "🔴"
        else:
            grade = "F — Critical"
            grade_emoji = "🔴"

        # Build message
        sector_icons = {
            "Technology": "💻", "Healthcare": "🏥", "Financial Services": "🏦",
            "Consumer Cyclical": "🛍️", "Consumer Defensive": "🛒", "Industrials": "🏭",
            "Energy": "⚡", "Utilities": "💡", "Real Estate": "🏠",
            "Basic Materials": "⛏️", "Communication Services": "📡", "Unknown": "❓"
        }

        msg = "🎯 *DIVERSIFICATION ANALYSIS*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
        msg += f"{grade_emoji} *Score: {d_score}/100* — {grade}\n\n"

        msg += f"📊 *Sector Breakdown* ({len(sectors)} sectors):\n"
        for sec, val in sorted_sectors:
            pct = val / total_value * 100
            icon = sector_icons.get(sec, "❓")
            bar_len = int(pct / 5)
            bar = "█" * bar_len + "░" * (20 - bar_len)
            msg += f"  {icon} {sec}\n"
            msg += f"    `{bar}` {pct:.1f}% (${val:,.0f})\n"
        msg += "\n"

        msg += "🏗️ *Market Cap Mix:*\n"
        for bucket, val in cap_buckets.items():
            if val > 0:
                pct = val / total_value * 100
                msg += f"  {'🐘' if 'Mega' in bucket else '🦁' if 'Large' in bucket else '🐕' if 'Mid' in bucket else '🐁'} {bucket}: {pct:.1f}%\n"
        msg += "\n"

        msg += "📈 *Top Holdings:*\n"
        for sym, pct in stock_pcts[:5]:
            warn = " ⚠️" if pct > 25 else ""
            msg += f"  • *{sym}*: {pct:.1f}%{warn}\n"
        msg += "\n"

        msg += f"📉 *Portfolio Beta:* {weighted_beta:.2f}\n"
        if weighted_beta > 1.3:
            msg += "   ⚠️ High volatility risk\n"
        elif weighted_beta < 0.8:
            msg += "   🛡️ Defensive portfolio\n"
        else:
            msg += "   ✅ Moderate risk\n"
        msg += "\n"

        # Recommendations
        recs = []
        if top_sector_pct > 40:
            recs.append(f"⚠️ {sorted_sectors[0][0]} is {top_sector_pct:.0f}% — reduce sector concentration")
        if len(sectors) < 4:
            recs.append(f"📋 Only {len(sectors)} sectors — add Healthcare, Energy, or Financials")
        if stock_pcts and stock_pcts[0][1] > 25:
            recs.append(f"⚠️ {stock_pcts[0][0]} is {stock_pcts[0][1]:.0f}% — trim position")
        if num_stocks < 8:
            recs.append(f"📋 Only {num_stocks} stocks — aim for 10-15")
        if weighted_beta > 1.3:
            recs.append("🛡️ Add low-beta stocks (utilities, consumer staples)")

        if recs:
            msg += "💡 *Recommendations:*\n"
            for r in recs:
                msg += f"  {r}\n"
        else:
            msg += "✅ Portfolio diversification looks solid!\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /goals - Financial Goals Tracker
# ═══════════════════════════════════════════════════════════════

GOALS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "financial_goals.json")

def _load_goals():
    try:
        with open(GOALS_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {"goals": []}

def _save_goals(data):
    with open(GOALS_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

async def goals(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Financial goals — net worth targets, portfolio milestones"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    data = _load_goals()
    goal_list = data.get('goals', [])

    # Calculate current net worth
    portfolio_data = _load_portfolio()
    holdings = portfolio_data.get('holdings', [])
    free_cash = _usd_cash_total(portfolio_data)
    reserves = portfolio_data.get('reserves', {})
    ils_bank = reserves.get('ILS', 0)
    ils_checking = reserves.get('ILS_checking', 0)
    eur_reserve = reserves.get('EUR', 0)

    # Get USD/ILS rate
    try:
        usdils = yf.Ticker('USDILS=X')
        rate_hist = usdils.history(period='1d')
        usd_ils_rate = float(rate_hist['Close'].iloc[-1]) if not rate_hist.empty else 3.6
    except:
        usd_ils_rate = 3.6

    try:
        eurusd = yf.Ticker('EURUSD=X')
        eur_hist = eurusd.history(period='1d')
        eur_usd_rate = float(eur_hist['Close'].iloc[-1]) if not eur_hist.empty else 1.08
    except:
        eur_usd_rate = 1.08

    # Portfolio value in USD
    portfolio_val_usd = 0
    if holdings:
        symbols = list(set(h['symbol'] for h in holdings))
        batch = await asyncio.to_thread(
            yf.download, symbols, period='1d', group_by='ticker', progress=False, threads=True
        )
        for h in holdings:
            try:
                if len(symbols) == 1:
                    df = batch
                else:
                    df = batch[h['symbol']]
                price = float(df['Close'].dropna().iloc[-1])
                portfolio_val_usd += price * h['shares']
            except:
                portfolio_val_usd += h.get('total_cost', 0)

    total_usd = portfolio_val_usd + free_cash + (eur_reserve * eur_usd_rate)
    total_ils = (total_usd * usd_ils_rate) + ils_bank + ils_checking

    msg = "🎯 *FINANCIAL GOALS*\n"
    msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
    msg += f"💰 *Current Net Worth:*\n"
    msg += f"  🇺🇸 ${total_usd:,.0f} USD\n"
    msg += f"  🇮🇱 ₪{total_ils:,.0f} ILS\n\n"

    # Also calculate reserves-only totals for reserves goals
    reserves = portfolio_data.get('reserves', {})
    reserves_ils = reserves.get('ILS', 0) + reserves.get('ILS_checking', 0)
    reserves_eur = reserves.get('EUR', 0)
    try:
        eur_in_ils = reserves_eur * (eur_usd_rate * usd_ils_rate)
    except:
        eur_in_ils = reserves_eur * 3.89
    reserves_total_ils = reserves_ils + eur_in_ils
    reserves_total_usd = (reserves_ils / usd_ils_rate) + (reserves_eur * eur_usd_rate) if usd_ils_rate else 0

    if not goal_list:
        msg += "📋 No goals set yet.\n\n"
    else:
        for i, g in enumerate(goal_list):
            target = g['target']
            currency = g.get('currency', 'USD')
            goal_type = g.get('type', 'net_worth')
            if goal_type == 'reserves':
                current = reserves_total_usd if currency == 'USD' else reserves_total_ils
            else:
                current = total_usd if currency == 'USD' else total_ils
            sym_char = '$' if currency == 'USD' else '₪'
            progress = min(current / target * 100, 100) if target else 0
            bar_len = int(progress / 5)
            bar = "█" * bar_len + "░" * (20 - bar_len)
            remaining = max(target - current, 0)
            emoji = "✅" if progress >= 100 else "🔄"
            type_icon = "🏦" if goal_type == 'reserves' else "💼"
            msg += f"{emoji} {type_icon} *{g['name']}*\n"
            msg += f"  🎯 Target: {sym_char}{target:,.0f}\n"
            msg += f"  📊 `{bar}` {progress:.1f}%\n"
            msg += f"  💰 Current: {sym_char}{current:,.0f}\n"
            if progress < 100:
                msg += f"  📏 Remaining: {sym_char}{remaining:,.0f}\n"
                # Show monthly investment plan
                months_left, monthly_needed, _ = _calculate_goal_monthly(g, current)
                if months_left is not None and months_left > 0:
                    msg += f"  ⏳ {months_left} months left\n"
                    msg += f"  💵 Need: *{sym_char}{monthly_needed:,.0f}/month*\n"
                elif months_left == 0:
                    msg += f"  ⚠️ Deadline reached!\n"
            else:
                msg += f"  🎉 GOAL REACHED!\n"
            if g.get('deadline'):
                msg += f"  📅 Deadline: {g['deadline']}\n"
            # Show contributions summary
            contribs = g.get('contributions', [])
            if contribs:
                total_contrib = sum(c.get('amount', 0) for c in contribs)
                msg += f"  📥 Total invested: {sym_char}{total_contrib:,.0f} ({len(contribs)} deposits)\n"
            msg += "\n"

    msg += "*Options:*\n"
    msg += "1️⃣ New goal\n"
    msg += "2️⃣ Delete goal\n"
    msg += "❌ Cancel\n"

    await update.message.reply_text(msg, parse_mode='Markdown')
    context.user_data['state'] = 'goals_menu'


