async def _handle_goals_purchase_cost(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Price, then say straight away whether it is affordable and when."""
    text = (update.message.text or '').strip()
    if text.lower() in ('cancel', 'ביטול', 'בטל', '❌'):
        context.user_data.pop('purchase', None)
        context.user_data.pop('state', None)
        await update.message.reply_text("👍 בוטל.")
        return
    try:
        cost = float(text.replace(',', '').replace('₪', ''))
        if cost <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ שלח מספר, למשל 4500")
        return

    item = context.user_data.get('purchase', {}).get('item', 'פריט')
    context.user_data.pop('purchase', None)
    context.user_data.pop('state', None)

    try:
        data = _load_goals()
        data.setdefault('goals', []).append({
            'name': item, 'type': 'purchase', 'target': cost, 'currency': 'ILS',
            'created': datetime.now().strftime('%Y-%m-%d'),
            'notified': False, 'contributions': [],
        })
        _save_goals(data)
    except Exception as e:
        _planner_log(f"saving purchase goal failed: {e}")
        await update.message.reply_text(f"❌ לא הצלחתי לשמור: {e}")
        return

    await _planner_reply(update, await _purchase_status_text(item, cost, created_now=True))


async def _purchase_status_text(item, cost, created_now=False):
    """Can it be bought from the future-expenses fund, and if not, when."""
    try:
        balances = await _planner_balances()
        fx = await asyncio.to_thread(_planner_fx_sync)
        plan = _load_plan()
    except Exception as e:
        _planner_log(f"purchase status failed: {e}")
        return f"🛒 *{item}* — {sp.money(cost, 'ILS')}\n\n❌ לא הצלחתי לחשב: {e}"

    fund = float(balances.get('ILS_FUTURE', 0) or 0)
    lines = [f"🛒 *{item}*", f"💰 מחיר: *{sp.money(cost, 'ILS')}*", '',
             f"🎯 בקרן הוצאות עתידיות: *{sp.money(fund, 'ILS')}*"]

    if fund >= cost:
        lines.append('')
        lines.append(f"🟢 *אפשר לקנות עכשיו!*")
        lines.append(f"_יישאר {sp.money(fund - cost, 'ILS')} בקרן._")
    else:
        short = round(cost - fund, 2)
        lines.append(f"🔴 חסר: *{sp.money(short, 'ILS')}*")
        months = sp.months_until(plan, balances, fx, 'ILS_FUTURE', cost)
        per_month = sp.monthly_contribution(plan, 'ILS_FUTURE', fx)
        lines.append('')
        if months:
            target_month = sp.shift_month(sp.month_key(), months)
            lines.append(f"📅 בקצב הנוכחי (*{sp.money(per_month, 'ILS')}* לחודש):")
            lines.append(f"   עוד *{months} חודשים* — בערך {sp.month_name(target_month)}")
        elif per_month <= 0:
            lines.append("⚠️ התוכנית לא מפנה כסף לקרן הזו, אז לא תגיע לסכום.")
            lines.append("_עדכן הקצאה עם /setplan_")
        else:
            lines.append("⚠️ בקצב הנוכחי זה ייקח יותר מ-10 שנים.")

    if created_now:
        lines.append('')
        lines.append("_אודיע לך כשהקרן תגיע לסכום._")
    return '\n'.join(lines)


