def _calculate_goal_monthly(goal, current_value):
    """Calculate months remaining and monthly investment needed for a goal"""
    target = goal['target']
    remaining = max(target - current_value, 0)
    deadline = goal.get('deadline')
    if not deadline or remaining <= 0:
        return None, None, None
    
    try:
        # Support multiple date formats
        for fmt in ['%Y-%m-%d', '%d-%m-%Y', '%d/%m/%Y', '%m-%d-%Y']:
            try:
                deadline_dt = datetime.strptime(deadline, fmt)
                break
            except:
                continue
        else:
            return None, None, None
        
        now = datetime.now()
        months_left = ((deadline_dt.year - now.year) * 12 + (deadline_dt.month - now.month))
        if months_left <= 0:
            return 0, remaining, deadline_dt
        
        monthly_needed = remaining / months_left
        return months_left, monthly_needed, deadline_dt
    except:
        return None, None, None


async def _handle_goals_new_deadline(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip()
    
    # Validate the date
    deadline = None
    deadline_dt = None
    for fmt in ['%Y-%m-%d', '%d-%m-%Y', '%d/%m/%Y', '%m-%d-%Y']:
        try:
            deadline_dt = datetime.strptime(text, fmt)
            deadline = deadline_dt.strftime('%Y-%m-%d')  # Normalize to YYYY-MM-DD
            break
        except:
            continue
    
    if not deadline:
        await update.message.reply_text(
            "❌ Invalid date format. Please try again:\n"
            "Send like `2026-12-31` or `31-12-2026`",
            parse_mode='Markdown'
        )
        return
    
    # Check date is in the future
    if deadline_dt <= datetime.now():
        await update.message.reply_text("❌ Date must be in the future! Try again:")
        return

    name = context.user_data.get('goal_name', 'Goal')
    target = context.user_data.get('goal_target', 0)
    currency = context.user_data.get('goal_currency', 'USD')

    # Calculate current value based on goal type
    goal_type = context.user_data.get('goal_type', 'net_worth')
    if goal_type == 'reserves':
        current_value = await _get_current_reserves_value(currency)
    else:
        current_value = await _get_current_net_worth_for_currency(currency)
    remaining = max(target - current_value, 0)
    
    # Calculate months and monthly needed
    now = datetime.now()
    months_left = max(((deadline_dt.year - now.year) * 12 + (deadline_dt.month - now.month)), 1)
    monthly_needed = remaining / months_left if remaining > 0 else 0

    goal_type = context.user_data.get('goal_type', 'net_worth')
    data = _load_goals()
    data['goals'].append({
        'name': name,
        'target': target,
        'currency': currency,
        'type': goal_type,
        'deadline': deadline,
        'created': datetime.now().strftime('%Y-%m-%d'),
        'monthly_needed': round(monthly_needed, 2),
        'last_reminder': None,
        'contributions': [],  # Track deposits: [{date, amount, note}]
    })
    _save_goals(data)

    type_label = "🏦 Reserves Only" if goal_type == 'reserves' else "💼 Net Worth"
    symbol = '$' if currency == 'USD' else '₪'
    msg = f"✅ Goal created!\n\n"
    msg += f"🎯 *{name}*\n"
    msg += f"📂 Type: {type_label}\n"
    msg += f"💰 Target: {symbol}{target:,.0f} {currency}\n"
    msg += f"📅 Deadline: {deadline}\n"
    msg += f"⏳ Time left: {months_left} months\n\n"
    msg += f"💰 *Current:* {symbol}{current_value:,.0f}\n"
    msg += f"📏 *Remaining:* {symbol}{remaining:,.0f}\n\n"
    msg += f"📊 *Monthly investment plan:*\n"
    msg += f"  💵 You need to invest *{symbol}{monthly_needed:,.0f}/month* to reach your goal\n\n"
    msg += f"🔔 I'll remind you on the *8th of every month*\n"
    msg += f"📈 I'll also notify you after every buy/sell"
    await update.message.reply_text(msg, parse_mode='Markdown')

    context.user_data.pop('state', None)
    context.user_data.pop('goal_name', None)
    context.user_data.pop('goal_target', None)
    context.user_data.pop('goal_currency', None)
    context.user_data.pop('goal_type', None)


async def _get_current_net_worth_for_currency(currency):
    """Get current net worth in the specified currency"""
    portfolio_data = _load_portfolio()
    holdings = portfolio_data.get('holdings', [])
    free_cash = _usd_cash_total(portfolio_data)
    reserves = portfolio_data.get('reserves', {})
    ils_bank = reserves.get('ILS', 0)
    ils_checking = reserves.get('ILS_checking', 0)
    eur_reserve = reserves.get('EUR', 0)

    try:
        usdils = yf.Ticker('USDILS=X')
        rate_hist = usdils.history(period='1d')
        usd_ils_rate = float(rate_hist['Close'].iloc[-1]) if not rate_hist.empty else 3.6
    except:
        usd_ils_rate = 3.6
    try:
        eurusd = yf.Ticker('EURUSD=X')
        eur_hist = eurusd.history(period='1d')
        eur_usd_rate = float(eur_hist['Close'].iloc[-1]) if not eur_hist.empty else 1.08
    except:
        eur_usd_rate = 1.08

    portfolio_val_usd = 0
    if holdings:
        symbols = list(set(h['symbol'] for h in holdings))
        try:
            batch = await asyncio.to_thread(
                yf.download, symbols, period='1d', group_by='ticker', progress=False, threads=True
            )
            for h in holdings:
                try:
                    if len(symbols) == 1:
                        df = batch
                    else:
                        df = batch[h['symbol']]
                    price = float(df['Close'].dropna().iloc[-1])
                    portfolio_val_usd += price * h['shares']
                except:
                    portfolio_val_usd += h.get('total_cost', 0)
        except:
            for h in holdings:
                portfolio_val_usd += h.get('total_cost', 0)

    total_usd = portfolio_val_usd + free_cash + (eur_reserve * eur_usd_rate)
    total_ils = (total_usd * usd_ils_rate) + ils_bank + ils_checking

    return total_usd if currency == 'USD' else total_ils


async def _get_current_reserves_value(currency):
    """Get current reserves value (bank reserves only) in the specified currency"""
    portfolio_data = _load_portfolio()
    reserves = portfolio_data.get('reserves', {})
    ils_bank = reserves.get('ILS', 0)
    ils_checking = reserves.get('ILS_checking', 0)
    eur_reserve = reserves.get('EUR', 0)

    try:
        usdils = yf.Ticker('USDILS=X')
        rate_hist = usdils.history(period='1d')
        usd_ils_rate = float(rate_hist['Close'].iloc[-1]) if not rate_hist.empty else 3.6
    except:
        usd_ils_rate = 3.6
    try:
        eurusd = yf.Ticker('EURUSD=X')
        eur_hist = eurusd.history(period='1d')
        eur_usd_rate = float(eur_hist['Close'].iloc[-1]) if not eur_hist.empty else 1.08
    except:
        eur_usd_rate = 1.08

    if currency == 'ILS':
        # ILS reserves + EUR converted to ILS
        eur_in_ils = eur_reserve * eur_usd_rate * usd_ils_rate
        return ils_bank + ils_checking + eur_in_ils
    else:
        # USD: convert everything to USD
        ils_total = ils_bank + ils_checking
        return (ils_total / usd_ils_rate) + (eur_reserve * eur_usd_rate)


async def _send_goals_update_notification(app, trigger_action, symbol_name=None, amount_change=None):
    """Send goal progress notification after portfolio changes (buy/sell)"""
    try:
        data = _load_goals()
        goal_list = data.get('goals', [])
        if not goal_list:
            return

        for g in goal_list:
            currency = g.get('currency', 'USD')
            target = g['target']
            goal_type = g.get('type', 'net_worth')
            if goal_type == 'reserves':
                current_value = await _get_current_reserves_value(currency)
            else:
                current_value = await _get_current_net_worth_for_currency(currency)
            remaining = max(target - current_value, 0)
            progress = min(current_value / target * 100, 100) if target else 0
            sym = '$' if currency == 'USD' else '₪'

            # Recalculate monthly needed
            months_left, monthly_needed, _ = _calculate_goal_monthly(g, current_value)

            # Update stored monthly_needed
            if monthly_needed is not None:
                g['monthly_needed'] = round(monthly_needed, 2)

            bar_len = int(progress / 5)
            bar = "█" * bar_len + "░" * (20 - bar_len)

            action_emoji = "🟢" if trigger_action == 'buy' else "🔴"
            action_text = f"{action_emoji} *{trigger_action.upper()}: {symbol_name}*" if symbol_name else f"{action_emoji} Portfolio updated"

            msg = f"🎯 *GOAL UPDATE*\n"
            msg += f"━━━━━━━━━━━━━━━━━━━━\n\n"
            msg += f"{action_text}\n\n"
            msg += f"📌 *{g['name']}*\n"
            msg += f"  🎯 Target: {sym}{target:,.0f}\n"
            msg += f"  📊 `{bar}` {progress:.1f}%\n"
            msg += f"  💰 Current: {sym}{current_value:,.0f}\n"

            if progress >= 100:
                msg += f"  🎉 *GOAL REACHED!*\n"
            else:
                msg += f"  📏 Remaining: {sym}{remaining:,.0f}\n"
                if months_left is not None and months_left > 0:
                    msg += f"  ⏳ {months_left} months left\n"
                    msg += f"  💵 Need: {sym}{monthly_needed:,.0f}/month\n"
                elif months_left == 0:
                    msg += f"  ⚠️ Deadline reached! Still need {sym}{remaining:,.0f}\n"

        _save_goals(data)

        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=msg,
            parse_mode='Markdown'
        )
    except Exception as e:
        print(f"Goals notification error: {e}")


async def _monthly_portfolio_performance_task(app):
    """Background task: send monthly portfolio performance report on the 1st of each month at 10:00 AM Israel time"""
    import pytz
    await asyncio.sleep(180)  # Wait for bot to be ready
    israel_tz = pytz.timezone('Asia/Jerusalem')
    sent_this_month = None
    print("📅 Monthly portfolio performance task started - sends on 1st of each month")

    while True:
        try:
            now = datetime.now(israel_tz)
            current_month = now.strftime('%Y-%m')

            # Send on the 1st of each month at 10:00 AM Israel time
            if now.day == 1 and now.hour == 10 and now.minute < 5 and sent_this_month != current_month:
                try:
                    portfolio_data = _load_portfolio()
                    portfolio_log = portfolio_data.get('portfolio_log', [])
                    sold_history = portfolio_data.get('sold_history', [])
                    holdings = portfolio_data.get('holdings', [])

                    # Determine the previous month
                    if now.month == 1:
                        prev_month_year = now.year - 1
                        prev_month_num = 12
                    else:
                        prev_month_year = now.year
                        prev_month_num = now.month - 1
                    prev_month_str = f"{prev_month_year}-{prev_month_num:02d}"
                    
                    from calendar import monthrange
                    month_name = datetime(prev_month_year, prev_month_num, 1).strftime('%B %Y')

                    # Get logs from the previous month
                    month_logs = [l for l in portfolio_log if l['date'].startswith(prev_month_str)]

                    # Find start value: last log before the month, or first log of month
                    logs_before = [l for l in portfolio_log if l['date'] < f"{prev_month_str}-01"]
                    start_value = logs_before[-1]['value'] if logs_before else (month_logs[0]['value'] if month_logs else 0)

                    # End value: last log entry of the month
                    end_value = month_logs[-1]['value'] if month_logs else start_value

                    # Value change
                    value_change = end_value - start_value

                    # Realized P/L from stocks sold during the month
                    month_realized = 0
                    month_sold_stocks = []
                    for s in sold_history:
                        sell_date = s.get('sell_date', '')
                        if sell_date.startswith(prev_month_str):
                            pl = s.get('profit_loss', 0)
                            month_realized += pl
                            month_sold_stocks.append(s)

                    # Daily P/L sum (from true_daily_pl if available)
                    daily_pl_sum = sum(l.get('true_daily_pl', 0) for l in month_logs if l.get('true_daily_pl') is not None)

                    # Calculate current unrealized P/L
                    unrealized_pl = 0
                    total_cost = 0
                    total_market_value = 0
                    try:
                        symbols = [h['symbol'] for h in holdings]
                        if symbols:
                            batch = await asyncio.to_thread(
                                yf.download, symbols, period='1d', group_by='ticker', progress=False, threads=True
                            )
                            for h in holdings:
                                sym = h['symbol']
                                shares = h['shares']
                                cost = h.get('total_cost', shares * h.get('purchase_price', 0))
                                total_cost += cost
                                try:
                                    if batch is not None and not batch.empty:
                                        if len(symbols) == 1:
                                            try:
                                                sh = batch[sym]
                                            except (KeyError, TypeError):
                                                sh = batch
                                        else:
                                            sh = batch[sym]
                                        if sh is not None and not sh.empty and 'Close' in sh.columns:
                                            price = float(sh['Close'].dropna().iloc[-1])
                                            val = shares * price
                                            total_market_value += val
                                        else:
                                            total_market_value += cost
                                    else:
                                        total_market_value += cost
                                except:
                                    total_market_value += cost
                            unrealized_pl = total_market_value - total_cost
                    except:
                        pass

                    # All-time realized P/L
                    all_time_realized = sum(s.get('profit_loss', 0) for s in sold_history)
                    total_invested_ever = total_cost + sum(s.get('cost_basis', 0) for s in sold_history)
                    total_pl = unrealized_pl + all_time_realized
                    total_pl_pct = (total_pl / total_invested_ever * 100) if total_invested_ever > 0 else 0

                    # Count trading days
                    trading_days = len(month_logs)

                    # Trades during the month
                    month_buys = []
                    month_sells = []
                    for log in month_logs:
                        for m in log.get('movements', []):
                            if m['type'] == 'BUY':
                                month_buys.append(m)
                            else:
                                month_sells.append(m)

                    # Build message
                    msg = f"📅 *MONTHLY PORTFOLIO REPORT*\n"
                    msg += f"📆 *{month_name}*\n"
                    msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

                    # Value summary
                    msg += f"💰 *Start of Month:* ${start_value:,.2f}\n"
                    msg += f"💰 *End of Month:* ${end_value:,.2f}\n"
                    chg_emoji = "📈" if value_change >= 0 else "📉"
                    chg_pct = (value_change / start_value * 100) if start_value > 0 else 0
                    msg += f"{chg_emoji} *Value Change:* ${value_change:+,.2f} ({chg_pct:+.1f}%)\n\n"

                    # Month's realized P/L
                    if month_sold_stocks:
                        real_emoji = "🟢" if month_realized >= 0 else "🔴"
                        msg += f"📤 *Realized P/L ({len(month_sold_stocks)} sales):* {real_emoji} ${month_realized:+,.2f}\n"
                        for s in month_sold_stocks:
                            s_emoji = "🟢" if s['profit_loss'] >= 0 else "🔴"
                            msg += f"   {s_emoji} {s['symbol']} ({s['shares']:.0f}) ${s['profit_loss']:+,.2f} ({s.get('profit_pct', 0):+.1f}%)\n"
                        msg += "\n"

                    # Trading activity
                    if month_buys or month_sells:
                        msg += f"📋 *Trades:* {len(month_buys)} buys, {len(month_sells)} sells\n"
                        total_bought = sum(m['total'] for m in month_buys)
                        total_sold_amount = sum(m['total'] for m in month_sells)
                        if total_bought > 0:
                            msg += f"   ➕ Total Bought: ${total_bought:,.2f}\n"
                        if total_sold_amount > 0:
                            msg += f"   ➖ Total Sold: ${total_sold_amount:,.2f}\n"
                        msg += "\n"

                    msg += f"📊 *Trading Days Logged:* {trading_days}\n\n"

                    # Overall portfolio P/L (same as /portfolio Total P/L)
                    msg += "━━━━━━━━━━━━━━━━━━━━\n"
                    msg += "*ALL-TIME PORTFOLIO P/L*\n"
                    unreal_emoji = "🟢" if unrealized_pl >= 0 else "🔴"
                    unreal_pct = (unrealized_pl / total_cost * 100) if total_cost > 0 else 0
                    msg += f"{unreal_emoji} Unrealized: ${unrealized_pl:+,.2f} ({unreal_pct:+.1f}%)\n"
                    real_all_emoji = "🟢" if all_time_realized >= 0 else "🔴"
                    msg += f"{real_all_emoji} Realized: ${all_time_realized:+,.2f} ({len(sold_history)} trades)\n"
                    total_emoji = "🟢" if total_pl >= 0 else "🔴"
                    msg += f"{total_emoji} *Total P/L: ${total_pl:+,.2f} ({total_pl_pct:+.1f}%)*\n"

                    await app.bot.send_message(
                        chat_id=TELEGRAM_CHAT_ID,
                        text=msg,
                        parse_mode='Markdown'
                    )
                    sent_this_month = current_month
                    print(f"📅 Monthly portfolio performance report sent for {month_name}")

                except Exception as e:
                    print(f"⚠️ Error generating monthly report: {e}")
                    import traceback
                    traceback.print_exc()

            # Sleep 30 seconds
            await asyncio.sleep(30)

        except Exception as e:
            print(f"Monthly performance task error: {e}")
            await asyncio.sleep(60)


async def _goals_monthly_reminder_task(app):
    """Background task: remind about goals on the 8th of every month at 10:00 AM Israel time"""
    import pytz
    await asyncio.sleep(120)  # Wait for bot to be ready
    israel_tz = pytz.timezone('Asia/Jerusalem')
    print("🎯 Goals monthly reminder task started")

    while True:
        try:
            now = datetime.now(israel_tz)
            
            # Check if it's the 8th of the month and around 10:00 AM
            if now.day == 8 and now.hour == 10 and now.minute < 5:
                data = _load_goals()
                goal_list = data.get('goals', [])
                
                if goal_list:
                    modified = False
                    for g in goal_list:
                        # Check if we already sent reminder this month
                        last_reminder = g.get('last_reminder')
                        current_month = now.strftime('%Y-%m')
                        if last_reminder == current_month:
                            continue
                        
                        currency = g.get('currency', 'USD')
                        target = g['target']
                        goal_type = g.get('type', 'net_worth')
                        if goal_type == 'reserves':
                            current_value = await _get_current_reserves_value(currency)
                        else:
                            current_value = await _get_current_net_worth_for_currency(currency)
                        remaining = max(target - current_value, 0)
                        progress = min(current_value / target * 100, 100) if target else 0
                        sym = '$' if currency == 'USD' else '₪'
                        
                        months_left, monthly_needed, deadline_dt = _calculate_goal_monthly(g, current_value)
                        
                        bar_len = int(progress / 5)
                        bar = "█" * bar_len + "░" * (20 - bar_len)
                        
                        msg = f"🔔 *MONTHLY GOAL REMINDER*\n"
                        msg += f"━━━━━━━━━━━━━━━━━━━━\n\n"
                        msg += f"📌 *{g['name']}*\n\n"
                        msg += f"🎯 Target: {sym}{target:,.0f}\n"
                        msg += f"💰 Current: {sym}{current_value:,.0f}\n"
                        msg += f"📊 `{bar}` {progress:.1f}%\n\n"
                        
                        if progress >= 100:
                            msg += f"🎉 *CONGRATULATIONS! GOAL REACHED!*\n"
                        else:
                            msg += f"📏 Remaining: {sym}{remaining:,.0f}\n"
                            if months_left is not None and months_left > 0:
                                msg += f"⏳ {months_left} months until deadline\n"
                                msg += f"💵 *Invest {sym}{monthly_needed:,.0f} this month* to stay on track\n"
                            elif months_left == 0:
                                msg += f"⚠️ *Deadline month!* Still need {sym}{remaining:,.0f}\n"
                        
                        # Show contribution history summary
                        contribs = g.get('contributions', [])
                        if contribs:
                            last_3 = contribs[-3:]
                            msg += f"\n📥 *Recent contributions:*\n"
                            for c in last_3:
                                msg += f"  • {c['date']}: {sym}{c['amount']:,.0f}"
                                if c.get('note'):
                                    msg += f" ({c['note']})"
                                msg += "\n"
                        
                        msg += f"\n💡 Use /goals to view all details"
                        
                        await app.bot.send_message(
                            chat_id=TELEGRAM_CHAT_ID,
                            text=msg,
                            parse_mode='Markdown'
                        )
                        
                        g['last_reminder'] = current_month
                        modified = True
                    
                    if modified:
                        _save_goals(data)
                
                # Sleep 6 hours to avoid re-triggering
                await asyncio.sleep(6 * 3600)
            else:
                # Check every 3 minutes
                await asyncio.sleep(180)
        except Exception as e:
            print(f"Goals reminder task error: {e}")
            await asyncio.sleep(300)


async def _track_goal_contribution(app, action, symbol, cost_or_proceeds):
    """Track buy as contribution toward goal, recalculate monthly needed"""
    try:
        data = _load_goals()
        goal_list = data.get('goals', [])
        if not goal_list:
            return
        
        modified = False
        for g in goal_list:
            if action == 'buy':
                # Record the buy as a contribution
                g.setdefault('contributions', []).append({
                    'date': datetime.now().strftime('%Y-%m-%d'),
                    'amount': round(cost_or_proceeds, 2),
                    'note': f'Bought {symbol}',
                    'type': 'buy'
                })
                modified = True
        
        if modified:
            _save_goals(data)
        
        # Send update notification
        await _send_goals_update_notification(app, action, symbol, cost_or_proceeds)
    except Exception as e:
        print(f"Goal contribution tracking error: {e}")


async def _handle_goals_delete(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip()
    if text.lower() in ['cancel', '❌']:
        await update.message.reply_text("👍 Cancelled.")
        context.user_data.pop('state', None)
        return

    data = _load_goals()
    try:
        idx = int(text) - 1
        if 0 <= idx < len(data['goals']):
            removed = data['goals'].pop(idx)
            _save_goals(data)
            await update.message.reply_text(f"🗑️ Deleted: *{removed['name']}*", parse_mode='Markdown')
        else:
            await update.message.reply_text("❌ Invalid number.")
    except:
        await update.message.reply_text("❌ Send a number.")
    context.user_data.pop('state', None)


