async def momentum(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Scan portfolio + watchlist for momentum signals"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("🚀 *Scanning for momentum signals...*", parse_mode='Markdown')

    try:
        # Get symbols from portfolio + watchlist
        portfolio_data = _load_portfolio()
        portfolio_symbols = list(set(h['symbol'] for h in portfolio_data.get('holdings', [])))

        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        watchlist_symbols = []
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                wl_data = json.load(f)
            default_wl = wl_data.get('watchlists', {}).get('default', {})
            watchlist_symbols = list(default_wl.get('stocks', {}).keys())

        all_symbols = list(set(portfolio_symbols + watchlist_symbols))
        if not all_symbols:
            await update.message.reply_text("❌ No stocks in portfolio or watchlist!")
            return

        results = []
        for sym in all_symbols:
            try:
                hist = await asyncio.to_thread(lambda s=sym: yf.Ticker(s).history(period='6mo'))
                if hist.empty or len(hist) < 50:
                    continue

                closes = hist['Close']
                volumes = hist['Volume']
                current = float(closes.iloc[-1])

                # SMA 20 and 50
                sma20 = float(closes.tail(20).mean())
                sma50 = float(closes.tail(50).mean())

                # RSI (14-day)
                delta = closes.diff()
                gain = delta.where(delta > 0, 0).tail(14).mean()
                loss = (-delta.where(delta < 0, 0)).tail(14).mean()
                rs = gain / loss if loss != 0 else 100
                rsi = 100 - (100 / (1 + rs))

                # Volume trend
                vol_avg_20 = float(volumes.tail(20).mean())
                vol_today = float(volumes.iloc[-1])
                vol_ratio = vol_today / vol_avg_20 if vol_avg_20 else 1

                # Price vs SMAs
                above_sma20 = current > sma20
                above_sma50 = current > sma50
                sma_cross = sma20 > sma50  # Golden cross condition

                # 1-month return
                if len(closes) >= 21:
                    ret_1m = ((current / float(closes.iloc[-21])) - 1) * 100
                else:
                    ret_1m = 0

                # 1-week return
                if len(closes) >= 5:
                    ret_1w = ((current / float(closes.iloc[-5])) - 1) * 100
                else:
                    ret_1w = 0

                # Momentum score
                score = 0
                signals = []

                if above_sma20:
                    score += 15
                if above_sma50:
                    score += 15
                if sma_cross:
                    score += 20
                    signals.append("Golden Cross 🌟")

                if 50 < rsi < 70:
                    score += 20
                    signals.append("Strong RSI")
                elif rsi > 70:
                    score += 5
                    signals.append("⚠️ Overbought")
                elif rsi < 30:
                    signals.append("⚠️ Oversold")

                if vol_ratio > 1.5:
                    score += 15
                    signals.append("High Volume 📊")
                elif vol_ratio > 1.0:
                    score += 5

                if ret_1m > 10:
                    score += 15
                elif ret_1m > 5:
                    score += 10
                elif ret_1m > 0:
                    score += 5

                source = "💼" if sym in portfolio_symbols else "👀"

                results.append({
                    'symbol': sym,
                    'score': score,
                    'rsi': rsi,
                    'price': current,
                    'sma20': sma20,
                    'sma50': sma50,
                    'vol_ratio': vol_ratio,
                    'ret_1w': ret_1w,
                    'ret_1m': ret_1m,
                    'signals': signals,
                    'source': source,
                })

            except Exception as e:
                continue

        if not results:
            await update.message.reply_text("❌ Could not analyze stocks. Try again later.")
            return

        results.sort(key=lambda x: x['score'], reverse=True)

        msg = "🚀 *MOMENTUM SCANNER*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Top momentum
        msg += "🔥 *Strongest Momentum:*\n"
        for r in results[:8]:
            score_bar = "█" * (r['score'] // 10) + "░" * (10 - r['score'] // 10)
            msg += f"\n{r['source']} *{r['symbol']}* — Score: {r['score']}/100\n"
            msg += f"  💰 ${r['price']:.2f} | RSI: {r['rsi']:.0f}\n"
            msg += f"  📈 1W: {r['ret_1w']:+.1f}% | 1M: {r['ret_1m']:+.1f}%\n"
            msg += f"  📊 Vol: {r['vol_ratio']:.1f}x avg\n"
            if r['signals']:
                msg += f"  ✨ {', '.join(r['signals'])}\n"

        # Oversold (potential reversals)
        oversold = [r for r in results if r['rsi'] < 30]
        if oversold:
            msg += "\n\n⚠️ *Oversold (Potential Reversal):*\n"
            for r in oversold[:3]:
                msg += f"  📉 *{r['symbol']}* — RSI: {r['rsi']:.0f} | 1M: {r['ret_1m']:+.1f}%\n"

        msg += f"\n\n📊 Scanned: {len(results)} stocks"
        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /insiders - Insider Trading Activity
# ═══════════════════════════════════════════════════════════════

async def insiders(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show insider trading activity for a stock"""
    user_id = update.effective_user.id
    if not is_authorized(user_id):
        await unauthorized_message(update)
        return

    if not context.args:
        pending_commands[user_id] = 'insiders'
        await update.message.reply_text(
            "🕵️ *Insider Trading*\n\nSend a stock symbol (e.g. `AAPL`) or `PORTFOLIO`:",
            parse_mode='Markdown'
        )
        return

    target = context.args[0].upper()
    await _do_insiders(update, target)


async def _do_insiders(update: Update, target: str):
    """Fetch insider trading data"""
    await update.message.reply_text(f"🕵️ *Fetching insider data for {target}...*", parse_mode='Markdown')

    try:
        if target == 'PORTFOLIO':
            portfolio_data = _load_portfolio()
            symbols = list(set(h['symbol'] for h in portfolio_data.get('holdings', [])))
        else:
            symbols = [target]

        if not symbols:
            await update.message.reply_text("❌ No stocks to check!")
            return

        all_insider_data = []
        for sym in symbols:
            try:
                ticker = yf.Ticker(sym)

                # Get insider transactions
                try:
                    insider_tx = ticker.insider_transactions
                    if insider_tx is not None and not insider_tx.empty:
                        for _, row in insider_tx.head(10).iterrows():
                            all_insider_data.append({
                                'symbol': sym,
                                'insider': str(row.get('Text', row.get('Insider', 'Unknown'))),
                                'shares': row.get('Shares', 0),
                                'value': row.get('Value', 0),
                                'date': str(row.get('Start Date', row.get('Date', '')))[:10],
                            })
                except:
                    pass

                # Also try insider_purchases (summary)
                try:
                    purchases = ticker.insider_purchases
                    if purchases is not None and not purchases.empty:
                        for _, row in purchases.iterrows():
                            all_insider_data.append({
                                'symbol': sym,
                                'insider': str(row.get('Insider Trading', row.get('Text', 'Summary'))),
                                'shares': row.get('Shares', 0),
                                'value': 0,
                                'date': 'Recent',
                            })
                except:
                    pass

            except Exception as e:
                continue

        if not all_insider_data:
            # Fallback - get institutional holders
            msg = f"🕵️ *INSIDER DATA: {target}*\n"
            msg += "━━━━━━━━━━━━━━━━━━━━\n\n"
            msg += "⚠️ No recent insider transactions found.\n\n"

            # Try institutional holders instead
            if len(symbols) == 1:
                try:
                    ticker = yf.Ticker(symbols[0])
                    inst = ticker.institutional_holders
                    if inst is not None and not inst.empty:
                        msg += "🏢 *Top Institutional Holders:*\n"
                        for _, row in inst.head(8).iterrows():
                            name = str(row.get('Holder', 'Unknown'))[:30]
                            shares = row.get('Shares', 0)
                            pct = row.get('pctHeld', row.get('% Out', 0))
                            if isinstance(pct, (int, float)):
                                pct_str = f"{pct*100:.1f}%" if pct < 1 else f"{pct:.1f}%"
                            else:
                                pct_str = str(pct)
                            msg += f"  🏦 {name}\n"
                            msg += f"     {shares:,.0f} shares ({pct_str})\n"
                except:
                    pass

            msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
            await update.message.reply_text(msg, parse_mode='Markdown')
            return

        msg = f"🕵️ *INSIDER TRADING: {target}*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        buys = [d for d in all_insider_data if d.get('shares', 0) > 0 or 'buy' in str(d.get('insider', '')).lower() or 'purchase' in str(d.get('insider', '')).lower()]
        sells = [d for d in all_insider_data if d.get('shares', 0) < 0 or 'sale' in str(d.get('insider', '')).lower() or 'sell' in str(d.get('insider', '')).lower()]

        buy_total = sum(abs(d.get('shares', 0)) for d in buys)
        sell_total = sum(abs(d.get('shares', 0)) for d in sells)

        if buy_total > sell_total:
            msg += "🟢 *Net: BUYING* — Insiders are bullish\n\n"
        elif sell_total > buy_total:
            msg += "🔴 *Net: SELLING* — Insiders reducing exposure\n\n"
        else:
            msg += "🟡 *Net: NEUTRAL*\n\n"

        for d in all_insider_data[:15]:
            shares = d.get('shares', 0)
            if isinstance(shares, (int, float)) and shares != 0:
                action = "🟢 BUY" if shares > 0 else "🔴 SELL"
                msg += f"{action} *{d['symbol']}*\n"
                msg += f"  👤 {d['insider'][:40]}\n"
                msg += f"  📊 {abs(shares):,.0f} shares"
                if d.get('value') and d['value'] != 0:
                    msg += f" (${abs(d['value']):,.0f})"
                msg += f"\n  📅 {d['date']}\n\n"
            else:
                msg += f"📋 *{d['symbol']}*: {d['insider'][:50]}\n"
                msg += f"  📅 {d['date']}\n\n"

        msg += f"🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /earningswatch - Upcoming Earnings for Portfolio/Watchlist
# ═══════════════════════════════════════════════════════════════

async def earningswatch(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show upcoming earnings dates for all portfolio + watchlist stocks"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("📅 *Scanning upcoming earnings...*", parse_mode='Markdown')

    try:
        from datetime import date

        # Gather all symbols
        portfolio_data = _load_portfolio()
        portfolio_symbols = list(set(h['symbol'] for h in portfolio_data.get('holdings', [])))

        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        watchlist_symbols = []
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                wl_data = json.load(f)
            default_wl = wl_data.get('watchlists', {}).get('default', {})
            watchlist_symbols = list(default_wl.get('stocks', {}).keys())

        all_symbols = list(set(portfolio_symbols + watchlist_symbols))
        if not all_symbols:
            await update.message.reply_text("❌ No stocks in portfolio or watchlist!")
            return

        earnings_data = []
        for sym in all_symbols:
            try:
                ticker = yf.Ticker(sym)
                earnings_date = None

                # Try calendar
                try:
                    cal = ticker.calendar
                    if isinstance(cal, dict):
                        edates = cal.get('Earnings Date', [])
                        if edates:
                            edate = edates[0]
                            if hasattr(edate, 'date'):
                                edate = edate.date()
                            elif isinstance(edate, str):
                                edate = datetime.strptime(edate, '%Y-%m-%d').date()
                            earnings_date = edate
                except:
                    pass

                # Fallback: earnings_dates DF
                if earnings_date is None:
                    try:
                        ed = ticker.earnings_dates
                        if ed is not None and not ed.empty:
                            future = ed[ed['Reported EPS'].isna()]
                            if not future.empty:
                                edate = future.index[0]
                                if hasattr(edate, 'date'):
                                    edate = edate.date()
                                earnings_date = edate
                    except:
                        pass

                if earnings_date:
                    days_until = (earnings_date - date.today()).days
                    source = "💼" if sym in portfolio_symbols else "👀"
                    earnings_data.append({
                        'symbol': sym,
                        'date': earnings_date,
                        'days': days_until,
                        'source': source,
                    })
            except:
                continue

        if not earnings_data:
            await update.message.reply_text("❌ No earnings dates found. Data may be unavailable.")
            return

        # Sort by date
        earnings_data.sort(key=lambda x: x['days'])

        msg = "📅 *EARNINGS WATCH*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Past (recently reported)
        past = [e for e in earnings_data if e['days'] < 0]
        this_week = [e for e in earnings_data if 0 <= e['days'] <= 7]
        next_2w = [e for e in earnings_data if 7 < e['days'] <= 14]
        later = [e for e in earnings_data if 14 < e['days'] <= 60]
        far = [e for e in earnings_data if e['days'] > 60]

        if this_week:
            msg += "🔴 *THIS WEEK:*\n"
            for e in this_week:
                if e['days'] == 0:
                    when = "TODAY!"
                elif e['days'] == 1:
                    when = "TOMORROW"
                else:
                    when = f"in {e['days']}d"
                msg += f"  {e['source']} *{e['symbol']}* — {e['date'].strftime('%b %d')} ({when}) ⚠️\n"
            msg += "\n"

        if next_2w:
            msg += "🟡 *NEXT 2 WEEKS:*\n"
            for e in next_2w:
                msg += f"  {e['source']} *{e['symbol']}* — {e['date'].strftime('%b %d')} ({e['days']}d)\n"
            msg += "\n"

        if later:
            msg += "🟢 *COMING UP (2-8 weeks):*\n"
            for e in later:
                msg += f"  {e['source']} *{e['symbol']}* — {e['date'].strftime('%b %d')} ({e['days']}d)\n"
            msg += "\n"

        if far:
            msg += "⚪ *LATER:*\n"
            for e in far[:5]:
                msg += f"  {e['source']} *{e['symbol']}* — {e['date'].strftime('%b %d')} ({e['days']}d)\n"
            msg += "\n"

        if past:
            msg += "✅ *RECENTLY REPORTED:*\n"
            for e in past[-5:]:
                msg += f"  {e['source']} *{e['symbol']}* — {e['date'].strftime('%b %d')} ({abs(e['days'])}d ago)\n"
            msg += "\n"

        msg += f"📊 Tracked: {len(earnings_data)} stocks"
        msg += f"\n💼 = Portfolio | 👀 = Watchlist"
        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /dividends - Dividend Tracker for Portfolio
# ═══════════════════════════════════════════════════════════════

async def dividends(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show dividend info for portfolio stocks"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("💰 *Analyzing dividends...*", parse_mode='Markdown')

    try:
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])

        if not holdings:
            await update.message.reply_text("❌ No stocks in portfolio!")
            return

        # Aggregate
        symbol_data = {}
        for h in holdings:
            s = h['symbol']
            if s not in symbol_data:
                symbol_data[s] = {'shares': 0, 'cost': 0}
            symbol_data[s]['shares'] += h['shares']
            symbol_data[s]['cost'] += h['total_cost']

        dividend_stocks = []
        no_dividend = []
        total_annual_income = 0

        for sym, data in symbol_data.items():
            try:
                ticker = yf.Ticker(sym)
                info = ticker.info
                div_yield = info.get('dividendYield', 0) or 0
                div_rate = info.get('dividendRate', 0) or 0
                price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
                ex_date = info.get('exDividendDate', None)
                payout = info.get('payoutRatio', 0) or 0

                if div_rate > 0:
                    annual_income = div_rate * data['shares']
                    total_annual_income += annual_income
                    yield_on_cost = (div_rate / (data['cost'] / data['shares'])) * 100 if data['cost'] > 0 else 0

                    # Get ex-date
                    ex_date_str = "N/A"
                    if ex_date:
                        from datetime import date
                        if isinstance(ex_date, (int, float)):
                            ex_dt = datetime.fromtimestamp(ex_date).date()
                            ex_date_str = ex_dt.strftime('%b %d, %Y')
                            days_until = (ex_dt - date.today()).days
                            if 0 < days_until <= 14:
                                ex_date_str += f" ⚠️ ({days_until}d)"
                        elif hasattr(ex_date, 'strftime'):
                            ex_date_str = ex_date.strftime('%b %d, %Y')

                    dividend_stocks.append({
                        'symbol': sym,
                        'yield': div_yield * 100,
                        'rate': div_rate,
                        'annual_income': annual_income,
                        'yield_on_cost': yield_on_cost,
                        'payout': payout * 100,
                        'ex_date': ex_date_str,
                        'shares': data['shares'],
                        'price': price,
                    })
                else:
                    no_dividend.append(sym)

            except Exception as e:
                no_dividend.append(sym)

        msg = "💰 *DIVIDEND TRACKER*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        if dividend_stocks:
            dividend_stocks.sort(key=lambda x: x['annual_income'], reverse=True)

            msg += f"💵 *Total Annual Income: ${total_annual_income:,.2f}*\n"
            msg += f"📅 Monthly Average: ${total_annual_income/12:,.2f}\n\n"

            msg += "📊 *Dividend-Paying Stocks:*\n"
            for d in dividend_stocks:
                msg += f"\n{'💎' if d['yield'] >= 3 else '💰'} *{d['symbol']}*\n"
                msg += f"  📈 Yield: {d['yield']:.2f}% (${d['rate']:.2f}/share)\n"
                msg += f"  💵 Annual: ${d['annual_income']:,.2f} ({d['shares']:.0f} shares)\n"
                msg += f"  🎯 Yield on Cost: {d['yield_on_cost']:.2f}%\n"
                if d['payout'] > 0:
                    payout_emoji = "🟢" if d['payout'] < 60 else "🟡" if d['payout'] < 80 else "🔴"
                    msg += f"  {payout_emoji} Payout Ratio: {d['payout']:.0f}%\n"
                msg += f"  📅 Ex-Date: {d['ex_date']}\n"
        else:
            msg += "📋 No dividend-paying stocks in portfolio.\n"

        if no_dividend:
            msg += f"\n⚪ *No Dividend:* {', '.join(no_dividend)}\n"

        # Summary stats
        portfolio_value = sum(d['price'] * d['shares'] for d in dividend_stocks if d['price'])
        if portfolio_value > 0:
            avg_yield = total_annual_income / portfolio_value * 100
            msg += f"\n📊 *Portfolio Dividend Yield:* {avg_yield:.2f}%\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /correlation - Portfolio Correlation Matrix
# ═══════════════════════════════════════════════════════════════

async def correlation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show portfolio stock correlation analysis"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("📊 *Calculating correlations...*", parse_mode='Markdown')

    try:
        import pandas as pd
        import numpy as np

        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])

        if not holdings:
            await update.message.reply_text("❌ No stocks in portfolio!")
            return

        symbols = list(set(h['symbol'] for h in holdings))
        if len(symbols) < 2:
            await update.message.reply_text("❌ Need at least 2 stocks for correlation analysis!")
            return

        # Download 6 months of data
        data = await asyncio.to_thread(
            yf.download, symbols, period='6mo', group_by='ticker', progress=False, threads=True
        )

        # Build returns DataFrame
        returns_dict = {}
        for sym in symbols:
            try:
                if len(symbols) == 1:
                    closes = data['Close'].dropna()
                else:
                    closes = data[sym]['Close'].dropna()
                daily_returns = closes.pct_change().dropna()
                returns_dict[sym] = daily_returns
            except:
                continue

        if len(returns_dict) < 2:
            await update.message.reply_text("❌ Not enough price data for correlation!")
            return

        returns_df = pd.DataFrame(returns_dict)
        corr_matrix = returns_df.corr()

        # Find highest and lowest correlations
        pairs = []
        syms = list(returns_dict.keys())
        for i in range(len(syms)):
            for j in range(i + 1, len(syms)):
                c = corr_matrix.loc[syms[i], syms[j]]
                if not np.isnan(c):
                    pairs.append((syms[i], syms[j], c))

        pairs.sort(key=lambda x: x[2], reverse=True)

        # Portfolio average correlation
        corr_values = [p[2] for p in pairs]
        avg_corr = sum(corr_values) / len(corr_values) if corr_values else 0

        msg = "📊 *PORTFOLIO CORRELATION*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Overall diversification from correlation perspective
        if avg_corr < 0.3:
            div_label = "🟢 Well Diversified"
            div_advice = "Low correlation = good risk distribution"
        elif avg_corr < 0.5:
            div_label = "🟡 Moderately Diversified"
            div_advice = "Some stocks move together — acceptable"
        elif avg_corr < 0.7:
            div_label = "🟠 Poorly Diversified"
            div_advice = "Many stocks correlated — add uncorrelated assets"
        else:
            div_label = "🔴 Highly Correlated"
            div_advice = "Portfolio moves as one block — diversify!"

        msg += f"📈 *Avg Correlation:* {avg_corr:.2f} — {div_label}\n"
        msg += f"💡 {div_advice}\n\n"

        # Most correlated pairs (risk)
        if pairs:
            msg += "🔴 *Most Correlated (Risk):*\n"
            for s1, s2, c in pairs[:5]:
                bar_len = int(abs(c) * 10)
                bar = "█" * bar_len + "░" * (10 - bar_len)
                msg += f"  `{bar}` {c:.2f} — {s1} ↔ {s2}\n"
            msg += "\n"

            # Least correlated pairs (good)
            msg += "🟢 *Least Correlated (Good):*\n"
            for s1, s2, c in pairs[-5:]:
                bar_len = int(abs(c) * 10)
                bar = "█" * bar_len + "░" * (10 - bar_len)
                msg += f"  `{bar}` {c:.2f} — {s1} ↔ {s2}\n"
            msg += "\n"

        # Correlation clusters
        high_corr_groups = {}
        for s1, s2, c in pairs:
            if c > 0.7:
                if s1 not in high_corr_groups:
                    high_corr_groups[s1] = set()
                if s2 not in high_corr_groups:
                    high_corr_groups[s2] = set()
                high_corr_groups[s1].add(s2)
                high_corr_groups[s2].add(s1)

        if high_corr_groups:
            msg += "⚠️ *Correlated Clusters:*\n"
            seen = set()
            for sym, related in high_corr_groups.items():
                if sym not in seen:
                    cluster = {sym} | related
                    seen.update(cluster)
                    msg += f"  🔗 {' ↔ '.join(sorted(cluster))}\n"
            msg += "  _These stocks move together — consider trimming_\n\n"

        # Quick matrix for small portfolios
        if len(syms) <= 8:
            msg += "📋 *Correlation Matrix:*\n"
            header = "      " + "".join(f"{s:>6}" for s in syms) + "\n"
            msg += f"`{header}`"
            for s1 in syms:
                row = f"{s1:>5} "
                for s2 in syms:
                    c = corr_matrix.loc[s1, s2]
                    row += f"{c:>5.2f} "
                msg += f"`{row}`\n"
            msg += "\n"

        msg += f"📊 Analyzed: {len(syms)} stocks, {len(pairs)} pairs"
        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        msg += "\n_Based on 6-month daily returns_"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /macro - Macro Economic Dashboard
# ═══════════════════════════════════════════════════════════════

async def macro(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Macro economic dashboard — key indicators, yields, currencies, commodities"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("🌍 *Loading macro dashboard...*", parse_mode='Markdown')

    try:
        import numpy as np

        # Define all instruments to fetch
        instruments = {
            # US Treasury yields
            '^TNX': ('10Y Treasury', 'yield'),
            '^FVX': ('5Y Treasury', 'yield'),
            '^TYX': ('30Y Treasury', 'yield'),
            '^IRX': ('3M T-Bill', 'yield'),
            # Currencies
            'DX-Y.NYB': ('US Dollar Index', 'currency'),
            'EURUSD=X': ('EUR/USD', 'currency'),
            'USDILS=X': ('USD/ILS', 'currency'),
            'USDJPY=X': ('USD/JPY', 'currency'),
            'GBPUSD=X': ('GBP/USD', 'currency'),
            # Commodities
            'GC=F': ('Gold', 'commodity'),
            'SI=F': ('Silver', 'commodity'),
            'CL=F': ('Crude Oil (WTI)', 'commodity'),
            'NG=F': ('Natural Gas', 'commodity'),
            # Crypto
            'BTC-USD': ('Bitcoin', 'crypto'),
            'ETH-USD': ('Ethereum', 'crypto'),
            # Market indices for context
            '^GSPC': ('S&P 500', 'index'),
            '^VIX': ('VIX (Fear)', 'index'),
        }

        symbols = list(instruments.keys())
        data = await asyncio.to_thread(
            yf.download, symbols, period='5d', group_by='ticker', progress=False, threads=True
        )

        results = {}
        for sym, (name, category) in instruments.items():
            try:
                if len(symbols) == 1:
                    df = data
                else:
                    df = data[sym]
                if df.empty or len(df) < 2:
                    continue
                curr = float(df['Close'].dropna().iloc[-1])
                prev = float(df['Close'].dropna().iloc[-2])
                chg = ((curr - prev) / prev) * 100 if prev else 0
                results[sym] = {'name': name, 'cat': category, 'price': curr, 'change': chg}
            except:
                pass

        msg = "🌍 *MACRO ECONOMIC DASHBOARD*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Treasury Yields
        msg += "🏦 *US Treasury Yields:*\n"
        for sym in ['^IRX', '^FVX', '^TNX', '^TYX']:
            if sym in results:
                r = results[sym]
                arrow = "📈" if r['change'] >= 0 else "📉"
                msg += f"  {arrow} {r['name']}: {r['price']:.2f}% ({r['change']:+.2f}%)\n"
        
        # Yield curve inversion check
        if '^TNX' in results and '^IRX' in results:
            spread = results['^TNX']['price'] - results['^IRX']['price']
            if spread < 0:
                msg += f"  ⚠️ *Yield curve INVERTED* (spread: {spread:.2f}%)\n"
            else:
                msg += f"  ✅ Yield curve normal (spread: {spread:.2f}%)\n"
        msg += "\n"

        # Currencies
        msg += "💱 *Currencies:*\n"
        for sym in ['DX-Y.NYB', 'EURUSD=X', 'USDILS=X', 'USDJPY=X', 'GBPUSD=X']:
            if sym in results:
                r = results[sym]
                arrow = "🟢" if r['change'] >= 0 else "🔴"
                if sym == 'USDILS=X':
                    msg += f"  {arrow} {r['name']}: ₪{r['price']:.3f} ({r['change']:+.2f}%)\n"
                elif sym == 'DX-Y.NYB':
                    msg += f"  {arrow} {r['name']}: {r['price']:.2f} ({r['change']:+.2f}%)\n"
                else:
                    msg += f"  {arrow} {r['name']}: {r['price']:.4f} ({r['change']:+.2f}%)\n"
        msg += "\n"

        # Commodities
        msg += "🛢️ *Commodities:*\n"
        for sym in ['GC=F', 'SI=F', 'CL=F', 'NG=F']:
            if sym in results:
                r = results[sym]
                arrow = "🟢" if r['change'] >= 0 else "🔴"
                msg += f"  {arrow} {r['name']}: ${r['price']:,.2f} ({r['change']:+.2f}%)\n"
        msg += "\n"

        # Crypto
        msg += "🪙 *Crypto:*\n"
        for sym in ['BTC-USD', 'ETH-USD']:
            if sym in results:
                r = results[sym]
                arrow = "🟢" if r['change'] >= 0 else "🔴"
                msg += f"  {arrow} {r['name']}: ${r['price']:,.0f} ({r['change']:+.2f}%)\n"
        msg += "\n"

        # Market sentiment
        msg += "📊 *Market Sentiment:*\n"
        for sym in ['^GSPC', '^VIX']:
            if sym in results:
                r = results[sym]
                if sym == '^VIX':
                    if r['price'] < 15:
                        mood = "😌 Low fear"
                    elif r['price'] < 20:
                        mood = "😐 Normal"
                    elif r['price'] < 25:
                        mood = "😟 Elevated"
                    elif r['price'] < 30:
                        mood = "😰 High fear"
                    else:
                        mood = "🚨 Extreme fear"
                    msg += f"  {mood} — VIX: {r['price']:.1f} ({r['change']:+.2f}%)\n"
                else:
                    arrow = "🟢" if r['change'] >= 0 else "🔴"
                    msg += f"  {arrow} {r['name']}: {r['price']:,.1f} ({r['change']:+.2f}%)\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /summary - Portfolio Summary Report
# ═══════════════════════════════════════════════════════════════

async def summary(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Complete portfolio summary — allocation, performance, cash, goals"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("📋 *Generating summary...*", parse_mode='Markdown')

    try:
        import numpy as np
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        free_cash = _usd_cash_total(portfolio_data)
        reserves = portfolio_data.get('reserves', {})
        ils_bank = reserves.get('ILS', 0)
        ils_checking = reserves.get('ILS_checking', 0)
        eur_reserve = reserves.get('EUR', 0)

        if not holdings and free_cash == 0:
            await update.message.reply_text("❌ Portfolio is empty!")
            return

        # Get exchange rates
        try:
            usdils = yf.Ticker('USDILS=X')
            rate_hist = usdils.history(period='1d')
            usd_ils_rate = float(rate_hist['Close'].iloc[-1]) if not rate_hist.empty else 3.6
        except:
            usd_ils_rate = 3.6
        try:
            eurusd = yf.Ticker('EURUSD=X')
            eur_hist = eurusd.history(period='1d')
            eur_usd_rate = float(eur_hist['Close'].iloc[-1]) if not eur_hist.empty else 1.08
        except:
            eur_usd_rate = 1.08

        # Get current prices
        symbol_data = {}
        for h in holdings:
            s = h['symbol']
            if s not in symbol_data:
                symbol_data[s] = {'shares': 0, 'cost': 0}
            symbol_data[s]['shares'] += h['shares']
            symbol_data[s]['cost'] += h['total_cost']

        symbols = list(symbol_data.keys())
        stock_results = []
        total_value = 0
        total_cost = 0

        if symbols:
            batch = await asyncio.to_thread(
                yf.download, symbols, period='5d', group_by='ticker', progress=False, threads=True
            )
            for sym in symbols:
                try:
                    if len(symbols) == 1:
                        df = batch
                    else:
                        df = batch[sym]
                    price = float(df['Close'].dropna().iloc[-1])
                    prev = float(df['Close'].dropna().iloc[-2]) if len(df['Close'].dropna()) >= 2 else price
                    shares = symbol_data[sym]['shares']
                    cost = symbol_data[sym]['cost']
                    value = price * shares
                    pl = value - cost
                    pl_pct = (pl / cost * 100) if cost > 0 else 0
                    day_chg = ((price - prev) / prev * 100) if prev else 0
                    total_value += value
                    total_cost += cost
                    stock_results.append({
                        'symbol': sym, 'shares': shares, 'price': price,
                        'value': value, 'cost': cost, 'pl': pl, 'pl_pct': pl_pct,
                        'day_chg': day_chg
                    })
                except:
                    cost = symbol_data[sym]['cost']
                    total_value += cost
                    total_cost += cost

        # Sort by value descending
        stock_results.sort(key=lambda x: x['value'], reverse=True)

        total_pl = total_value - total_cost
        total_pl_pct = (total_pl / total_cost * 100) if total_cost > 0 else 0

        # Total assets
        ils_in_usd = (ils_bank + ils_checking) / usd_ils_rate if usd_ils_rate > 0 else 0
        total_usd = total_value + free_cash + (eur_reserve * eur_usd_rate)
        grand_total_usd = total_usd + ils_in_usd  # Everything converted to USD
        total_ils = (total_usd * usd_ils_rate) + ils_bank + ils_checking

        msg = "📋 *PORTFOLIO SUMMARY*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Net worth
        msg += "💰 *Total Net Worth:*\n"
        msg += f"  🇺🇸 ${grand_total_usd:,.0f} USD\n"
        msg += f"  🇮🇱 ₪{total_ils:,.0f} ILS\n\n"

        # Asset allocation pie
        msg += "📊 *Asset Allocation:*\n"
        stock_pct = (total_value / grand_total_usd * 100) if grand_total_usd > 0 else 0
        cash_pct = (free_cash / grand_total_usd * 100) if grand_total_usd > 0 else 0
        eur_pct = ((eur_reserve * eur_usd_rate) / grand_total_usd * 100) if grand_total_usd > 0 else 0
        ils_pct = (ils_in_usd / grand_total_usd * 100) if grand_total_usd > 0 else 0
        msg += f"  📈 Stocks: ${total_value:,.0f} ({stock_pct:.0f}%)\n"
        msg += f"  💵 USD Cash: ${free_cash:,.0f} ({cash_pct:.0f}%)\n"
        if eur_reserve > 0:
            msg += f"  💶 EUR: €{eur_reserve:,.0f} ({eur_pct:.0f}%)\n"
        if ils_bank + ils_checking > 0:
            msg += f"  🏦 ILS: ₪{ils_bank + ils_checking:,.0f} ({ils_pct:.0f}%)\n"
        msg += "\n"

        # Portfolio P/L
        pl_emoji = "🟢" if total_pl >= 0 else "🔴"
        msg += f"📈 *Portfolio Performance:*\n"
        msg += f"  💰 Invested: ${total_cost:,.0f}\n"
        msg += f"  💵 Current: ${total_value:,.0f}\n"
        msg += f"  {pl_emoji} P/L: ${total_pl:+,.0f} ({total_pl_pct:+.1f}%)\n\n"

        # Top 5 holdings
        msg += "🏆 *Top Holdings:*\n"
        for s in stock_results[:5]:
            pct_of_port = (s['value'] / total_value * 100) if total_value > 0 else 0
            emoji = "🟢" if s['pl'] >= 0 else "🔴"
            msg += f"  {emoji} *{s['symbol']}*: ${s['value']:,.0f} ({pct_of_port:.0f}%) P/L: {s['pl_pct']:+.1f}%\n"
        msg += "\n"

        # Best & worst performers
        if len(stock_results) >= 2:
            best = max(stock_results, key=lambda x: x['pl_pct'])
            worst = min(stock_results, key=lambda x: x['pl_pct'])
            msg += "📊 *Performance Extremes:*\n"
            msg += f"  🏆 Best: {best['symbol']} ({best['pl_pct']:+.1f}%)\n"
            msg += f"  💀 Worst: {worst['symbol']} ({worst['pl_pct']:+.1f}%)\n\n"

        # Today's movers
        if stock_results:
            today_best = max(stock_results, key=lambda x: x['day_chg'])
            today_worst = min(stock_results, key=lambda x: x['day_chg'])
            msg += "📅 *Today:*\n"
            msg += f"  🟢 {today_best['symbol']}: {today_best['day_chg']:+.2f}%\n"
            msg += f"  🔴 {today_worst['symbol']}: {today_worst['day_chg']:+.2f}%\n\n"

        # Goals progress (if any)
        try:
            goals_data = _load_goals()
            goal_list = goals_data.get('goals', [])
            if goal_list:
                msg += "🎯 *Goals:*\n"
                for g in goal_list:
                    target = g['target']
                    currency = g.get('currency', 'USD')
                    current = total_usd if currency == 'USD' else total_ils
                    sym_char = '$' if currency == 'USD' else '₪'
                    progress = min(current / target * 100, 100) if target else 0
                    bar_len = int(progress / 10)
                    bar = "█" * bar_len + "░" * (10 - bar_len)
                    msg += f"  `{bar}` {progress:.0f}% — {g['name']} ({sym_char}{target:,.0f})\n"
                msg += "\n"
        except:
            pass

        msg += f"🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /dca - Dollar Cost Averaging Calculator
# ═══════════════════════════════════════════════════════════════

async def dca(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """DCA calculator — show impact of dollar cost averaging on a stock"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    if not context.args:
        # Show DCA for portfolio holdings
        await update.message.reply_text(
            "📊 *DCA Calculator*\n\n"
            "Usage: `/dca SYMBOL [monthly_amount]`\n\n"
            "Examples:\n"
            "• `/dca AAPL` — DCA analysis with $500/month\n"
            "• `/dca NVDA 1000` — DCA $1,000/month\n"
            "• `/dca PORTFOLIO` — DCA across portfolio\n",
            parse_mode='Markdown'
        )
        return

    target = context.args[0].upper()
    monthly_amount = 500  # default
    if len(context.args) > 1:
        try:
            monthly_amount = float(context.args[1].replace('$', '').replace(',', ''))
        except:
            pass

    await update.message.reply_text(f"📊 *Calculating DCA for {target}...*", parse_mode='Markdown')

    try:
        import numpy as np

        if target == 'PORTFOLIO':
            portfolio_data = _load_portfolio()
            holdings = portfolio_data.get('holdings', [])
            if not holdings:
                await update.message.reply_text("❌ Portfolio is empty!")
                return
            symbols = list(set(h['symbol'] for h in holdings))
            # Use equal weight DCA
            per_stock = monthly_amount / len(symbols)
        else:
            symbols = [target]
            per_stock = monthly_amount

        # Download 2 years of monthly data
        data = await asyncio.to_thread(
            yf.download, symbols, period='2y', interval='1mo', progress=False, threads=True
        )

        if data.empty:
            await update.message.reply_text(f"❌ No data found for {target}. Check the ticker!")
            return

        msg = "📊 *DCA ANALYSIS*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        total_dca_invested = 0
        total_dca_value = 0
        total_lump_value = 0
        total_lump_invested = 0

        for sym in symbols:
            try:
                # Handle MultiIndex columns: ('Close', 'WDC')
                import pandas as pd
                if isinstance(data.columns, pd.MultiIndex):
                    if sym in data['Close'].columns:
                        closes = data['Close'][sym].dropna()
                    elif len(symbols) == 1:
                        closes = data['Close'].iloc[:, 0].dropna()
                    else:
                        continue
                else:
                    closes = data['Close'].dropna()
                if len(closes) < 3:
                    continue

                # DCA simulation: invest per_stock every month
                total_shares_dca = 0
                total_invested_dca = 0
                buy_prices = []

                for price in closes:
                    p = float(price)
                    if p > 0:
                        shares_bought = per_stock / p
                        total_shares_dca += shares_bought
                        total_invested_dca += per_stock
                        buy_prices.append(p)

                if not buy_prices:
                    continue

                current_price = buy_prices[-1]
                dca_value = total_shares_dca * current_price
                dca_avg_price = total_invested_dca / total_shares_dca if total_shares_dca > 0 else 0
                dca_return = ((dca_value - total_invested_dca) / total_invested_dca * 100) if total_invested_dca > 0 else 0

                # Lump sum comparison: invest everything at the start
                lump_price = buy_prices[0]
                lump_shares = total_invested_dca / lump_price
                lump_value = lump_shares * current_price
                lump_return = ((lump_value - total_invested_dca) / total_invested_dca * 100) if total_invested_dca > 0 else 0

                total_dca_invested += total_invested_dca
                total_dca_value += dca_value
                total_lump_invested += total_invested_dca
                total_lump_value += lump_value

                if len(symbols) <= 3:
                    emoji = "🟢" if dca_return >= 0 else "🔴"
                    msg += f"📈 *{sym}* (${per_stock:,.0f}/month × {len(buy_prices)} months)\n"
                    msg += f"  💵 Total invested: ${total_invested_dca:,.0f}\n"
                    msg += f"  📊 Avg price: ${dca_avg_price:.2f}\n"
                    msg += f"  💰 Current value: ${dca_value:,.0f}\n"
                    msg += f"  {emoji} DCA Return: {dca_return:+.1f}%\n"
                    lump_emoji = "🟢" if lump_return >= 0 else "🔴"
                    msg += f"  {lump_emoji} Lump sum would be: {lump_return:+.1f}%\n"
                    winner = "DCA 🏆" if dca_return > lump_return else "Lump Sum 🏆"
                    msg += f"  ⚖️ Winner: {winner}\n\n"
            except:
                pass

        # Portfolio summary
        if total_dca_invested > 0:
            overall_dca_ret = ((total_dca_value - total_dca_invested) / total_dca_invested * 100)
            overall_lump_ret = ((total_lump_value - total_lump_invested) / total_lump_invested * 100)

            if len(symbols) > 3:
                msg += f"📈 *Portfolio DCA* (${monthly_amount:,.0f}/month split across {len(symbols)} stocks)\n\n"

            msg += f"📊 *Summary (2-Year Backtest):*\n"
            msg += f"  💵 Total invested: ${total_dca_invested:,.0f}\n"
            dca_emoji = "🟢" if overall_dca_ret >= 0 else "🔴"
            msg += f"  {dca_emoji} DCA value: ${total_dca_value:,.0f} ({overall_dca_ret:+.1f}%)\n"
            lump_emoji = "🟢" if overall_lump_ret >= 0 else "🔴"
            msg += f"  {lump_emoji} Lump sum: ${total_lump_value:,.0f} ({overall_lump_ret:+.1f}%)\n\n"

            winner = "DCA" if overall_dca_ret > overall_lump_ret else "Lump Sum"
            diff = abs(overall_dca_ret - overall_lump_ret)
            msg += f"  🏆 *{winner} wins by {diff:.1f}%*\n\n"

            # Future projection
            msg += f"🔮 *If you start DCA ${monthly_amount:,.0f}/month now:*\n"
            for years in [1, 3, 5]:
                months = years * 12
                invested = monthly_amount * months
                # Use historical annual return for projection
                annual_ret = overall_dca_ret / 2  # 2-year data, annualize
                monthly_ret = (1 + annual_ret / 100) ** (1/12) - 1
                fv = 0
                for m in range(months):
                    fv = (fv + monthly_amount) * (1 + monthly_ret)
                msg += f"  📅 {years}Y: ${invested:,.0f} invested → ${fv:,.0f}\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        msg += "\n_Past performance doesn't guarantee future results._"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# ═══════════════════════════════════════════════════════════════
# /risk - Portfolio Risk Analysis
# ═══════════════════════════════════════════════════════════════

async def risk(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Portfolio risk analysis — volatility, beta, VaR, stress tests"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("⚠️ *Analyzing portfolio risk...*", parse_mode='Markdown')

    try:
        import numpy as np
        import pandas as pd

        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])

        if not holdings:
            await update.message.reply_text("❌ Portfolio is empty!")
            return

        # Aggregate holdings
        symbol_data = {}
        for h in holdings:
            s = h['symbol']
            if s not in symbol_data:
                symbol_data[s] = {'shares': 0, 'cost': 0}
            symbol_data[s]['shares'] += h['shares']
            symbol_data[s]['cost'] += h['total_cost']

        symbols = list(symbol_data.keys())

        # Download 1 year of data + S&P 500 for beta calculation
        all_syms = symbols + ['^GSPC']
        data = await asyncio.to_thread(
            yf.download, all_syms, period='1y', group_by='ticker', progress=False, threads=True
        )

        # Extract daily returns
        returns_dict = {}
        weights = {}
        total_value = 0

        for sym in symbols:
            try:
                if len(all_syms) == 1:
                    closes = data['Close'].dropna()
                else:
                    closes = data[sym]['Close'].dropna()
                if len(closes) < 20:
                    continue
                price = float(closes.iloc[-1])
                value = price * symbol_data[sym]['shares']
                total_value += value
                returns_dict[sym] = closes.pct_change().dropna()
                weights[sym] = value
            except:
                pass

        if not returns_dict:
            await update.message.reply_text("❌ Not enough data for risk analysis!")
            return

        # Normalize weights
        for sym in weights:
            weights[sym] /= total_value

        # S&P 500 returns for beta
        try:
            if len(all_syms) == 1:
                sp_closes = data['Close'].dropna()
            else:
                sp_closes = data['^GSPC']['Close'].dropna()
            sp_returns = sp_closes.pct_change().dropna()
        except:
            sp_returns = None

        # Portfolio daily returns (weighted)
        returns_df = pd.DataFrame(returns_dict)
        portfolio_returns = sum(returns_df[sym].fillna(0) * weights[sym] for sym in returns_dict)

        # 1. Portfolio Volatility
        daily_vol = float(portfolio_returns.std())
        annual_vol = daily_vol * np.sqrt(252)
        sp_annual_vol = float(sp_returns.std() * np.sqrt(252)) if sp_returns is not None else 0.15

        # 2. Portfolio Beta
        if sp_returns is not None:
            # Align indices
            common_idx = portfolio_returns.index.intersection(sp_returns.index)
            port_aligned = portfolio_returns.loc[common_idx]
            sp_aligned = sp_returns.loc[common_idx]
            if len(common_idx) > 20:
                cov = float(np.cov(port_aligned, sp_aligned)[0][1])
                sp_var = float(np.var(sp_aligned))
                portfolio_beta = cov / sp_var if sp_var > 0 else 1.0
            else:
                portfolio_beta = 1.0
        else:
            portfolio_beta = 1.0

        # 3. Value at Risk (VaR) - 95% and 99%
        var_95 = float(np.percentile(portfolio_returns, 5)) * total_value
        var_99 = float(np.percentile(portfolio_returns, 1)) * total_value

        # 4. Maximum Drawdown
        cumulative = (1 + portfolio_returns).cumprod()
        peak = cumulative.expanding(min_periods=1).max()
        drawdown = (cumulative - peak) / peak
        max_drawdown = float(drawdown.min()) * 100

        # 5. Sharpe Ratio (assuming 5% risk-free rate)
        annual_return = float((cumulative.iloc[-1] ** (252 / len(cumulative)) - 1))
        risk_free = 0.05
        sharpe = (annual_return - risk_free) / annual_vol if annual_vol > 0 else 0

        # 6. Sortino Ratio (downside deviation)
        downside = portfolio_returns[portfolio_returns < 0]
        downside_dev = float(downside.std() * np.sqrt(252)) if len(downside) > 0 else annual_vol
        sortino = (annual_return - risk_free) / downside_dev if downside_dev > 0 else 0

        # 7. Individual stock betas and volatilities
        stock_risks = []
        for sym in returns_dict:
            try:
                sym_vol = float(returns_dict[sym].std() * np.sqrt(252))
                sym_beta = 1.0
                if sp_returns is not None:
                    common = returns_dict[sym].index.intersection(sp_returns.index)
                    if len(common) > 20:
                        s_cov = float(np.cov(returns_dict[sym].loc[common], sp_returns.loc[common])[0][1])
                        sp_v = float(np.var(sp_returns.loc[common]))
                        sym_beta = s_cov / sp_v if sp_v > 0 else 1.0
                stock_risks.append({
                    'symbol': sym, 'weight': weights[sym] * 100,
                    'vol': sym_vol * 100, 'beta': sym_beta
                })
            except:
                pass

        stock_risks.sort(key=lambda x: x['vol'], reverse=True)

        # Build message
        msg = "⚠️ *PORTFOLIO RISK ANALYSIS*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Overall risk level
        if annual_vol < 0.15:
            risk_level = "🟢 Low Risk"
            risk_desc = "Below market volatility"
        elif annual_vol < 0.25:
            risk_level = "🟡 Moderate Risk"
            risk_desc = "Near market volatility"
        elif annual_vol < 0.40:
            risk_level = "🟠 High Risk"
            risk_desc = "Above market volatility"
        else:
            risk_level = "🔴 Very High Risk"
            risk_desc = "Significantly above market"

        msg += f"📊 *Risk Level:* {risk_level}\n"
        msg += f"  _{risk_desc}_\n\n"

        # Key metrics
        msg += "📈 *Key Metrics:*\n"
        msg += f"  📊 Annual Volatility: {annual_vol*100:.1f}% (S&P: {sp_annual_vol*100:.1f}%)\n"
        msg += f"  📉 Max Drawdown (1Y): {max_drawdown:.1f}%\n"
        msg += f"  🔄 Portfolio Beta: {portfolio_beta:.2f}\n"
        if portfolio_beta > 1.2:
            msg += f"    ↳ _More volatile than market_\n"
        elif portfolio_beta < 0.8:
            msg += f"    ↳ _Less volatile than market_\n"
        else:
            msg += f"    ↳ _Moves roughly with market_\n"
        msg += "\n"

        # VaR
        msg += "💸 *Value at Risk (daily):*\n"
        msg += f"  ⚠️ 95% VaR: ${abs(var_95):,.0f} (worst daily loss, 1-in-20 days)\n"
        msg += f"  🚨 99% VaR: ${abs(var_99):,.0f} (worst daily loss, 1-in-100 days)\n\n"

        # Risk-adjusted returns
        msg += "📊 *Risk-Adjusted Returns:*\n"
        msg += f"  📈 Annual Return: {annual_return*100:+.1f}%\n"
        sharpe_emoji = "🟢" if sharpe > 1 else "🟡" if sharpe > 0.5 else "🔴"
        msg += f"  {sharpe_emoji} Sharpe Ratio: {sharpe:.2f}"
        if sharpe > 1.5:
            msg += " (Excellent)\n"
        elif sharpe > 1:
            msg += " (Good)\n"
        elif sharpe > 0.5:
            msg += " (Moderate)\n"
        else:
            msg += " (Needs improvement)\n"
        sortino_emoji = "🟢" if sortino > 1.5 else "🟡" if sortino > 0.7 else "🔴"
        msg += f"  {sortino_emoji} Sortino Ratio: {sortino:.2f}\n\n"

        # Riskiest stocks
        msg += "🔥 *Riskiest Holdings:*\n"
        for s in stock_risks[:5]:
            beta_emoji = "🔴" if s['beta'] > 1.3 else "🟡" if s['beta'] > 1 else "🟢"
            msg += f"  {beta_emoji} *{s['symbol']}*: Vol {s['vol']:.0f}%, Beta {s['beta']:.2f} ({s['weight']:.0f}% of portfolio)\n"
        msg += "\n"

        # Stress test scenarios
        msg += "🧪 *Stress Test Scenarios:*\n"
        scenarios = [
            ('Market correction -10%', -0.10),
            ('Bear market -20%', -0.20),
            ('Crash like 2020 -34%', -0.34),
            ('2008-level crash -50%', -0.50),
        ]
        for scenario_name, shock in scenarios:
            loss = total_value * shock * portfolio_beta
            msg += f"  📉 {scenario_name}: *${loss:,.0f}*\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        msg += "\n_Based on 1-year historical data_"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


# /suggest - Smart Portfolio Rebalancing Suggestions
async def suggest(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Suggest stocks and dollar amounts to reduce portfolio risk and improve balance"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return

    await update.message.reply_text("🧠 *Analyzing your portfolio for rebalancing suggestions...*", parse_mode='Markdown')

    try:
        import numpy as np
        import pandas as pd

        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        free_cash = _usd_cash_total(portfolio_data)

        if not holdings:
            await update.message.reply_text("❌ Portfolio is empty!")
            return

        # Aggregate current holdings
        symbol_data = {}
        for h in holdings:
            s = h['symbol']
            if s not in symbol_data:
                symbol_data[s] = {'shares': 0, 'cost': 0}
            symbol_data[s]['shares'] += h['shares']
            symbol_data[s]['cost'] += h['total_cost']

        symbols = list(symbol_data.keys())

        # Candidate stabilizer stocks to evaluate
        # Mix of low-vol stocks, value, dividend, defensive, ETFs
        candidates = [
            'VOO', 'SCHD', 'VTI',   # Broad market / dividend ETFs
            'MSFT', 'AAPL', 'BRK-B', # Mega-cap stable
            'JNJ', 'PG', 'KO',       # Consumer defensive
            'LMT', 'RTX',            # Defense (stable)
            'COST', 'V',             # Quality growth
            'TLT', 'BND',            # Bond ETFs for low correlation
            'GLD',                    # Gold hedge
        ]
        # Remove any candidate already in portfolio
        candidates = [c for c in candidates if c not in symbol_data]

        # Download data for current holdings + S&P 500 + candidates
        all_syms = symbols + ['^GSPC'] + candidates
        data = await asyncio.to_thread(
            yf.download, all_syms, period='1y', group_by='ticker', progress=False, threads=True
        )

        # Extract current portfolio metrics
        returns_dict = {}
        current_values = {}
        total_value = 0

        for sym in symbols:
            try:
                closes = data[sym]['Close'].dropna()
                if len(closes) < 20:
                    continue
                price = float(closes.iloc[-1])
                value = price * symbol_data[sym]['shares']
                total_value += value
                returns_dict[sym] = closes.pct_change().dropna()
                current_values[sym] = {'value': value, 'price': price}
            except:
                pass

        if not returns_dict:
            await update.message.reply_text("❌ Not enough data for analysis!")
            return

        # S&P 500 returns
        try:
            sp_closes = data['^GSPC']['Close'].dropna()
            sp_returns = sp_closes.pct_change().dropna()
            sp_var = float(np.var(sp_returns))
        except:
            sp_returns = None
            sp_var = 1.0

        # Calculate current portfolio beta and volatility
        weights_current = {s: current_values[s]['value'] / total_value for s in returns_dict}
        returns_df = pd.DataFrame(returns_dict)
        portfolio_returns = sum(returns_df[sym].fillna(0) * weights_current[sym] for sym in returns_dict)
        current_vol = float(portfolio_returns.std() * np.sqrt(252))

        current_beta = 1.0
        if sp_returns is not None:
            common_idx = portfolio_returns.index.intersection(sp_returns.index)
            if len(common_idx) > 20:
                port_aligned = portfolio_returns.loc[common_idx]
                sp_aligned = sp_returns.loc[common_idx]
                cov_val = float(np.cov(port_aligned, sp_aligned)[0][1])
                current_beta = cov_val / sp_var if sp_var > 0 else 1.0

        # Per-stock betas for current holdings
        stock_betas = {}
        stock_vols = {}
        for sym in returns_dict:
            try:
                sym_returns = returns_dict[sym]
                stock_vols[sym] = float(sym_returns.std() * np.sqrt(252))
                if sp_returns is not None:
                    common = sym_returns.index.intersection(sp_returns.index)
                    if len(common) > 20:
                        s_cov = float(np.cov(sym_returns.loc[common], sp_returns.loc[common])[0][1])
                        stock_betas[sym] = s_cov / sp_var if sp_var > 0 else 1.0
                    else:
                        stock_betas[sym] = 1.0
                else:
                    stock_betas[sym] = 1.0
            except:
                stock_betas[sym] = 1.0
                stock_vols[sym] = 0.3

        # Evaluate candidate stocks
        candidate_info = {}
        for sym in candidates:
            try:
                closes = data[sym]['Close'].dropna()
                if len(closes) < 50:
                    continue
                price = float(closes.iloc[-1])
                rets = closes.pct_change().dropna()
                vol = float(rets.std() * np.sqrt(252))
                beta = 1.0
                if sp_returns is not None:
                    common = rets.index.intersection(sp_returns.index)
                    if len(common) > 20:
                        s_cov = float(np.cov(rets.loc[common], sp_returns.loc[common])[0][1])
                        beta = s_cov / sp_var if sp_var > 0 else 1.0

                # Annual return
                cumul = (1 + rets).cumprod()
                ann_ret = float(cumul.iloc[-1] ** (252 / len(cumul)) - 1)

                # Correlation with current portfolio
                common_port = rets.index.intersection(portfolio_returns.index)
                if len(common_port) > 20:
                    corr = float(np.corrcoef(rets.loc[common_port], portfolio_returns.loc[common_port])[0][1])
                else:
                    corr = 0.5

                candidate_info[sym] = {
                    'price': price, 'vol': vol, 'beta': beta,
                    'annual_return': ann_ret, 'corr_with_portfolio': corr
                }
            except:
                pass

        if not candidate_info:
            await update.message.reply_text("❌ Couldn't fetch candidate stock data!")
            return

        # ======= REBALANCING ALGORITHM =======
        # Target: beta ~1.0, vol < 20%
        TARGET_BETA = 1.0
        TARGET_VOL = 0.20

        # Score candidates: prefer low beta, low vol, low correlation with portfolio, decent return
        scored = []
        for sym, info in candidate_info.items():
            # Lower beta = better for reducing risk
            beta_score = max(0, (current_beta - info['beta']))  # how much it helps
            # Lower vol = better
            vol_score = max(0, (current_vol - info['vol']))
            # Lower correlation = more diversification benefit
            corr_score = max(0, (1 - info['corr_with_portfolio']))
            # Positive returns preferred
            ret_score = max(0, info['annual_return']) * 2

            # Composite score
            score = beta_score * 3 + vol_score * 2 + corr_score * 2 + ret_score
            scored.append((sym, info, score))

        scored.sort(key=lambda x: x[2], reverse=True)

        # Select top 5 candidates
        top_candidates = scored[:5]

        # Calculate how much NEW money is needed to reach target beta
        # Formula: (current_val * current_beta + new_val * new_beta) / (current_val + new_val) = target_beta
        # new_val = current_val * (current_beta - target_beta) / (target_beta - avg_new_beta)
        avg_cand_beta = np.mean([c[1]['beta'] for c in top_candidates])

        if current_beta > TARGET_BETA and avg_cand_beta < current_beta:
            total_new_needed = total_value * (current_beta - TARGET_BETA) / (TARGET_BETA - avg_cand_beta) if (TARGET_BETA - avg_cand_beta) != 0 else 0
            total_new_needed = max(0, total_new_needed)
        else:
            total_new_needed = total_value * 0.15  # Suggest 15% allocation even if beta is ok

        # Cap at a reasonable amount (not more than 100% of current portfolio)
        total_new_needed = min(total_new_needed, total_value * 1.0)

        # Distribute among top candidates (weighted by score)
        total_score = sum(c[2] for c in top_candidates) or 1
        allocations = []
        for sym, info, score in top_candidates:
            alloc_pct = score / total_score
            alloc_usd = total_new_needed * alloc_pct
            shares_to_buy = int(alloc_usd / info['price']) if info['price'] > 0 else 0
            actual_cost = shares_to_buy * info['price']
            allocations.append({
                'symbol': sym, 'price': info['price'], 'beta': info['beta'],
                'vol': info['vol'] * 100, 'annual_return': info['annual_return'] * 100,
                'corr': info['corr_with_portfolio'],
                'shares': shares_to_buy, 'cost': actual_cost, 'alloc_pct': alloc_pct * 100,
                'score': score
            })

        actual_total = sum(a['cost'] for a in allocations)

        # Calculate projected metrics after adding these stocks
        new_total_value = total_value + actual_total
        projected_beta = (total_value * current_beta + sum(a['cost'] * a['beta'] for a in allocations)) / new_total_value if new_total_value > 0 else current_beta
        # Approximate projected vol (simplified weighted average)
        projected_vol_approx = (total_value * current_vol + sum(a['cost'] * a['vol'] / 100 for a in allocations)) / new_total_value if new_total_value > 0 else current_vol

        # ======= BUILD MESSAGE =======
        msg = "🧠 *SMART REBALANCING SUGGESTIONS*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Current state
        msg += "📊 *Current Portfolio:*\n"
        msg += f"  💰 Value: ${total_value:,.0f}\n"
        msg += f"  📊 Beta: {current_beta:.2f}\n"
        msg += f"  📈 Volatility: {current_vol*100:.1f}%\n"
        risk_emoji = "🔴" if current_beta > 1.3 else "🟠" if current_beta > 1.1 else "🟡" if current_beta > 0.9 else "🟢"
        msg += f"  {risk_emoji} Risk: {'High' if current_beta > 1.3 else 'Above Avg' if current_beta > 1.1 else 'Moderate' if current_beta > 0.9 else 'Low'}\n\n"

        # Target
        msg += "🎯 *Target After Rebalancing:*\n"
        msg += f"  📊 Beta: {current_beta:.2f} → {projected_beta:.2f}\n"
        msg += f"  📈 Volatility: {current_vol*100:.1f}% → ~{projected_vol_approx*100:.1f}%\n"
        msg += f"  💵 New investment needed: *${actual_total:,.0f}*\n\n"

        # Recommendations
        msg += "🛒 *RECOMMENDED PURCHASES:*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n"
        for a in allocations:
            if a['shares'] == 0:
                continue
            beta_tag = "🟢" if a['beta'] < 0.8 else "🟡" if a['beta'] < 1.1 else "🟠"
            msg += f"\n{beta_tag} *{a['symbol']}*\n"
            msg += f"  📊 Beta: {a['beta']:.2f} | Vol: {a['vol']:.0f}% | Return: {a['annual_return']:+.0f}%\n"
            msg += f"  🛒 Buy *{a['shares']} shares* @ ${a['price']:.2f}\n"
            msg += f"  💵 Cost: *${a['cost']:,.0f}* ({a['alloc_pct']:.0f}% of new money)\n"

        msg += "\n━━━━━━━━━━━━━━━━━━━━\n"
        msg += f"💰 *Total to invest: ${actual_total:,.0f}*\n"
        if free_cash >= actual_total:
            msg += f"✅ You have ${free_cash:,.0f} cash — enough to cover this!\n"
        elif free_cash > 0:
            msg += f"⚠️ You have ${free_cash:,.0f} cash — need ${actual_total - free_cash:,.0f} more\n"
        else:
            msg += f"⚠️ You need to deposit ${actual_total:,.0f}\n"

        # Summary of what changes
        msg += f"\n📈 *After these purchases:*\n"
        msg += f"  📊 Portfolio Beta: {current_beta:.2f} → *{projected_beta:.2f}*\n"
        msg += f"  📈 Est. Volatility: {current_vol*100:.1f}% → *~{projected_vol_approx*100:.1f}%*\n"
        msg += f"  💰 Portfolio Value: ${total_value:,.0f} → *${new_total_value:,.0f}*\n"

        # Risk level improvement
        if projected_beta < 1.0:
            msg += f"  🟢 Risk Level: *Moderate/Conservative*\n"
        elif projected_beta < 1.1:
            msg += f"  🟡 Risk Level: *Moderate*\n"
        else:
            msg += f"  🟠 Risk Level: *Still above average*\n"

        # Highest risk stocks to consider trimming
        risky_stocks = [(sym, stock_betas.get(sym, 1), stock_vols.get(sym, 0.3) * 100, weights_current.get(sym, 0) * 100)
                        for sym in returns_dict if stock_betas.get(sym, 1) > 1.5]
        risky_stocks.sort(key=lambda x: x[1], reverse=True)

        if risky_stocks:
            msg += f"\n✂️ *Consider trimming these high-risk stocks:*\n"
            for sym, beta, vol, wt in risky_stocks[:3]:
                val = current_values.get(sym, {}).get('value', 0)
                # Suggest selling ~50% of high-beta positions
                sell_val = val * 0.5
                msg += f"  🔴 *{sym}* (Beta {beta:.2f}, Vol {vol:.0f}%) — sell ~${sell_val:,.0f}\n"
            trim_total = sum(current_values.get(s[0], {}).get('value', 0) * 0.5 for s in risky_stocks[:3])
            msg += f"  _Trimming these frees ~${trim_total:,.0f} to reinvest_\n"

        msg += f"\n🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        msg += "\n_Based on 1Y data. Not financial advice._"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _hourly_backup_task(app):
    """Background task to backup data files every 12 hours"""
    
    # Wait 5 minutes for bot to be ready
    await asyncio.sleep(300)
    
    print("💾 Auto-backup task started - will backup every 6 hours")
    
    # Do an initial backup right away
    try:
        result = backup_manager.backup_data_only("hourly")
        if result["success"]:
            print(f"💾 Initial backup: {result['files_count']} files saved")
        else:
            print(f"⚠️ Initial backup had errors: {result['errors']}")
    except Exception as e:
        print(f"Initial backup error: {e}")
    
    while True:
        try:
            # Sleep for 6 hours (21600 seconds)
            await asyncio.sleep(21600)
            
            # Backup data files
            result = backup_manager.backup_data_only("hourly")
            
            if result["success"]:
                print(f"💾 6h backup: {result['files_count']} files saved to {result['folder']}")
            else:
                print(f"⚠️ 6h backup had errors: {result['errors']}")
                
        except Exception as e:
            print(f"6h backup error: {e}")
            await asyncio.sleep(60)


async def backup_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show backup status and options"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    try:
        # Get backup summary
        summary = backup_manager.get_backup_summary()
        backups = backup_manager.list_backups()
        
        msg = "💾 *BACKUP STATUS*\n"
        msg += "━" * 20 + "\n\n"
        
        msg += f"⏰ *Auto Backups (6h):* {summary['hourly_count']}\n"
        msg += f"🔧 *Full Backups:* {summary['manual_count']}\n"
        msg += f"📦 *Total Size:* {summary['total_size_mb']} MB\n\n"
        
        if summary["latest_hourly"]:
            created = summary["latest_hourly"]["created"][:19].replace("T", " ")
            msg += f"📍 *Latest Auto (6h):*\n"
            msg += f"   {created}\n"
            msg += f"   ({summary['latest_hourly']['files']} files)\n\n"
        
        if summary["latest_manual"]:
            created = summary["latest_manual"]["created"][:19].replace("T", " ")
            msg += f"📍 *Latest Full:*\n"
            msg += f"   {summary['latest_manual']['name']}\n"
            msg += f"   {created}\n"
            msg += f"   ({summary['latest_manual']['size_mb']} MB)\n\n"
        
        # List recent manual backups
        if backups["manual"]:
            msg += "📋 *Available Backups:*\n"
            for i, b in enumerate(backups["manual"][:5]):
                msg += f"  {i+1}. {b['name'][:25]}... ({b['size_mb']}MB)\n"
        
        # Backup file names contain underscores, which Markdown reads as the start
        # of italics and never finds the end of; the helper retries as plain text.
        await _planner_reply(update, msg)

        # Show action buttons
        keyboard = [
            [
                InlineKeyboardButton("💾 Backup Now", callback_data="backup_now"),
                InlineKeyboardButton("📦 Full Backup", callback_data="backup_full"),
            ],
            [
                InlineKeyboardButton("📋 List All", callback_data="backup_list"),
                InlineKeyboardButton("🔄 Restore Latest", callback_data="backup_restore_latest"),
            ],
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        await update.message.reply_text(
            "⚙️ *Backup Options:*",
            reply_markup=reply_markup,
            parse_mode='Markdown'
        )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def handle_backup_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle backup-related callbacks"""
    query = update.callback_query
    await query.answer()
    
    data = query.data
    
    if data == "backup_now":
        # Quick data backup
        await query.edit_message_text("💾 Creating data backup...")
        result = backup_manager.backup_data_only("manual")
        
        if result["success"]:
            msg = f"✅ *Backup Complete!*\n\n"
            msg += f"📁 Saved {result['files_count']} files\n"
            msg += f"📍 Location:\n`{result['folder']}`"
        else:
            msg = f"⚠️ *Backup had errors:*\n"
            for err in result["errors"]:
                msg += f"  - {err}\n"
        
        await query.edit_message_text(msg, parse_mode='Markdown')
    
    elif data == "backup_full":
        # Full backup (data + code)
        await query.edit_message_text("📦 Creating full backup (data + code)...\nThis may take a moment...")
        result = backup_manager.backup_full("telegram_command")
        
        if result["success"]:
            msg = f"✅ *Full Backup Complete!*\n\n"
            msg += f"📁 Backed up {result['files_count']} items\n"
            msg += f"📍 ZIP file:\n`{result['zip_path']}`"
        else:
            msg = f"⚠️ *Backup had errors:*\n"
            for err in result["errors"][:5]:
                msg += f"  - {err}\n"
        
        await query.edit_message_text(msg, parse_mode='Markdown')
    
    elif data == "backup_list":
        # List all backups
        backups = backup_manager.list_backups()
        
        msg = "📋 *All Backups:*\n\n"
        
        if backups["manual"]:
            msg += "*Manual (Full):*\n"
            for b in backups["manual"][:10]:
                created = b["created"][:16].replace("T", " ")
                msg += f"  `{b['name'][:20]}` - {b['size_mb']}MB\n"
        
        if backups["hourly"]:
            msg += "\n*Auto 6h (Data Only):*\n"
            for b in backups["hourly"][:10]:
                msg += f"  `{b['name'][:25]}` ({b['files']} files)\n"
        
        await query.edit_message_text(msg, parse_mode='Markdown')
    
    elif data == "backup_restore_latest":
        # Show restore confirmation
        backups = backup_manager.list_backups()
        
        if backups["manual"]:
            latest = backups["manual"][0]
            msg = f"🔄 *Restore from:*\n`{latest['name']}`\n\n"
            msg += "⚠️ This will restore DATA FILES ONLY.\n"
            msg += "Your portfolios, alerts, and settings will be restored.\n\n"
            msg += "Code files will NOT be changed."
            
            keyboard = [
                [
                    InlineKeyboardButton("✅ Yes, Restore Data", callback_data=f"backup_confirm_restore:{latest['name']}"),
                    InlineKeyboardButton("❌ Cancel", callback_data="backup_cancel"),
                ]
            ]
            reply_markup = InlineKeyboardMarkup(keyboard)
            await query.edit_message_text(msg, parse_mode='Markdown', reply_markup=reply_markup)
        else:
            await query.edit_message_text("❌ No backups available to restore")
    
    elif data.startswith("backup_confirm_restore:"):
        # Actually restore
        backup_name = data.split(":", 1)[1]
        backup_path = backup_manager.BACKUP_DIR / "manual" / backup_name
        
        await query.edit_message_text("🔄 Restoring data...")
        result = backup_manager.restore_backup(backup_path, restore_data=True, restore_code=False)
        
        if result["success"]:
            msg = f"✅ *Restore Complete!*\n\n"
            msg += f"📁 Restored {len(result['restored'])} files:\n"
            for item in result["restored"][:10]:
                msg += f"  - {item}\n"
            msg += "\n⚠️ Restart the bot for changes to take effect."
        else:
            msg = f"❌ *Restore had errors:*\n"
            for err in result["errors"]:
                msg += f"  - {err}\n"
        
        await query.edit_message_text(msg, parse_mode='Markdown')
    
    elif data == "backup_cancel":
        await query.edit_message_text("Cancelled.")


# ============= REMINDER SYSTEM =============

# Conversation states for reminder
REMINDER_TYPE = 100
REMINDER_MESSAGE = 101
REMINDER_DATE = 102
REMINDER_TIMES = 103

# Store for pending reminder creation
pending_reminders = {}

def _get_reminders_file():
    """Get path to reminders storage file"""
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "reminders.json")

def _get_reminder_log_file():
    """Get path to reminder log file"""
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "reminder_log.json")

def _load_reminders():
    """Load reminders from file"""
    file_path = _get_reminders_file()
    if os.path.exists(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            pass
    return {"reminders": []}

def _save_reminders(data):
    """Save reminders to file"""
    with open(_get_reminders_file(), 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

def _load_reminder_log():
    """Load reminder log from file"""
    file_path = _get_reminder_log_file()
    if os.path.exists(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            pass
    return {"log": []}

def _save_reminder_log(data):
    """Save reminder log to file"""
    with open(_get_reminder_log_file(), 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

def _add_to_reminder_log(reminder_type, message, scheduled_date, scheduled_time, sent_at):
    """Add a sent reminder to the log"""
    log_data = _load_reminder_log()
    log_data["log"].append({
        "type": reminder_type,
        "message": message,
        "scheduled_date": scheduled_date,
        "scheduled_time": scheduled_time,
        "sent_at": sent_at
    })
    # Keep last 100 entries
    if len(log_data["log"]) > 100:
        log_data["log"] = log_data["log"][-100:]
    _save_reminder_log(log_data)


