    if message_text.lower() in ['cancel', '/cancel', 'ביטול']:
        await update.message.reply_text("❌ Reminder creation cancelled.")
        if user_id in pending_reminders:
            del pending_reminders[user_id]
        return ConversationHandler.END
    
    if user_id not in pending_reminders:
        pending_reminders[user_id] = {}
    
    pending_reminders[user_id]["message"] = message_text
    
