            InlineKeyboardButton(f"{'✓ ' if '13:00' in times else ''}1:00 PM", callback_data="rtime:13:00"),
            InlineKeyboardButton(f"{'✓ ' if '14:00' in times else ''}2:00 PM", callback_data="rtime:14:00"),
