async def reminders_list(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """List all scheduled reminders"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    data = _load_reminders()
    reminders = data.get("reminders", [])
    
    # Filter out past reminders
    import pytz
    israel_tz = pytz.timezone('Asia/Jerusalem')
    now = datetime.now(israel_tz)
    today = now.strftime("%Y-%m-%d")
    
    active_reminders = []
    for r in reminders:
        # Check if reminder date is in the future or today with unsent times
        if r["date"] > today:
            active_reminders.append(r)
        elif r["date"] == today:
            # Check if any times haven't been sent yet
            unsent_times = [t for t in r["times"] if t not in r.get("times_sent", [])]
            current_time = now.strftime("%H:%M")
            future_times = [t for t in unsent_times if t > current_time]
            if future_times:
                active_reminders.append(r)
    
    if not active_reminders:
        await update.message.reply_text(
            "📋 *Scheduled Reminders*\n\n"
            "No active reminders.\n\n"
            "Use /remindme to create one!",
            parse_mode='Markdown'
        )
        return
    
    msg = "📋 *Scheduled Reminders*\n"
    msg += "━" * 20 + "\n\n"
    
    type_emojis = {"notification": "🔔", "update": "📢", "reminder": "⏰"}
    
    for r in active_reminders[:10]:  # Show max 10
        emoji = type_emojis.get(r["type"], "📝")
        times_display = ", ".join([_format_time_12h(t) for t in r["times"]])
        
        msg += f"{emoji} *{r['type'].title()}*\n"
        msg += f"📅 {r['date']}\n"
        msg += f"⏰ {times_display}\n"
        msg += f"📝 {r['message'][:50]}{'...' if len(r['message']) > 50 else ''}\n"
        msg += f"🆔 ID: {r['id']}\n\n"
    
    msg += "_Use /reminderlog to see sent reminders_"
    
    await update.message.reply_text(msg, parse_mode='Markdown')


async def reminder_log(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the history of sent reminders"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    log_data = _load_reminder_log()
    log = log_data.get("log", [])
    
    if not log:
        await update.message.reply_text(
            "📜 *Reminder History*\n\n"
            "No reminders have been sent yet.",
            parse_mode='Markdown'
        )
        return
    
    # Show most recent first
    log = list(reversed(log[-20:]))  # Last 20, newest first
    
    msg = "📜 *Reminder History*\n"
    msg += "━" * 20 + "\n\n"
    
    type_emojis = {"notification": "🔔", "update": "📢", "reminder": "⏰"}
    
    for entry in log:
        emoji = type_emojis.get(entry["type"], "📝")
        msg += f"{emoji} *{entry['type'].title()}*\n"
        msg += f"📅 Scheduled: {entry['scheduled_date']} {_format_time_12h(entry['scheduled_time'])}\n"
        msg += f"📤 Sent: {entry['sent_at']}\n"
        msg += f"📝 {entry['message'][:40]}{'...' if len(entry['message']) > 40 else ''}\n\n"
    
    await update.message.reply_text(msg, parse_mode='Markdown')


async def _reminder_check_task(app):
    """Background task to check and send reminders"""
    import pytz
    
    # Wait for bot to be ready
    await asyncio.sleep(60)
    
    israel_tz = pytz.timezone('Asia/Jerusalem')
    
    print("⏰ Reminder check task started")
    
    while True:
        try:
            now = datetime.now(israel_tz)
            current_date = now.strftime("%Y-%m-%d")
            current_time = now.strftime("%H:%M")
            
            data = _load_reminders()
            reminders = data.get("reminders", [])
            modified = False
            
            for reminder in reminders:
                # Check if it's the right date
                if reminder["date"] != current_date:
                    continue
                
                # Check each time
                for scheduled_time in reminder["times"]:
                    # Check if already sent
                    if scheduled_time in reminder.get("times_sent", []):
                        continue
                    
                    # Check if it's time (within 1 minute window)
                    if scheduled_time <= current_time and scheduled_time > (now - timedelta(minutes=2)).strftime("%H:%M"):
                        # Send the reminder
                        type_emojis = {"notification": "🔔", "update": "📢", "reminder": "⏰"}
                        emoji = type_emojis.get(reminder["type"], "📝")
                        
                        msg = f"{emoji} *{reminder['type'].upper()}*\n"
                        msg += "━" * 15 + "\n\n"
                        msg += f"{reminder['message']}\n\n"
                        msg += f"_Scheduled for {_format_time_12h(scheduled_time)}_"
                        
                        try:
                            await app.bot.send_message(
                                chat_id=TELEGRAM_CHAT_ID,
                                text=msg,
                                parse_mode='Markdown'
                            )
                            print(f"⏰ Sent reminder: {reminder['type']} at {current_time}")
                            
                            # Mark as sent
                            if "times_sent" not in reminder:
                                reminder["times_sent"] = []
                            reminder["times_sent"].append(scheduled_time)
                            modified = True
                            
                            # Add to log
                            _add_to_reminder_log(
                                reminder["type"],
                                reminder["message"],
                                reminder["date"],
                                scheduled_time,
                                now.strftime("%Y-%m-%d %H:%M:%S")
                            )
                        except Exception as e:
                            print(f"Error sending reminder: {e}")
            
            # Save if modified
            if modified:
                _save_reminders(data)
                
                # Clean up old reminders (older than today with all times sent)
                data["reminders"] = [
                    r for r in data["reminders"]
                    if r["date"] >= current_date or 
                    (r["date"] == current_date and len(r.get("times_sent", [])) < len(r["times"]))
                ]
                _save_reminders(data)
            
            # Check every 30 seconds
            await asyncio.sleep(30)
            
        except Exception as e:
            print(f"Reminder task error: {e}")
            await asyncio.sleep(60)


async def _daily_portfolio_log_task(app):
    """Background task to log portfolio value and send daily report at end of trading day"""
    import pytz
    
    # Wait for bot to be ready
    await asyncio.sleep(30)
    
    est = pytz.timezone('US/Eastern')
    
    # Check if we already sent today by looking at portfolio log
    def already_sent_today():
        try:
            portfolio_data = _load_portfolio()
            portfolio_log = portfolio_data.get('portfolio_log', [])
            if portfolio_log:
                last_log = portfolio_log[-1]
                last_date = last_log.get('date', '')
                today = datetime.now(est).strftime('%Y-%m-%d')
                sent_flag = last_log.get('notification_sent', False)
                return last_date == today and sent_flag
        except:
            pass
        return False
    
    def mark_sent_today():
        try:
            portfolio_data = _load_portfolio()
            portfolio_log = portfolio_data.get('portfolio_log', [])
            if portfolio_log:
                portfolio_log[-1]['notification_sent'] = True
                _save_portfolio(portfolio_data)
        except:
            pass
    
    print("📊 Daily portfolio report task started - will send at 4:15 PM EST on weekdays")
    
    while True:
        try:
            now = datetime.now(est)
            
            # Run at 4:15 PM EST (15 minutes after market close) on weekdays
            # Check between 4:15 and 4:20 to have a 5-minute window
            if now.hour == 16 and 15 <= now.minute <= 20:
                # Only on weekdays
                if now.weekday() < 5:  # Monday = 0, Friday = 4
                    if not already_sent_today():
                        log_entry = _save_daily_portfolio_log()
                        print(f"📊 Portfolio log saved: ${log_entry['value']:,.2f} ({log_entry['date']})")
                        
                        # Send daily report to Telegram
                        await _send_daily_portfolio_report(app, log_entry)
                        mark_sent_today()
                        print(f"✅ Daily report sent at {now.strftime('%H:%M')} EST")
            
            # Sleep for 30 seconds to check more frequently
            await asyncio.sleep(30)
            
        except Exception as e:
            print(f"Portfolio log error: {e}")
            await asyncio.sleep(60)


async def _send_daily_portfolio_report(app, log_entry):
    """Send daily portfolio performance report to Telegram"""
    try:
        value = log_entry['value']
        prev_value = log_entry.get('prev_value', 0)
        true_pl = log_entry.get('true_daily_pl', 0)
        true_pl_pct = log_entry.get('true_daily_pl_pct', 0)
        movements = log_entry.get('movements', [])
        stocks = log_entry.get('stocks', {})
        
        # Build message
        message = "🔔 *DAILY PORTFOLIO REPORT*\n"
        message += f"📅 {log_entry['date']}\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        # Portfolio value
        message += f"💰 *Portfolio Value: ${value:,.2f}*\n"
        
        # Yesterday's value
        if prev_value > 0:
            message += f"📊 Yesterday: ${prev_value:,.2f}\n"
        
        # Today's P/L (true: open-based for held, buy-price-based for new buys, open-to-sell for sells)
        if true_pl != 0 or prev_value > 0:
            emoji = "📈" if true_pl >= 0 else "📉"
            message += f"\n{emoji} *Today's P/L: ${true_pl:+,.2f} ({true_pl_pct:+.2f}%)*\n"
        
        # Top gainers/losers from stocks
        if stocks:
            stock_changes = []
            # Handle both list and dict formats
            if isinstance(stocks, dict):
                for symbol, data in stocks.items():
                    if isinstance(data, dict):
                        day_change = data.get('day_change_pct', 0)
                        stock_changes.append((symbol, day_change, data.get('value', 0)))
            elif isinstance(stocks, list):
                for item in stocks:
                    if isinstance(item, dict):
                        symbol = item.get('symbol', 'N/A')
                        day_change = item.get('day_change_pct', 0)
                        stock_changes.append((symbol, day_change, item.get('value', 0)))
            
            if stock_changes:
                stock_changes.sort(key=lambda x: x[1], reverse=True)
                
                if len(stock_changes) >= 2:
                    message += "\n🟢 *Top Gainers:*\n"
                    for i, (sym, chg, val) in enumerate(stock_changes[:3]):
                        message += f"   {i+1}. {sym}: {chg:+.2f}%\n"
                    
                    message += "\n🔴 *Top Losers:*\n"
                    worst_3 = stock_changes[-3:] if len(stock_changes) >= 3 else stock_changes[-len(stock_changes):]
                    worst_3.reverse()  # Show worst first
                    for i, (sym, chg, val) in enumerate(worst_3):
                        message += f"   {i+1}. {sym}: {chg:+.2f}%\n"
        
        # Show movements if any
        if movements:
            message += "\n📋 *Today's Trades:*\n"
            for m in movements:
                if m['type'] == 'BUY':
                    message += f"   ➕ BUY: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f}\n"
                else:
                    message += f"   ➖ SELL: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f}\n"
        
        message += "\n━━━━━━━━━━━━━━━━━━━━\n"
        message += "_Market closed. See you tomorrow!_ 🔔"
        
        # Send to user
        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=message,
            parse_mode='Markdown'
        )
        print(f"✅ Daily portfolio report sent to Telegram")
        
    except Exception as e:
        print(f"⚠️ Error sending daily report: {e}")


