async def monthlyreport(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Manually trigger monthly portfolio performance report. Use /monthlyreport or /monthlyreport 2026-01"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("📅 Generating monthly report...")

    try:
        from calendar import monthrange

        portfolio_data = _load_portfolio()
        portfolio_log = portfolio_data.get('portfolio_log', [])
        sold_history = portfolio_data.get('sold_history', [])
        holdings = portfolio_data.get('holdings', [])

        # Determine which month to report on
        now = datetime.now()
        if context.args and len(context.args) >= 1:
            # User specified month: /monthlyreport 2026-01
            target_month = context.args[0]
            try:
                dt = datetime.strptime(target_month, '%Y-%m')
                report_year = dt.year
                report_month = dt.month
            except ValueError:
                await update.message.reply_text("❌ Invalid format. Use: /monthlyreport 2026-01")
                return
        else:
            # Default: previous month
            if now.month == 1:
                report_year = now.year - 1
                report_month = 12
            else:
                report_year = now.year
                report_month = now.month - 1

        month_str = f"{report_year}-{report_month:02d}"
        month_name = datetime(report_year, report_month, 1).strftime('%B %Y')

        # Get logs from the target month
        month_logs = [l for l in portfolio_log if l['date'].startswith(month_str)]

        # Find start value: last log before the month
        logs_before = [l for l in portfolio_log if l['date'] < f"{month_str}-01"]
        start_value = logs_before[-1]['value'] if logs_before else (month_logs[0]['value'] if month_logs else 0)

        # End value: last log entry of the month
        end_value = month_logs[-1]['value'] if month_logs else start_value

        if start_value == 0 and end_value == 0:
            await update.message.reply_text(f"📅 No portfolio data found for {month_name}.")
            return

        # Value change
        value_change = end_value - start_value

        # Realized P/L from stocks sold during the month
        month_realized = 0
        month_sold_stocks = []
        for s in sold_history:
            sell_date = s.get('sell_date', '')
            if sell_date.startswith(month_str):
                pl = s.get('profit_loss', 0)
                month_realized += pl
                month_sold_stocks.append(s)

        # Daily P/L sum 
        daily_pl_sum = sum(l.get('true_daily_pl', 0) for l in month_logs if l.get('true_daily_pl') is not None)

        # Calculate current unrealized P/L
        unrealized_pl = 0
        total_cost = 0
        total_market_value = 0
        try:
            symbols = [h['symbol'] for h in holdings]
            if symbols:
                batch = await asyncio.to_thread(
                    yf.download, symbols, period='1d', group_by='ticker', progress=False, threads=True
                )
                for h in holdings:
                    sym = h['symbol']
                    shares = h['shares']
                    cost = h.get('total_cost', shares * h.get('purchase_price', 0))
                    total_cost += cost
                    try:
                        if batch is not None and not batch.empty:
                            if len(symbols) == 1:
                                try:
                                    sh = batch[sym]
                                except (KeyError, TypeError):
                                    sh = batch
                            else:
                                sh = batch[sym]
                            if sh is not None and not sh.empty and 'Close' in sh.columns:
                                price = float(sh['Close'].dropna().iloc[-1])
                                val = shares * price
                                total_market_value += val
                            else:
                                total_market_value += cost
                        else:
                            total_market_value += cost
                    except:
                        total_market_value += cost
                unrealized_pl = total_market_value - total_cost
        except:
            pass

        # All-time realized P/L
        all_time_realized = sum(s.get('profit_loss', 0) for s in sold_history)
        total_invested_ever = total_cost + sum(s.get('cost_basis', 0) for s in sold_history)
        total_pl = unrealized_pl + all_time_realized
        total_pl_pct = (total_pl / total_invested_ever * 100) if total_invested_ever > 0 else 0

        # Count trading days
        trading_days = len(month_logs)

        # Trades during the month
        month_buys = []
        month_sells = []
        for log in month_logs:
            for m in log.get('movements', []):
                if m['type'] == 'BUY':
                    month_buys.append(m)
                else:
                    month_sells.append(m)

        # Build message
        msg = f"📅 *MONTHLY PORTFOLIO REPORT*\n"
        msg += f"📆 *{month_name}*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━\n\n"

        # Value summary
        msg += f"💰 *Start of Month:* ${start_value:,.2f}\n"
        msg += f"💰 *End of Month:* ${end_value:,.2f}\n"
        chg_emoji = "📈" if value_change >= 0 else "📉"
        chg_pct = (value_change / start_value * 100) if start_value > 0 else 0
        msg += f"{chg_emoji} *Value Change:* ${value_change:+,.2f} ({chg_pct:+.1f}%)\n\n"

        # Month's realized P/L
        if month_sold_stocks:
            real_emoji = "🟢" if month_realized >= 0 else "🔴"
            msg += f"📤 *Realized P/L ({len(month_sold_stocks)} sales):* {real_emoji} ${month_realized:+,.2f}\n"
            for s in month_sold_stocks:
                s_emoji = "🟢" if s['profit_loss'] >= 0 else "🔴"
                msg += f"   {s_emoji} {s['symbol']} ({s['shares']:.0f}) ${s['profit_loss']:+,.2f} ({s.get('profit_pct', 0):+.1f}%)\n"
            msg += "\n"

        # Trading activity
        if month_buys or month_sells:
            msg += f"📋 *Trades:* {len(month_buys)} buys, {len(month_sells)} sells\n"
            total_bought = sum(m['total'] for m in month_buys)
            total_sold_amount = sum(m['total'] for m in month_sells)
            if total_bought > 0:
                msg += f"   ➕ Total Bought: ${total_bought:,.2f}\n"
            if total_sold_amount > 0:
                msg += f"   ➖ Total Sold: ${total_sold_amount:,.2f}\n"
            msg += "\n"

        msg += f"📊 *Trading Days Logged:* {trading_days}\n\n"

        # Overall portfolio P/L (same as /portfolio)
        msg += "━━━━━━━━━━━━━━━━━━━━\n"
        msg += "*ALL-TIME PORTFOLIO P/L*\n"
        unreal_emoji = "🟢" if unrealized_pl >= 0 else "🔴"
        unreal_pct = (unrealized_pl / total_cost * 100) if total_cost > 0 else 0
        msg += f"{unreal_emoji} Unrealized: ${unrealized_pl:+,.2f} ({unreal_pct:+.1f}%)\n"
        real_all_emoji = "🟢" if all_time_realized >= 0 else "🔴"
        msg += f"{real_all_emoji} Realized: ${all_time_realized:+,.2f} ({len(sold_history)} trades)\n"
        total_emoji = "🟢" if total_pl >= 0 else "🔴"
        msg += f"{total_emoji} *Total P/L: ${total_pl:+,.2f} ({total_pl_pct:+.1f}%)*\n"

        await update.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def sectors(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Analyze portfolio sector exposure and diversification"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    await update.message.reply_text("🔍 Analyzing sector exposure...")
    
    try:
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        
        if not holdings:
            await update.message.reply_text("❌ No stocks in portfolio!")
            return
        
        # Define all major sectors for diversification check
        all_sectors = [
            "Technology", "Healthcare", "Financial Services", "Consumer Cyclical",
            "Consumer Defensive", "Industrials", "Energy", "Utilities",
            "Real Estate", "Basic Materials", "Communication Services"
        ]
        
        # Sector icons
        sector_icons = {
            "Technology": "💻",
            "Healthcare": "🏥",
            "Financial Services": "🏦",
            "Consumer Cyclical": "🛍️",
            "Consumer Defensive": "🛒",
            "Industrials": "🏭",
            "Energy": "⚡",
            "Utilities": "💡",
            "Real Estate": "🏠",
            "Basic Materials": "⛏️",
            "Communication Services": "📡",
            "Unknown": "❓"
        }
        
        # Collect sector data
        sector_values = {}
        total_value = 0
        stock_sectors = []
        
        for holding in holdings:
            symbol = holding['symbol']
            shares = holding['shares']
            
            try:
                ticker = yf.Ticker(symbol)
                info = ticker.info
                
                # Get current price
                price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
                if not price:
                    hist = ticker.history(period='1d')
                    if not hist.empty:
                        price = hist['Close'].iloc[-1]
                
                value = shares * price
                total_value += value
                
                # Get sector and industry
                sector = info.get('sector', 'Unknown')
                if not sector:
                    sector = 'Unknown'
                
                # Get industry for more specific categorization
                industry = info.get('industry', '')
                if not industry:
                    industry = 'General'
                
                stock_sectors.append({
                    'symbol': symbol,
                    'sector': sector,
                    'industry': industry,
                    'value': value
                })
                
                if sector not in sector_values:
                    sector_values[sector] = 0
                sector_values[sector] += value
                
            except Exception as e:
                print(f"Error getting sector for {symbol}: {e}")
                stock_sectors.append({
                    'symbol': symbol,
                    'sector': 'Unknown',
                    'industry': 'Unknown',
                    'value': 0
                })
        
        if total_value == 0:
            await update.message.reply_text("❌ Could not calculate portfolio value!")
            return
        
        # Calculate percentages and sort by exposure
        sector_percentages = []
        for sector, value in sector_values.items():
            pct = (value / total_value) * 100
            sector_percentages.append((sector, value, pct))
        
        sector_percentages.sort(key=lambda x: x[2], reverse=True)
        
        # Group stocks by sector with their industries
        stocks_by_sector = {}
        for stock in stock_sectors:
            sector = stock['sector']
            if sector not in stocks_by_sector:
                stocks_by_sector[sector] = []
            stocks_by_sector[sector].append({
                'symbol': stock['symbol'],
                'industry': stock['industry']
            })
        
        # Build message
        message = "📊 *PORTFOLIO SECTOR ANALYSIS*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        # Sector breakdown
        message += "🥧 *Sector Exposure:*\n\n"
        
        for sector, value, pct in sector_percentages:
            icon = sector_icons.get(sector, "❓")
            # Create visual bar
            bar_length = int(pct / 5)  # 20 chars = 100%
            bar = "█" * bar_length + "░" * (20 - bar_length)
            message += f"{icon} *{sector}*\n"
            message += f"   `{bar}` {pct:.1f}%\n"
            message += f"   ${value:,.0f}\n"
            # Show stocks in this sector with their industries
            sector_stocks = stocks_by_sector.get(sector, [])
            if sector_stocks:
                # Group by industry within sector
                industry_groups = {}
                for s in sector_stocks:
                    ind = s['industry']
                    if ind not in industry_groups:
                        industry_groups[ind] = []
                    industry_groups[ind].append(s['symbol'])
                
                for industry, symbols in industry_groups.items():
                    # Shorten industry name for display
                    short_industry = industry.replace(' - ', '/').replace('—', '-')
                    message += f"   • _{short_industry}_: {', '.join(symbols)}\n"
            message += "\n"
        
        # Diversification Analysis
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += "📈 *DIVERSIFICATION RATING*\n\n"
        
        # Calculate diversification score
        num_sectors = len([s for s in sector_values.keys() if s != 'Unknown'])
        max_exposure = max(pct for _, _, pct in sector_percentages) if sector_percentages else 0
        
        # Scoring criteria
        score = 0
        issues = []
        recommendations = []
        
        # 1. Number of sectors (max 30 points)
        if num_sectors >= 8:
            score += 30
        elif num_sectors >= 6:
            score += 25
        elif num_sectors >= 4:
            score += 15
        elif num_sectors >= 2:
            score += 10
        else:
            score += 5
            issues.append("⚠️ Too few sectors")
        
        # 2. Concentration risk (max 40 points)
        if max_exposure <= 25:
            score += 40
        elif max_exposure <= 35:
            score += 30
        elif max_exposure <= 50:
            score += 20
            issues.append(f"⚠️ High concentration in one sector ({max_exposure:.0f}%)")
        else:
            score += 10
            issues.append(f"🚨 Very high concentration risk ({max_exposure:.0f}%)")
        
        # 3. Balance across sectors (max 30 points)
        if num_sectors >= 2:
            avg_exposure = 100 / num_sectors
            variance = sum((pct - avg_exposure) ** 2 for _, _, pct in sector_percentages) / num_sectors
            std_dev = variance ** 0.5
            
            if std_dev <= 10:
                score += 30
            elif std_dev <= 15:
                score += 25
            elif std_dev <= 20:
                score += 15
            else:
                score += 5
                issues.append("⚠️ Uneven sector distribution")
        
        # Determine rating
        if score >= 85:
            rating = "🌟 EXCELLENT"
            rating_desc = "Your portfolio is well diversified!"
        elif score >= 70:
            rating = "✅ GOOD"
            rating_desc = "Good diversification with room for improvement."
        elif score >= 50:
            rating = "⚠️ MODERATE"
            rating_desc = "Consider adding more sectors for better protection."
        else:
            rating = "🚨 POOR"
            rating_desc = "High risk! Strongly consider diversifying."
        
        message += f"*Rating:* {rating} ({score}/100)\n"
        message += f"_{rating_desc}_\n\n"
        
        # Show issues
        if issues:
            message += "*Issues Found:*\n"
            for issue in issues:
                message += f"   {issue}\n"
            message += "\n"
        
        # Generate recommendations
        existing_sectors = set(sector_values.keys())
        missing_sectors = [s for s in all_sectors if s not in existing_sectors]
        
        # Core sectors everyone should have some exposure to
        core_sectors = ["Technology", "Healthcare", "Financial Services", "Consumer Defensive"]
        missing_core = [s for s in core_sectors if s not in existing_sectors]
        
        message += "━━━━━━━━━━━━━━━━━━━━\n"
        message += "💡 *RECOMMENDATIONS*\n\n"
        
        if max_exposure > 40:
            top_sector = sector_percentages[0][0]
            message += f"1️⃣ *Reduce {top_sector} exposure*\n"
            message += f"   Currently {max_exposure:.0f}%, aim for <30%\n\n"
        
        if missing_core:
            message += f"2️⃣ *Add core sectors:*\n"
            for s in missing_core[:3]:
                icon = sector_icons.get(s, "❓")
                message += f"   {icon} {s}\n"
            message += "\n"
        
        if missing_sectors and len(missing_sectors) > len(missing_core):
            other_missing = [s for s in missing_sectors if s not in missing_core][:3]
            if other_missing:
                message += f"3️⃣ *Consider adding:*\n"
                for s in other_missing:
                    icon = sector_icons.get(s, "❓")
                    message += f"   {icon} {s}\n"
                message += "\n"
        
        # Example stocks for missing sectors
        sector_examples = {
            "Technology": "AAPL, MSFT, NVDA",
            "Healthcare": "JNJ, UNH, PFE",
            "Financial Services": "JPM, BAC, V",
            "Consumer Cyclical": "AMZN, TSLA, HD",
            "Consumer Defensive": "PG, KO, WMT",
            "Industrials": "CAT, HON, UPS",
            "Energy": "XOM, CVX, COP",
            "Utilities": "NEE, DUK, SO",
            "Real Estate": "AMT, PLD, SPG",
            "Basic Materials": "LIN, APD, FCX",
            "Communication Services": "GOOGL, META, DIS"
        }
        
        if missing_core or (score < 70 and missing_sectors):
            message += "📝 *Stock Ideas:*\n"
            sectors_to_show = missing_core if missing_core else missing_sectors[:3]
            for s in sectors_to_show[:3]:
                if s in sector_examples:
                    message += f"   {s}: {sector_examples[s]}\n"
        
        message += "\n━━━━━━━━━━━━━━━━━━━━"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def portfoliolog(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """View portfolio daily log history"""
    try:
        portfolio_data = _load_portfolio()
        portfolio_log = portfolio_data.get('portfolio_log', [])
        
        if not portfolio_log:
            await update.message.reply_text(
                "📊 *Portfolio Log*\n\n"
                "No logs yet. Log is updated daily at 4:30 PM EST.\n"
                "Use /logportfolio to manually log now.",
                parse_mode='Markdown'
            )
            return
        
        message = "📊 *PORTFOLIO DAILY LOG*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        # Show last 14 days
        for log in reversed(portfolio_log[-14:]):
            date = log['date']
            value = log['value']
            prev_value = log.get('prev_value', 0)
            movements = log.get('movements', [])
            market_profit = log.get('market_profit', 0)
            
            message += f"📅 *{date}*\n"
            
            # Get stored values or calculate
            total_bought = log.get('total_bought', sum(m['total'] for m in movements if m['type'] == 'BUY'))
            total_sold = log.get('total_sold', sum(m['total'] for m in movements if m['type'] == 'SELL'))
            
            if prev_value > 0:
                # Show starting value (previous day)
                message += f"   📊 Start: ${prev_value:,.2f}\n"
                
                # Show movements with their $ impact (these are NOT profit)
                for m in movements:
                    if m['type'] == 'BUY':
                        message += f"   ➕ BUY: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f} (+${m['total']:,.2f})\n"
                    else:
                        message += f"   ➖ SELL: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f} (-${m['total']:,.2f})\n"
                
                # Show TRUE market profit (not including buys/sells)
                if not market_profit:
                    net_movement = total_bought - total_sold
                    market_profit = value - prev_value - net_movement
                
                market_pct = (market_profit / prev_value * 100) if prev_value > 0 else 0
                
                if market_profit >= 0:
                    message += f"   📈 *Profit: ${market_profit:+,.2f} ({market_pct:+.1f}%)*\n"
                else:
                    message += f"   📉 *Loss: ${market_profit:+,.2f} ({market_pct:+.1f}%)*\n"
                
                message += f"   💰 End: ${value:,.2f}\n"
            else:
                # First entry - no previous value
                message += f"   💰 Value: ${value:,.2f}\n"
                for m in movements:
                    message += f"   ➕ {m['type']}: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f}\n"
            
            message += "\n"
        
        # Summary - calculate total profit
        if len(portfolio_log) >= 2:
            # Sum all daily P/L (prefer true_daily_pl, fallback to market_profit)
            total_market_profit = sum(
                log.get('true_daily_pl', log.get('market_profit', 0)) 
                for log in portfolio_log
            )
            total_cash_added = sum(log.get('net_cash_flow', 0) for log in portfolio_log)
            
            first_value = portfolio_log[0]['value']
            last_value = portfolio_log[-1]['value']
            
            message += "━━━━━━━━━━━━━━━━━━━━\n"
            message += f"📊 *Summary since {portfolio_log[0]['date']}:*\n"
            
            profit_emoji = "📈" if total_market_profit >= 0 else "📉"
            message += f"{profit_emoji} *Market Profit: ${total_market_profit:+,.2f}*\n"
            
            if total_cash_added != 0:
                cash_emoji = "➕" if total_cash_added > 0 else "➖"
                message += f"{cash_emoji} Net Invested: ${total_cash_added:+,.2f}\n"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def logportfolio(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Manually log current portfolio value"""
    try:
        log_entry = _save_daily_portfolio_log()
        
        movements_text = ""
        if log_entry.get('movements'):
            movements_text = "\n📋 *Today's Movements:*\n"
            for m in log_entry['movements']:
                if m['type'] == 'BUY':
                    movements_text += f"   ➕ BUY: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f} (+${m['total']:,.2f})\n"
                else:
                    movements_text += f"   ➖ SELL: {m['symbol']} {m['shares']:.0f} @ ${m['price']:.2f} (-${m['total']:,.2f})\n"
        
        profit_text = ""
        if log_entry.get('prev_value', 0) > 0:
            true_pl = log_entry.get('true_daily_pl', log_entry.get('market_profit', 0))
            true_pl_pct = log_entry.get('true_daily_pl_pct', log_entry.get('market_profit_pct', 0))
            if not true_pl_pct and log_entry.get('prev_value', 0) > 0:
                true_pl_pct = (true_pl / log_entry['prev_value'] * 100)
            
            if true_pl >= 0:
                profit_text = f"\n📈 *Today's P/L: ${true_pl:+,.2f} ({true_pl_pct:+.1f}%)*"
            else:
                profit_text = f"\n📉 *Today's P/L: ${true_pl:+,.2f} ({true_pl_pct:+.1f}%)*"
            profit_text += "\n_(from open prices)_"
        
        await update.message.reply_text(
            f"✅ *Portfolio Logged!*\n\n"
            f"📅 Date: {log_entry['date']}\n"
            f"📊 Previous: ${log_entry.get('prev_value', 0):,.2f}\n"
            f"💰 Current: ${log_entry['value']:,.2f}"
            f"{movements_text}"
            f"{profit_text}\n\n"
            f"Use /portfoliolog to view history",
            parse_mode='Markdown'
        )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def removeholding(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove a stock from portfolio (just deletes, no cash adjustment)"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'removeholding'
        await update.message.reply_text("➖ Which stock to remove from portfolio? Send the symbol:")
        return
    
    symbol = context.args[0].upper()
    await _do_removeholding(update, symbol)


async def _do_removeholding(update: Update, symbol: str):
    """Execute removing holding from portfolio (no cash adjustment)"""
    try:
        portfolio_data = _load_portfolio()
        
        # Find and remove the holding
        found = False
        for i, h in enumerate(portfolio_data['holdings']):
            if h['symbol'] == symbol:
                del portfolio_data['holdings'][i]
                found = True
                break
        
        if not found:
            await update.message.reply_text(f"ℹ️ {symbol} is not in your portfolio")
            return
        
        _save_portfolio(portfolio_data)
        await update.message.reply_text(f"✅ Removed *{symbol}* from portfolio!\n\n_Note: Use /sell to sell a stock and add proceeds to cash._", parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def sell(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Sell stock from portfolio - interactive step by step"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    user_id = update.effective_user.id
    
    # Start interactive flow
    pending_commands[user_id] = 'sell_symbol'
    await update.message.reply_text(
        "💰 *Sell Stock*\n\n"
        "What stock do you want to sell?\n"
        "Send the symbol (e.g. AAPL):",
        parse_mode='Markdown'
    )


async def _do_sell_final(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Execute the sell after gathering all info"""
    try:
        data = context.user_data.get('sell', {})
        symbol = data['symbol']
        shares_to_sell = data['shares']
        sell_price = data['price']
        sell_commission = data.get('commission', 0)
        
        portfolio_data = _load_portfolio()
        
        # Find the holding
        holding = None
        holding_idx = None
        for i, h in enumerate(portfolio_data['holdings']):
            if h['symbol'] == symbol:
                holding = h
                holding_idx = i
                break
        
        if not holding:
            await update.message.reply_text(f"ℹ️ {symbol} is not in your portfolio")
            return
        
        total_shares = holding['shares']
        total_cost = holding['total_cost']
        purchase_price = holding.get('purchase_price', 0)
        purchase_date = holding.get('purchase_date', 'Unknown')
        buy_commission_total = holding.get('commission', 0)
        
        # Calculate proportional buy commission for shares being sold
        buy_commission = (buy_commission_total / total_shares) * shares_to_sell if total_shares > 0 else 0
        total_commission = buy_commission + sell_commission
        
        if shares_to_sell > total_shares:
            await update.message.reply_text(f"❌ You only have {total_shares} shares of {symbol}")
            return

        # Which broker the shares come out of: the one holding them, or ask if both do.
        try:
            broker_split, broker = brk.after_sell(holding, shares_to_sell, data.get('broker'))
        except brk.NeedBroker as need:
            have = need.args[0]
            keyboard = InlineKeyboardMarkup([
                [InlineKeyboardButton(f"{brk.SHORT[b]} ({have[b]:g})", callback_data=f"sellbrk:{b}")
                 for b in brk.BROKERS],
                [InlineKeyboardButton("❌ Cancel", callback_data="sellbrk:cancel")]])
            await update.message.reply_text(
                f"🏛 *{symbol}* מוחזקת גם ב-Interactive וגם בבנק — מאיפה מכרת?",
                parse_mode='Markdown', reply_markup=keyboard)
            return
        except ValueError as e:
            await update.message.reply_text(f"❌ {e}")
            context.user_data.pop('sell', None)
            return
        
        # Calculate proceeds and P/L (including both buy and sell commissions)
        gross_proceeds = shares_to_sell * sell_price
        net_proceeds = gross_proceeds - sell_commission
        cost_basis = (total_cost / total_shares) * shares_to_sell
        # P/L now includes buy commission (already in cost_basis) and sell commission
        profit_loss = net_proceeds - cost_basis
        profit_pct = (profit_loss / cost_basis) * 100 if cost_basis > 0 else 0
        
        # Calculate holding period  
        sale_date = _us_market_date().strftime("%Y-%m-%d")
        holding_period = "Unknown"
        if purchase_date and purchase_date != "Unknown" and purchase_date != "Combined":
            try:
                buy_dt = datetime.strptime(purchase_date, "%Y-%m-%d")
                sell_dt = datetime.strptime(sale_date, "%Y-%m-%d")
                days_held = (sell_dt - buy_dt).days
                if days_held < 30:
                    holding_period = f"{days_held} days"
                elif days_held < 365:
                    months = days_held // 30
                    holding_period = f"{months} month{'s' if months > 1 else ''}"
                else:
                    years = days_held // 365
                    months = (days_held % 365) // 30
                    holding_period = f"{years}y {months}m"
            except:
                holding_period = "Unknown"
        
        # Update or remove holding
        if shares_to_sell >= total_shares:
            # Sell all - remove holding
            del portfolio_data['holdings'][holding_idx]
            remaining_shares = 0
        else:
            # Partial sell - update holding
            remaining_shares = total_shares - shares_to_sell
            remaining_cost = total_cost - cost_basis
            portfolio_data['holdings'][holding_idx]['shares'] = remaining_shares
            portfolio_data['holdings'][holding_idx]['total_cost'] = round(remaining_cost, 2)
            portfolio_data['holdings'][holding_idx]['brokers'] = broker_split
        
        # Capital-gains tax (25%) with loss offsetting (tax shield), Israeli-style:
        #  - A losing sale BANKS a shield of 25% x loss (running balance).
        #  - A profitable sale owes 25% x profit, but first CONSUMES the shield;
        #    only the remaining positive amount is actually withheld from cash.
        TAX_RATE = 0.25
        shield = portfolio_data.get('tax_shield_balance', 0)
        tax_withheld = 0
        tax_shield_earned = 0
        tax_shield_used = 0
        if profit_loss > 0:
            tax_owed = round(profit_loss * TAX_RATE, 2)
            tax_shield_used = round(min(shield, tax_owed), 2)
            tax_withheld = round(tax_owed - tax_shield_used, 2)
            shield = round(shield - tax_shield_used, 2)
        elif profit_loss < 0:
            tax_shield_earned = round(abs(profit_loss) * TAX_RATE, 2)
            shield = round(shield + tax_shield_earned, 2)
        portfolio_data['tax_shield_balance'] = shield

        # The bank withholds the tax at the sale; Interactive does not, so there
        # the whole proceeds stay in the account and the tax is due in the
        # annual report (still recorded, and still offset by the shield).
        cash_added = net_proceeds if broker == brk.IBKR else net_proceeds - tax_withheld
        tax_label = ("Tax due (25%) — not withheld by Interactive, annual report"
                     if broker == brk.IBKR else "Tax withheld (25%)")

        # Add (after-tax) proceeds to that broker's cash
        cash_key = brk.CASH_KEY[broker]
        current_cash = portfolio_data.get(cash_key, 0)
        new_cash = current_cash + cash_added
        portfolio_data[cash_key] = round(new_cash, 2)

        # Log the transaction with date (actual cash impact, net of tax)
        if tax_withheld:
            tax_note = f" (tax withheld ${tax_withheld:,.2f})"
        elif tax_shield_used:
            tax_note = f" (tax ${round(profit_loss * TAX_RATE, 2):,.2f} covered by shield)"
        elif tax_shield_earned:
            tax_note = f" (tax shield +${tax_shield_earned:,.2f})"
        else:
            tax_note = ""
        _log_cash_transaction(
            portfolio_data,
            cash_added,
            "stock_sale",
            f"Sold {symbol}{tax_note}" + (" (Interactive)" if broker == brk.IBKR else ""),
            broker=broker,
        )

        # Log to sold stocks history
        _log_sold_stock(
            portfolio_data,
            symbol=symbol,
            shares=shares_to_sell,
            buy_price=purchase_price,
            sell_price=sell_price,
            buy_date=purchase_date,
            sell_date=sale_date,
            holding_period=holding_period,
            cost_basis=cost_basis,
            proceeds=net_proceeds,
            buy_commission=buy_commission,
            sell_commission=sell_commission,
            profit_loss=profit_loss,
            profit_pct=profit_pct,
            tax_withheld=tax_withheld,
            tax_shield_earned=tax_shield_earned,
            tax_shield_used=tax_shield_used
        )
        portfolio_data['sold_history'][-1]['broker'] = broker
        if broker == brk.IBKR and tax_withheld:
            portfolio_data['sold_history'][-1]['tax_not_withheld'] = True

        _save_portfolio(portfolio_data)
        
        # Build response
        emoji = "🟢" if profit_loss >= 0 else "🔴"
        remaining_msg = f"\n📦 Remaining: {remaining_shares:.0f} shares" if remaining_shares > 0 else ""
        
        await update.message.reply_text(
            f"✅ *SOLD {symbol}*\n\n"
            f"📅 Date: {sale_date}\n"
            f"⏱ Held: {holding_period}\n"
            f"📊 *Sale Details:*\n"
            f"• Shares Sold: {shares_to_sell:.0f}\n"
            f"• Buy Price: ${purchase_price:.2f}\n"
            f"• Sell Price: ${sell_price:.2f}\n"
            f"• Buy Commission: ${buy_commission:.2f}\n"
            f"• Sell Commission: ${sell_commission:.2f}\n"
            f"• Gross Proceeds: ${gross_proceeds:,.2f}\n"
            f"• Net Proceeds: ${net_proceeds:,.2f}\n"
            f"• Cost Basis: ${cost_basis:,.2f}\n"
            f"{emoji} *P/L: ${profit_loss:+,.2f} ({profit_pct:+.1f}%)*\n"
            f"{'💸 ' + tax_label + ': -$' + format(tax_withheld, ',.2f') + chr(10) if tax_withheld else ''}"
            f"{'🛡️ Tax covered by shield: $' + format(tax_shield_used, ',.2f') + chr(10) if tax_shield_used else ''}"
            f"{'🛡️ Tax shield earned: +$' + format(tax_shield_earned, ',.2f') + chr(10) if tax_shield_earned else ''}"
            f"🛡️ Shield balance: ${shield:,.2f}\n"
            f"{remaining_msg}\n\n"
            f"🏛 {brk.LABEL[broker]}\n"
            f"💵 Cash: ${current_cash:,.2f} → *${new_cash:,.2f}*",
            parse_mode='Markdown'
        )

        # Cleanup
        context.user_data.pop('sell', None)
        
        # NOTE: Goal notification removed for sell operations.
        # Selling converts stock→cash (minus commission) and doesn't meaningfully
        # advance the goal. Showing a "goal update" after a sell at a loss is confusing.
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def sell_broker_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """sellbrk:IBKR | sellbrk:BANK | sellbrk:cancel -- a symbol held at both brokers."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    choice = (query.data or '').split(':')[-1]
    data = context.user_data.get('sell')
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    if choice not in brk.BROKERS or not data:
        context.user_data.pop('sell', None)
        await query.message.reply_text("❌ Sell cancelled." if choice == 'cancel'
                                       else "ℹ️ This sale is no longer pending — send /sell again.")
        return
    data['broker'] = choice
    await _do_sell_final(_ReplyTarget(query.message), context)


async def buy(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shortcut for /addholding - Buy stock and add to portfolio"""
    await addholding(update, context)


async def portfolio_analysis(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Deep analysis of portfolio or specific stocks with buy price ratings"""
    
    # Check if specific stocks provided
    if context.args:
        symbols = [s.upper() for s in context.args]
        await update.message.reply_text(f"🔍 Running analysis for {', '.join(symbols)}... This may take a moment.")
        await _run_stock_analysis(update, symbols, is_portfolio=False)
        return
    
    # Otherwise ask what to analyze
    context.user_data['state'] = 'analysis_choice'
    await update.message.reply_text(
        "🔍 *Stock Analysis*\n\n"
        "What would you like to analyze?\n\n"
        "1️⃣ Send `WATCHLIST` to analyze watchlist stocks\n"
        "2️⃣ Send `PORTFOLIO` to analyze portfolio holdings\n"
        "3️⃣ Send stock symbols (e.g. `AAPL NVDA TSLA`)",
        parse_mode='Markdown'
    )


async def _handle_analysis_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle analysis choice selection"""
    text = update.message.text.upper().strip()
    
    if text == 'WATCHLIST':
        # Get watchlist symbols
        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                watchlists = json.load(f)
            symbols = watchlists.get('default', [])
        else:
            symbols = []
        
        if not symbols:
            await update.message.reply_text("❌ Watchlist is empty!")
            context.user_data.pop('state', None)
            return
        
        await update.message.reply_text(f"🔍 Analyzing {len(symbols)} watchlist stocks... This may take a moment.")
        await _run_stock_analysis(update, symbols, is_portfolio=False)
        
    elif text == 'PORTFOLIO':
        # Get portfolio holdings
        portfolio_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
        
        if not os.path.exists(portfolio_file):
            await update.message.reply_text("❌ Portfolio file not found!")
            context.user_data.pop('state', None)
            return
        
        with open(portfolio_file, 'r', encoding='utf-8') as f:
            portfolio_data = json.load(f)
        
        holdings = portfolio_data.get('holdings', [])
        
        if not holdings:
            await update.message.reply_text("📋 Portfolio is empty!")
            context.user_data.pop('state', None)
            return
        
        await update.message.reply_text(f"🔍 Analyzing {len(holdings)} portfolio holdings... This may take a moment.")
        await _run_portfolio_analysis(update, holdings)
        
    else:
        # Assume it's stock symbols
        symbols = text.split()
        if symbols:
            await update.message.reply_text(f"🔍 Analyzing {', '.join(symbols)}... This may take a moment.")
            await _run_stock_analysis(update, symbols, is_portfolio=False)
        else:
            await update.message.reply_text("❌ Please send WATCHLIST, PORTFOLIO, or stock symbols")
            return
    
    context.user_data.pop('state', None)


async def _run_stock_analysis(update: Update, symbols: list, is_portfolio: bool = False):
    """Run analysis on specific stock symbols"""
    try:
        analysis_data = []
        
        for symbol in symbols:
            try:
                stock = yf.Ticker(symbol)
                info = stock.info
                hist = stock.history(period='1y')
                
                if hist.empty:
                    continue
                
                current_price = hist['Close'].iloc[-1]
                name = info.get('shortName', symbol)
                
                # Calculate key metrics
                high_52w = info.get('fiftyTwoWeekHigh', current_price)
                low_52w = info.get('fiftyTwoWeekLow', current_price)
                target_mean = info.get('targetMeanPrice', current_price)
                pe_ratio = info.get('trailingPE', 0)
                
                # Where is current price in 52-week range (0-100)
                price_range_pct = ((current_price - low_52w) / (high_52w - low_52w)) * 100 if high_52w != low_52w else 50
                
                # Upside to analyst target
                upside = ((target_mean - current_price) / current_price) * 100 if target_mean else 0
                
                # Calculate score (0-100)
                score = 0
                reasons = []
                
                # 1. Price position in range (40 points)
                if price_range_pct < 30:
                    score += 40
                    reasons.append("Near 52w low - potential value")
                elif price_range_pct < 50:
                    score += 30
                    reasons.append("In lower half of range")
                elif price_range_pct < 70:
                    score += 20
                    reasons.append("In upper half of range")
                else:
                    score += 10
                    reasons.append("Near 52w high - extended")
                
                # 2. Analyst upside (30 points)
                if upside > 30:
                    score += 30
                    reasons.append(f"High upside potential {upside:.0f}%")
                elif upside > 15:
                    score += 20
                    reasons.append(f"Good upside {upside:.0f}%")
                elif upside > 0:
                    score += 10
                    reasons.append(f"Some upside {upside:.0f}%")
                else:
                    reasons.append("At/above target")
                
                # 3. PE Ratio check (30 points)
                if pe_ratio and pe_ratio > 0:
                    if pe_ratio < 15:
                        score += 30
                        reasons.append(f"Low P/E ({pe_ratio:.1f})")
                    elif pe_ratio < 25:
                        score += 20
                        reasons.append(f"Fair P/E ({pe_ratio:.1f})")
                    elif pe_ratio < 40:
                        score += 10
                        reasons.append(f"High P/E ({pe_ratio:.1f})")
                    else:
                        reasons.append(f"Very high P/E ({pe_ratio:.1f})")
                else:
                    score += 15
                    reasons.append("P/E N/A")
                
                # Rating
                if score >= 80:
                    rating = "🌟 STRONG BUY"
                elif score >= 60:
                    rating = "✅ BUY"
                elif score >= 40:
                    rating = "🟡 HOLD"
                elif score >= 20:
                    rating = "⚠️ CAUTION"
                else:
                    rating = "🔴 AVOID"
                
                analysis_data.append({
                    'symbol': symbol,
                    'name': name,
                    'current_price': current_price,
                    'score': score,
                    'rating': rating,
                    'reasons': reasons,
                    'upside': upside,
                    'target': target_mean or current_price,
                    'high_52w': high_52w,
                    'low_52w': low_52w
                })
                
            except Exception as e:
                continue
        
        if not analysis_data:
            await update.message.reply_text("❌ Could not analyze any of the provided stocks")
            return
        
        # Build message
        message = "🔍 *STOCK ANALYSIS*\n"
        message += "━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        for item in analysis_data:
            message += f"*{item['symbol']}* - {item['name'][:20]}\n"
            message += f"   {item['rating']} ({item['score']}/100)\n"
            message += f"   💵 Price: ${item['current_price']:.2f}\n"
            message += f"   📉 52w: ${item['low_52w']:.2f} - ${item['high_52w']:.2f}\n"
            message += f"   🎯 Target: ${item['target']:.2f} ({item['upside']:+.1f}%)\n"
            message += f"   📝 {item['reasons'][0]}\n\n"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def _run_portfolio_analysis(update: Update, holdings: list):
    """Run analysis on portfolio holdings"""
    try:
        analysis_data = []
        total_score = 0
        total_weight = 0
        
        for holding in holdings:
            symbol = holding['symbol']
            shares = holding['shares']
            avg_price = holding['purchase_price']
            cost = holding['total_cost']
            
            try:
                stock = yf.Ticker(symbol)
                info = stock.info
                hist = stock.history(period='1y')
                
                if hist.empty:
                    continue
                
                current_price = hist['Close'].iloc[-1]
                
                # Calculate key metrics
                high_52w = info.get('fiftyTwoWeekHigh', current_price)
                low_52w = info.get('fiftyTwoWeekLow', current_price)
                target_mean = info.get('targetMeanPrice', current_price)
                
                # Where is current price in 52-week range (0-100)
                price_range_pct = ((current_price - low_52w) / (high_52w - low_52w)) * 100 if high_52w != low_52w else 50
                
                # Where was buy price in 52-week range
                buy_range_pct = ((avg_price - low_52w) / (high_52w - low_52w)) * 100 if high_52w != low_52w else 50
                
                # Profit/Loss
                profit_pct = ((current_price - avg_price) / avg_price) * 100
                
                # Upside to analyst target
                upside = ((target_mean - current_price) / current_price) * 100 if target_mean else 0
                
                # Calculate buy price rating (0-100)
                buy_score = 0
                buy_reasons = []
                
                # 1. Profit check (40 points max)
                if profit_pct > 50:
                    buy_score += 40
                    buy_reasons.append("Excellent gains >50%")
                elif profit_pct > 20:
                    buy_score += 30
                    buy_reasons.append("Strong gains >20%")
                elif profit_pct > 0:
                    buy_score += 20
                    buy_reasons.append("Profitable position")
                elif profit_pct > -10:
                    buy_score += 10
                    buy_reasons.append("Small loss <10%")
                else:
                    buy_reasons.append(f"Significant loss {profit_pct:.1f}%")
                
                # 2. Buy price vs 52-week range (30 points max)
                if buy_range_pct < 30:
                    buy_score += 30
                    buy_reasons.append("Bought near 52w low")
                elif buy_range_pct < 50:
                    buy_score += 20
                    buy_reasons.append("Bought in lower half")
                elif buy_range_pct < 70:
                    buy_score += 10
                    buy_reasons.append("Bought in upper half")
                else:
                    buy_reasons.append("Bought near 52w high")
                
                # 3. Upside potential (30 points max)
                if upside > 30:
                    buy_score += 30
                    buy_reasons.append(f"High upside {upside:.0f}%")
                elif upside > 15:
                    buy_score += 20
                    buy_reasons.append(f"Good upside {upside:.0f}%")
                elif upside > 0:
                    buy_score += 10
                    buy_reasons.append(f"Some upside {upside:.0f}%")
                else:
                    buy_reasons.append("Above analyst target")
                
                # Rating label
                if buy_score >= 80:
                    rating = "🌟 EXCELLENT"
                elif buy_score >= 60:
                    rating = "✅ GOOD"
                elif buy_score >= 40:
                    rating = "🟡 FAIR"
                elif buy_score >= 20:
                    rating = "⚠️ POOR"
                else:
                    rating = "🔴 BAD"
                
                # Weight by position size
                position_value = current_price * shares
                total_weight += position_value
                total_score += buy_score * position_value
                
                analysis_data.append({
                    'symbol': symbol,
                    'shares': shares,
                    'avg_price': avg_price,
                    'current_price': current_price,
                    'profit_pct': profit_pct,
                    'buy_score': buy_score,
                    'rating': rating,
                    'reasons': buy_reasons,
                    'upside': upside,
                    'target': target_mean,
                    'position_value': position_value
                })
                
            except Exception as e:
                continue
        
        # Sort by score (worst first for improvement focus)
        analysis_data.sort(key=lambda x: x['buy_score'])
        
        # Build message
        message = "🔍 *PORTFOLIO ANALYSIS*\n"
        message += "━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        for item in analysis_data:
            profit_emoji = "🟢" if item['profit_pct'] >= 0 else "🔴"
            
            message += f"*{item['symbol']}* - {item['rating']}\n"
            message += f"   Score: {item['buy_score']}/100\n"
            message += f"   💵 Buy: ${item['avg_price']:.2f} → Now: ${item['current_price']:.2f}\n"
            message += f"   {profit_emoji} P/L: {item['profit_pct']:+.1f}%\n"
            message += f"   🎯 Target: ${item['target']:.2f} ({item['upside']:+.1f}%)\n"
            message += f"   📝 {item['reasons'][0]}\n\n"
        
        # Overall portfolio rating
        overall_score = (total_score / total_weight) if total_weight > 0 else 0
        
        if overall_score >= 80:
            overall_rating = "🌟 EXCELLENT"
        elif overall_score >= 60:
            overall_rating = "✅ GOOD"
        elif overall_score >= 40:
            overall_rating = "🟡 FAIR"
        elif overall_score >= 20:
            overall_rating = "⚠️ NEEDS WORK"
        else:
            overall_rating = "🔴 POOR"
        
        message += "━━━━━━━━━━━━━━━━━━━━━━\n"
        message += f"*OVERALL PORTFOLIO RATING*\n"
        message += f"📊 Score: *{overall_score:.0f}/100*\n"
        message += f"📈 Rating: *{overall_rating}*\n\n"
        
        # Best and worst positions
        best = max(analysis_data, key=lambda x: x['buy_score'])
        worst = min(analysis_data, key=lambda x: x['buy_score'])
        
        message += f"🏆 Best Buy: *{best['symbol']}* ({best['buy_score']}/100)\n"
        message += f"⚠️ Weakest: *{worst['symbol']}* ({worst['buy_score']}/100)\n"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
        # Send AI recommendations if available
        if HAS_OPENAI:
            await update.message.reply_text("🤖 Generating AI recommendations...")
            
            summary = "\n".join([
                f"{item['symbol']}: bought at ${item['avg_price']:.2f}, now ${item['current_price']:.2f} ({item['profit_pct']:+.1f}%), target ${item['target']:.2f}, score {item['buy_score']}/100"
                for item in analysis_data
            ])
            
            prompt = f"""Analyze this stock portfolio and provide brief recommendations:

{summary}

Overall score: {overall_score:.0f}/100

Give 3-4 bullet points:
1. What's working well
2. What needs attention  
3. Specific action items (hold/add/trim)
Keep it concise (under 150 words)."""

            try:
                response = client.chat.completions.create(
                    model="gpt-4o",
                    messages=[
                        {"role": "system", "content": "You are a portfolio analyst. Be direct and actionable."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=300
                )
                ai_advice = response.choices[0].message.content.strip()
                await update.message.reply_text(f"🤖 *AI Recommendations:*\n\n{ai_advice}", parse_mode='Markdown')
            except:
                pass
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


