async def portfolio_research(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Deep AI research on entire portfolio — sell prices, buy/sell/hold, entry strategies"""
    user_id = update.effective_user.id
    if not is_authorized(user_id):
        await unauthorized_message(update)
        return

    portfolio_data = _load_portfolio()
    holdings = portfolio_data.get('holdings', [])

    if not holdings:
        await update.message.reply_text("📋 Portfolio is empty! Use /buy to add stocks first.")
        return

    sold_history = portfolio_data.get('sold_history', [])
    free_cash = _usd_cash_total(portfolio_data)

    status_msg = await update.message.reply_text(
        f"🔬 <b>Deep Portfolio Research</b>\n\n"
        f"📊 Analyzing {len(holdings)} holdings...\n"
        f"💰 Free cash: ${free_cash:,.2f}\n\n"
        f"⏳ Step 1/3: Fetching market data...",
        parse_mode='HTML'
    )

    import asyncio
    import math

    # Step 1: Batch fetch all stock data via yfinance (fast - single API call)
    symbols_list = list(set(h['symbol'] for h in holdings))
    try:
        batch_data = await asyncio.to_thread(
            yf.download, symbols_list, period='6mo', group_by='ticker', progress=False, threads=True
        )
        # Also get info for each stock
        stock_infos = {}
        for sym in symbols_list:
            try:
                info = await asyncio.to_thread(lambda s=sym: yf.Ticker(s).info)
                stock_infos[sym] = info
            except:
                stock_infos[sym] = {}
    except Exception as e:
        await update.message.reply_text(f"❌ Error fetching market data: {str(e)[:200]}")
        return

    # Step 2: Get AI market intelligence via Perplexity
    try:
        await status_msg.edit_text(
            f"🔬 <b>Deep Portfolio Research</b>\n\n"
            f"🤖 Step 2/3: Getting AI market intelligence for {len(symbols_list)} stocks...",
            parse_mode='HTML'
        )
    except:
        pass

    perplexity_intel = ""
    try:
        import requests as req
        symbols_str = ", ".join(symbols_list)
        perp_response = await asyncio.to_thread(lambda: req.post(
            "https://api.perplexity.ai/chat/completions",
            headers={
                "Authorization": f"Bearer {PERPLEXITY_API_KEY}",
                "Content-Type": "application/json"
            },
            json={
                "model": "sonar-pro",
                "messages": [
                    {"role": "system", "content": "You are a stock market analyst. Be concise and specific."},
                    {"role": "user", "content": f"Give me a brief current outlook (2-3 sentences each) for these stocks: {symbols_str}. Include: recent news, analyst consensus, key upcoming catalysts, and any red flags. Focus on actionable info."}
                ],
                "max_tokens": 3000,
                "temperature": 0.2
            },
            timeout=60
        ))
        if perp_response.status_code == 200:
            perplexity_intel = perp_response.json()['choices'][0]['message']['content']
    except Exception as e:
        print(f"Perplexity portfolio intel error: {e}")

    # Step 3: Build comprehensive data for GPT-4o verdict
    try:
        await status_msg.edit_text(
            f"🔬 <b>Deep Portfolio Research</b>\n\n"
            f"🏆 Step 3/3: Generating portfolio verdict...",
            parse_mode='HTML'
        )
    except:
        pass

    holdings_data = []
    total_cost_all = 0
    total_value_all = 0

    for holding in holdings:
        symbol = holding['symbol']
        shares = holding.get('shares', 0)
        buy_price = holding.get('purchase_price', holding.get('avg_price', 0))
        total_cost = holding.get('total_cost', buy_price * shares)
        purchase_date = holding.get('purchase_date', 'Unknown')

        # Get current price and technicals from batch data
        current_price = buy_price
        sma_50 = sma_200 = rsi = prev_close = high_52w = low_52w = 0
        try:
            if len(symbols_list) == 1:
                hist = batch_data
            else:
                hist = batch_data[symbol] if symbol in batch_data.columns.get_level_values(0) else None

            if hist is not None and not hist.empty:
                close = hist['Close'].dropna()
                if len(close) >= 1:
                    current_price = float(close.iloc[-1])
                    prev_close = float(close.iloc[-2]) if len(close) > 1 else current_price
                    if len(close) >= 50:
                        sma_50 = float(close.iloc[-50:].mean())
                    if len(close) >= 120:
                        sma_200 = float(close.iloc[-120:].mean())  # ~6mo approx
                    # RSI calculation
                    if len(close) >= 15:
                        delta = close.diff().iloc[-14:]
                        gain = delta.where(delta > 0, 0).mean()
                        loss = (-delta.where(delta < 0, 0)).mean()
                        rs = gain / loss if loss != 0 else 100
                        rsi = 100 - (100 / (1 + rs))
        except:
            pass

        # Get analyst targets from info
        info = stock_infos.get(symbol, {})
        target_mean = info.get('targetMeanPrice', 0)
        target_high = info.get('targetHighPrice', 0)
        target_low = info.get('targetLowPrice', 0)
        pe_ratio = info.get('trailingPE', 0)
        fwd_pe = info.get('forwardPE', 0)
        high_52w = info.get('fiftyTwoWeekHigh', 0)
        low_52w = info.get('fiftyTwoWeekLow', 0)
        recommendation = info.get('recommendationKey', 'N/A')
        sector = info.get('sector', 'N/A')
        name = info.get('shortName', symbol)

        current_value = current_price * shares
        pnl = current_value - total_cost
        pnl_pct = ((current_price - buy_price) / buy_price * 100) if buy_price else 0
        day_change_pct = ((current_price - prev_close) / prev_close * 100) if prev_close else 0

        total_cost_all += total_cost
        total_value_all += current_value

        holdings_data.append(
            f"\n{'━' * 40}\n"
            f"📌 {symbol} ({name}) — {sector}\n"
            f"   Shares: {shares} | Buy: ${buy_price:.2f} | Now: ${current_price:.2f} | Today: {day_change_pct:+.1f}%\n"
            f"   Cost: ${total_cost:,.2f} | Value: ${current_value:,.2f} | P/L: ${pnl:+,.2f} ({pnl_pct:+.1f}%)\n"
            f"   Bought: {purchase_date}\n"
            f"   52W Range: ${low_52w:.2f} - ${high_52w:.2f}\n"
            f"   SMA50: ${sma_50:.2f} | RSI: {rsi:.0f}\n"
            f"   P/E: {pe_ratio:.1f} | Fwd P/E: {fwd_pe:.1f}\n"
            f"   Analyst: {recommendation} | Targets: ${target_low:.2f} / ${target_mean:.2f} / ${target_high:.2f}"
        )

    total_pnl = total_value_all - total_cost_all

    # Build sold history summary
    sold_summary = ""
    if sold_history:
        recent_sold = sold_history[-5:]
        sold_lines = []
        for s in recent_sold:
            sold_lines.append(f"  {s.get('symbol','?')}: bought ${s.get('buy_price',0):.2f} → sold ${s.get('sell_price',0):.2f} ({s.get('profit_pct',0):+.1f}%) on {s.get('sell_date','?')}")
        sold_summary = f"\nRecent Sold History:\n" + "\n".join(sold_lines)

    # Perplexity intelligence section
    intel_section = ""
    if perplexity_intel:
        intel_section = f"\n\nAI MARKET INTELLIGENCE (from Perplexity - real-time web data):\n{perplexity_intel}"

    verdict_prompt = f"""You are my personal portfolio advisor. I need a COMPLETE portfolio review.

MY PORTFOLIO:
- Total invested: ${total_cost_all:,.2f}
- Current value: ${total_value_all:,.2f}
- Unrealized P/L: ${total_pnl:+,.2f} ({(total_pnl/total_cost_all*100) if total_cost_all else 0:+.1f}%)
- Free cash available: ${free_cash:,.2f}
{sold_summary}

HOLDINGS WITH FULL MARKET DATA:
{"".join(holdings_data)}
{intel_section}

Based on ALL the data above, give me a COMPLETE portfolio action plan:

📊 PORTFOLIO OVERVIEW
- Total value, P/L summary, portfolio health grade (A/B/C/D/F)

🏷️ FOR EACH STOCK — give one of these verdicts:
  ✅ HOLD (with target sell price for maximum gains + reasoning)
  🟢 BUY MORE (how much more, at what price, why)
  🔴 SELL NOW (at what price, why, urgency level)
  ⚠️ TRIM (sell partial position — how many shares, at what price)

For each stock include:
- 🎯 Optimal sell price (for max gains based on technicals + fundamentals)
- 🛑 Stop loss price (where to cut losses)
- ⏰ Timeline (how long to hold)

💰 CASH DEPLOYMENT (I have ${free_cash:,.2f} available):
- Should I buy more of existing holdings? Which ones and how much?
- Or wait for better entries?

📈 TOP ACTION ITEMS (ranked by urgency):
1. Most urgent action
2. Second priority
3. Third priority

⚠️ BIGGEST PORTFOLIO RISKS right now

Be extremely specific with exact dollar prices and share counts. Be direct and actionable. No hedging."""

    try:
        response = client.chat.completions.create(
            model="gpt-4o",
            messages=[
                {"role": "system", "content": "You are an expert portfolio advisor. Give extremely specific, actionable advice with exact prices and numbers. Be direct."},
                {"role": "user", "content": verdict_prompt}
            ],
            max_tokens=4000,
            temperature=0.3
        )
        verdict_text = response.choices[0].message.content.strip()

        final_msg = (
            f"{'━' * 30}\n"
            f"🔬 <b>DEEP PORTFOLIO RESEARCH</b>\n"
            f"{'━' * 30}\n\n"
            f"📊 {len(holdings)} stocks analyzed\n"
            f"💰 Portfolio: ${total_value_all:,.2f} (P/L: ${total_pnl:+,.2f})\n\n"
            f"{verdict_text}"
        )
        await _send_research_chunks(update, final_msg)

    except Exception as e:
        print(f"Portfolio research verdict error: {e}")
        await update.message.reply_text(f"❌ Error generating verdict: {str(e)[:200]}")

    try:
        await status_msg.edit_text(
            f"🔬 <b>Deep Portfolio Research Complete!</b>\n\n"
            f"✅ Analyzed {len(holdings)} holdings\n"
            f"🏆 See full verdict above ⬆️",
            parse_mode='HTML'
        )
    except:
        pass


