async def earnings(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show upcoming earnings report dates"""
    # If symbol provided directly
    if context.args:
        symbol = context.args[0].upper()
        await _show_single_earnings(update, symbol)
        return

    # Otherwise ask what to check: a tap, a number, a word, or a symbol
    context.user_data['state'] = 'earnings_choice'
    await update.message.reply_text(
        "📅 *Earnings Report Dates*\n\n"
        "What would you like to check?\n\n"
        "1️⃣ Portfolio stocks (send `1` or tap below)\n"
        "2️⃣ Watchlist stocks (send `2` or tap below)\n"
        "3️⃣ Send a stock symbol (e.g. `AAPL`)",
        parse_mode='Markdown',
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("1️⃣ Portfolio", callback_data="earn:portfolio"),
            InlineKeyboardButton("2️⃣ Watchlist", callback_data="earn:watchlist")]])
    )


EARNINGS_PORTFOLIO = ('1', '1️⃣', 'PORTFOLIO', 'תיק')
EARNINGS_WATCHLIST = ('2', '2️⃣', 'WATCHLIST', 'רשימה')
_TICKER = re.compile(r'[A-Z][A-Z0-9.\-]{0,9}')


async def _earnings_for_group(target, which):
    """The earnings list for the portfolio or the watchlist. False when it is empty."""
    if which == 'portfolio':
        symbols = [h['symbol'] for h in _load_portfolio().get('holdings', [])]
        label = "Portfolio"
    else:
        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        symbols = []
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                watchlists = json.load(f)
            symbols = list(watchlists.get('watchlists', {}).get('default', {}).get('stocks', {}).keys())
        label = "Watchlist"
    if not symbols:
        await target.message.reply_text(f"❌ {label} is empty!")
        return False
    await _show_earnings_list(target, symbols, label)
    return True


async def earnings_choice_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """earn:portfolio | earn:watchlist -- the buttons under /earnings."""
    query = update.callback_query
    if not is_authorized(query.from_user.id):
        await query.answer("Not authorized", show_alert=True)
        return
    await query.answer()
    context.user_data.pop('state', None)
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    await _earnings_for_group(_ReplyTarget(query.message), query.data.split(':', 1)[1])


async def _handle_earnings_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle earnings choice selection: 1 / 2 (or the words), 3, or a symbol."""
    text = update.message.text.upper().strip()

    if text in EARNINGS_PORTFOLIO:
        await _earnings_for_group(update, 'portfolio')
    elif text in EARNINGS_WATCHLIST:
        await _earnings_for_group(update, 'watchlist')
    elif text in ('3', '3️⃣'):
        await update.message.reply_text("🔎 Send the stock symbol (e.g. `AAPL`)", parse_mode='Markdown')
        return                                      # still waiting for the symbol
    elif _TICKER.fullmatch(text):
        await _show_single_earnings(update, text)
    else:
        await update.message.reply_text("❌ Send 1 (portfolio), 2 (watchlist), or a stock symbol like AAPL.")
        return                                      # still waiting

    context.user_data.pop('state', None)


async def _show_single_earnings(update: Update, symbol: str):
    """Show earnings date for a single stock"""
    await update.message.reply_text(f"⏳ Fetching earnings data for {symbol}...")
    
    try:
        from datetime import datetime, date
        stock = yf.Ticker(symbol)
        info = stock.info
        
        company_name = info.get('shortName', symbol)
        
        # Try to get earnings date from calendar
        earnings_date = None
        
        try:
            calendar = stock.calendar
            if calendar is not None:
                # Calendar is a dict now
                if isinstance(calendar, dict):
                    earnings_list = calendar.get('Earnings Date', [])
                    if earnings_list and len(earnings_list) > 0:
                        earnings_date = earnings_list[0]
                # Could also be a DataFrame
                elif hasattr(calendar, 'empty') and not calendar.empty:
                    if 'Earnings Date' in calendar.index:
                        earnings_dates = calendar.loc['Earnings Date']
                        if hasattr(earnings_dates, 'iloc') and len(earnings_dates) > 0:
                            earnings_date = earnings_dates.iloc[0]
                        else:
                            earnings_date = earnings_dates
        except Exception as e:
            pass
        
        # Fallback: try earnings_dates DataFrame (historical + upcoming)
        if earnings_date is None:
            try:
                ed = stock.earnings_dates
                if ed is not None and not ed.empty:
                    # Get future dates (NaN in Reported EPS means not reported yet)
                    future_dates = ed[ed['Reported EPS'].isna()]
                    if not future_dates.empty:
                        # Get the earliest future date
                        earnings_date = future_dates.index[0]
                        if hasattr(earnings_date, 'date'):
                            earnings_date = earnings_date.date()
            except:
                pass
        
        if earnings_date is None:
            await update.message.reply_text(
                f"📅 *{symbol}* - {company_name}\n\n"
                f"❓ No earnings date available",
                parse_mode='Markdown'
            )
            return
        
        # Calculate days until earnings
        today = date.today()
        
        # Convert to date if needed
        if hasattr(earnings_date, 'date') and callable(earnings_date.date):
            earnings_dt = earnings_date.date()
        elif hasattr(earnings_date, 'date'):
            earnings_dt = earnings_date
        else:
            earnings_dt = earnings_date
        
        days_until = (earnings_dt - today).days
        
        # Format the message
        if days_until < 0:
            timing = f"📆 {abs(days_until)} days ago"
            emoji = "✅"
        elif days_until == 0:
            timing = "🔔 *TODAY!*"
            emoji = "🚨"
        elif days_until == 1:
            timing = "⚠️ *TOMORROW!*"
            emoji = "🚨"
        elif days_until <= 7:
            timing = f"⚠️ In *{days_until} days*"
            emoji = "📢"
        elif days_until <= 30:
            timing = f"📅 In {days_until} days"
            emoji = "📊"
        else:
            timing = f"📅 In {days_until} days"
            emoji = "📋"
        
        date_str = earnings_dt.strftime("%B %d, %Y") if hasattr(earnings_dt, 'strftime') else str(earnings_dt)
        
        await update.message.reply_text(
            f"{emoji} *{symbol}* - {company_name}\n\n"
            f"📅 Earnings Date: *{date_str}*\n"
            f"{timing}",
            parse_mode='Markdown'
        )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error fetching earnings for {symbol}: {str(e)}")


async def _show_earnings_list(update: Update, symbols: list, source: str):
    """Show earnings dates for multiple stocks"""
    await update.message.reply_text(f"⏳ Fetching earnings data for {len(symbols)} stocks...")
    
    from datetime import datetime, date
    today = date.today()
    
    earnings_data = []
    no_data = []
    
    for symbol in symbols:
        try:
            stock = yf.Ticker(symbol)
            
            earnings_date = None
            
            # Try calendar first (it's a dict now)
            try:
                calendar = stock.calendar
                if calendar is not None:
                    if isinstance(calendar, dict):
                        earnings_list = calendar.get('Earnings Date', [])
                        if earnings_list and len(earnings_list) > 0:
                            earnings_date = earnings_list[0]
                    elif hasattr(calendar, 'empty') and not calendar.empty:
                        if 'Earnings Date' in calendar.index:
                            earnings_dates = calendar.loc['Earnings Date']
                            if hasattr(earnings_dates, 'iloc') and len(earnings_dates) > 0:
                                earnings_date = earnings_dates.iloc[0]
                            else:
                                earnings_date = earnings_dates
            except:
                pass
            
            # Fallback: try earnings_dates DataFrame
            if earnings_date is None:
                try:
                    ed = stock.earnings_dates
                    if ed is not None and not ed.empty:
                        future_dates = ed[ed['Reported EPS'].isna()]
                        if not future_dates.empty:
                            earnings_date = future_dates.index[0]
                            if hasattr(earnings_date, 'date'):
                                earnings_date = earnings_date.date()
                except:
                    pass
            
            if earnings_date is None:
                no_data.append(symbol)
                continue
            
            # Calculate days until
            if hasattr(earnings_date, 'date') and callable(earnings_date.date):
                earnings_dt = earnings_date.date()
            elif hasattr(earnings_date, 'date'):
                earnings_dt = earnings_date
            else:
                earnings_dt = earnings_date
            
            days_until = (earnings_dt - today).days
            
            earnings_data.append({
                'symbol': symbol,
                'date': earnings_dt,
                'days': days_until
            })
            
        except:
            no_data.append(symbol)
    
    if not earnings_data and not no_data:
        await update.message.reply_text("❌ Could not fetch any earnings data")
        return
    
    # Sort by days until (soonest first)
    earnings_data.sort(key=lambda x: x['days'])
    
    message = f"📅 *{source} Earnings Calendar*\n"
    message += "━━━━━━━━━━━━━━━━━━━━━━\n\n"
    
    # Group by timing
    urgent = [e for e in earnings_data if 0 <= e['days'] <= 7]
    upcoming = [e for e in earnings_data if 7 < e['days'] <= 30]
    later = [e for e in earnings_data if e['days'] > 30]
    past = [e for e in earnings_data if e['days'] < 0]
    
    if urgent:
        message += "🚨 *THIS WEEK:*\n"
        for e in urgent:
            date_str = e['date'].strftime("%b %d") if hasattr(e['date'], 'strftime') else str(e['date'])
            if e['days'] == 0:
                message += f"  🔔 *{e['symbol']}* - {date_str} (*TODAY*)\n"
            elif e['days'] == 1:
                message += f"  ⚠️ *{e['symbol']}* - {date_str} (*TOMORROW*)\n"
            else:
                message += f"  📢 *{e['symbol']}* - {date_str} ({e['days']} days)\n"
        message += "\n"
    
    if upcoming:
        message += "📊 *THIS MONTH:*\n"
        for e in upcoming:
            date_str = e['date'].strftime("%b %d") if hasattr(e['date'], 'strftime') else str(e['date'])
            message += f"  📅 {e['symbol']} - {date_str} ({e['days']} days)\n"
        message += "\n"
    
    if later:
        message += "📋 *LATER:*\n"
        for e in later[:10]:  # Limit to 10
            date_str = e['date'].strftime("%b %d") if hasattr(e['date'], 'strftime') else str(e['date'])
            message += f"  📆 {e['symbol']} - {date_str} ({e['days']} days)\n"
        if len(later) > 10:
            message += f"  ... and {len(later) - 10} more\n"
        message += "\n"
    
    if past:
        message += "✅ *RECENTLY REPORTED:*\n"
        for e in past[-5:]:  # Last 5
            date_str = e['date'].strftime("%b %d") if hasattr(e['date'], 'strftime') else str(e['date'])
            message += f"  ✓ {e['symbol']} - {date_str} ({abs(e['days'])} days ago)\n"
        message += "\n"
    
    if no_data:
        message += f"❓ *No data:* {', '.join(no_data[:10])}"
        if len(no_data) > 10:
            message += f" +{len(no_data) - 10} more"
    
    await update.message.reply_text(message, parse_mode='Markdown')


async def start_monitor(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Start the news monitoring from Telegram"""
    global monitor_process
    user_id = update.effective_user.id
    
    # Check if already running
    if monitor_process is not None and monitor_process.poll() is None:
        await update.message.reply_text("ℹ️ News monitor is already running!")
        return
    
    # If specific stocks provided, start monitoring those
    if context.args:
        symbols = [s.upper() for s in context.args]
        context.user_data['monitor_symbols'] = symbols
        await _start_monitor_with_symbols(update, symbols, "custom")
        return
    
    # Otherwise ask what to monitor
    context.user_data['state'] = 'monitor_choice'
    await update.message.reply_text(
        "📡 *Start News Monitor*\n\n"
        "What would you like to monitor?\n\n"
        "1️⃣ Send `WATCHLIST` to monitor watchlist stocks\n"
        "2️⃣ Send `PORTFOLIO` to monitor portfolio stocks\n"
        "3️⃣ Send `BOTH` to monitor watchlist + portfolio\n"
        "4️⃣ Send stock symbols (e.g. `AAPL NVDA TSLA`)",
        parse_mode='Markdown'
    )


async def _handle_monitor_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle monitor choice selection"""
    text = update.message.text.upper().strip()
    
    if text == 'WATCHLIST':
        # Get watchlist symbols
        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                watchlists = json.load(f)
            # Handle nested structure: watchlists.watchlists.default.stocks
            default_wl = watchlists.get('watchlists', {}).get('default', {})
            stocks_dict = default_wl.get('stocks', {})
            symbols = list(stocks_dict.keys())
        else:
            symbols = []
        
        if not symbols:
            await update.message.reply_text("❌ Watchlist is empty!")
            context.user_data.pop('state', None)
            return
        
        await _start_monitor_with_symbols(update, symbols, "watchlist")
        
    elif text == 'PORTFOLIO':
        # Get portfolio symbols
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        symbols = [h['symbol'] for h in holdings]
        
        if not symbols:
            await update.message.reply_text("❌ Portfolio is empty!")
            context.user_data.pop('state', None)
            return
        
        await _start_monitor_with_symbols(update, symbols, "portfolio")
    
    elif text == 'BOTH':
        # Get both watchlist and portfolio symbols
        all_symbols = set()
        
        # Get watchlist
        watchlist_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchlists.json")
        if os.path.exists(watchlist_file):
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                watchlists = json.load(f)
            # Handle nested structure: watchlists.watchlists.default.stocks
            default_wl = watchlists.get('watchlists', {}).get('default', {})
            stocks_dict = default_wl.get('stocks', {})
            all_symbols.update(stocks_dict.keys())
        
        # Get portfolio
        portfolio_data = _load_portfolio()
        holdings = portfolio_data.get('holdings', [])
        all_symbols.update([h['symbol'] for h in holdings])
        
        symbols = list(all_symbols)
        
        if not symbols:
            await update.message.reply_text("❌ Both watchlist and portfolio are empty!")
            context.user_data.pop('state', None)
            return
        
        await _start_monitor_with_symbols(update, symbols, "watchlist + portfolio")
        
    else:
        # Assume it's stock symbols
        symbols = text.split()
        if symbols:
            await _start_monitor_with_symbols(update, symbols, "custom")
        else:
            await update.message.reply_text("❌ Please send WATCHLIST, PORTFOLIO, or stock symbols")
            return
    
    context.user_data.pop('state', None)


async def _start_monitor_with_symbols(update: Update, symbols: list, source: str):
    """Start monitoring specific symbols"""
    global monitor_process
    
    await update.message.reply_text(f"🚀 Starting news monitor for {len(symbols)} stocks...")
    
    try:
        # Get the path to news_monitor.py
        script_dir = os.path.dirname(os.path.abspath(__file__))
        monitor_script = os.path.join(script_dir, "news_monitor.py")
        python_exe = os.path.join(script_dir, ".venv", "Scripts", "python.exe")
        
        if not os.path.exists(monitor_script):
            await update.message.reply_text("❌ news_monitor.py not found!")
            return
        
        # Start the monitor as a subprocess with symbols
        cmd = [python_exe, monitor_script, "start"] + symbols
        monitor_process = subprocess.Popen(
            cmd,
            cwd=script_dir,
            creationflags=subprocess.CREATE_NEW_CONSOLE  # Opens in new window on Windows
        )
        
        symbols_list = ", ".join(symbols[:10])
        if len(symbols) > 10:
            symbols_list += f"... (+{len(symbols)-10} more)"
        
        await update.message.reply_text(
            f"✅ *News Monitor Started!*\n\n"
            f"📡 Monitoring: {source}\n"
            f"📋 Stocks: {symbols_list}\n"
            f"🔔 You'll receive alerts when news is detected.\n\n"
            "Use /stopmonitor to stop monitoring.",
            parse_mode='Markdown'
        )
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error starting monitor: {str(e)}")


async def stop_monitor(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Stop the news monitoring"""
    global monitor_process
    
    if monitor_process is None or monitor_process.poll() is not None:
        await update.message.reply_text("ℹ️ News monitor is not running.")
        return
    
    try:
        monitor_process.terminate()
        monitor_process.wait(timeout=5)
        monitor_process = None
        await update.message.reply_text("🛑 News monitor stopped.")
    except Exception as e:
        # Force kill if terminate didn't work
        try:
            monitor_process.kill()
            monitor_process = None
            await update.message.reply_text("🛑 News monitor force stopped.")
        except:
            await update.message.reply_text(f"❌ Error stopping monitor: {str(e)}")


async def monitor_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Check if news monitor is running"""
    global monitor_process
    
    if monitor_process is not None and monitor_process.poll() is None:
        await update.message.reply_text("✅ News monitor is *running*", parse_mode='Markdown')
    else:
        await update.message.reply_text("⏹️ News monitor is *stopped*\n\nUse /monitor to start.", parse_mode='Markdown')


async def trending(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Get Reddit trending stocks using ApeWisdom API - styled like swaggystocks"""
    await update.message.reply_text("⏳ Fetching Reddit trending stocks...")
    
    try:
        import requests
        import html
        
        # Use ApeWisdom API - aggregates mentions from wallstreetbets, stocks, investing, etc.
        url = "https://apewisdom.io/api/v1.0/filter/all-stocks"
        headers = {'User-Agent': 'StockBot/1.0'}
        
        response = requests.get(url, headers=headers, timeout=15)
        
        if response.status_code != 200:
            await update.message.reply_text("❌ Failed to fetch trending data")
            return
        
        data = response.json()
        results = data.get('results', [])[:10]  # Top 10
        
        if not results:
            await update.message.reply_text("📭 No trending stocks found")
            return
        
        message = "🔥 *WSB Trending Stocks*\n\n"
        
        for stock_data in results:
            rank = stock_data.get('rank', '?')
            ticker = stock_data.get('ticker', 'N/A')
            name = html.unescape(stock_data.get('name', 'Unknown'))
            mentions = stock_data.get('mentions', 0)
            upvotes = stock_data.get('upvotes', 0)
            rank_24h = stock_data.get('rank_24h_ago', 0)
            mentions_24h = stock_data.get('mentions_24h_ago', 0)
            
            # Calculate sentiment based on upvote/mention ratio and momentum
            # Higher upvotes per mention = more bullish sentiment
            upvote_ratio = upvotes / mentions if mentions > 0 else 0
            
            # Calculate rank change momentum
            rank_change = (rank_24h - rank) if rank_24h and rank_24h > 0 else 0
            
            # Calculate mention growth
            mention_growth = 0
            if mentions_24h and mentions_24h > 0:
                mention_growth = ((mentions - mentions_24h) / mentions_24h) * 100
            
            # Estimate sentiment (simplified algorithm)
            # Factors: upvote ratio (positive engagement), rank change (momentum), mention growth
            sentiment_score = 50  # Start neutral
            
            # Upvote ratio impact (avg ~10-20 upvotes per mention is neutral)
            if upvote_ratio > 30:
                sentiment_score += 20
            elif upvote_ratio > 15:
                sentiment_score += 10
            elif upvote_ratio < 5:
                sentiment_score -= 10
            
            # Rank change impact
            if rank_change > 10:
                sentiment_score += 15
            elif rank_change > 5:
                sentiment_score += 10
            elif rank_change > 0:
                sentiment_score += 5
            elif rank_change < -10:
                sentiment_score -= 15
            elif rank_change < -5:
                sentiment_score -= 10
            elif rank_change < 0:
                sentiment_score -= 5
            
            # Mention growth impact
            if mention_growth > 50:
                sentiment_score += 10
            elif mention_growth > 20:
                sentiment_score += 5
            elif mention_growth < -30:
                sentiment_score -= 10
            elif mention_growth < -10:
                sentiment_score -= 5
            
            # Clamp sentiment to 0-100
            sentiment_score = max(0, min(100, sentiment_score))
            
            # Determine sentiment label
            if sentiment_score >= 65:
                sentiment = "🟢 Bullish"
                sentiment_pct = sentiment_score
            elif sentiment_score <= 35:
                sentiment = "🔴 Bearish"
                sentiment_pct = 100 - sentiment_score
            else:
                sentiment = "⚪ Neutral"
                sentiment_pct = 50 + abs(50 - sentiment_score)
            
            # Truncate name if too long
            if len(name) > 25:
                name = name[:22] + "..."
            
            # Format like swaggystocks
            message += f"*{ticker}*  _WSB Rank #{rank}_\n"
            message += f"📊 {mentions} mentions  •  {sentiment} {sentiment_pct}%\n"
            message += f"_{name}_\n\n"
        
        message += "_Data from ApeWisdom • Updated every few hours_"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


async def hype(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Check Reddit hype/sentiment for a specific stock - /hype AAPL"""
    if not context.args:
        await update.message.reply_text(
            "📊 *Reddit Hype Checker*\n\n"
            "Usage: `/hype SYMBOL`\n"
            "Example: `/hype AAPL`\n\n"
            "Check how hyped a stock is on Reddit (WSB, stocks, investing)",
            parse_mode='Markdown'
        )
        return
    
    symbol = context.args[0].upper()
    await update.message.reply_text(f"⏳ Checking Reddit hype for *{symbol}*...", parse_mode='Markdown')
    
    try:
        import requests
        import html
        import re
        from bs4 import BeautifulSoup
        
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        
        # First, try to get data from the ApeWisdom API (all stocks list)
        api_url = "https://apewisdom.io/api/v1.0/filter/all-stocks"
        api_response = requests.get(api_url, headers=headers, timeout=15)
        
        stock_data = None
        all_stocks = []
        
        if api_response.status_code == 200:
            data = api_response.json()
            all_stocks = data.get('results', [])
            total_stocks = data.get('count', 0)
            
            # Find the stock in the list
            for stock in all_stocks:
                if stock.get('ticker', '').upper() == symbol:
                    stock_data = stock
                    break
        
        # Try to scrape the individual stock page for more details
        page_url = f"https://apewisdom.io/stocks/{symbol}"
        page_response = requests.get(page_url, headers=headers, timeout=15)
        
        page_sentiment = None
        page_keywords = []
        wsb_mentions = None
        wsb_sentiment = None
        positive_pct = None
        negative_pct = None
        
        if page_response.status_code == 200:
            soup = BeautifulSoup(page_response.text, 'html.parser')
            page_text = soup.get_text()
            
            # Extract sentiment percentage
            sentiment_match = re.search(r'Sentiment\s*(\d+)%', page_text)
            if sentiment_match:
                page_sentiment = int(sentiment_match.group(1))
            
            # Extract positive/negative breakdown
            pos_neg_match = re.search(r'received\s*(\d+)%\s*positive.*?(\d+)%\s*negative', page_text, re.IGNORECASE)
            if pos_neg_match:
                positive_pct = int(pos_neg_match.group(1))
                negative_pct = int(pos_neg_match.group(2))
            
            # Extract nearby keywords
            keywords_match = re.search(r'Nearby keywords:\s*([^\[]+)', page_text)
            if keywords_match:
                raw_keywords = keywords_match.group(1)
                # Parse keywords like "msft x8 calls x7 amzn x4"
                keyword_pairs = re.findall(r'(\w+)\s*x(\d+)', raw_keywords)
                page_keywords = [(k, int(c)) for k, c in keyword_pairs[:10]]
            
            # Extract WSB specific data
            wsb_match = re.search(r'mentioned\s*(\d+)\s*times\s*on\s*WallstreetBets', page_text)
            if wsb_match:
                wsb_mentions = int(wsb_match.group(1))
            
            wsb_sentiment_match = re.search(r'Sentiment on WSB[^\d]*(\d+)%', page_text)
            if wsb_sentiment_match:
                wsb_sentiment = int(wsb_sentiment_match.group(1))
        
        # Get stock info from yfinance
        try:
            stock = yf.Ticker(symbol)
            info = stock.info
            stock_name = info.get('longName', info.get('shortName', symbol))
            current_price = info.get('currentPrice') or info.get('regularMarketPrice', 0)
            market_cap = info.get('marketCap', 0)
            day_change = info.get('regularMarketChangePercent', 0)
        except:
            stock_name = symbol
            current_price = 0
            market_cap = 0
            day_change = 0
        
        # Build the response message
        message = f"🔥 *Reddit Hype Analysis: {symbol}*\n"
        message += f"_{stock_name}_\n\n"
        
        if current_price:
            message += f"💰 *Price:* ${current_price:.2f}"
            if day_change:
                emoji = "📈" if day_change > 0 else "📉"
                message += f" ({emoji} {day_change:+.2f}%)"
            message += "\n"
        
        if market_cap:
            if market_cap >= 1e12:
                cap_str = f"${market_cap/1e12:.2f}T"
            elif market_cap >= 1e9:
                cap_str = f"${market_cap/1e9:.2f}B"
            else:
                cap_str = f"${market_cap/1e6:.0f}M"
            message += f"📊 *Market Cap:* {cap_str}\n"
        
        message += "\n━━━━━━━━━━━━━━━━━━━━\n"
        message += "📱 *Reddit Sentiment*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        if stock_data:
            rank = stock_data.get('rank', 'N/A')
            mentions = stock_data.get('mentions', 0)
            upvotes = stock_data.get('upvotes', 0)
            rank_24h = stock_data.get('rank_24h_ago', 0)
            mentions_24h = stock_data.get('mentions_24h_ago', 0)
            
            message += f"🏆 *WSB Rank:* #{rank} of {total_stocks}\n"
            
            # Rank change
            if rank_24h and rank_24h > 0:
                rank_change = rank_24h - rank
                if rank_change > 0:
                    message += f"   📈 Up {rank_change} positions from yesterday\n"
                elif rank_change < 0:
                    message += f"   📉 Down {abs(rank_change)} positions from yesterday\n"
                else:
                    message += f"   ➡️ Same position as yesterday\n"
            
            message += f"\n💬 *Mentions:* {mentions}"
            if mentions_24h and mentions_24h > 0:
                mention_change = ((mentions - mentions_24h) / mentions_24h) * 100
                emoji = "📈" if mention_change > 0 else "📉"
                message += f" ({emoji} {mention_change:+.0f}% vs 24h ago)"
            message += "\n"
            
            message += f"⬆️ *Upvotes:* {upvotes:,}\n"
        else:
            message += f"⚠️ *{symbol}* is not currently trending on Reddit\n"
            message += f"   (Not in top {total_stocks} discussed stocks)\n"
        
        # Sentiment from page scraping
        if page_sentiment is not None:
            sentiment_emoji = "🟢" if page_sentiment >= 60 else "🔴" if page_sentiment <= 40 else "⚪"
            message += f"\n{sentiment_emoji} *Overall Sentiment:* {page_sentiment}%"
            
            if positive_pct is not None and negative_pct is not None:
                message += f"\n   ✅ {positive_pct}% positive • ❌ {negative_pct}% negative"
        
        if wsb_sentiment is not None and wsb_sentiment != page_sentiment:
            wsb_emoji = "🟢" if wsb_sentiment >= 60 else "🔴" if wsb_sentiment <= 40 else "⚪"
            message += f"\n{wsb_emoji} *WSB Sentiment:* {wsb_sentiment}%"
        
        # Keywords
        if page_keywords:
            message += "\n\n🏷️ *Associated Keywords:*\n"
            keyword_str = ", ".join([f"`{k}` ({c})" for k, c in page_keywords[:8]])
            message += f"   {keyword_str}"
        
        # AI Analysis
        message += "\n\n━━━━━━━━━━━━━━━━━━━━\n"
        message += "🤖 *AI Analysis*\n"
        message += "━━━━━━━━━━━━━━━━━━━━\n\n"
        
        analysis = _generate_hype_analysis(
            symbol, stock_name, stock_data, page_sentiment, 
            positive_pct, negative_pct, page_keywords, 
            current_price, day_change, total_stocks
        )
        message += analysis
        
        message += "\n\n_Data from ApeWisdom.io_"
        
        await update.message.reply_text(message, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error checking hype: {str(e)}")


def _generate_hype_analysis(symbol, name, stock_data, sentiment, positive_pct, negative_pct, 
                           keywords, price, day_change, total_stocks):
    """Generate AI analysis based on Reddit hype data"""
    
    analysis_parts = []
    
    # Determine hype level
    if stock_data:
        rank = stock_data.get('rank', 999)
        mentions = stock_data.get('mentions', 0)
        upvotes = stock_data.get('upvotes', 0)
        rank_24h = stock_data.get('rank_24h_ago', 0)
        mentions_24h = stock_data.get('mentions_24h_ago', 0)
        
        # Hype level assessment
        if rank <= 5:
            hype_level = "🚀 *EXTREMELY HIGH HYPE*"
            analysis_parts.append(f"{symbol} is one of the TOP 5 most discussed stocks on Reddit right now.")
        elif rank <= 15:
            hype_level = "🔥 *HIGH HYPE*"
            analysis_parts.append(f"{symbol} is in the top 15 most discussed stocks, showing significant retail interest.")
        elif rank <= 50:
            hype_level = "📈 *MODERATE HYPE*"
            analysis_parts.append(f"{symbol} has moderate Reddit attention, ranking #{rank} among discussed stocks.")
        elif rank <= 100:
            hype_level = "📊 *LOW HYPE*"
            analysis_parts.append(f"{symbol} has some Reddit discussion but isn't a major focus (rank #{rank}).")
        else:
            hype_level = "😴 *MINIMAL HYPE*"
            analysis_parts.append(f"{symbol} has minimal Reddit attention currently.")
        
        # Momentum analysis
        if rank_24h and rank_24h > 0:
            rank_change = rank_24h - rank
            if rank_change >= 20:
                analysis_parts.append(f"⚡ *Surging Interest:* Jumped {rank_change} positions in 24h - something is happening!")
            elif rank_change >= 5:
                analysis_parts.append(f"📈 *Growing Interest:* Moving up in rankings, gaining traction.")
            elif rank_change <= -20:
                analysis_parts.append(f"📉 *Fading Interest:* Dropped {abs(rank_change)} positions - hype may be cooling off.")
            elif rank_change <= -5:
                analysis_parts.append(f"📉 *Declining Interest:* Slowly losing Reddit attention.")
        
        # Mention trend
        if mentions_24h and mentions_24h > 0:
            mention_growth = ((mentions - mentions_24h) / mentions_24h) * 100
            if mention_growth > 100:
                analysis_parts.append(f"💥 *Viral Alert:* Mentions more than doubled (+{mention_growth:.0f}%) - watch for volatility!")
            elif mention_growth > 30:
                analysis_parts.append(f"🔔 *Increasing Buzz:* Mentions up {mention_growth:.0f}% - building momentum.")
            elif mention_growth < -50:
                analysis_parts.append(f"📉 *Dying Down:* Mentions dropped {abs(mention_growth):.0f}% - interest waning.")
    else:
        hype_level = "❄️ *NO HYPE*"
        analysis_parts.append(f"{symbol} is NOT among the top discussed stocks on Reddit.")
        analysis_parts.append("This could mean: low retail interest, or the stock flies under the radar.")
    
    # Sentiment analysis
    if sentiment is not None:
        if sentiment >= 75:
            analysis_parts.append(f"💚 *Very Bullish Sentiment:* {sentiment}% positive - Reddit is very optimistic about this stock.")
        elif sentiment >= 60:
            analysis_parts.append(f"🟢 *Bullish Sentiment:* {sentiment}% positive - generally favorable Reddit opinion.")
        elif sentiment <= 30:
            analysis_parts.append(f"🔴 *Very Bearish Sentiment:* Only {sentiment}% positive - Reddit is pessimistic.")
        elif sentiment <= 45:
            analysis_parts.append(f"📉 *Bearish Sentiment:* {sentiment}% positive - more negative than positive comments.")
        else:
            analysis_parts.append(f"⚪ *Mixed Sentiment:* {sentiment}% positive - Reddit opinion is divided.")
    
    # Keyword context
    if keywords:
        keyword_names = [k[0].lower() for k in keywords[:5]]
        bullish_keywords = {'calls', 'buy', 'moon', 'bullish', 'long', 'hold', 'buying', 'green'}
        bearish_keywords = {'puts', 'sell', 'crash', 'bearish', 'short', 'selling', 'red', 'dump'}
        
        bullish_found = [k for k in keyword_names if k in bullish_keywords]
        bearish_found = [k for k in keyword_names if k in bearish_keywords]
        
        if bullish_found and not bearish_found:
            analysis_parts.append(f"🎯 *Keywords suggest bullish activity* (mentions of: {', '.join(bullish_found)})")
        elif bearish_found and not bullish_found:
            analysis_parts.append(f"⚠️ *Keywords suggest bearish activity* (mentions of: {', '.join(bearish_found)})")
        elif bullish_found and bearish_found:
            analysis_parts.append(f"⚔️ *Mixed signals in keywords* - both bullish ({', '.join(bullish_found)}) and bearish ({', '.join(bearish_found)}) terms.")
    
    # Final verdict
    analysis_parts.append("")  # Empty line
    
    if stock_data and sentiment is not None:
        rank = stock_data.get('rank', 999)
        
        if rank <= 10 and sentiment >= 65:
            analysis_parts.append("🎰 *VERDICT: HIGH RISK/HIGH REWARD* - Very hyped with bullish sentiment. Classic meme stock setup - could moon or dump. Trade carefully!")
        elif rank <= 10 and sentiment <= 40:
            analysis_parts.append("⚠️ *VERDICT: CAUTION* - Heavily discussed but sentiment is bearish. Reddit may be expecting a drop.")
        elif rank <= 30 and sentiment >= 60:
            analysis_parts.append("👍 *VERDICT: WATCH CLOSELY* - Good Reddit attention with positive sentiment. Could be building momentum.")
        elif rank <= 30 and sentiment <= 45:
            analysis_parts.append("🤔 *VERDICT: MIXED SIGNALS* - Being discussed but sentiment is negative. Do your own research.")
        elif rank > 100 and sentiment and sentiment >= 60:
            analysis_parts.append("💎 *VERDICT: UNDER THE RADAR* - Low hype but positive sentiment among those discussing it. Could be a sleeper.")
        elif rank > 100:
            analysis_parts.append("📊 *VERDICT: LOW RETAIL INTEREST* - Not a Reddit favorite. May trade more on fundamentals than hype.")
        else:
            analysis_parts.append("📈 *VERDICT: MODERATE INTEREST* - Some Reddit attention. Monitor for changes in sentiment or momentum.")
    elif not stock_data:
        analysis_parts.append("📋 *VERDICT: INSTITUTIONAL PLAY* - Not on Reddit's radar. Likely driven by fundamentals, not retail hype.")
    
    return hype_level + "\n\n" + "\n\n".join(analysis_parts)


