TRIGGERED_ALERTS_FILE = "triggered_alerts.json"

def _load_price_alerts():
    """Load price alerts from file"""
    try:
        if os.path.exists(PRICE_ALERTS_FILE):
            with open(PRICE_ALERTS_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
    except:
        pass
    return []

def _save_price_alerts(alerts):
    """Save price alerts to file"""
    try:
        with open(PRICE_ALERTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(alerts, f, indent=2)
    except Exception as e:
        print(f"Error saving price alerts: {e}")

def _load_triggered_alerts():
    """Load triggered alerts history from file"""
    try:
        if os.path.exists(TRIGGERED_ALERTS_FILE):
            with open(TRIGGERED_ALERTS_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
    except:
        pass
    return []

def _save_triggered_alerts(alerts):
    """Save triggered alerts history to file"""
    try:
        with open(TRIGGERED_ALERTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(alerts, f, indent=2)
    except Exception as e:
        print(f"Error saving triggered alerts: {e}")

def _cleanup_triggered_alerts():
    """Move triggered alerts from active to history file"""
    alerts = _load_price_alerts()
    triggered_history = _load_triggered_alerts()
    
    # Separate triggered and active alerts
    still_active = []
    newly_triggered = []
    
    for alert in alerts:
        if alert.get('triggered', False):
            newly_triggered.append(alert)
        else:
            still_active.append(alert)
    
    # Add newly triggered to history
    if newly_triggered:
        triggered_history.extend(newly_triggered)
        _save_triggered_alerts(triggered_history)
        _save_price_alerts(still_active)
    
    return len(newly_triggered), len(still_active)


async def triggered_alerts_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show history of triggered price alerts - /triggered"""
    if not is_authorized(update.effective_user.id):
        await unauthorized_message(update)
        return
    
    if context.args and context.args[0].lower() == 'clear':
        _save_triggered_alerts([])
        await update.message.reply_text("✅ Triggered alerts history cleared.")
        return

    history = _load_triggered_alerts()
    active_triggered = [a for a in _load_price_alerts() if a.get('triggered')]
    triggered = active_triggered + history

    if not triggered:
        await update.message.reply_text(
            "📭 *No Triggered Alerts*\n\n"
            "When price alerts trigger, they'll appear here.",
            parse_mode='Markdown'
        )
        return

    triggered.sort(key=lambda x: x.get('triggered_at', ''), reverse=True)

    header = "📜 *Triggered Alerts*\n━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
    footer = f"_Total: {len(triggered)} triggered alerts_\n_Use `/triggered clear` to clear history_"

    blocks = []
    for i, alert in enumerate(triggered, 1):
        direction_emoji = "📈" if alert['direction'] == 'UP' else "📉"
        target_price = alert.get('target_price', 0)
        triggered_price = alert.get('triggered_price', target_price)
        triggered_at = alert.get('triggered_at', 'Unknown')
        alert_type = alert.get('alert_type', 'percent')

        block = f"{i}. *{alert['symbol']}* {direction_emoji}\n"
        if alert_type == 'price_target':
            block += f"   🎯 Target: ${target_price:.2f}\n"
        else:
            block += f"   Alert: {alert['direction']} {alert.get('percent', 0):.1f}%\n"
            block += f"   Target: ${target_price:.2f}\n"
        block += f"   ✅ Hit: ${triggered_price:.2f}\n"
        block += f"   📅 {triggered_at}\n"
        if alert.get('note'):
            clean_note = alert['note'].replace('\n', ' ').replace('_', ' ')
            block += f"   📝 _{clean_note}_\n"
        block += "\n"
        blocks.append(block)

    CHUNK_LIMIT = 3800
    chunks = []
    current = header
    for block in blocks:
        if len(current) + len(block) > CHUNK_LIMIT:
            chunks.append(current)
            current = ""
        current += block
    if len(current) + len(footer) > CHUNK_LIMIT:
        chunks.append(current)
        chunks.append(footer)
    else:
        chunks.append(current + footer)

    for chunk in chunks:
        await update.message.reply_text(chunk, parse_mode='Markdown')


