def _get_israeli_fund_data(fund_number: str) -> dict:
    """Fetch Israeli mutual fund data from Bizportal"""
    import requests
    from bs4 import BeautifulSoup
    import re
    
    result = {
        'fund_number': fund_number,
        'name': None,
        'price': None,
        'currency': 'ILS',
        'daily_change': None,
        'monthly_change': None,
        'yearly_change': None,
        'error': None
    }
    
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept-Language': 'en-US,en;q=0.9,he;q=0.8'
        }
        
        # Use Bizportal - cleaner data format
        url = f"https://www.bizportal.co.il/mutualfunds/quote/generalview/{fund_number}"
        response = requests.get(url, headers=headers, timeout=15)
        
        if response.status_code != 200:
            result['error'] = f"HTTP {response.status_code}"
            return result
        
        soup = BeautifulSoup(response.text, 'html.parser')
        page_text = response.text
        
        # Get fund name from h1
        title = soup.find('h1')
        if title:
            result['name'] = title.get_text(strip=True)
        
        # Bizportal format: "מחיר פדיון 266.03  מחיר קנייה 266.03 -1.32%"
        # Price pattern
        price_match = re.search(r'מחיר (?:פדיון|קנייה)\s*([\d.]+)', page_text)
        if price_match:
            try:
                result['price'] = float(price_match.group(1))
            except:
                pass
        
        # Daily change - right after price, format: "-1.32%"
        daily_match = re.search(r'מחיר קנייה\s*[\d.]+\s*([+-]?[\d.]+)%', page_text)
        if daily_match:
            try:
                result['daily_change'] = float(daily_match.group(1))
            except:
                pass
        
        # Monthly change - "% החודש: 5.92%"
        monthly_match = re.search(r'% החודש:\s*([+-]?[\d.]+)%', page_text)
        if monthly_match:
            try:
                result['monthly_change'] = float(monthly_match.group(1))
            except:
                pass
        
        # Yearly change - "% 12 חודשים: 44.58%" or "% השנה:"
        yearly_match = re.search(r'% 12 חודשים:\s*([+-]?[\d.]+)%', page_text)
        if yearly_match:
            try:
                result['yearly_change'] = float(yearly_match.group(1))
            except:
                pass
        
        # Alternative: YTD
        if not result['yearly_change']:
            ytd_match = re.search(r'% השנה:\s*([+-]?[\d.]+)%', page_text)
            if ytd_match:
                try:
                    result['yearly_change'] = float(ytd_match.group(1))
                except:
                    pass
        
        if not result['price'] and not result['daily_change']:
            result['error'] = "Could not parse fund data"
            
    except Exception as e:
        result['error'] = str(e)
    
    return result


def _get_israeli_stock_data(symbol: str) -> dict:
    """Fetch Israeli stock data from yfinance using .TA suffix
    
    This uses yfinance which provides TASE data with .TA suffix.
    Price is in ILA (Israeli Agorot, 1/100 of a Shekel).
    """
    import yfinance as yf
    
    result = {
        'symbol': symbol,
        'name': None,
        'price': None,
        'price_ils': None,  # Price in Shekels
        'currency': 'ILA',
        'daily_change': None,
        'daily_change_pct': None,
        'prev_close': None,
        'open': None,
        'high': None,
        'low': None,
        'volume': None,
        'market_cap': None,
        'error': None
    }
    
    try:
        # Ensure .TA suffix for TASE
        yahoo_symbol = symbol if symbol.upper().endswith('.TA') else f"{symbol}.TA"
        
        stock = yf.Ticker(yahoo_symbol)
        info = stock.info
        
        if not info or info.get('regularMarketPrice') is None:
            result['error'] = f"Symbol {symbol} not found on TASE"
            return result
        
        result['name'] = info.get('shortName', info.get('longName', symbol))
        result['price'] = info.get('currentPrice', info.get('regularMarketPrice'))
        result['currency'] = info.get('currency', 'ILA')
        
        # Convert to ILS if in ILA (Agorot)
        if result['price'] and result['currency'] == 'ILA':
            result['price_ils'] = result['price'] / 100  # 100 Agorot = 1 Shekel
        else:
            result['price_ils'] = result['price']
        
        result['daily_change_pct'] = info.get('regularMarketChangePercent')
        result['daily_change'] = info.get('regularMarketChange')
        result['prev_close'] = info.get('previousClose', info.get('regularMarketPreviousClose'))
        result['open'] = info.get('regularMarketOpen')
        result['high'] = info.get('regularMarketDayHigh')
        result['low'] = info.get('regularMarketDayLow')
        result['volume'] = info.get('regularMarketVolume')
        result['market_cap'] = info.get('marketCap')
        
    except Exception as e:
        result['error'] = str(e)
    
    return result


