    emoji = "🟩" if change_pct >= 0 else "🔴"
    change_sign = "+" if change_pct >= 0 else ""
    
    msg = f"🇮🇱 *{data['name']}* ({symbol})\n"
    msg += f"━━━━━━━━━━━━━━━━━━━━\n"
