def _get_zacks_rating(symbol: str) -> dict:
    """Scrape Zacks rating for a stock"""
    import requests
    from bs4 import BeautifulSoup
    
    result = {
        'symbol': symbol.upper(),
        'rank': None,
        'rank_text': None,
        'style_scores': {},
        'industry_rank': None,
        'recommendation': None,
        'error': None
    }
    
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        }
        
        url = f"https://www.zacks.com/stock/quote/{symbol}"
        response = requests.get(url, headers=headers, timeout=15)
        
        if response.status_code != 200:
            result['error'] = f"HTTP {response.status_code}"
            return result
        
        soup = BeautifulSoup(response.text, 'lxml')
        
        # Get Zacks Rank (1-5)
        rank_elem = soup.find('p', class_='rank_view')
        if rank_elem:
            rank_text = rank_elem.get_text(strip=True)
            # Extract number and text
            if '1-Strong Buy' in rank_text or 'Strong Buy' in rank_text:
                result['rank'] = '1'
                result['rank_text'] = 'Strong Buy'
            elif '2-Buy' in rank_text or rank_text == 'Buy':
                result['rank'] = '2'
                result['rank_text'] = 'Buy'
            elif '3-Hold' in rank_text or rank_text == 'Hold':
                result['rank'] = '3'
                result['rank_text'] = 'Hold'
            elif '4-Sell' in rank_text or rank_text == 'Sell':
                result['rank'] = '4'
                result['rank_text'] = 'Sell'
            elif '5-Strong Sell' in rank_text or 'Strong Sell' in rank_text:
                result['rank'] = '5'
                result['rank_text'] = 'Strong Sell'
        
        # Alternative: look for rank in different elements (stocks and ETFs)
        if not result['rank']:
            rank_container = soup.find('div', class_='zr_rankbox')
            if rank_container:
                # Get all rank_chip spans
                all_chips = rank_container.find_all('span', class_='rank_chip')
                
                # For ETFs: look for rankrect_X class (not mfrankrect_X which is the legend)
                # The actual rank has class like "rankrect_3" for Hold, and contains the rank number
                for chip in all_chips:
                    classes = chip.get('class', [])
                    # Check if any class contains 'rankrect_' but not 'mfrankrect'
                    is_actual_rank = any('rankrect_' in c and 'mfrankrect' not in c for c in classes)
                    if is_actual_rank:
                        rank_num = chip.get_text(strip=True)
                        if rank_num and rank_num.isdigit():
                            result['rank'] = rank_num
                            rank_map = {'1': 'Strong Buy', '2': 'Buy', '3': 'Hold', '4': 'Sell', '5': 'Strong Sell'}
                            result['rank_text'] = rank_map.get(rank_num, 'Unknown')
                            break
        
        # Get Style Scores (VGM)
        style_section = soup.find('div', class_='zr_rankbox')
        if style_section:
            scores = style_section.find_all('span', class_='composite_val')
            score_labels = ['Value', 'Growth', 'Momentum', 'VGM']
            for i, score in enumerate(scores[:4]):
                if i < len(score_labels):
                    result['style_scores'][score_labels[i]] = score.get_text(strip=True)
        
        # Get Industry Rank
        industry_elem = soup.find('a', href=lambda x: x and '/zacks-industry-rank' in str(x))
        if industry_elem:
            industry_text = industry_elem.get_text(strip=True)
            result['industry_rank'] = industry_text
        
        # Generate recommendation
        if result['rank']:
            rank_int = int(result['rank'])
            if rank_int <= 2:
                result['recommendation'] = 'Consider buying - Zacks expects outperformance'
            elif rank_int == 3:
                result['recommendation'] = 'Hold - Neutral outlook'
            else:
                result['recommendation'] = 'Consider avoiding - Zacks expects underperformance'
        
    except Exception as e:
        result['error'] = str(e)
    
    return result


async def zacks_rating(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Get Zacks rating for a stock"""
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'zacks'
        await update.message.reply_text(
            "📊 *Zacks Rating*\n\n"
            "Send me a stock symbol to get Zacks analysis.\n"
            "Example: `AAPL` or `NVDA`",
            parse_mode='Markdown'
        )
        return
    
    symbol = context.args[0].upper()
    await _do_zacks(update, symbol)


async def _do_zacks(update: Update, symbol: str):
    """Execute Zacks rating lookup"""
    await update.message.reply_text(f"⏳ Fetching Zacks rating for {symbol}...")
    
    try:
        # Use run_in_executor to avoid blocking the event loop
        loop = asyncio.get_event_loop()
        rating = await loop.run_in_executor(None, _get_zacks_rating, symbol)
        
        if rating['error']:
            await update.message.reply_text(f"❌ Error fetching Zacks data: {rating['error']}")
            return
        
        if not rating['rank']:
            await update.message.reply_text(f"❌ Could not find Zacks rating for {symbol}")
            return
        
        # Rank emoji
        rank_emoji = {
            '1': '🌟🟢',
            '2': '✅🟢',
            '3': '🟡',
            '4': '⚠️🔴',
            '5': '🔴❌'
        }.get(rating['rank'], '❓')
        
        message = f"📊 *ZACKS RATING: {symbol}*\n"
        message += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        message += f"{rank_emoji} *Zacks Rank: #{rating['rank']} - {rating['rank_text']}*\n\n"
        
        # Style Scores
        if rating['style_scores']:
            message += f"📈 *Style Scores:*\n"
            for score_name, score_val in rating['style_scores'].items():
                score_emoji = '🟢' if score_val in ['A', 'B'] else '🟡' if score_val == 'C' else '🔴'
                message += f"   {score_emoji} {score_name}: {score_val}\n"
            message += "\n"
        
        # Industry Rank
        if rating['industry_rank']:
            message += f"🏭 *Industry:* {rating['industry_rank']}\n\n"
        
        # Recommendation
        if rating['recommendation']:
            message += f"💡 *Recommendation:*\n{rating['recommendation']}\n\n"
        
        # Add link
        message += f"🔗 [View on Zacks](https://www.zacks.com/stock/quote/{symbol})"
        
        await update.message.reply_text(message, parse_mode='Markdown', disable_web_page_preview=True)
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)}")


