async def _run_deep_analysis(update: Update, symbol: str, model: str = 'sonar-pro'):
    """Run comprehensive deep analysis for a stock"""
    import math
    model_names = {'sonar-pro': '⚡ Sonar Pro', 'sonar-reasoning': '🧠 Reasoning', 'sonar-deep-research': '🔬 Deep Research'}
    model_label = model_names.get(model, model)
    
    await update.message.reply_text(
        f"🔬 *Running Deep Analysis for {symbol}*\n"
        f"🤖 Model: {model_label}\n\n"
        f"⏳ This will take 30-60 seconds..."
        f"{'\n⚠️ Deep Research mode may take 2-3 minutes...' if model == 'sonar-deep-research' else ''}\n"
        f"Analyzing: News, Trends, Analyst Ratings, Technicals, AI Insights",
        parse_mode='Markdown'
    )
    
    try:
        # ═══════════════════════════════════════════════════════════════
        # SECTION 1: BASIC DATA COLLECTION
        # ═══════════════════════════════════════════════════════════════
        stock = yf.Ticker(symbol)
        info = stock.info
        
        if not info or info.get('regularMarketPrice') is None:
            await update.message.reply_text(f"❌ Could not find stock: {symbol}")
            return
        
        # Basic info
        name = info.get('longName', info.get('shortName', symbol))
        sector = info.get('sector', 'Unknown')
        industry = info.get('industry', 'Unknown')
        current_price = info.get('regularMarketPrice') or info.get('currentPrice', 0)
        market_cap = info.get('marketCap', 0)
        
        # Historical data
        hist_1y = stock.history(period='1y')
        hist_3mo = stock.history(period='3mo')
        hist_1mo = stock.history(period='1mo')
        hist_5d = stock.history(period='5d')
        
        if hist_1y.empty:
            await update.message.reply_text(f"❌ No historical data for {symbol}")
            return
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 2: PRICE ANALYSIS
        # ═══════════════════════════════════════════════════════════════
        high_52w = info.get('fiftyTwoWeekHigh', current_price)
        low_52w = info.get('fiftyTwoWeekLow', current_price)
        avg_50d = info.get('fiftyDayAverage', current_price)
        avg_200d = info.get('twoHundredDayAverage', current_price)
        
        # Calculate returns
        def safe_return(hist, days):
            if len(hist) >= days:
                old = hist['Close'].iloc[-days]
                new = hist['Close'].iloc[-1]
                return ((new - old) / old) * 100 if old else 0
            return 0
        
        return_1w = safe_return(hist_5d, min(5, len(hist_5d)))
        return_1m = safe_return(hist_1mo, min(21, len(hist_1mo)))
        return_3m = safe_return(hist_3mo, min(63, len(hist_3mo)))
        return_1y = safe_return(hist_1y, min(252, len(hist_1y)))
        
        # Position in 52-week range
        range_position = ((current_price - low_52w) / (high_52w - low_52w)) * 100 if high_52w != low_52w else 50
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 3: TECHNICAL INDICATORS
        # ═══════════════════════════════════════════════════════════════
        closes = hist_1y['Close']
        
        # RSI (14-day)
        delta = closes.diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        rs = gain / loss
        rsi = 100 - (100 / (1 + rs.iloc[-1])) if loss.iloc[-1] != 0 else 50
        
        # MACD
        ema12 = closes.ewm(span=12, adjust=False).mean()
        ema26 = closes.ewm(span=26, adjust=False).mean()
        macd_line = ema12 - ema26
        signal_line = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist = macd_line.iloc[-1] - signal_line.iloc[-1]
        
        # Bollinger Bands
        sma20 = closes.rolling(window=20).mean()
        std20 = closes.rolling(window=20).std()
        bb_upper = sma20.iloc[-1] + (2 * std20.iloc[-1])
        bb_lower = sma20.iloc[-1] - (2 * std20.iloc[-1])
        bb_position = ((current_price - bb_lower) / (bb_upper - bb_lower)) * 100 if bb_upper != bb_lower else 50
        
        # Volume analysis
        avg_volume = hist_1y['Volume'].mean()
        current_volume = hist_1y['Volume'].iloc[-1]
        volume_ratio = current_volume / avg_volume if avg_volume > 0 else 1
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 4: FUNDAMENTAL METRICS
        # ═══════════════════════════════════════════════════════════════
        pe_trailing = info.get('trailingPE', 0)
        pe_forward = info.get('forwardPE', 0)
        peg_ratio = info.get('pegRatio', 0)
        pb_ratio = info.get('priceToBook', 0)
        ps_ratio = info.get('priceToSalesTrailing12Months', 0)
        profit_margin = info.get('profitMargins', 0) * 100 if info.get('profitMargins') else 0
        roe = info.get('returnOnEquity', 0) * 100 if info.get('returnOnEquity') else 0
        debt_equity = info.get('debtToEquity', 0)
        revenue_growth = info.get('revenueGrowth', 0) * 100 if info.get('revenueGrowth') else 0
        earnings_growth = info.get('earningsGrowth', 0) * 100 if info.get('earningsGrowth') else 0
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 5: ANALYST RATINGS & TARGETS
        # ═══════════════════════════════════════════════════════════════
        target_mean = info.get('targetMeanPrice', current_price)
        target_high = info.get('targetHighPrice', current_price)
        target_low = info.get('targetLowPrice', current_price)
        recommendation = info.get('recommendationKey', 'none')
        num_analysts = info.get('numberOfAnalystOpinions', 0)
        
        upside = ((target_mean - current_price) / current_price) * 100 if current_price else 0
        
        # Get analyst recommendations breakdown
        recommendations = stock.recommendations
        recent_recs = {}
        if recommendations is not None and not recommendations.empty:
            recent = recommendations.tail(20)
            for _, row in recent.iterrows():
                firm = row.get('Firm', 'Unknown')
                grade = row.get('To Grade', row.get('toGrade', 'Unknown'))
                action = row.get('Action', '')
                recent_recs[firm] = {'grade': grade, 'action': action}
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 6: NEWS ANALYSIS
        # ═══════════════════════════════════════════════════════════════
        news = stock.news
        news_sentiment = 0
        news_count = len(news) if news else 0
        news_items = []  # Store headline + link
        
        if news:
            for item in news[:10]:
                headline = item.get('title', '')
                link = item.get('link', '')
                publisher = item.get('publisher', '')
                # Only add if both title and link are present
                if headline and link:
                    news_items.append({'headline': headline, 'link': link, 'publisher': publisher})
                # Simple sentiment scoring
                positive_words = ['up', 'gain', 'rise', 'surge', 'beat', 'profit', 'growth', 'bullish', 'buy', 'upgrade']
                negative_words = ['down', 'fall', 'drop', 'miss', 'loss', 'decline', 'bearish', 'sell', 'downgrade', 'cut']
                headline_lower = headline.lower()
                for word in positive_words:
                    if word in headline_lower:
                        news_sentiment += 1
                for word in negative_words:
                    if word in headline_lower:
                        news_sentiment -= 1
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 7: SCORING SYSTEM
        # ═══════════════════════════════════════════════════════════════
        
        # Swing Trading Score (technical-heavy)
        swing_score = 0
        swing_reasons = []
        
        # RSI
        if 30 <= rsi <= 40:
            swing_score += 20
            swing_reasons.append(f"RSI oversold bounce zone ({rsi:.0f})")
        elif 60 <= rsi <= 70:
            swing_score += 10
            swing_reasons.append(f"RSI momentum ({rsi:.0f})")
        elif rsi < 30:
            swing_score += 15
            swing_reasons.append(f"RSI deeply oversold ({rsi:.0f})")
        elif rsi > 70:
            swing_score -= 10
            swing_reasons.append(f"⚠️ RSI overbought ({rsi:.0f})")
        
        # MACD
        if macd_hist > 0:
            swing_score += 15
            swing_reasons.append("MACD bullish crossover")
        else:
            swing_reasons.append("MACD bearish")
        
        # Bollinger Bands
        if bb_position < 20:
            swing_score += 20
            swing_reasons.append("Near lower Bollinger Band (oversold)")
        elif bb_position > 80:
            swing_reasons.append("⚠️ Near upper Bollinger Band (overbought)")
        
        # Volume
        if volume_ratio > 1.5:
            swing_score += 10
            swing_reasons.append(f"High volume ({volume_ratio:.1f}x avg)")
        
        # Price vs MAs
        if current_price > avg_50d and avg_50d > avg_200d:
            swing_score += 15
            swing_reasons.append("Price above 50/200 MA (uptrend)")
        elif current_price < avg_50d and avg_50d < avg_200d:
            swing_reasons.append("⚠️ Below MAs (downtrend)")
        
        swing_score = max(0, min(100, swing_score + 40))  # Base 40
        
        # Short-Term Score (1-3 months - momentum + analysts)
        short_score = 0
        short_reasons = []
        
        # Recent performance
        if return_1m > 5:
            short_score += 15
            short_reasons.append(f"Strong month (+{return_1m:.1f}%)")
        elif return_1m < -10:
            short_reasons.append(f"⚠️ Weak month ({return_1m:.1f}%)")
        
        # RSI
        if 40 <= rsi <= 65:
            short_score += 15
            short_reasons.append(f"Healthy RSI ({rsi:.0f})")
        
        # Analyst sentiment
        if recommendation in ['strongBuy', 'buy']:
            short_score += 20
            short_reasons.append(f"Analysts: {recommendation}")
        elif recommendation == 'hold':
            short_score += 10
            short_reasons.append("Analysts: Hold")
        
        # Upside potential
        if upside > 15:
            short_score += 15
            short_reasons.append(f"Target upside +{upside:.0f}%")
        elif upside < -10:
            short_reasons.append(f"⚠️ Below target ({upside:.0f}%)")
        
        # News momentum
        if news_sentiment > 0:
            short_score += 10
            short_reasons.append("Positive news sentiment")
        elif news_sentiment < 0:
            short_reasons.append("⚠️ Negative news")
        
        short_score = max(0, min(100, short_score + 35))  # Base 35
        
        # Medium-Term Score (3-12 months - growth + value)
        medium_score = 0
        medium_reasons = []
        
        # Revenue/Earnings growth
        if revenue_growth > 15:
            medium_score += 20
            medium_reasons.append(f"Strong revenue growth ({revenue_growth:.0f}%)")
        elif revenue_growth > 5:
            medium_score += 10
            medium_reasons.append(f"Moderate revenue growth ({revenue_growth:.0f}%)")
        
        if earnings_growth > 20:
            medium_score += 20
            medium_reasons.append(f"Strong earnings growth ({earnings_growth:.0f}%)")
        
        # PE valuation
        if pe_forward and pe_forward > 0:
            if pe_forward < 15:
                medium_score += 15
                medium_reasons.append(f"Low forward P/E ({pe_forward:.1f})")
            elif pe_forward < 25:
                medium_score += 10
                medium_reasons.append(f"Fair forward P/E ({pe_forward:.1f})")
            elif pe_forward > 50:
                medium_reasons.append(f"⚠️ High P/E ({pe_forward:.1f})")
        
        # PEG ratio
        if peg_ratio and 0 < peg_ratio < 1:
            medium_score += 15
            medium_reasons.append(f"Excellent PEG ({peg_ratio:.2f})")
        elif peg_ratio and 1 <= peg_ratio < 2:
            medium_score += 10
            medium_reasons.append(f"Good PEG ({peg_ratio:.2f})")
        
        # Range position
        if range_position < 40:
            medium_score += 10
            medium_reasons.append("Trading in lower range")
        
        medium_score = max(0, min(100, medium_score + 30))  # Base 30
        
        # Long-Term Score (1-5 years - fundamentals)
        long_score = 0
        long_reasons = []
        
        # Profitability
        if profit_margin > 20:
            long_score += 20
            long_reasons.append(f"Excellent margins ({profit_margin:.1f}%)")
        elif profit_margin > 10:
            long_score += 10
            long_reasons.append(f"Good margins ({profit_margin:.1f}%)")
        
        # ROE
        if roe > 20:
            long_score += 15
            long_reasons.append(f"Strong ROE ({roe:.1f}%)")
        elif roe > 10:
            long_score += 10
            long_reasons.append(f"Decent ROE ({roe:.1f}%)")
        
        # Debt
        if debt_equity and debt_equity < 50:
            long_score += 15
            long_reasons.append(f"Low debt ({debt_equity:.0f}%)")
        elif debt_equity and debt_equity > 100:
            long_reasons.append(f"⚠️ High debt ({debt_equity:.0f}%)")
        
        # Market position
        if market_cap > 100e9:
            long_score += 10
            long_reasons.append("Large-cap stability")
        elif market_cap > 10e9:
            long_score += 5
            long_reasons.append("Mid-cap")
        
        # Revenue growth consistency
        if revenue_growth > 10:
            long_score += 15
            long_reasons.append("Sustained growth")
        
        long_score = max(0, min(100, long_score + 25))  # Base 25
        
        # ═══════════════════════════════════════════════════════════════
        # SECTION 8: BUILD REPORT MESSAGE
        # ═══════════════════════════════════════════════════════════════
        
        def score_to_rating(score):
            if score >= 80: return "🌟 STRONG BUY"
            elif score >= 65: return "✅ BUY"
            elif score >= 50: return "🟡 HOLD"
            elif score >= 35: return "⚠️ CAUTION"
            else: return "🔴 AVOID"
        
        def format_market_cap(mc):
            if mc >= 1e12: return f"${mc/1e12:.2f}T"
            elif mc >= 1e9: return f"${mc/1e9:.1f}B"
            elif mc >= 1e6: return f"${mc/1e6:.1f}M"
            return f"${mc:,.0f}"
        
        # Part 1: Company Overview
        msg1 = f"🔬 *DEEP ANALYSIS: {symbol}*\n"
        msg1 += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        msg1 += f"*{name}*\n"
        msg1 += f"🏢 {sector} | {industry}\n"
        msg1 += f"💵 *${current_price:.2f}* | Cap: {format_market_cap(market_cap)}\n\n"
        
        msg1 += f"📈 *Performance:*\n"
        msg1 += f"   1W: {return_1w:+.1f}%  |  1M: {return_1m:+.1f}%\n"
        msg1 += f"   3M: {return_3m:+.1f}%  |  1Y: {return_1y:+.1f}%\n"
        msg1 += f"   52W Range: ${low_52w:.2f} - ${high_52w:.2f}\n"
        msg1 += f"   Position: {range_position:.0f}% of range\n"
        
        await update.message.reply_text(msg1, parse_mode='Markdown')
        
        # Part 2: Technical Analysis
        msg2 = f"📊 *TECHNICAL INDICATORS*\n"
        msg2 += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        msg2 += f"📍 RSI (14): {rsi:.1f} "
        if rsi < 30: msg2 += "(Oversold)\n"
        elif rsi > 70: msg2 += "(Overbought)\n"
        else: msg2 += "(Neutral)\n"
        
        msg2 += f"📍 MACD: {'Bullish' if macd_hist > 0 else 'Bearish'}\n"
        msg2 += f"📍 50-Day MA: ${avg_50d:.2f} ({'Above' if current_price > avg_50d else 'Below'})\n"
        msg2 += f"📍 200-Day MA: ${avg_200d:.2f} ({'Above' if current_price > avg_200d else 'Below'})\n"
        msg2 += f"📍 Volume: {volume_ratio:.1f}x average\n"
        msg2 += f"📍 Bollinger: {bb_position:.0f}% position\n"
        
        await update.message.reply_text(msg2, parse_mode='Markdown')
        
        # Part 3: Fundamentals
        msg3 = f"💰 *FUNDAMENTALS*\n"
        msg3 += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        msg3 += f"📍 P/E (TTM): {pe_trailing:.1f}\n" if pe_trailing else ""
        msg3 += f"📍 P/E (Fwd): {pe_forward:.1f}\n" if pe_forward else ""
        msg3 += f"📍 PEG Ratio: {peg_ratio:.2f}\n" if peg_ratio else ""
        msg3 += f"📍 P/B Ratio: {pb_ratio:.2f}\n" if pb_ratio else ""
        msg3 += f"📍 Profit Margin: {profit_margin:.1f}%\n" if profit_margin else ""
        msg3 += f"📍 ROE: {roe:.1f}%\n" if roe else ""
        msg3 += f"📍 Debt/Equity: {debt_equity:.0f}%\n" if debt_equity else ""
        msg3 += f"📍 Revenue Growth: {revenue_growth:+.1f}%\n" if revenue_growth else ""
        msg3 += f"📍 Earnings Growth: {earnings_growth:+.1f}%\n" if earnings_growth else ""
        
        await update.message.reply_text(msg3, parse_mode='Markdown')
        
        # Part 4: Analyst Ratings
        msg4 = f"👔 *ANALYST RATINGS*\n"
        msg4 += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        msg4 += f"🎯 *Price Targets:*\n"
        msg4 += f"   Low: ${target_low:.2f} | Mean: ${target_mean:.2f} | High: ${target_high:.2f}\n"
        msg4 += f"   Upside to Mean: {upside:+.1f}%\n"
        msg4 += f"   Analysts: {num_analysts}\n\n"
        msg4 += f"📊 Consensus: *{recommendation.upper() if recommendation else 'N/A'}*\n\n"
        
        # Show some recent analyst actions
        if recent_recs:
            msg4 += f"*Recent Actions:*\n"
            count = 0
            for firm, data in list(recent_recs.items())[:6]:
                msg4 += f"   • {firm[:15]}: {data['grade']}\n"
                count += 1
        
        # Add analyst research links
        msg4 += f"\n🔗 *Analyst Research:*\n"
        msg4 += f"• [TipRanks](https://www.tipranks.com/stocks/{symbol}/forecast)\n"
        msg4 += f"• [Zacks Ratings](https://www.zacks.com/stock/quote/{symbol})\n"
        msg4 += f"• [Benzinga](https://www.benzinga.com/quote/{symbol})\n"
        
        await update.message.reply_text(msg4, parse_mode='Markdown', disable_web_page_preview=True)
        
        # Part 5: News with clickable links
        msg5 = f"📰 *NEWS & LINKS*\n"
        msg5 += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        msg5 += f"Sentiment Score: {news_sentiment:+d} "
        if news_sentiment > 0: msg5 += "(Positive)\n"
        elif news_sentiment < 0: msg5 += "(Negative)\n"
        else: msg5 += "(Neutral)\n"
        msg5 += f"Recent articles: {news_count}\n\n"
        
        if news_items:
            msg5 += "*Headlines:*\n"
            for i, item in enumerate(news_items[:5], 1):
                headline = item['headline'][:80]
                link = item['link']
                publisher = item['publisher'][:15] if item['publisher'] else ""
                msg5 += f"{i}. [{headline}]({link})\n"
        else:
            msg5 += "No recent news found from Yahoo Finance.\n"
        
        # Add useful research links
        msg5 += f"\n🔗 *Research Links:*\n"
        msg5 += f"• [Yahoo Finance](https://finance.yahoo.com/quote/{symbol})\n"
        msg5 += f"• [TradingView](https://www.tradingview.com/symbols/{symbol})\n"
        msg5 += f"• [MarketWatch](https://www.marketwatch.com/investing/stock/{symbol})\n"
        msg5 += f"• [Seeking Alpha](https://seekingalpha.com/symbol/{symbol})\n"
        msg5 += f"• [Finviz](https://finviz.com/quote.ashx?t={symbol})\n"
        
        await update.message.reply_text(msg5, parse_mode='Markdown', disable_web_page_preview=True)
        
        # Part 6: Timeframe Recommendations
        msg6 = f"🎯 *RECOMMENDATIONS BY TIMEFRAME*\n"
        msg6 += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        msg6 += f"⚡ *SWING TRADING* (Days-Weeks)\n"
        msg6 += f"   Score: {swing_score}/100 | {score_to_rating(swing_score)}\n"
        for reason in swing_reasons[:3]:
            msg6 += f"   • {reason}\n"
        msg6 += f"\n"
        
        msg6 += f"📅 *SHORT TERM* (1-3 Months)\n"
        msg6 += f"   Score: {short_score}/100 | {score_to_rating(short_score)}\n"
        for reason in short_reasons[:3]:
            msg6 += f"   • {reason}\n"
        msg6 += f"\n"
        
        msg6 += f"📆 *MEDIUM TERM* (3-12 Months)\n"
        msg6 += f"   Score: {medium_score}/100 | {score_to_rating(medium_score)}\n"
        for reason in medium_reasons[:3]:
            msg6 += f"   • {reason}\n"
        msg6 += f"\n"
        
        msg6 += f"🏦 *LONG TERM* (1-5 Years)\n"
        msg6 += f"   Score: {long_score}/100 | {score_to_rating(long_score)}\n"
        for reason in long_reasons[:3]:
            msg6 += f"   • {reason}\n"
        
        await update.message.reply_text(msg6, parse_mode='Markdown')
        
        # Part 7: PrimoAgent Analysis (if available)
        primo_msg = f"🤖 *PRIMOAGENT AI ANALYSIS*\n"
        primo_msg += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        try:
            from primo_agent.workflow import run_primo_analysis
            from io import StringIO
            
            # Run PrimoAgent
            class QuietConsole:
                def print(self, *args, **kwargs): pass
                def status(self, *args, **kwargs): 
                    class DummyContext:
                        def __enter__(self): return self
                        def __exit__(self, *args): pass
                    return DummyContext()
            
            primo_results = await run_primo_analysis([symbol], openai_api_key=OPENAI_API_KEY, console=QuietConsole())
            
            if symbol in primo_results and primo_results[symbol].get('success'):
                result = primo_results[symbol]
                decision = result.get('portfolio_decision', {})
                tech = result.get('technical_analysis', {})
                news_intel = result.get('news_intelligence', {})
                
                signal = decision.get('trading_signal', 'N/A')
                confidence = decision.get('confidence_level', 0)
                position_size = decision.get('position_size', 0)
                reasoning = decision.get('reasoning', 'N/A')
                
                signal_emoji = "🟢" if signal == "BUY" else "🔴" if signal == "SELL" else "🟡"
                
                primo_msg += f"{signal_emoji} *Signal: {signal}*\n"
                primo_msg += f"   Confidence: {confidence:.0%}\n"
                primo_msg += f"   Position Size: {position_size}%\n\n"
                primo_msg += f"💭 *Reasoning:*\n{reasoning[:500]}\n"
                
                # NLP Features
                nlp = news_intel.get('nlp_features', {})
                if nlp:
                    primo_msg += f"\n*NLP Insights:*\n"
                    for feature, value in list(nlp.items())[:4]:
                        primo_msg += f"   • {feature}: {value:+.1f}\n"
            else:
                primo_msg += "⚠️ PrimoAgent analysis unavailable\n"
                
        except Exception as e:
            primo_msg += f"⚠️ PrimoAgent not available\n"
        
        await update.message.reply_text(primo_msg, parse_mode='Markdown')
        
        # Part 8: Perplexity AI Analysis - Entry Price & Deep Insights
        perplexity_msg = f"🔮 *PERPLEXITY AI ANALYSIS*\n"
        perplexity_msg += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        if PERPLEXITY_API_KEY:
            try:
                import requests
                
                perplexity_prompt = f"""Analyze {symbol} ({name}) stock for a potential investment:

Current Data:
- Current Price: ${current_price:.2f}
- 52-Week Range: ${low_52w:.2f} - ${high_52w:.2f}
- Position in Range: {range_position:.0f}%
- Analyst Target: ${target_mean:.2f} (Mean), ${target_low:.2f} (Low), ${target_high:.2f} (High)
- P/E Ratio: {pe_forward:.1f}
- RSI: {rsi:.1f}
- Revenue Growth: {revenue_growth:.1f}%
- Consensus: {recommendation}

Please provide:
1. **Reasonable Entry Price**: What's a good entry price to buy this stock? Consider support levels, recent price action, and value.
2. **Key Risk Factors**: What are the main risks for this stock right now?
3. **Catalysts**: What upcoming events or factors could move this stock?
4. **Verdict**: Is it a good time to buy, wait for a pullback, or avoid?

Be specific with price levels and actionable advice."""

                headers = {
                    "Authorization": f"Bearer {PERPLEXITY_API_KEY}",
                    "Content-Type": "application/json"
                }
                
                payload = {
                    "model": model,
                    "messages": [
                        {
                            "role": "system",
                            "content": "You are a professional stock analyst. Provide concise, actionable analysis with specific price levels. Focus on entry points and risk/reward."
                        },
                        {
                            "role": "user",
                            "content": perplexity_prompt
                        }
                    ],
                    "max_tokens": 800,
                    "temperature": 0.2
                }
                
                response = requests.post(
                    "https://api.perplexity.ai/chat/completions",
                    headers=headers,
                    json=payload,
                    timeout=300 if model == 'sonar-deep-research' else 60
                )
                
                if response.status_code == 200:
                    result = response.json()
                    perplexity_analysis = result['choices'][0]['message']['content']
                    perplexity_msg += f"{perplexity_analysis}\n"
                else:
                    perplexity_msg += f"⚠️ Perplexity API error: {response.status_code}\n"
                    
            except Exception as e:
                perplexity_msg += f"⚠️ Perplexity analysis error: {str(e)[:100]}\n"
        else:
            perplexity_msg += "⚠️ Perplexity API key not configured\n"
            perplexity_msg += "Add PERPLEXITY_API_KEY to your .env file\n"
        
        await update.message.reply_text(perplexity_msg, parse_mode='Markdown')
        
        # Part 9: Final Conclusions (AI-generated if available)
        conclusion_msg = f"📋 *FINAL CONCLUSIONS*\n"
        conclusion_msg += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
        
        # Calculate overall score
        overall_score = (swing_score * 0.15 + short_score * 0.25 + medium_score * 0.30 + long_score * 0.30)
        
        conclusion_msg += f"*Overall Score: {overall_score:.0f}/100*\n"
        conclusion_msg += f"*Rating: {score_to_rating(overall_score)}*\n\n"
        
        if HAS_OPENAI:
            # Generate AI conclusion
            prompt = f"""Based on this stock analysis for {symbol} ({name}):

Price: ${current_price:.2f} ({range_position:.0f}% of 52-week range)
Returns: 1M {return_1m:+.1f}%, 1Y {return_1y:+.1f}%
RSI: {rsi:.1f}, MACD: {'Bullish' if macd_hist > 0 else 'Bearish'}
P/E: {pe_forward:.1f}, Revenue Growth: {revenue_growth:.1f}%
Analyst Target: ${target_mean:.2f} ({upside:+.1f}% upside)
Consensus: {recommendation}

Scores:
- Swing Trading: {swing_score}/100
- Short-term (1-3mo): {short_score}/100
- Medium-term (3-12mo): {medium_score}/100
- Long-term (1-5yr): {long_score}/100

Provide a brief conclusion (3-4 sentences) with:
1. Key strength or weakness
2. Best timeframe for this stock
3. Specific action recommendation
Keep it direct and actionable."""

            try:
                response = client.chat.completions.create(
                    model="gpt-4o",
                    messages=[
                        {"role": "system", "content": "You are a professional stock analyst. Be direct, specific, and actionable."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=200
                )
                ai_conclusion = response.choices[0].message.content.strip()
                conclusion_msg += f"🤖 *AI Summary:*\n{ai_conclusion}\n"
            except:
                pass
        
        conclusion_msg += f"\n⏰ Analysis Date: {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        conclusion_msg += f"\n\n📊 *Your Decision = AI (20%) + Research (30%) + Charts (20%) + Fundamentals (20%) + Gut (10%)*"
        
        await update.message.reply_text(conclusion_msg, parse_mode='Markdown')
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error during analysis: {str(e)}")


async def perplexity_chat(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Chat with Perplexity AI - ask any question"""
    user_id = update.effective_user.id
    
    if not context.args:
        pending_commands[user_id] = 'perplexity_chat'
        await update.message.reply_text(
            "🔮 *Perplexity AI Chat*\n\n"
            "Ask me anything! I'll search the web and provide an informed answer.\n\n"
            "Examples:\n"
            "• `What are the best AI stocks to buy in 2026?`\n"
            "• `Is NVDA overvalued at current prices?`\n"
            "• `What's the outlook for semiconductor stocks?`\n"
            "• `Compare AAPL vs MSFT for long-term investment`",
            parse_mode='Markdown'
        )
        return
    
    question = ' '.join(context.args)
    await update.message.reply_text(
        f"🔮 *Perplexity AI Chat*\n\n"
        f"Choose AI research depth:",
        parse_mode='Markdown',
        reply_markup=_get_model_keyboard('ask', question)
    )


async def _run_perplexity_chat(update: Update, question: str, model: str = 'sonar-pro'):
    """Run Perplexity AI chat query"""
    import requests
    model_names = {'sonar-pro': '⚡ Sonar Pro', 'sonar-reasoning': '🧠 Reasoning', 'sonar-deep-research': '🔬 Deep Research'}
    model_label = model_names.get(model, model)
    
    await update.message.reply_text(
        f"🔮 *Asking Perplexity AI...*\n"
        f"🤖 Model: {model_label}\n\n"
        f"📝 _{question}_\n\n"
        f"⏳ Searching and analyzing..."
        f"{'\n⚠️ Deep Research mode may take 2-3 minutes...' if model == 'sonar-deep-research' else ''}",
        parse_mode='Markdown'
    )
    
    if not PERPLEXITY_API_KEY:
        await update.message.reply_text(
            "❌ Perplexity API key not configured.\n"
            "Add `PERPLEXITY_API_KEY` to your .env file."
        )
        return
    
    try:
        headers = {
            "Authorization": f"Bearer {PERPLEXITY_API_KEY}",
            "Content-Type": "application/json"
        }
        
        payload = {
            "model": model,
            "messages": [
                {
                    "role": "system",
                    "content": "You are a helpful financial analyst assistant. Provide clear, well-researched answers about stocks, markets, and investments. Include specific data, prices, and actionable insights when relevant. Be concise but thorough."
                },
                {
                    "role": "user",
                    "content": question
                }
            ],
            "max_tokens": 1500,
            "temperature": 0.2
        }
        
        response = requests.post(
            "https://api.perplexity.ai/chat/completions",
            headers=headers,
            json=payload,
            timeout=300 if model == 'sonar-deep-research' else 60
        )
        
        if response.status_code == 200:
            result = response.json()
            answer = result['choices'][0]['message']['content']
            
            # Split long messages (Telegram has 4096 char limit)
            disclaimer = "\n\n📊 *Your Decision = AI (20%) + Research (30%) + Charts (20%) + Fundamentals (20%) + Gut (10%)*"
            if len(answer) > 3600:
                # Split into chunks
                chunks = [answer[i:i+3600] for i in range(0, len(answer), 3600)]
                for i, chunk in enumerate(chunks):
                    if i == 0:
                        await update.message.reply_text(
                            f"🔮 *Perplexity AI Response* ({model_label})\n"
                            f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
                            f"{chunk}",
                            parse_mode='Markdown'
                        )
                    elif i == len(chunks) - 1:
                        await update.message.reply_text(chunk + disclaimer, parse_mode='Markdown')
                    else:
                        await update.message.reply_text(chunk, parse_mode='Markdown')
            else:
                await update.message.reply_text(
                    f"🔮 *Perplexity AI Response* ({model_label})\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
                    f"{answer}{disclaimer}",
                    parse_mode='Markdown'
                )
        else:
            await update.message.reply_text(
                f"❌ Perplexity API error: {response.status_code}\n"
                f"Response: {response.text[:200]}"
            )
            
    except requests.exceptions.Timeout:
        await update.message.reply_text("❌ Request timed out. Please try again.")
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)[:200]}")


async def market_why(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Explain why the market is moving today - comprehensive news analysis"""
    import requests
    from datetime import datetime
    
    await update.message.reply_text(
        "📊 *MARKET ANALYSIS*\n\n"
        "⏳ Researching today's market movements...\n"
        "• Gathering major indices data\n"
        "• Analyzing breaking news\n"
        "• Identifying sector impacts\n"
        "• Finding winners & losers\n\n"
        "_This may take 30-60 seconds..._",
        parse_mode='Markdown'
    )
    
    try:
        # Get current market data
        indices = {
            '^GSPC': 'S&P 500',
            '^DJI': 'Dow Jones',
            '^IXIC': 'Nasdaq',
            '^RUT': 'Russell 2000',
            '^VIX': 'VIX (Fear Index)'
        }
        
        market_data = []
        for symbol, name in indices.items():
            try:
                ticker = yf.Ticker(symbol)
                hist = ticker.history(period='2d')
                if len(hist) >= 2:
                    current = hist['Close'].iloc[-1]
                    prev = hist['Close'].iloc[-2]
                    change_pct = ((current - prev) / prev) * 100
                    market_data.append(f"• {name}: {change_pct:+.2f}%")
                elif len(hist) == 1:
                    current = hist['Close'].iloc[-1]
                    info = ticker.info
                    prev = info.get('previousClose', current)
                    change_pct = ((current - prev) / prev) * 100
                    market_data.append(f"• {name}: {change_pct:+.2f}%")
            except:
                pass
        
        market_summary = "\n".join(market_data) if market_data else "Market data unavailable"
        
        # Get sector performance
        sectors = {
            'XLK': 'Technology',
            'XLF': 'Financials', 
            'XLE': 'Energy',
            'XLV': 'Healthcare',
            'XLI': 'Industrials',
            'XLP': 'Consumer Staples',
            'XLY': 'Consumer Discretionary',
            'XLB': 'Materials',
            'XLU': 'Utilities',
            'XLRE': 'Real Estate'
        }
        
        sector_data = []
        for symbol, name in sectors.items():
            try:
                ticker = yf.Ticker(symbol)
                hist = ticker.history(period='2d')
                if len(hist) >= 2:
                    current = hist['Close'].iloc[-1]
                    prev = hist['Close'].iloc[-2]
                    change_pct = ((current - prev) / prev) * 100
                    sector_data.append((name, change_pct))
            except:
                pass
        
        # Sort sectors by performance
        sector_data.sort(key=lambda x: x[1], reverse=True)
        top_sectors = [f"🟢 {s[0]}: {s[1]:+.2f}%" for s in sector_data[:3]]
        bottom_sectors = [f"🔴 {s[0]}: {s[1]:+.2f}%" for s in sector_data[-3:]]
        
        today = datetime.now().strftime("%B %d, %Y")
        
        # Use Perplexity to analyze the news
        if not PERPLEXITY_API_KEY:
            await update.message.reply_text(
                "❌ Perplexity API key not configured.\n"
                "Add `PERPLEXITY_API_KEY` to your .env file."
            )
            return
        
        prompt = f"""Today is {today}. Analyze today's stock market movements and news.

Current Market Status:
{market_summary}

Top Performing Sectors: {', '.join([s[0] for s in sector_data[:3]]) if sector_data else 'N/A'}
Worst Performing Sectors: {', '.join([s[0] for s in sector_data[-3:]]) if sector_data else 'N/A'}

Please provide a comprehensive analysis:

1. **WHAT HAPPENED TODAY** 📰
   - What are the main news events driving markets today?
   - Any Fed announcements, economic data, earnings, or geopolitical events?

2. **WHY THE MARKET IS MOVING** 📊
   - Explain the key reasons behind today's market direction
   - Connect the dots between news and market reaction

3. **SECTOR IMPACT ANALYSIS** 🏭
   - Which sectors are most affected and why?
   - What's driving the outperformers and underperformers?

4. **POTENTIAL CONSEQUENCES** ⚠️
   - What could this lead to in coming days/weeks?
   - Any knock-on effects to watch?

5. **WINNERS & LOSERS** 🎯
   - **LIKELY WINNERS**: Name 5-7 specific stocks (with tickers) that could benefit
   - **LIKELY LOSERS**: Name 5-7 specific stocks (with tickers) that could suffer
   - Explain why each is positioned to win or lose

6. **ACTIONABLE INSIGHTS** 💡
   - What should investors do today?
   - Any buying opportunities or risks to avoid?

Be specific with stock tickers, prices, and actionable advice. Focus on TODAY's news and events."""

        headers = {
            "Authorization": f"Bearer {PERPLEXITY_API_KEY}",
            "Content-Type": "application/json"
        }
        
        payload = {
            "model": "sonar-pro",
            "messages": [
                {
                    "role": "system",
                    "content": "You are an expert financial analyst providing real-time market analysis. Be specific with tickers, numbers, and actionable insights. Focus on today's actual news and events. Always cite specific companies with their ticker symbols."
                },
                {
                    "role": "user",
                    "content": prompt
                }
            ],
            "max_tokens": 2500,
            "temperature": 0.2
        }
        
        response = requests.post(
            "https://api.perplexity.ai/chat/completions",
            headers=headers,
            json=payload,
            timeout=90
        )
        
        if response.status_code == 200:
            result = response.json()
            analysis = result['choices'][0]['message']['content']
            
            # Build header with market data
            header = f"📊 *MARKET ANALYSIS - {today}*\n"
            header += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            header += f"*📈 CURRENT INDICES:*\n{market_summary}\n\n"
            
            if top_sectors and bottom_sectors:
                header += f"*🏆 TOP SECTORS:*\n" + "\n".join(top_sectors) + "\n\n"
                header += f"*📉 BOTTOM SECTORS:*\n" + "\n".join(bottom_sectors) + "\n\n"
            
            header += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            
            full_msg = header + analysis
            
            # Split long messages
            if len(full_msg) > 3800:
                chunks = [full_msg[i:i+3800] for i in range(0, len(full_msg), 3800)]
                for i, chunk in enumerate(chunks):
                    try:
                        await update.message.reply_text(chunk, parse_mode='Markdown')
                    except:
                        # If markdown fails, send without formatting
                        await update.message.reply_text(chunk)
            else:
                try:
                    await update.message.reply_text(full_msg, parse_mode='Markdown')
                except:
                    await update.message.reply_text(full_msg)
        else:
            await update.message.reply_text(
                f"❌ Perplexity API error: {response.status_code}\n"
                f"Response: {response.text[:200]}"
            )
            
    except requests.exceptions.Timeout:
        await update.message.reply_text("❌ Request timed out. The analysis is taking too long. Please try again.")
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {str(e)[:300]}")


