async def _auto_start_zacks_monitor(app):
    """Automatically start Zacks monitor on bot startup (with 10 min delay)"""
    global zacks_monitor_task
    
    try:
        # Wait 10 minutes before starting
        print("⏳ Zacks monitor will auto-start in 10 minutes...")
        await asyncio.sleep(10 * 60)  # 10 minutes delay
        
        # Get symbols to monitor
        symbols = _get_all_monitored_symbols()
        
        if not symbols:
            print("⚠️ No stocks to monitor for Zacks (add to portfolio/watchlist)")
            return
        
        print(f"📊 Auto-starting Zacks monitor for {len(symbols)} stocks...")
        
        # Check initial ratings (silently, no message)
        # Use run_in_executor to avoid blocking the event loop
        loop = asyncio.get_event_loop()
        for symbol in symbols:
            try:
                rating = await loop.run_in_executor(None, _get_zacks_rating, symbol)
                if rating['rank']:
                    zacks_ratings_cache[symbol] = {
                        'rank': rating['rank'],
                        'rank_text': rating['rank_text'],
                        'last_checked': datetime.now()
                    }
                await asyncio.sleep(1)  # Rate limiting
            except:
                continue
        
        # Save cache
        _save_zacks_cache()
        
        # Start background monitor loop
        zacks_monitor_task = asyncio.create_task(_auto_zacks_loop(app))
        
        print(f"✅ Zacks monitor auto-started! Monitoring {len(zacks_ratings_cache)} stocks")
        
        # Send notification to user
        try:
            await app.bot.send_message(
                chat_id=TELEGRAM_CHAT_ID,
                text=f"🤖 *Bot Started!*\n\n"
                     f"✅ Zacks Monitor auto-started\n"
                     f"📊 Monitoring {len(symbols)} stocks\n"
                     f"⏰ Checking every 2 hours\n"
                     f"📋 10-hour summary updates\n\n"
                     f"Use /zackslist to see all ratings",
                parse_mode='Markdown'
            )
        except:
            pass
            
    except Exception as e:
        print(f"⚠️ Could not auto-start Zacks monitor: {e}")


async def _auto_zacks_loop(app):
    """Background loop for auto-started Zacks monitoring with smart timing"""
    global zacks_ratings_cache
    import pytz
    
    est = pytz.timezone('US/Eastern')
    last_check_time = None
    sent_pre_market_today = False
    sent_post_market_today = False
    last_market_hours_check = None
    
    while True:
        try:
            # Check every 10 minutes to see if we should run
            await asyncio.sleep(10 * 60)
            
            now_est = datetime.now(est)
            current_time = now_est.time()
            current_weekday = now_est.weekday()  # 0=Monday, 6=Sunday
            
            # Skip weekends
            if current_weekday >= 5:
                sent_pre_market_today = False
                sent_post_market_today = False
                continue
            
            # Reset daily flags at midnight
            if current_time.hour == 0 and current_time.minute < 15:
                sent_pre_market_today = False
                sent_post_market_today = False
            
            should_check = False
            check_reason = ""
            
            # Pre-market check: 7:30 AM EST (2 hours before 9:30 open)
            if not sent_pre_market_today and current_time.hour == 7 and 25 <= current_time.minute <= 40:
                should_check = True
                check_reason = "pre_market"
                sent_pre_market_today = True
            
            # Post-market check: 4:20 PM EST (20 minutes after 4:00 close)
            elif not sent_post_market_today and current_time.hour == 16 and 15 <= current_time.minute <= 30:
                should_check = True
                check_reason = "post_market"
                sent_post_market_today = True
            
            # During market hours: every 4 hours (roughly 9:30, 13:30)
            elif 9 <= current_time.hour < 16:
                if last_market_hours_check is None:
                    should_check = True
                    check_reason = "market_hours"
                    last_market_hours_check = now_est
                else:
                    hours_since_last = (now_est - last_market_hours_check).total_seconds() / 3600
                    if hours_since_last >= 4:
                        should_check = True
                        check_reason = "market_hours"
                        last_market_hours_check = now_est
            
            if not should_check:
                continue
            
            # Get all monitored symbols
            symbols = _get_all_monitored_symbols()
            
            if not symbols:
                continue
            
            changes = []
            
            # Use run_in_executor to avoid blocking the event loop
            loop = asyncio.get_event_loop()
            for symbol in symbols:
                try:
                    rating = await loop.run_in_executor(None, _get_zacks_rating, symbol)
                    
                    if rating['error'] or not rating['rank']:
                        continue
                    
                    current_rank = rating['rank']
                    current_text = rating['rank_text']
                    
                    # Check for change
                    if symbol in zacks_ratings_cache:
                        old_rank = zacks_ratings_cache[symbol].get('rank')
                        old_text = zacks_ratings_cache[symbol].get('rank_text')
                        
                        if old_rank and old_rank != current_rank:
                            direction = "⬆️ UPGRADE" if int(current_rank) < int(old_rank) else "⬇️ DOWNGRADE"
                            changes.append({
                                'symbol': symbol,
                                'old_rank': old_rank,
                                'old_text': old_text,
                                'new_rank': current_rank,
                                'new_text': current_text,
                                'direction': direction
                            })
                    
                    # Update cache
                    zacks_ratings_cache[symbol] = {
                        'rank': current_rank,
                        'rank_text': current_text,
                        'last_checked': datetime.now()
                    }
                    
                    _save_zacks_cache()
                    await asyncio.sleep(2)
                    
                except:
                    continue
            
            # Send alerts based on timing
            if changes:
                if check_reason == "pre_market":
                    header = "🌅 *PRE-MARKET ZACKS UPDATE*\n"
                    header += f"_2 hours before market open_\n"
                elif check_reason == "post_market":
                    header = "🌆 *POST-MARKET ZACKS SUMMARY*\n"
                    header += f"_Today's rating changes_\n"
                else:
                    header = "📊 *ZACKS RATING CHANGES*\n"
                    header += f"_Market hours check_\n"
                
                header += "━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
                
                msg = header
                for change in changes:
                    msg += f"{change['direction']} *{change['symbol']}*\n"
                    msg += f"   #{change['old_rank']} {change['old_text']} → #{change['new_rank']} {change['new_text']}\n\n"
                
                msg += f"_Checked {len(symbols)} stocks at {now_est.strftime('%I:%M %p EST')}_"
                
                try:
                    await app.bot.send_message(
                        chat_id=TELEGRAM_CHAT_ID,
                        text=msg,
                        parse_mode='Markdown',
                        disable_web_page_preview=True
                    )
                except:
                    pass
            elif check_reason in ["pre_market", "post_market"]:
                # Send "no changes" message for pre/post market
                if check_reason == "pre_market":
                    msg = "🌅 *PRE-MARKET ZACKS CHECK*\n"
                    msg += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
                    msg += f"✅ No rating changes detected\n"
                    msg += f"📊 Checked {len(symbols)} stocks\n"
                    msg += f"⏰ {now_est.strftime('%I:%M %p EST')}"
                else:
                    msg = "🌆 *POST-MARKET ZACKS CHECK*\n"
                    msg += f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
                    msg += f"✅ No rating changes today\n"
                    msg += f"📊 Checked {len(symbols)} stocks\n"
                    msg += f"⏰ {now_est.strftime('%I:%M %p EST')}"
                
                try:
                    await app.bot.send_message(
                        chat_id=TELEGRAM_CHAT_ID,
                        text=msg,
                        parse_mode='Markdown'
                    )
                except:
                    pass
                
        except asyncio.CancelledError:
            break
        except Exception as e:
            print(f"Zacks loop error: {e}")
            continue


async def _send_auto_zacks_summary(app):
    """Send Zacks summary for auto-started monitor"""
    global zacks_ratings_cache
    
    if not zacks_ratings_cache:
        return
    
    script_dir = os.path.dirname(os.path.abspath(__file__))
    
    # Get portfolio/watchlist symbols
    portfolio_symbols = set()
    portfolio_file = os.path.join(script_dir, "my_portfolio.json")
    if os.path.exists(portfolio_file):
        try:
            with open(portfolio_file, 'r', encoding='utf-8') as f:
                portfolio = json.load(f)
            for holding in portfolio.get('holdings', []):
                portfolio_symbols.add(holding['symbol'].upper())
        except:
            pass
    
    watchlist_symbols = set()
    watchlist_file = os.path.join(script_dir, "watchlists.json")
    if os.path.exists(watchlist_file):
        try:
            with open(watchlist_file, 'r', encoding='utf-8') as f:
                watchlists = json.load(f)
            default_watchlist = watchlists.get('watchlists', {}).get('default', {})
            stocks_dict = default_watchlist.get('stocks', {})
            for symbol in stocks_dict.keys():
                watchlist_symbols.add(symbol.upper())
        except:
            pass
    
    watchlist_symbols = watchlist_symbols - portfolio_symbols
    
    rating_emoji = {'1': '🟢', '2': '🔵', '3': '🟡', '4': '🟠', '5': '🔴'}
    rating_names = {'1': 'Strong Buy', '2': 'Buy', '3': 'Hold', '4': 'Sell', '5': 'Strong Sell'}
    
    def format_stock(symbol, pct_change=None, dollar_change=None):
        data = zacks_ratings_cache.get(symbol, {})
        rank = data.get('rank', '?')
        emoji = rating_emoji.get(rank, '⚪')
        name = rating_names.get(rank, 'N/A')
        if dollar_change is not None:
            change_emoji = '📈' if dollar_change >= 0 else '📉'
            return f"{emoji} {symbol} (#{rank}) {change_emoji} ${dollar_change:+,.2f}"
        if pct_change is not None:
            change_emoji = '📈' if pct_change >= 0 else '📉'
            return f"{emoji} {symbol} (#{rank}) {change_emoji} {pct_change:+.2f}%"
        return f"{emoji} {symbol} (#{rank} {name})"
    
    def get_price_change(symbol):
        try:
            stock = yf.Ticker(symbol)
            info = stock.info
            current = info.get('regularMarketPrice') or info.get('currentPrice', 0)
            prev_close = info.get('previousClose') or info.get('regularMarketPreviousClose', current)
            if prev_close and prev_close > 0:
                return ((current - prev_close) / prev_close) * 100
        except:
            pass
        return 0
    
    def get_portfolio_dollar_change(symbol):
        try:
            # Get shares from portfolio
            shares = 0
            portfolio_file_path = os.path.join(script_dir, "my_portfolio.json")
            if os.path.exists(portfolio_file_path):
                with open(portfolio_file_path, 'r', encoding='utf-8') as f:
                    portfolio_data = json.load(f)
                for holding in portfolio_data.get('holdings', []):
                    if holding['symbol'].upper() == symbol.upper():
                        shares = holding.get('shares', 0)
                        break
            
            if shares == 0:
                return 0
            
            stock = yf.Ticker(symbol)
            info = stock.info
            current = info.get('regularMarketPrice') or info.get('currentPrice', 0)
            prev_close = info.get('previousClose') or info.get('regularMarketPreviousClose', current)
            
            if prev_close and prev_close > 0:
                return (current - prev_close) * shares
        except:
            pass
        return 0
    
    # Helper to get Zacks rank for sorting (1=Strong Buy, 5=Strong Sell)
    def get_zacks_rank(symbol):
        if symbol in zacks_ratings_cache:
            return zacks_ratings_cache[symbol].get('rank', 99)
        return 99
    
    msg = "📊 *Zacks Ratings Summary*\n"
    msg += "━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
    
    portfolio_in_cache = [s for s in portfolio_symbols if s in zacks_ratings_cache]
    if portfolio_in_cache:
        # Get $ changes for all portfolio stocks
        portfolio_changes = {}
        for symbol in portfolio_in_cache:
            portfolio_changes[symbol] = get_portfolio_dollar_change(symbol)
        
        # Sort by Zacks rank (1=Strong Buy first, 5=Strong Sell last), then by $ change within same rank
        portfolio_in_cache.sort(key=lambda s: (get_zacks_rank(s), -portfolio_changes.get(s, 0)))
        
        msg += "💼 *PORTFOLIO* (by Zacks rating)\n"
        for symbol in portfolio_in_cache:
            dollar_pl = portfolio_changes.get(symbol, 0)
            msg += f"{format_stock(symbol, dollar_change=dollar_pl)}\n"
        msg += "\n"
    
    watchlist_in_cache = [s for s in watchlist_symbols if s in zacks_ratings_cache]
    if watchlist_in_cache:
        # Get price changes for all watchlist stocks
        watchlist_changes = {}
        for symbol in watchlist_in_cache:
            watchlist_changes[symbol] = get_price_change(symbol)
        
        # Sort by Zacks rank (1=Strong Buy first, 5=Strong Sell last), then by % change within same rank
        watchlist_in_cache.sort(key=lambda s: (get_zacks_rank(s), -watchlist_changes.get(s, 0)))
        
        msg += "👀 *WATCHLIST* (by Zacks rating)\n"
        for symbol in watchlist_in_cache:
            pct = watchlist_changes.get(symbol, 0)
            msg += f"{format_stock(symbol, pct)}\n"
        msg += "\n"
    
    msg += "━━━━━━━━━━━━━━━━━━━━━━━━\n"
    msg += "🟢 Strong Buy  🔵 Buy  🟡 Hold\n"
    msg += "🟠 Sell  🔴 Strong Sell\n"
    msg += "━━━━━━━━━━━━━━━━━━━━━━━━\n"
    msg += f"📈 Total: {len(portfolio_in_cache) + len(watchlist_in_cache)} stocks\n"
    msg += f"🕐 {datetime.now().strftime('%Y-%m-%d %H:%M')}"
    
    try:
        await app.bot.send_message(
            chat_id=TELEGRAM_CHAT_ID,
            text=msg,
            parse_mode='Markdown'
        )
    except:
        pass


