def _format_dividend_pick(rank: int, stock: dict) -> str:
    """Format a single dividend stock pick for display"""
    symbol = stock['symbol']
    
    if rank == 1:
        rank_emoji = "🥇"
    elif rank == 2:
        rank_emoji = "🥈"
    elif rank == 3:
        rank_emoji = "🥉"
    else:
        rank_emoji = f"{rank}."
    
    zacks_emoji = {'1': '🟢', '2': '🔵', '3': '🟡', '4': '🟠', '5': '🔴'}.get(stock.get('zacks_rank', ''), '⚪')
    
    msg = f"{rank_emoji} *{symbol}* - {stock.get('name', symbol)}\n"
    msg += f"   💵 ${stock.get('price', 0):.2f}\n"
    
    div_yield = stock.get('dividend_yield', 0) * 100
    div_rate = stock.get('dividend_rate', 0)
    msg += f"   💰 ${div_rate:.2f}/yr ({div_yield:.2f}%)\n"
    msg += f"   {zacks_emoji} Zacks: {stock.get('zacks_text', 'N/A')}\n"
    msg += f"   🎯 Score: {stock['total_score']:.0f}/100\n\n"
    
    return msg


async def _analyze_dividend_stock(symbol: str) -> dict:
    """Analyze a single stock for dividend + growth potential"""
    
    result = {
        'symbol': symbol,
        'name': symbol,
        'total_score': 0,
        'price': 0,
        'day_change_pct': 0,
        'dividend_yield': 0,
        'dividend_rate': 0,
        'dividend_growth': 0,
        'payout_ratio': 0,
        'perf_1y': 0,
        'signals': [],
        'zacks_rank': None,
        'zacks_text': 'N/A'
    }
    
    try:
        stock = yf.Ticker(symbol)
        info = stock.info
        
        # Get current price
        current_price = info.get('regularMarketPrice') or info.get('currentPrice', 0)
        if not current_price or current_price == 0:
            return None
        
        result['price'] = current_price
        result['name'] = info.get('shortName', symbol)[:25]  # Truncate long names
        
        # Day change
        prev_close = info.get('previousClose', current_price)
        if prev_close:
            result['day_change_pct'] = ((current_price - prev_close) / prev_close) * 100
        
        score = 0
        
        # ============= DIVIDEND METRICS (max 40 points) =============
        
        dividend_yield = info.get('dividendYield', 0) or 0
        dividend_rate = info.get('dividendRate', 0) or 0
        payout_ratio = info.get('payoutRatio', 0) or 0
        
        # Normalize dividend yield - yfinance sometimes returns percentage, sometimes decimal
        # If yield > 1, it's probably already a percentage (like 3.5 for 3.5%)
        if dividend_yield > 1:
            dividend_yield = dividend_yield / 100  # Convert to decimal
        
        # If still seems wrong or missing, calculate from rate/price
        if dividend_yield <= 0 or dividend_yield > 0.25:  # > 25% is unrealistic
            if dividend_rate > 0 and current_price > 0:
                dividend_yield = dividend_rate / current_price
        
        # Normalize payout ratio too
        if payout_ratio > 5:  # If > 500%, probably returned as percentage
            payout_ratio = payout_ratio / 100
        
        result['dividend_yield'] = dividend_yield
        result['dividend_rate'] = dividend_rate
        result['payout_ratio'] = payout_ratio
        
        # Must have dividend to be considered
        if dividend_yield <= 0:
            return None
        
        # High dividend yield (max 15 points)
        if dividend_yield >= 0.06:  # 6%+
            score += 15
            result['signals'].append(f'High Yield {dividend_yield*100:.1f}%')
        elif dividend_yield >= 0.04:  # 4-6%
            score += 12
            result['signals'].append('Good Yield')
        elif dividend_yield >= 0.025:  # 2.5-4%
            score += 8
        elif dividend_yield >= 0.015:  # 1.5-2.5%
            score += 5
        else:
            score += 2
        
        # High dollar dividend (max 10 points)
        if dividend_rate >= 6:  # $6+/year
            score += 10
            result['signals'].append(f'${dividend_rate:.2f}/yr')
        elif dividend_rate >= 4:  # $4-6/year
            score += 8
        elif dividend_rate >= 2:  # $2-4/year
            score += 5
        elif dividend_rate >= 1:  # $1-2/year
            score += 3
        
        # Safe payout ratio (max 10 points) - lower is safer
        if payout_ratio > 0:
            if payout_ratio <= 0.50:  # 50% or less - very safe
                score += 10
                result['signals'].append('Safe Payout')
            elif payout_ratio <= 0.70:  # 50-70% - safe
                score += 7
            elif payout_ratio <= 0.85:  # 70-85% - moderate
                score += 4
            elif payout_ratio <= 1.0:  # 85-100% - risky
                score += 1
            else:  # Over 100% - unsustainable
                score -= 5
        
        # Dividend growth (5 year) - max 5 points
        five_year_div_growth = info.get('fiveYearAvgDividendYield', 0)
        # Estimate growth from trailing vs forward
        trailing_div = info.get('trailingAnnualDividendYield', 0) or 0
        if trailing_div and dividend_yield:
            # Rough growth estimate
            div_growth_est = (dividend_yield - trailing_div) / trailing_div * 100 if trailing_div > 0 else 0
            result['dividend_growth'] = div_growth_est
            if div_growth_est > 10:
                score += 5
            elif div_growth_est > 5:
                score += 3
        
        # ============= GROWTH POTENTIAL (max 25 points) =============
        
        # 1-year performance
        try:
            hist = stock.history(period='1y')
            if not hist.empty and len(hist) > 200:
                first_price = hist['Close'].iloc[0]
                perf_1y = ((current_price - first_price) / first_price) * 100
                result['perf_1y'] = perf_1y
                
                if perf_1y > 30:
                    score += 10
                    result['signals'].append('Strong Growth')
                elif perf_1y > 15:
                    score += 8
                elif perf_1y > 5:
                    score += 5
                elif perf_1y > 0:
                    score += 3
                elif perf_1y > -10:
                    score += 1
                else:
                    score -= 3
        except:
            pass
        
        # Revenue/earnings growth
        revenue_growth = info.get('revenueGrowth', 0) or 0
        earnings_growth = info.get('earningsGrowth', 0) or 0
        
        if revenue_growth > 0.10:  # 10%+ revenue growth
            score += 5
        elif revenue_growth > 0.05:
            score += 3
        
        if earnings_growth > 0.15:  # 15%+ earnings growth
            score += 5
            result['signals'].append('Earnings Growth')
        elif earnings_growth > 0.08:
            score += 3
        
        # Forward PE vs Trailing PE (growth expected)
        pe_ratio = info.get('trailingPE')
        forward_pe = info.get('forwardPE')
        if pe_ratio and forward_pe and forward_pe < pe_ratio:
            score += 3
        
        # Reasonable valuation for dividend stock
        if pe_ratio and pe_ratio < 20:
            score += 2
        
        # ============= ZACKS RATING (max 20 points) =============
        
        if symbol in zacks_ratings_cache:
            zacks_data = zacks_ratings_cache[symbol]
            zacks_rank = zacks_data.get('rank')
            zacks_text = zacks_data.get('rank_text', 'N/A')
        else:
            try:
                loop = asyncio.get_event_loop()
                zacks_result = await loop.run_in_executor(None, _get_zacks_rating, symbol)
                zacks_rank = zacks_result.get('rank')
                zacks_text = zacks_result.get('rank_text', 'N/A')
            except:
                zacks_rank = None
                zacks_text = 'N/A'
        
        result['zacks_rank'] = zacks_rank
        result['zacks_text'] = zacks_text
        
        if zacks_rank:
            if zacks_rank == '1':
                score += 20
                result['signals'].append('Zacks Strong Buy')
            elif zacks_rank == '2':
                score += 15
                result['signals'].append('Zacks Buy')
            elif zacks_rank == '3':
                score += 8
            elif zacks_rank == '4':
                score -= 3
            elif zacks_rank == '5':
                score -= 8
        
        # ============= ANALYST RATINGS (max 10 points) =============
        
        rec = info.get('recommendationKey', '').lower()
        if rec in ['strong_buy', 'strongbuy']:
            score += 10
        elif rec == 'buy':
            score += 8
        elif rec in ['outperform', 'overweight']:
            score += 6
        elif rec == 'hold':
            score += 2
        
        # ============= STABILITY BONUS (max 5 points) =============
        
        beta = info.get('beta', 1)
        if beta and beta < 0.8:  # Low volatility
            score += 5
            result['signals'].append('Low Volatility')
        elif beta and beta < 1.0:
            score += 3
        
        result['total_score'] = min(100, max(0, score))
        
        return result
        
    except Exception as e:
        return None


def main():
    """Start the bot"""
    import signal
    
    # Write PID file so restart_bot.bat can find and kill us
    pid_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'bot.pid')
    
    # Check if another instance is running
    if os.path.exists(pid_file):
        try:
            with open(pid_file, 'r') as f:
                old_pid = int(f.read().strip())
            # Try to kill the old instance
            os.kill(old_pid, signal.SIGTERM)
            print(f"⚠️ Killed previous bot instance (PID: {old_pid})")
            import time
            time.sleep(2)
        except (ProcessLookupError, ValueError, PermissionError, OSError):
            pass  # Process already dead or invalid PID
    
    # Write our PID
    with open(pid_file, 'w') as f:
        f.write(str(os.getpid()))
    
    print("🤖 Starting Interactive Telegram Bot...")
    print(f"Bot Token: {TELEGRAM_BOT_TOKEN[:20]}...")
    
    # Load Zacks cache from file
    _load_zacks_cache()
    
    # Create application with concurrent updates and timeouts
    from telegram.ext import Defaults
    # A restart mid-question must not lose the question: the typed-answer step
    # (pending_commands) and each user's conversation state (user_data) are kept
    # on disk. user_data is flushed every 2s, since the bot is stopped by force.
    from telegram.ext import PicklePersistence, PersistenceInput
    _here = os.path.dirname(os.path.abspath(__file__))
    pending_commands.attach(os.path.join(_here, 'pending_commands.json'))
    persistence = PicklePersistence(
        filepath=os.path.join(_here, 'bot_conversations.pickle'),
        store_data=PersistenceInput(bot_data=False, chat_data=False, user_data=True, callback_data=False),
        update_interval=2)
    app = (Application.builder().token(TELEGRAM_BOT_TOKEN).persistence(persistence)
           .concurrent_updates(True).connect_timeout(30).read_timeout(30).write_timeout(30).build())
    # Before any command handler: forget unfinished questions from earlier commands.
    app.add_handler(MessageHandler(filters.COMMAND, _new_command_resets_flows), group=-1)
    
